/**
 * Escapes strings that begin with spreadsheet formula characters (=, +, -, @)
 * or leading apostrophes/whitespace followed by formula characters,
 * unless the string is a valid signed numeric value (e.g. "-123.45")
 * or a pure numeric arithmetic sum expression (e.g. "=120.50+45.00").
 */
function sanitizeSheetCell_(val) {
  if (val === null || val === undefined) return "";
  if (typeof val !== "string") return val;
  const trimmed = val.trimStart();
  if (/^[+-]?\d+(\.\d+)?$/.test(trimmed.trim())) return val;
  if (/^=[0-9\s+\-*/().]+$/.test(trimmed.trim()) && /[0-9]/.test(trimmed)) return val;
  if (/^[\s'’]*[=+\-@]/.test(val)) {
    return "'" + val.replace(/^[\s'’]+/, "");
  }
  return val;
}

function sanitizeSheetMatrix_(rows) {
  if (!Array.isArray(rows)) return [];
  return rows.map(row => Array.isArray(row) ? row.map(cell => sanitizeSheetCell_(cell)) : row);
}

// --- Global Cache for KeyInfo Sheet ---
const _keyInfoCache = {
  sheet: null
};

// --- Execution-Scoped Connector Error Tracking ---
let _lastConnectorError = null;

function setLastConnectorError(errMessage) {
  if (errMessage) {
    _lastConnectorError = String(errMessage);
  }
}

function getLastConnectorError() {
  return _lastConnectorError;
}

function clearLastConnectorError() {
  _lastConnectorError = null;
}

/**
 * Central Helper: Logs to console if headless, Alerts UI if not.
 * @param {string} message - The message to display.
 * @param {boolean} isHeadless - Context flag.
 */
function logOrAlert(message, isHeadless) {
  const msgStr = String(message || '');
  if (/failed|error|exception/i.test(msgStr) && !msgStr.includes('0 errors') && !msgStr.includes('No error')) {
    setLastConnectorError(msgStr);
  }
  if (isHeadless) {
    console.log("[Headless]: " + message); // FIXED: Removed duplicate Logger.log
  } else {
    console.log("[UI]: " + message);       // FIXED: Replaced Logger with console for consistency
    SpreadsheetApp.getUi().alert(message);
  }
}

/**
 * Helper function to get a value from a specific cell in the 'KeyInfo' sheet.
 * Caches the sheet object for performance. 
 */
async function getKeyInfoValue(cellA1Notation) {
  try {
    if (!_keyInfoCache.sheet) {
      const ss = SpreadsheetApp.getActiveSpreadsheet();
      const sheet = ss.getSheetByName('KeyInfo');
      if (!sheet) {
        throw new Error("The required sheet 'KeyInfo' could not be found.");
      }
      _keyInfoCache.sheet = sheet;
    }
    let value = _keyInfoCache.sheet.getRange(cellA1Notation).getValue();
    if (value === null || value === undefined || value.toString().trim() === '') {
      // Auto-heal empty accounting tenant/realm IDs via Pulse Token Broker
      if (cellA1Notation === 'X2' && typeof getBrokerXeroAccessToken === 'function') {
        try {
          (await getBrokerXeroAccessToken());
          value = _keyInfoCache.sheet.getRange('X2').getValue();
        } catch (_) {}
      } else if (cellA1Notation === 'X3' && typeof getBrokerQBAccessToken === 'function') {
        try {
          (await getBrokerQBAccessToken());
          value = _keyInfoCache.sheet.getRange('X3').getValue();
        } catch (_) {}
      }

      if (value === null || value === undefined || value.toString().trim() === '') {
        throw new Error(`The required value in 'KeyInfo' sheet, cell ${cellA1Notation}, is empty.`);
      }
    }
    return value;
  } catch (e) {
    throw new Error(`Configuration Error: ${e.message}`);
  }
}

/**
 * Returns a clean display name for the current client / sheet instance.
 * @returns {string}
 */
function getClientDisplayName() {
  // 1. Check KeyInfo!B1 in active spreadsheet (Highest Priority)
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    if (ss) {
      const keyInfo = ss.getSheetByName('KeyInfo');
      if (keyInfo) {
        const val = keyInfo.getRange('B1').getValue();
        if (val && String(val).trim() !== '') {
          return String(val).trim();
        }
      }
    }
  } catch (e) {
    console.log("getClientDisplayName: Error reading KeyInfo!B1: " + e.message);
  }

  // 2. Fallback to ScriptProperties CURRENT_RUN_CLIENT
  try {
    const props = PropertiesService.getScriptProperties();
    const storedClient = props.getProperty('CURRENT_RUN_CLIENT');
    if (storedClient && storedClient.trim() !== '') {
      return storedClient.trim();
    }
  } catch (e) {}

  // 3. Fallback to Spreadsheet Name
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    if (ss) {
      const name = ss.getName();
      // If sheet is named "Acme - Master" or "Client X Master", strip suffix
      return name.replace(/\s*-\s*Master.*$/i, '').replace(/Master\s*-\s*/i, '').trim();
    }
  } catch (e) {}

  return "Client";
}


/**
 * Fetches invoices from Xero.
 * UPDATED: Handles Credit Notes by reducing the Invoice Amount ("Net of Credit").
 * - Fully credited invoices are skipped.
 * - Partially credited invoices are scaled down proportionally.
 */
async function getXeroInvoices(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const SHEET_NAME = "InvFromApp";
  try {
    // --- CONFIGURATION ---
    const rawDate = (await getKeyInfoValue('B2'));
    let importMode = "Whole";
    try {
       const modeVal = (await getKeyInfoValue('F8'));
       if (String(modeVal).trim().toLowerCase() === 'lines') importMode = "Lines";
    } catch(e) { console.log("F8 not set, defaulting to Whole mode."); }

    if (!rawDate || !(rawDate instanceof Date)) throw new Error("Cell B2 in KeyInfo must contain a valid date.");
    
    const cutoffDate = new Date(rawDate);
    cutoffDate.setMonth(cutoffDate.getMonth() - 12);

    const accessToken = (await getXeroAccessToken());
    const xeroTenantId = (await getKeyInfoValue('X2'));
    
    // --- FETCH ---
    let allInvoices = [];
    let page = 1;
    let keepFetching = true;
    const baseUrl = 'https://api.xero.com/api.xro/2.0/Invoices?where=Type%3d%3d%22ACCREC%22&order=Date%20DESC';
    const options = {
      'method': 'get',
      'headers': { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': xeroTenantId, 'Accept': 'application/json' },
      'muteHttpExceptions': true
    };
    Logger.log(`Starting Xero Fetch (Cutoff: ${cutoffDate.toLocaleDateString()})...`);

    while (keepFetching) {
        const response = (await UrlFetchApp.fetch(`${baseUrl}&page=${page}`, options));
        if (response.getResponseCode() === 200) {
            const pageInvoices = JSON.parse(response.getContentText()).Invoices || [];
            if (pageInvoices.length > 0) {
                allInvoices = allInvoices.concat(pageInvoices);
                const lastInvDate = new Date(pageInvoices[pageInvoices.length - 1].DateString || pageInvoices[pageInvoices.length - 1].Date);
                if (lastInvDate < cutoffDate) keepFetching = false;
                else page++;
            } else {
                keepFetching = false;
            }
        } else {
            throw new Error(`Xero API Error on Page ${page}: ${response.getContentText()}`);
        }
        if (page > 50) keepFetching = false;
    }

    // --- FILTER & CALCULATE NET-OF-CREDIT ---
    const initialCount = allInvoices.length;
    const invoices = allInvoices.filter(inv => {
      const invDate = new Date(inv.DateString || inv.Date); 
      if (invDate < cutoffDate) return false;

      const total = parseFloat(inv.Total) || 0;
      const credited = parseFloat(inv.AmountCredited) || 0;

      // FIXED: Allow fully credited invoices to pass through so they import as £0
      // if (credited > 0 && Math.abs(total - credited) < 0.01) return false;

      return true;
    });
    
    Logger.log(`Filtered Xero Invoices: Kept ${invoices.length} of ${initialCount}`);

    // --- MAP DATA ---
    let mappedData = [];
    
    // Helper to calculate "Net of Credit" values
    const getEffectiveValues = (inv) => {
        const originalTotal = parseFloat(inv.Total) || 0;
        const credit = parseFloat(inv.AmountCredited) || 0;
        const effectiveTotal = originalTotal - credit;
        
        // Calculate reduction ratio
        const ratio = (originalTotal > 0) ? (effectiveTotal / originalTotal) : 1;
        
        return {
            total: effectiveTotal,
            subTotal: (parseFloat(inv.SubTotal) || 0) * ratio,
            tax: (parseFloat(inv.TotalTax) || 0) * ratio,
            ratio: ratio
        };
    };

    // Helper to extract the latest active payment or credit date from a Xero invoice
    const getLatestInvoicePaymentDate_ = (inv) => {
      if (inv.FullyPaidOnDate) return inv.FullyPaidOnDate;

      const parseEpoch = (raw) => {
        if (!raw) return 0;
        const match = String(raw).match(/\/Date\((\d+)/);
        if (match) return parseInt(match[1], 10);
        const d = new Date(raw);
        return isNaN(d.getTime()) ? 0 : d.getTime();
      };

      let latestDateRaw = "";
      let latestMs = 0;

      // 1. Direct bank payments (skip DELETED)
      if (Array.isArray(inv.Payments)) {
        inv.Payments.forEach(p => {
          if (p.Status === "DELETED") return;
          const ms = parseEpoch(p.Date);
          if (ms > latestMs) {
            latestMs = ms;
            latestDateRaw = p.Date;
          }
        });
      }

      // 2. Applied credit notes
      if (Array.isArray(inv.CreditNotes)) {
        inv.CreditNotes.forEach(cn => {
          const ms = parseEpoch(cn.AppliedDate || cn.Date);
          if (ms > latestMs) {
            latestMs = ms;
            latestDateRaw = cn.AppliedDate || cn.Date;
          }
        });
      }

      // 3. Prepayments and overpayments
      const otherAllocations = [...(inv.Prepayments || []), ...(inv.Overpayments || [])];
      otherAllocations.forEach(alloc => {
        const ms = parseEpoch(alloc.AppliedDate || alloc.Date);
        if (ms > latestMs) {
          latestMs = ms;
          latestDateRaw = alloc.AppliedDate || alloc.Date;
        }
      });

      return latestDateRaw;
    };

    if (importMode === "Lines") {
       invoices.forEach(inv => {
          const isPaid = (inv.Status === 'PAID');
          const parentRef = inv.Reference || "";
          const eff = getEffectiveValues(inv); // Get reduced totals

          const cashPaid = parseFloat(inv.AmountPaid) || 0;
          const currentBalance = Math.max(0, Math.round((eff.total - cashPaid) * 100) / 100);

          if (inv.LineItems && inv.LineItems.length > 0) {
              const type = (inv.LineAmountTypes || 'Exclusive').toUpperCase();

              // Pre-calculate line financials
              const rawLineFinancials = inv.LineItems.map(line => {
                  const rawLineAmt = line.LineAmount || 0;
                  const rawLineTax = line.TaxAmount || 0;
                  const effectiveLineAmt = rawLineAmt * eff.ratio;
                  const effectiveLineTax = rawLineTax * eff.ratio;

                  let lineTotal = 0;
                  let lineSubTotal = 0;
                  if (type === 'INCLUSIVE') {
                      lineTotal = effectiveLineAmt; 
                      lineSubTotal = effectiveLineAmt - effectiveLineTax;
                  } else {
                      lineSubTotal = effectiveLineAmt; 
                      lineTotal = effectiveLineAmt + effectiveLineTax;
                  }
                  return {
                      lineTotal: Math.round(lineTotal * 100) / 100,
                      lineSubTotal: lineSubTotal,
                      effectiveLineTax: effectiveLineTax
                  };
              });

              // Pre-calculate proportional line paids with rounding reconciliation
              let rawLinePaids = rawLineFinancials.map(fin => {
                  if (isPaid || currentBalance <= 0.005) return fin.lineTotal;
                  if (cashPaid <= 0.005) return 0;
                  const lineRatio = eff.total > 0 ? (fin.lineTotal / eff.total) : (1 / inv.LineItems.length);
                  return Math.round(cashPaid * lineRatio * 100) / 100;
              });

              if (!isPaid && currentBalance > 0.005 && cashPaid > 0.005 && inv.LineItems.length > 0) {
                  const sumLinePaids = rawLinePaids.reduce((sum, p) => sum + p, 0);
                  const paidDiff = Math.round((cashPaid - sumLinePaids) * 100) / 100;
                  if (Math.abs(paidDiff) > 0 && Math.abs(paidDiff) <= 0.05) {
                      let maxIdx = 0;
                      for (let li = 1; li < rawLinePaids.length; li++) {
                          if (rawLinePaids[li] > rawLinePaids[maxIdx]) maxIdx = li;
                      }
                      if (rawLinePaids[maxIdx] + paidDiff >= 0) {
                          rawLinePaids[maxIdx] = Math.round((rawLinePaids[maxIdx] + paidDiff) * 100) / 100;
                      }
                  }
              }

              inv.LineItems.forEach((line, index) => {
                  const lineId = `${inv.InvoiceID}-${index + 1}`;
                  const lineInvNumber = `${inv.InvoiceNumber}-${index + 1}`;
                  const lineDesc = line.Description || "";
                  const combinedRef = [parentRef, lineDesc].filter(Boolean).join(" - ");

                  const fin = rawLineFinancials[index];
                  const lineTotal = fin.lineTotal;
                  const lineSubTotal = fin.lineSubTotal;
                  const effectiveLineTax = fin.effectiveLineTax;

                  // Proportional payment allocation across lines
                  const lineAmountPaid = rawLinePaids[index];
                  const lineAmountDue = Math.max(0, Math.round((lineTotal - lineAmountPaid) * 100) / 100);

                  const linePaidDate = getLatestInvoicePaymentDate_(inv);

                  mappedData.push([
                      lineId,                 
                      inv.Contact?.Name,      
                      lineInvNumber,          
                      combinedRef,            
                      inv.Type,               
                      inv.DateString,         
                      inv.DueDateString,      
                      inv.Status,             
                      lineAmountDue,          
                      lineAmountPaid,         
                      lineTotal, // Uses the reduced total
                      linePaidDate,    
                      inv.SentToContact,      
                      lineSubTotal,           
                      effectiveLineTax,
                      inv.CurrencyCode,       
                      inv.CurrencyRate        
                  ]);
              });
          }
       });

    } else {
       // === WHOLE MODE ===
       mappedData = invoices.map(invoice => {
          const eff = getEffectiveValues(invoice);
          
          // Amount Paid (Cash) = Original Paid. 
          // New Balance = Effective Total - Cash Paid.
          const cashPaid = parseFloat(invoice.AmountPaid) || 0;
          const newBalance = eff.total - cashPaid;

          const invoicePaidDate = getLatestInvoicePaymentDate_(invoice);

          return [
            invoice.InvoiceID,
            invoice.Contact?.Name,
            invoice.InvoiceNumber, 
            invoice.Reference,
            invoice.Type,
            invoice.DateString,
            invoice.DueDateString,
            invoice.Status,
            newBalance, // Adjusted Balance
            cashPaid,
            eff.total, // Adjusted Total
            invoicePaidDate,
            invoice.SentToContact,
            eff.subTotal,
            eff.tax,
            invoice.CurrencyCode,
            invoice.CurrencyRate
          ];
        });
    }

    const pullResult = (await writeToGoogleSheet(mappedData, SPREADSHEET_ID, SHEET_NAME, importMode));
    _updateTimestamp("InvComp", "L2");
    
    console.log(`[getXeroInvoices] writeToGoogleSheet completed. Returned New: ${pullResult?.newInvoices?.length || 0}, Updated: ${pullResult?.updatedInvoices?.length || 0}`);
    logOrAlert(`Successfully synced ${mappedData.length} rows. Mode: ${importMode}`, isHeadless);
    return pullResult;
  } catch (e) {
    console.error(`[getXeroInvoices] Error: ${e.message}`);
    logOrAlert(`Xero Invoice Sync Failed: ${e.message}`, isHeadless);
    return { newInvoices: [], updatedInvoices: [] };
  }
}

/**
 * Refreshes the Xero access token using the stored refresh token.
 */
async function refreshXeroAccessToken() {
  const properties = PropertiesService.getScriptProperties();
  const tokenUrl = 'https://identity.xero.com/connect/token';
  const clientId = (await getKeyInfoValue('S2'));
  const clientSecret = (await getKeyInfoValue('S3'));
  const refreshToken = properties.getProperty('REFRESH_TOKEN');
  if (!refreshToken) {
    throw new Error('Xero credentials (REFRESH_TOKEN) are not configured in Script Properties.');
  }

  const payload = {
    'grant_type': 'refresh_token',
    'refresh_token': refreshToken
  };
  const headers = {
    'Authorization': 'Basic ' + Utilities.base64Encode(`${clientId}:${clientSecret}`)
  };
  const options = {
    'method': 'post',
    'headers': headers,
    'payload': payload,
    'muteHttpExceptions': true
  };
  Logger.log('Attempting to refresh the access token...');
  const response = (await UrlFetchApp.fetch(tokenUrl, options));
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();
  if (responseCode === 200) {
    const jsonResponse = JSON.parse(responseText);
    properties.setProperty('ACCESS_TOKEN', jsonResponse.access_token);
    properties.setProperty('REFRESH_TOKEN', jsonResponse.refresh_token);
    // FIXED: Force standard string conversion to prevent scientific notation bugs
    properties.setProperty('TOKEN_EXPIRY', String(Date.now() + (28 * 60 * 1000)));
    console.log('Successfully refreshed access and refresh tokens.');
    return jsonResponse.access_token;
  } else {
    throw new Error(`Failed to refresh Xero token. Server Response: ${responseText}`);
  }
}

/**
 * Retrieves the current access token.
 * First queries the Central Pulse Vault Token Broker (which auto-migrates local tokens if not yet in Vault).
 * Falls back to legacy local ScriptProperties refresh if the broker is unreachable.
 */
async function getXeroAccessToken() {
  // 1. Try Central Pulse Token Broker first
  if (typeof getBrokerXeroAccessToken === 'function') {
    try {
      const brokerToken = (await getBrokerXeroAccessToken());
      if (brokerToken) {
        console.log('Obtained fresh Xero access token from Central Pulse Vault.');
        return brokerToken;
      }
    } catch (brokerErr) {
      console.warn('Central Pulse Broker attempt failed, falling back to legacy properties: ' + brokerErr.message);
    }
  }

  // 2. Legacy fallback to local ScriptProperties
  const properties = PropertiesService.getScriptProperties();
  const accessToken = properties.getProperty('ACCESS_TOKEN');
  const tokenExpiry = properties.getProperty('TOKEN_EXPIRY');

  // FIXED: Using Number() instead of parseInt() to handle scientific notation
  if (!accessToken || !tokenExpiry || Date.now() > Number(tokenExpiry)) {
    console.log('Access token missing or expired, attempting legacy refresh.');
    return (await refreshXeroAccessToken());
  }
  
  return accessToken;
}

async function writeToGoogleSheet(finalData, spreadsheetId, sheetName, importMode = "Whole") {
  if (!finalData) finalData = [];

  // Sanitize all cells: convert null / undefined to empty string ("") and escape formula-leading strings.
  // Google Sheets API batchUpdate skips null values, leaving old cell content intact.
  // Passing "" explicitly clears the cell in Google Sheets.
  finalData = sanitizeSheetMatrix_(finalData);

  const ss = (await SpreadsheetApp.openById(spreadsheetId));
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) throw new Error('Sheet with name "' + sheetName + '" not found.');

  const props = PropertiesService.getScriptProperties();
  const lastMode = props.getProperty('INV_LAST_IMPORT_MODE');
  const lastRow = sheet.getLastRow();

  const timeZone = ss.getSpreadsheetTimeZone();
  const INVOICE_HEADERS_MAP = [
    "Invoice ID", "Client Name", "Invoice Number", "Description", "Type",
    "Sent Date", "Due Date", "Status", "Amount Due", "Amount Paid", "Total",
    "Fully Paid Date", "Sent To Contact", "SubTotal (Excl VAT)", "Total Tax (VAT)", "Currency", "Currency Rate"
  ];

  // --- EDGE CASE: MODE CHANGE OR EMPTY SHEET ---
  if (lastMode !== importMode || lastRow <= 1) {
    if (lastRow > 1) {
      sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn()).clearContent();
    }
    if (sheet.getLastRow() === 0) {
      const headers = [
        "InvoiceID", "ContactName", "InvoiceNumber", "Reference", "Type",
        "Date", "DueDate", "Status", "AmountDue", "AmountPaid", "Total",
        "FullyPaidOnDate", "SentToContact", "SubTotal", "TotalTax", "CurrencyCode", "CurrencyRate"
      ];
      sheet.appendRow(headers);
    }
    if (finalData.length > 0) {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, finalData.length, 1).setNumberFormat("@");
      sheet.getRange(startRow, 3, finalData.length, 1).setNumberFormat("@");
      sheet.getRange(startRow, 4, finalData.length, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, finalData.length, finalData[0].length).setValues(finalData);
    }
    
    props.setProperty('INV_LAST_IMPORT_MODE', importMode);
    if (finalData.length > 0) _logDataChangeAlert();
    Logger.log(`Mode change or initialization. Full overwrite complete. Wrote ${finalData.length} rows.`);
    const initialNewInvoices = finalData.map(r => formatNewInvoiceLogEntry_(r, timeZone));
    return { newInvoices: initialNewInvoices, updatedInvoices: [] };
  }

  // --- DELTA UPDATE ENGINE (WITH SLOT REUSE) ---
  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  
  finalData.forEach(row => incomingMap.set(String(row[0]), row));

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  const newInvoicesList = [];
  const updatedInvoicesList = [];

  // 1. Identify Updates and Empty Slots
  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    // Treat completely blank rows as free slots to be reclaimed
    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      // Exists in Sheet, missing from Xero -> Mark slot for reuse/clear
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      // Exists in both -> Compare for changes
      const newData = incomingMap.get(rowId);
      
      // Check for actual field differences between sheet row and incoming invoice
      const changes = getInvoiceFieldChanges_(oldData[i], newData, INVOICE_HEADERS_MAP, timeZone);
      if (changes.length > 0) {
        console.log(`[writeToGoogleSheet] Row ${sheetRowNum} (Inv #${newData[2]}) changed: ${changes.join("; ")}`);
        valueUpdates.push({
          range: `${sheetName}!A${sheetRowNum}`,
          values: [newData]
        });
        dataChanged = true;

        const invNum = String(newData[2] || oldData[i][2] || 'N/A').trim();
        const clientName = String(newData[1] || oldData[i][1] || 'Unknown Client').trim();
        const desc = String(newData[3] || oldData[i][3] || 'No description').trim();
        updatedInvoicesList.push(`Inv #${invNum} (${clientName} | ${desc}) - ${changes.join(", ")}`);
      }
      // Remove from map so we know whatever is left over is brand new
      incomingMap.delete(rowId);
    }
  }

  // 2. Identify Appends
  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) {
    dataChanged = true;
    rowsToAppend.forEach(r => {
      newInvoicesList.push(formatNewInvoiceLogEntry_(r, timeZone));
    });
  }

  console.log(`[writeToGoogleSheet] Comparison complete. Checked: ${oldData.length} existing rows. Detected New: ${newInvoicesList.length}, Updated: ${updatedInvoicesList.length}, Slots to clear: ${rowsToDelete.length}`);

  if (!dataChanged) {
    Logger.log('No changes detected in Xero. Sheet is up to date.');
    return { newInvoices: [], updatedInvoices: [] };
  }

  // 3. Slot Reuse Logic (Fill gaps before appending to bottom)
  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({
        range: `${sheetName}!A${recycleRow}`,
        values: [newRowData]
      });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 3, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 4, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  // 4. Clear Remaining Gaps (Instead of physically deleting the rows)
  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  // 5. Execute all value updates in a single Advanced API batch
  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({
      valueInputOption: "USER_ENTERED",
      data: valueUpdates
    }, spreadsheetId));
  }

  _logDataChangeAlert();
  Logger.log(`Delta Update Complete: Executed surgical updates and slot recycling.`);
  return { newInvoices: newInvoicesList, updatedInvoices: updatedInvoicesList };
}

function formatNewInvoiceLogEntry_(row, timeZone) {
  const invNum = String(row[2] || 'N/A').trim();
  const clientName = String(row[1] || 'Unknown Client').trim();
  const desc = String(row[3] || 'No description').trim();
  const subTotal = parseFloat(row[13]) || 0;
  const tax = parseFloat(row[14]) || 0;
  const vatMark = tax > 0 ? " +VAT" : "";
  const sentDate = formatLogDate_(row[5], timeZone);
  const dueDate = formatLogDate_(row[6], timeZone);
  const amtStr = formatLogAmount_(subTotal);
  return `Inv #${invNum} (${clientName} | ${desc}) - Amount: £${amtStr}${vatMark} | Sent: ${sentDate || 'N/A'} | Due: ${dueDate || 'N/A'}`;
}

function getInvoiceFieldChanges_(oldRow, newRow, headersMap, timeZone) {
  const changes = [];
  const maxCols = Math.max(oldRow.length, newRow.length);
  for (let c = 1; c < maxCols; c++) {
    const oldVal = oldRow[c];
    const newVal = newRow[c];

    // Dates: Sent Date (5), Due Date (6), Fully Paid Date (11)
    if ([5, 6, 11].includes(c)) {
      const oldYmd = normalizeDateToYmd_(oldVal, timeZone);
      const newYmd = normalizeDateToYmd_(newVal, timeZone);
      if (oldYmd === newYmd) continue;
      const headerName = headersMap[c] || `Col ${c}`;
      const oldFormatted = formatLogDate_(oldVal, timeZone) || (oldVal ? String(oldVal) : 'Blank');
      const newFormatted = formatLogDate_(newVal, timeZone) || (newVal ? String(newVal) : 'Blank');
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
      continue;
    }

    // Amounts: Amount Due (8), Amount Paid (9), Total (10), SubTotal (13), Total Tax (14)
    if ([8, 9, 10, 13, 14].includes(c)) {
      let cleanOld = oldVal;
      if (cleanOld instanceof Date) {
        const epochZero = new Date(1899, 11, 30).getTime();
        cleanOld = Math.round(((cleanOld.getTime() - epochZero) / 86400000) * 100) / 100;
      }
      let cleanNew = newVal;
      if (cleanNew instanceof Date) {
        const epochZero = new Date(1899, 11, 30).getTime();
        cleanNew = Math.round(((cleanNew.getTime() - epochZero) / 86400000) * 100) / 100;
      }
      const n1 = (cleanOld === null || cleanOld === undefined || cleanOld === '') ? 0 : Number(cleanOld);
      const n2 = (cleanNew === null || cleanNew === undefined || cleanNew === '') ? 0 : Number(cleanNew);
      if (!isNaN(n1) && !isNaN(n2) && Math.abs(n1 - n2) < 0.005) continue;
      const headerName = headersMap[c] || `Col ${c}`;
      const oldFormatted = formatLogAmount_(cleanOld);
      const newFormatted = formatLogAmount_(cleanNew);
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
      continue;
    }

    // General fields (Client Name, Inv Number, Description, Type, Status, Currency, etc.)
    const isDiff = (typeof valuesAreDifferent === 'function') ? valuesAreDifferent(oldVal, newVal) : (oldVal !== newVal);
    if (isDiff) {
      const headerName = headersMap[c] || `Col ${c}`;
      const oldFormatted = (oldVal === null || oldVal === undefined || String(oldVal).trim() === '') ? 'Blank' : String(oldVal).trim();
      const newFormatted = (newVal === null || newVal === undefined || String(newVal).trim() === '') ? 'Blank' : String(newVal).trim();
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
    }
  }
  return changes;
}

function normalizeDateToYmd_(val, timeZone) {
  if (val === null || val === undefined || val === "") return "";
  if (val instanceof Date) {
    if (isNaN(val.getTime())) return "";
    if (typeof Utilities !== 'undefined' && Utilities.formatDate) {
      return Utilities.formatDate(val, timeZone || "GMT", "yyyy-MM-dd");
    }
    const y = val.getFullYear();
    const m = String(val.getMonth() + 1).padStart(2, '0');
    const d = String(val.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  if (typeof val === 'number' && val > 20000 && val < 70000) {
    const epoch = new Date(1899, 11, 30);
    const d = new Date(epoch.getTime() + Math.round(val * 86400000));
    if (typeof Utilities !== 'undefined' && Utilities.formatDate) {
      return Utilities.formatDate(d, timeZone || "GMT", "yyyy-MM-dd");
    }
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }
  if (typeof val === 'string') {
    const s = val.trim();
    if (!s) return "";
    // Xero Microsoft JSON date format: /Date(1726876800000+0000)/
    const xeroMatch = s.match(/\/Date\((\d+)(?:[+-]\d+)?\)\//);
    if (xeroMatch) {
      const d = new Date(parseInt(xeroMatch[1], 10));
      if (!isNaN(d.getTime())) {
        if (typeof Utilities !== 'undefined' && Utilities.formatDate) {
          return Utilities.formatDate(d, timeZone || "GMT", "yyyy-MM-dd");
        }
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
      }
    }
    // ISO format: YYYY-MM-DD or YYYY-MM-DDTHH:mm:ss
    const isoMatch = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[T\s].*)?$/);
    if (isoMatch) {
      return `${isoMatch[1]}-${isoMatch[2].padStart(2, '0')}-${isoMatch[3].padStart(2, '0')}`;
    }
    // Text month format: 21-Sep-2026, 21-Sep-26, 21 Sep 2026
    const textDateMatch = s.match(/^(\d{1,2})[-/\s]([A-Za-z]{3,9})[-/\s](\d{2,4})(?:[T\s].*)?$/);
    if (textDateMatch) {
      const months = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
      const mKey = textDateMatch[2].slice(0, 3).toLowerCase();
      if (months[mKey]) {
        let y = textDateMatch[3];
        if (y.length === 2) y = (parseInt(y, 10) > 50 ? '19' : '20') + y;
        return `${y}-${String(months[mKey]).padStart(2, '0')}-${textDateMatch[1].padStart(2, '0')}`;
      }
    }
    // UK format: DD/MM/YYYY or DD/MM/YY (with optional time)
    const dmyMatch = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})(?:[T\s].*)?$/);
    if (dmyMatch) {
      let y = dmyMatch[3];
      if (y.length === 2) y = (parseInt(y, 10) > 50 ? '19' : '20') + y;
      return `${y}-${dmyMatch[2].padStart(2, '0')}-${dmyMatch[1].padStart(2, '0')}`;
    }
    // Long date string fallback: Mon Sep 21 2026 14:39:55 GMT+0100...
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
      if (typeof Utilities !== 'undefined' && Utilities.formatDate) {
        return Utilities.formatDate(d, timeZone || "GMT", "yyyy-MM-dd");
      }
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}`;
    }
  }
  return "";
}

function formatLogDate_(val, timeZone) {
  const ymd = normalizeDateToYmd_(val, timeZone);
  if (!ymd) return (val === null || val === undefined) ? "" : String(val).trim();
  const parts = ymd.split('-');
  const mIndex = parseInt(parts[1], 10) - 1;
  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const mStr = monthNames[mIndex] || parts[1];
  const yy = parts[0].slice(-2);
  return `${parts[2]}-${mStr}-${yy}`;
}

function formatLogAmount_(val) {
  if (val === null || val === undefined || val === "") return "0.00";
  if (val instanceof Date) {
    const epochZero = new Date(1899, 11, 30).getTime();
    val = Math.round(((val.getTime() - epochZero) / 86400000) * 100) / 100;
  }
  const num = parseFloat(String(val).replace(/[^0-9.-]/g, ''));
  if (isNaN(num)) return String(val).trim();
  return num.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}



/**
 * Fetches the Profit & Loss Report from Xero.
 * Original 12-Loop Engine: Bypasses Xero's truncation bug and 11-period limit.
 */
async function getXeroProfitAndLossReport(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const SHEET_NAME = "PLFromApp";
  try {
    const accessToken = (await getXeroAccessToken());
    const xeroTenantId = (await getKeyInfoValue('X2'));
    console.log('Starting P&L report fetch for Tenant ID: ' + xeroTenantId);
    const reportData = {
      headers: ['Description'],
      rowMap: new Map(),
      rowOrder: []
    };
    const formatDateToYyyyMmDd = (date) => {
      const year = date.getFullYear();
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const day = date.getDate().toString().padStart(2, '0');
      return `${year}-${month}-${day}`;
    };
    for (let i = 0; i < 12; i++) {
      const today = new Date();
      const targetDate = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const fromDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
      const toDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);
      const fromDateStr = formatDateToYyyyMmDd(fromDate);
      const toDateStr = formatDateToYyyyMmDd(toDate);
      const monthHeader = fromDate.toLocaleString('default', { month: 'long', year: 'numeric' });
      
      reportData.headers.splice(1, 0, monthHeader);
      
      const url = `https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss?fromDate=${fromDateStr}&toDate=${toDateStr}&standardLayout=false`;
      const options = {
        'method': 'get',
        'headers': { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': xeroTenantId, 'Accept': 'application/json' },
        'muteHttpExceptions': true
      };
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) {
        console.log(`Error fetching data for ${monthHeader}: ${response.getContentText()}`);
        continue;
      }

      const jsonResponse = JSON.parse(response.getContentText());
      const monthReport = jsonResponse.Reports[0];
      // Process Structure
      const getReportStructure = (report) => {
        const structure = [];
        if (!report || !report.Rows) return structure;
        const processNode = (r) => {
          let title = '';
          if (r.RowType === 'Section') {
            title = r.Title;
            structure.push({ title: title, type: r.RowType });
            if (r.Rows) r.Rows.forEach(processNode);
          } else if (r.RowType === 'Row' || r.RowType === 'SummaryRow') {
            title = r.Cells[0].Value;
            structure.push({ title: title, type: r.RowType });
          }
        };
        report.Rows.forEach(processNode);
        return structure;
      };
      const monthRowOrder = getReportStructure(monthReport);

      if (reportData.rowOrder.length === 0) {
        reportData.rowOrder = monthRowOrder;
      } else {
        // Merge Logic
        const masterTitles = new Set(reportData.rowOrder.map(r => r.title));
        monthRowOrder.forEach((monthRow, index) => {
          if (!masterTitles.has(monthRow.title)) {
            let predecessorIndexInMaster = -1;
            for (let j = index - 1; j >= 0; j--) {
              const predecessorTitle = monthRowOrder[j].title;
              const masterIndex = reportData.rowOrder.findIndex(r => r.title === predecessorTitle);
         
              if (masterIndex !== -1) {
                predecessorIndexInMaster = masterIndex;
                break;
              }
            }
            if (predecessorIndexInMaster !== -1) {
               
              reportData.rowOrder.splice(predecessorIndexInMaster + 1, 0, monthRow);
            } else {
              let successorIndexInMaster = -1;
              for (let j = index + 1; j < monthRowOrder.length; j++) {
                const successorTitle = monthRowOrder[j].title;
                const masterIndex = reportData.rowOrder.findIndex(r => r.title === successorTitle);
                if (masterIndex !== -1) {
                  successorIndexInMaster = masterIndex;
                  break;
                }
              }
              if (successorIndexInMaster !== -1) {
                reportData.rowOrder.splice(successorIndexInMaster, 0, monthRow);
              } else {
                reportData.rowOrder.push(monthRow);
              }
            }
            masterTitles.add(monthRow.title);
          }
        });
      }

      // Map Data
      const processRowData = (row) => {
        if (row.RowType === 'Section' && row.Rows) {
          row.Rows.forEach(processRowData);
        } else if ((row.RowType === 'Row' || row.RowType === 'SummaryRow') && row.Cells.length > 1) {
          const title = row.Cells[0].Value;
          const value = row.Cells[1].Value;
          if (!reportData.rowMap.has(title)) {
            reportData.rowMap.set(title, {});
          }
          reportData.rowMap.get(title)[monthHeader] = value;
        }
      };
      if (monthReport && monthReport.Rows) {
        monthReport.Rows.forEach(processRowData);
      }
    }

    if (reportData.rowOrder.length > 0) {
      (await writePLToGoogleSheet(reportData, SPREADSHEET_ID, SHEET_NAME));
      _updateTimestamp("PLComp", "C1"); 
      logOrAlert("Successfully updated P&L Report.", isHeadless);
    } else {
      logOrAlert("Failed to fetch any report data after 12 attempts.", isHeadless);
    }
  } catch (e) {
    logOrAlert("Xero P&L Failed: " + e.message, isHeadless);
  }
}

/**
 * Assembles and writes the P&L report to the Google Sheet.
 */
async function writePLToGoogleSheet(reportData, spreadsheetId, sheetName) {
  const ss = (await SpreadsheetApp.openById(spreadsheetId));
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }
  sheet.clear();

  const dataToWrite = [];
  dataToWrite.push(reportData.headers);
  reportData.rowOrder.forEach(rowInfo => {
    const newRow = [rowInfo.title];
    if (rowInfo.type === 'Section') {
      for (let i = 1; i < reportData.headers.length; i++) newRow.push('');
    } else {
      const rowData = reportData.rowMap.get(rowInfo.title) || {};
      for (let i = 1; i < reportData.headers.length; i++) {
        const monthHeader = reportData.headers[i];
        newRow.push(rowData[monthHeader] || '0.00');
      }
    }
    dataToWrite.push(newRow);
 
  });

  if (dataToWrite.length > 1) {
    const range = sheet.getRange(1, 1, dataToWrite.length, reportData.headers.length);
    range.setValues(sanitizeSheetMatrix_(dataToWrite));
  }
}

/**
 * A utility function to fetch and display the Tenant IDs.
 */
async function checkMyXeroTenantID() {
  const ui = SpreadsheetApp.getUi();
  try {
    const accessToken = (await getXeroAccessToken());
    if (!accessToken) {
      ui.alert('Could not get an access token. Please re-authorize the script.');
      return;
    }

    const url = 'https://api.xero.com/connections';
    const options = {
      'method': 'get',
      'headers': {
        'Authorization': 'Bearer ' + accessToken,
        'Accept': 'application/json'
      },
      'muteHttpExceptions': true
    };
    const response = (await UrlFetchApp.fetch(url, options));
    if (response.getResponseCode() !== 200) {
      ui.alert(`Failed to get connections. Error ${response.getResponseCode()}: ${response.getContentText()}`);
      return;
    }

    const connections = JSON.parse(response.getContentText());
    if (connections.length === 0) {
      ui.alert('Authorization successful, but no Xero organizations are connected.');
      return;
    }

    let message = ' Connection successful!\n\nAuthorized Organizations:\n\n';
    connections.forEach(conn => {
      message += `Company: ${conn.tenantName}\nID: ${conn.tenantId}\n\n`;
    });
    message += 'Please check the ID in the logs/KeyInfo sheet.';
    ui.alert(message);
  } catch (e) {
    ui.alert('An error occurred: ' + e.message);
  }
}

async function forceReAuthorization() {
  (await DriveApp.getRootFolder());
  Logger.log('Re-authorization check complete.');
}

function _updateTimestamp(sheetName, cellA1Notation) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheetByName(sheetName);
    if (sheet) {
      sheet.getRange(cellA1Notation).setValue(new Date());
      Logger.log(`Timestamp updated in ${sheetName}!${cellA1Notation}`);
    }
  } catch (e) {
    Logger.log(`Warning: Failed to update timestamp. Error: ${e.message}`);
  }
}

function _logDataChangeAlert() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let alertSheet = ss.getSheetByName('DataChgAlert');
    if (!alertSheet) {
      alertSheet = ss.insertSheet('DataChgAlert', 0);
      alertSheet.getRange('A1').setValue('Data Source');
      alertSheet.getRange('B1').setValue('Changed?');
      alertSheet.getRange('C1').setValue('Last Change Time');
    }
    alertSheet.getRange('B2').setValue('Yes');
    alertSheet.getRange('C2').setValue(new Date());
  } catch (e) {
    Logger.log(`Failed to log data change alert: ${e.message}`);
  }
}

function ClearInvoiceChangeAlert() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("DataChgAlert");
  if (sheet) {
    sheet.getRange("B2:C2").clearContent();
    sheet.getRange("AQ2").setValue("No");
  }
}

function ClearCRMChangeAlert() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("DataChgAlert");
  if (sheet) sheet.getRange("H2:I2").clearContent();
}

/**
 * Writes a structured log entry to the 'AutoLog' tab.
 * Inserts at the END (Far Right).
 * - Strips HTML tags from details for clean text.
 * - Forces "Normal" font weight.
 */
function writeToAutoLog(category, summary, details) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let logSheet = ss.getSheetByName("AutoLog");
  
  if (!logSheet) {
    logSheet = ss.insertSheet("AutoLog", ss.getNumSheets());
    logSheet.getRange("A1:D1").setValues([["Timestamp", "Category", "Summary", "Details"]]).setFontWeight("bold").setBackground("#f3f3f3");
    logSheet.setColumnWidth(1, 120); 
    logSheet.setColumnWidth(2, 100); 
    logSheet.setColumnWidth(3, 250); 
    logSheet.setColumnWidth(4, 500); 
    logSheet.setFrozenRows(1);
  }

  const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM-yy HH:mm");
  
  // Clean HTML tags from inputs (e.g. <b>)
  const cleanSummary = String(summary).replace(/<\/?[^>]+(>|$)/g, ""); 
  const cleanDetails = String(details).replace(/<\/?[^>]+(>|$)/g, "");

  // Insert new row at Top (Row 2)
  logSheet.insertRowAfter(1);
  
  const cellRange = logSheet.getRange(2, 1, 1, 4);
  cellRange.setValues([[timestamp, sanitizeSheetCell_(String(category || "")), sanitizeSheetCell_(cleanSummary), sanitizeSheetCell_(cleanDetails)]]);
  cellRange.setVerticalAlignment("top");
  cellRange.setWrapStrategy(SpreadsheetApp.WrapStrategy.WRAP);
  
  // FIX: Force Normal Font Weight (prevents inheriting Bold from header)
  cellRange.setFontWeight("normal");

  // Colour Coding
  const colors = { "INVOICES": "#e6f4ea", "CRM": "#e8f0fe", "EXPENSES": "#fce8e6", "RUN START": "#f1f3f4", "RUN END": "#3c4043" };
  const fontColors = { "RUN END": "#ffffff" }; 
  
  if (colors[category]) cellRange.setBackground(colors[category]);
  if (fontColors[category]) cellRange.setFontColor(fontColors[category]);

  // 60-Day Cleanup 
  try {
    const lastRow = logSheet.getLastRow();
    if (lastRow > 100) { 
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - 60);
      
      const checkStart = Math.max(2, lastRow - 10);
      const dates = logSheet.getRange(checkStart, 1, lastRow - checkStart + 1, 1).getValues();
      
      let deleteFrom = -1;
      for (let i = 0; i < dates.length; i++) {
        const rowDate = new Date(dates[i][0]);
        if (!isNaN(rowDate.getTime()) && rowDate < cutoffDate) {
           deleteFrom = checkStart + i;
           break;
        }
      }
      
      if (deleteFrom !== -1) {
         const rowsToDelete = lastRow - deleteFrom + 1;
         logSheet.deleteRows(deleteFrom, rowsToDelete);
      }
    }
  } catch (e) {
    console.log("AutoLog Cleanup Error: " + e.message);
  }
}



