// --- DATA CHUNKING HELPER FUNCTIONS ---

function chunkAndCache(key, data) {
  const cache = CacheService.getScriptCache();
  const jsonString = JSON.stringify(data);
  const maxChunkSize = 90000;
  const numChunks = Math.ceil(jsonString.length / maxChunkSize);

  const chunkKeys = [];
  for (let i = 0; i < numChunks; i++) {
    const chunkKey = `${key}_chunk_${i}_${Date.now()}`;
    chunkKeys.push(chunkKey);
  }

  const chunksToCache = {};
  chunkKeys.forEach((key, i) => {
    chunksToCache[key] = jsonString.substr(i * maxChunkSize, maxChunkSize);
  });
  cache.putAll(chunksToCache, 600);
  return chunkKeys;
}

function retrieveAndAssembleFromCache(chunkKeys) {
  const cache = CacheService.getScriptCache();
  const chunks = cache.getAll(chunkKeys);
  let jsonString = '';
  chunkKeys.forEach(key => {
    if (chunks[key]) {
      jsonString += chunks[key];
    } else {
      throw new Error(`Cache chunk missing: ${key}. The session may have expired.`);
    }
  });
  return JSON.parse(jsonString);
}

/**
 * Scans the EXTERNAL CLIENT 'Confirmed' sheet for overdue invoices.
 * UPDATED: Logs "Before -> After" values for clearer auditing.
 */
async function updateOverdueInvoicesInConfirmed(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");

  const runConfig = alertSheet.getRange("B47").getValue();
  if (String(runConfig).trim().toLowerCase() !== "yes") return { count: 0, logs: [] };

  const defaultDays = parseInt(alertSheet.getRange("B52").getValue()) || 30;

  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) return { count: 0, logs: ["Error: Overdue Invoices - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };

  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    return { count: 0, logs: ["Error: Overdue Invoices - " + e.message], hasError: true, error: e.message };
  }

  const sheet = clientSs.getSheetByName("Confirmed");
  if (!sheet) {
    return { count: 0, logs: ["Error: Overdue Invoices - 'Confirmed' sheet not found in Client Spreadsheet."], hasError: true, error: "'Confirmed' sheet not found in Client Spreadsheet." };
  }
  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim().toLowerCase());
  const validStatuses = ["", "sent", "draft", "part-paid (balance)"];
  const today = new Date();
  const currentMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  const targetDate = new Date(today.getFullYear(), today.getMonth(), 5);
  const updates = [];
  const logDetails = [];
  const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM HH:mm");

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    for (let slot = 1; slot <= 3; slot++) {
      const statusColIdx = headers.indexOf(`inv ${slot} status`);
      const sendDateColIdx = headers.indexOf(`inv ${slot} send date`);
      const daysColIdx = headers.indexOf(`inv ${slot} days to pay`);
      if (statusColIdx === -1 || daysColIdx === -1) continue;

      const statusVal = String(row[statusColIdx]).trim().toLowerCase();
      const sendDateVal = row[sendDateColIdx];
      const daysVal = row[daysColIdx];

      if (validStatuses.includes(statusVal)) {
        // --- 1. FIX MISSING DAYS (CONDITIONAL) ---
        let currentDaysToPay = parseInt(daysVal, 10);
        
        // Only fix days if there is actually a date in the Send Date cell
        const hasSendDate = (sendDateVal instanceof Date) || (sendDateVal && String(sendDateVal).trim() !== "");

        if (hasSendDate && (isNaN(currentDaysToPay) || currentDaysToPay === 0)) {
            const client = row[headers.indexOf('client')] || "Unknown";
            const job = row[headers.indexOf('job name')] || "Unknown";
            
            // Capture previous value for log
            const prevVal = (daysVal === "" || daysVal === null) ? "Blank" : daysVal;
            
            let daysToApply = defaultDays;
            if (statusVal === "part-paid (balance)") {
              const sendDate = (sendDateVal instanceof Date) ? sendDateVal : new Date(sendDateVal);
              if (!isNaN(sendDate.getTime())) {
                const targetDay5 = today.getDate() > 15
                  ? new Date(today.getFullYear(), today.getMonth() + 1, 5)
                  : new Date(today.getFullYear(), today.getMonth(), 5);
                daysToApply = Math.max(0, Math.ceil((targetDay5.getTime() - sendDate.getTime()) / (1000 * 60 * 60 * 24)));
              }
            }

            const auditMsg = `${timestamp}: 'Days to Pay' was ${prevVal} but Send Date exists. Auto-set to ${daysToApply}.`;
            
            updates.push({ row: i + 1, col: daysColIdx + 1, value: daysToApply, note: auditMsg });
            // UPDATED LOG FORMAT:
            logDetails.push(`[Confirmed] Fixed Days - Row ${i+1}, ${client} | ${job}, Slot ${slot}: ${prevVal} -> ${daysToApply}`);
            
            currentDaysToPay = daysToApply; 
        }

        // --- 2. CHECK OVERDUE ---
        if (hasSendDate && !isNaN(currentDaysToPay) && currentDaysToPay > 0) {
          const sendDate = (sendDateVal instanceof Date) ? sendDateVal : new Date(sendDateVal);
          
          if (!isNaN(sendDate.getTime())) {
            const expectedPaymentDate = new Date(sendDate);
            expectedPaymentDate.setDate(sendDate.getDate() + currentDaysToPay);

            if (expectedPaymentDate < currentMonthStart) {
              const diffTime = targetDate.getTime() - sendDate.getTime();
              const newDaysToPay = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
              
              if (newDaysToPay > 0 && newDaysToPay !== currentDaysToPay) {
                const client = row[headers.indexOf('client')] || "Unknown";
                const job = row[headers.indexOf('job name')] || "Unknown";
                const auditMsg = `${timestamp}: Auto-extended 'Days to Pay' from ${currentDaysToPay} to ${newDaysToPay} (Overdue). Client: ${client}, Job: ${job}`;
                
                updates.push({ row: i + 1, col: daysColIdx + 1, value: newDaysToPay, note: auditMsg });
                // UPDATED LOG FORMAT (Already good, but consistent):
                logDetails.push(`[Confirmed] Overdue Update - Row ${i+1}, ${client} | ${job}, Slot ${slot}: Extended days ${currentDaysToPay} -> ${newDaysToPay}`);
              }
            }
          }
        }
      }
    }
  }

  if (updates.length > 0) {
    if (updates.length <= 15) {
      const styledRanges = [];
      updates.forEach(u => {
        const cell = sheet.getRange(u.row, u.col);
        cell.setValue(u.value);
        if (u.note) {
          const old = cell.getNote();
          cell.setNote(old ? `${u.note}\n\n${old}` : u.note);
        }
        styledRanges.push(cell.getA1Notation());
      });
      if (styledRanges.length > 0) {
        sheet.getRangeList(styledRanges).setFontLine("underline").setNumberFormat("0");
      }
    } else {
      // FIXED: Batched 2D Array Writing for bulk Overdue updates (> 15)
      let minRow = Infinity, maxRow = 0, minCol = Infinity, maxCol = 0;
      updates.forEach(u => {
         if (u.row < minRow) minRow = u.row;
         if (u.row > maxRow) maxRow = u.row;
         if (u.col < minCol) minCol = u.col;
         if (u.col > maxCol) maxCol = u.col;
      });
      
      const numRows = maxRow - minRow + 1;
      const numCols = maxCol - minCol + 1;
      const range = sheet.getRange(minRow, minCol, numRows, numCols);
      
      const values = range.getValues();
      const notes = range.getNotes();
      const formulas = range.getFormulas();
      const rangesToFormat = [];

      // Protect all formulas inside the Overdue updates bounding box
      for (let r = 0; r < values.length; r++) {
        for (let c = 0; c < values[r].length; c++) {
          if (formulas[r][c]) {
            values[r][c] = formulas[r][c];
          }
        }
      }
      
      const colToLetter = (c) => {
          let temp, letter = '';
          while (c > 0) {
              temp = (c - 1) % 26;
              letter = String.fromCharCode(temp + 65) + letter;
              c = (c - temp - 1) / 26;
          }
          return letter;
      };

      updates.forEach(u => {
         const rIdx = u.row - minRow;
         const cIdx = u.col - minCol;
         values[rIdx][cIdx] = u.value;
         const oldNote = notes[rIdx][cIdx];
         notes[rIdx][cIdx] = oldNote ? `${u.note}\n\n${oldNote}` : u.note;
         rangesToFormat.push(`${colToLetter(u.col)}${u.row}`);
      });
      
      range.setValues(values);
      range.setNotes(notes);
      if (rangesToFormat.length > 0) {
         // FIXED: Force the cell format back to a standard Number ("0") to cure the "1900" date bug
         sheet.getRangeList(rangesToFormat).setFontLine("underline").setNumberFormat("0");
      }
    }
  }

  return { count: updates.length, logs: logDetails };
}

/**
 * Scans 'Confirmed' sheet for stale unsent invoices.
 * UPDATED: Uses BATCH WRITES to prevent timeouts.
 * UPDATED: Logs "Old -> New" date for audit trail.
 */
async function updateStaleUnsentInvoices(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");

  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) return { count: 0, logs: ["Error: Stale Invoices - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  
  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    return { count: 0, logs: ["Error: Stale Invoices - " + e.message], hasError: true, error: e.message };
  }

  const sheet = clientSs.getSheetByName("Confirmed");
  if (!sheet) {
    return { count: 0, logs: ["Error: Stale Invoices - 'Confirmed' sheet not found in Client Spreadsheet."], hasError: true, error: "'Confirmed' sheet not found in Client Spreadsheet." };
  }
  const data = sheet.getDataRange().getValues(); // Read all data once
  const headers = data[0].map(h => String(h).trim().toLowerCase().replace(/\s+/g, ' '));
  
  const today = new Date(); today.setHours(0,0,0,0);
  const currentMonthIdx = today.getMonth();
  const logDetails = [];
  const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM HH:mm");
  
  let updatesCount = 0;
  
  // Track updates: map column index to a map of {row: value}
  const columnUpdates = new Map(); 
  const noteUpdates = []; // Notes still need individual writes (API limitation), but they are faster than values

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    for (let slot = 1; slot <= 3; slot++) {
      const statusColIdx = headers.indexOf(`inv ${slot} status`);
      const sendDateColIdx = headers.indexOf(`inv ${slot} send date`);
      const daysColIdx = headers.indexOf(`inv ${slot} days to pay`); // Used for calc, not update here

      if (statusColIdx === -1 || sendDateColIdx === -1) continue;

      const statusVal = String(row[statusColIdx]).trim();
      const sendDateVal = row[sendDateColIdx];

      if (statusVal === "" && sendDateVal instanceof Date && !isNaN(sendDateVal.getTime())) {
           const sendDate = new Date(sendDateVal);
           sendDate.setHours(0,0,0,0);
           
           if (sendDate < today) {
             const daysVal = safeParseDays_(row[daysColIdx], `Stale Inv Row ${i+1}, Slot ${slot}`) || 0;
             const payDate = new Date(sendDate);
             payDate.setDate(sendDate.getDate() + daysVal);

             // Logic: If projected payment is THIS month (meaning we missed the boat), push it.
             if (payDate.getMonth() === currentMonthIdx && payDate.getFullYear() === today.getFullYear()) {
                
                let newTargetDate = new Date(today.getFullYear(), currentMonthIdx, 28);
                
                // Exception: If pushing to 28th STILL lands payment in this month (e.g. 0 days terms), move to next month
                const newProjPay = new Date(newTargetDate); 
                newProjPay.setDate(newTargetDate.getDate() + daysVal);
                
                if (newProjPay.getMonth() === currentMonthIdx) {
                    newTargetDate = new Date(today.getFullYear(), currentMonthIdx + 1, 1);
                }

                // --- NEW LOGGING LOGIC ---
                const oldDateStr = Utilities.formatDate(sendDate, ss.getSpreadsheetTimeZone(), "dd-MMM-yy");
                const newDateStr = Utilities.formatDate(newTargetDate, ss.getSpreadsheetTimeZone(), "dd-MMM-yy");
                
                // --- STAGE UPDATES (IN MEMORY) ---
                if (!columnUpdates.has(sendDateColIdx)) columnUpdates.set(sendDateColIdx, []);
                columnUpdates.get(sendDateColIdx).push({ row: i + 1, val: newTargetDate });

                const clientColIdx = headers.indexOf('client');
                const jobColIdx = headers.indexOf('job name');
                const retColIdx = headers.indexOf('retainer?');
                const amtColIdx = headers.indexOf(`inv ${slot} amt`);
                let client = (clientColIdx !== -1 ? row[clientColIdx] : "") || "";
                let job = (jobColIdx !== -1 ? row[jobColIdx] : "") || "";
                let rawRet = retColIdx !== -1 ? String(row[retColIdx] || "").trim().toLowerCase() : "";
                if ((!client || !job || !rawRet) && i > 1) {
                  for (let p = i - 1; p >= 1; p--) {
                    const pClient = clientColIdx !== -1 ? String(data[p][clientColIdx] || "").trim() : "";
                    const pJob = jobColIdx !== -1 ? String(data[p][jobColIdx] || "").trim() : "";
                    if (pClient || pJob) {
                      if (!client) client = pClient;
                      if (!job) job = pJob;
                      if (!rawRet && retColIdx !== -1) rawRet = String(data[p][retColIdx] || "").trim().toLowerCase();
                      break;
                    }
                  }
                }
                client = client || "Unknown";
                job = job || "Unknown";
                const jobType = (rawRet === "yes" || rawRet === "true" || (jobColIdx !== -1 && !String(row[jobColIdx] || "").trim())) ? "Retainer" : "Project";
                const rawAmt = amtColIdx !== -1 ? parseFloat(String(row[amtColIdx] || "").replace(/[£$,\s]/g, "")) : NaN;
                const amtPrefix = (!isNaN(rawAmt) && rawAmt > 0) ? `£${rawAmt.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}, ` : "";
                const noteMsg = `${timestamp}: Send date of stale unsent invoice changed from ${oldDateStr} to ${newDateStr}. Client: ${client}, Job: ${job}`;
                
                noteUpdates.push({ row: i + 1, col: sendDateColIdx + 1, msg: noteMsg });
                
                // UPDATED LOG MESSAGE
                logDetails.push(`[Confirmed] Stale Invoice - Row ${i+1}, ${client} | ${job} (${jobType}), Slot ${slot}: ${amtPrefix}Date moved ${oldDateStr} -> ${newDateStr}`);
                updatesCount++;
             }
           }
        }
    }
  }

  // --- BATCH EXECUTE UPDATES ---
  // 1. Write Column Values (Very Fast)
  columnUpdates.forEach((updates, colIndex) => {
      // Fetch the full column range to minimize I/O calls
      // (Optimization: We only write back the specific rows if they are contiguous, 
      // but for simplicity and safety against timeouts, we write individual cells or small blocks?
      // Actually, reading the whole col, modifying, and writing back is fastest.)
      
      const numRows = sheet.getLastRow();
      const colRange = sheet.getRange(1, colIndex + 1, numRows, 1);
      const colValues = colRange.getValues();
      
      updates.forEach(u => {
          // u.row is 1-based, array is 0-based
          colValues[u.row - 1][0] = u.val;
      });
      
      colRange.setValues(colValues);
  });

  // 2. Write Notes (Selective cell write for small updates <= 15 to avoid massive full-sheet note scans)
  if (noteUpdates.length > 0) {
      if (noteUpdates.length <= 15) {
          noteUpdates.forEach(n => {
              const cell = sheet.getRange(n.row, n.col);
              const oldNote = cell.getNote();
              cell.setNote(oldNote ? `${n.msg}\n\n${oldNote}` : n.msg);
          });
      } else {
          const notes = sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).getNotes();
          noteUpdates.forEach(n => {
              const oldNote = notes[n.row - 1][n.col - 1];
              notes[n.row - 1][n.col - 1] = oldNote ? `${n.msg}\n\n${oldNote}` : n.msg;
          });
          sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).setNotes(notes);
      }
  }

  return { count: updatesCount, logs: logDetails };
}

/**
 * NEW HELPER: Identifies parent/child job blocks and stages client name updates for all.
 */
function _stageClientNameUpdateForBlock(confirmedData, confirmedHeaderMap, startRowNumber, oldClient, newClient, jobName, changeLog, textChanges) {
  const clientCol = confirmedHeaderMap['Client'];
  const jobCol = confirmedHeaderMap['Job name'];
  
  if (clientCol === undefined || jobCol === undefined) return;

  const rowsInBlock = [startRowNumber];
  const startIdx = startRowNumber - 1; // 0-based index
  
  // FIXED: "Fuzzy" Matcher - strips spaces, lowercases, and treats "&" and "and" as identical
  const fuzzy = (str) => String(str || '').toLowerCase().replace(/&/g, 'and').replace(/\s+/g, '');
  
  const normalizedOldClient = fuzzy(oldClient);
  const normalizedJob = fuzzy(jobName);

  // 1. Look-Behind Scan (Find Parent and preceding children)
  for (let i = startIdx - 1; i >= 0; i--) {
    const rowClient = fuzzy(confirmedData[i][clientCol]);
    const rowJob = fuzzy(confirmedData[i][jobCol]);
    
    if (rowClient !== normalizedOldClient || rowJob !== normalizedJob) break;
    rowsInBlock.push(i + 1);
  }

  // 2. Look-Ahead Scan (Find subsequent children)
  for (let i = startIdx + 1; i < confirmedData.length; i++) {
    const rowClient = fuzzy(confirmedData[i][clientCol]);
    const rowJob = fuzzy(confirmedData[i][jobCol]);
    
    if (rowClient !== normalizedOldClient || rowJob !== normalizedJob) break;
    rowsInBlock.push(i + 1);
  }

  // 3. Stage changes for every row in the block
  rowsInBlock.forEach(rowNum => {
    changeLog.push({ row: rowNum, col: clientCol + 1, value: newClient });
    
    // FIXED: Update the in-memory array so subsequent searches match!
    confirmedData[rowNum - 1][clientCol] = newClient;
    
    // Only log the text change for the primary row to avoid log spam
    if (rowNum === startRowNumber && textChanges) {
      textChanges.push(`Client (Block Update): '${oldClient}' -> '${newClient}'`);
    }
  });
}


