/**
 * Master function to compare Revenue from the Dashboard against the Accounting App.
 */
async function runRevenueComparison(isHeadless = false, customTargetMonth = null) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  
  // 1. Setup Tabs
  const revCompSheet = ss.getSheetByName("RevComp") || ss.insertSheet("RevComp");
  const revFromAppSheet = ss.getSheetByName("RevFromApp") || ss.insertSheet("RevFromApp");
  
  // 2. Determine Target Month
  let targetDate = null;
  if (customTargetMonth) {
    if (customTargetMonth instanceof Date) {
      targetDate = new Date(customTargetMonth.getFullYear(), customTargetMonth.getMonth(), 1);
    } else if (typeof customTargetMonth === 'string') {
      const parts = customTargetMonth.trim().split(/[-/]/);
      if (parts.length >= 2) {
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10) - 1;
        if (!isNaN(y) && !isNaN(m)) {
          targetDate = new Date(y, m, 1);
        }
      }
    }
    if (targetDate && !isNaN(targetDate.getTime())) {
      revCompSheet.getRange("C2").setValue(targetDate);
    }
  }

  if (!targetDate) {
    const overrideDate = revCompSheet.getRange("C2").getValue();
    const defaultDate = revCompSheet.getRange("C1").getValue();
    targetDate = (overrideDate instanceof Date) ? overrideDate : (defaultDate instanceof Date ? defaultDate : null);
  }
  
  if (!targetDate) {
    const msg = "Please enter a valid date in C1 or C2 of RevComp.";
    console.log(msg);
    if (isHeadless) throw new Error(msg);
    return;
  }
  
  // Force to the 1st of the month for clean comparison
  targetDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
  const endOfMonth = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);
  
  console.log(`Starting Revenue Comparison for ${Utilities.formatDate(targetDate, ss.getSpreadsheetTimeZone(), "MMMM yyyy")}...`);

  // 3. Fetch Dashboard Data
  const dashboardData = (await getDashboardRevenueData_(ss, targetDate));
  
  // 4. Fetch Accounting App Data
  const appData = (await fetchAppRevenueForMonth_(targetDate, endOfMonth, isHeadless));
  
  // 5. Write App Data to 'RevFromApp' using a dedicated writer
  writeRevenueData_(ss, "RevFromApp", appData); 
  
  // 6. Present Comparison in 'RevComp'
  const summary = presentRevenueComparison_(revCompSheet, targetDate, dashboardData, appData);
  
  console.log("Revenue Comparison Complete. Please check the RevComp tab.");
  return {
    success: true,
    targetMonth: Utilities.formatDate(targetDate, ss.getSpreadsheetTimeZone(), "yyyy-MM"),
    targetMonthLabel: Utilities.formatDate(targetDate, ss.getSpreadsheetTimeZone(), "MMMM yyyy"),
    dashboardTotal: summary ? summary.dashTotal : 0,
    accountingTotal: summary ? summary.appTotal : 0,
    variance: summary ? summary.variance : 0
  };
}

/**
 * Replicates the Google Sheets LET formula to extract the block of data from the Client Sheet's 'Monthly' tab.
 */
async function getDashboardRevenueData_(ss, targetDate) {
  let monthlySheet = null;
  try {
    const clientSheetId = typeof getKeyInfoValue === "function" ? (await getKeyInfoValue("X28")) : null;
    if (clientSheetId) {
      monthlySheet = (await (await SpreadsheetApp.openById(clientSheetId)).getSheetByName("Monthly"));
    } else {
      const keyInfo = ss.getSheetByName("KeyInfo");
      const clientUrl = keyInfo ? String(keyInfo.getRange("C1").getValue() || "").trim() : "";
      if (clientUrl) {
        monthlySheet = (await (await SpreadsheetApp.openByUrl(clientUrl)).getSheetByName("Monthly"));
      }
    }
  } catch (e) {
    console.warn("Could not open Client Sheet Monthly tab directly, falling back to local tab:", e.message);
  }
  if (!monthlySheet) {
    monthlySheet = ss.getSheetByName("Monthly") || ss.getSheetByName("MthlyClient");
  }
  if (!monthlySheet) throw new Error("Sheet 'Monthly' not found on Client Sheet.");
  
  const lastRow = Math.min(monthlySheet.getLastRow() || 2500, 3000);
  const data = monthlySheet.getRange(1, 1, lastRow, 8).getValues();
  const targetYear = targetDate.getFullYear();
  const targetMonth = targetDate.getMonth();
  
  const isMatchDate = (cellVal) => {
    if (cellVal instanceof Date && !isNaN(cellVal.getTime())) {
      return cellVal.getFullYear() === targetYear && cellVal.getMonth() === targetMonth;
    }
    if (typeof cellVal === 'number' && cellVal > 30000 && cellVal < 60000) {
      // Excel/Google Sheets serial date: 25569 days between 1899-12-30 and 1970-01-01
      const d = new Date(Math.round((cellVal - 25569) * 86400 * 1000));
      return d.getUTCFullYear() === targetYear && d.getUTCMonth() === targetMonth;
    }
    return false;
  };

  const isAnyDate = (cellVal) => {
    if (cellVal instanceof Date && !isNaN(cellVal.getTime())) return true;
    if (typeof cellVal === 'number' && cellVal > 30000 && cellVal < 60000) return true;
    return false;
  };
  
  let startRowMatch = -1;
  let nextDateRow = data.length;
  
  for (let i = 0; i < data.length; i++) {
    const cellVal = data[i][0];
    if (isMatchDate(cellVal)) {
      startRowMatch = i;
      break;
    }
  }
  
  if (startRowMatch === -1) throw new Error(`Target date (${targetYear}-${String(targetMonth + 1).padStart(2, "0")}) not found in Monthly Tab.`);
  
  for (let i = startRowMatch + 1; i < data.length; i++) {
    const cellVal = data[i][0];
    if (isAnyDate(cellVal)) {
      nextDateRow = i;
      break;
    }
  }
  
  const dataStart = startRowMatch + 4;
  const dataEnd = nextDateRow - 3;
  
  if (dataStart > dataEnd) return []; 
  
  const extractedBlock = [];
  for (let i = dataStart; i <= dataEnd; i++) {
    const rowSlice = data[i].slice(2, 8);
    if (rowSlice.some(cell => String(cell).trim() !== "")) {
      extractedBlock.push(rowSlice);
    }
  }
  
  return extractedBlock;
}

/**
 * Routes to the correct accounting tool to fetch revenue for the targeted month.
 */
async function fetchAppRevenueForMonth_(startDate, endDate, isHeadless) {
  const rawToolName = (await getKeyInfoValue('Q4'));
  const toolName = String(rawToolName).trim().toLowerCase();
  
  if (toolName === 'xero') {
    return (await fetchXeroRevenueByDate_(startDate, endDate));
  } else if (toolName.includes('quickbook')) {
    return (await fetchQBRevenueByDate_(startDate, endDate));
  } else {
    throw new Error(`Accounting Tool (Q4) is set to "${rawToolName}". Unsupported for revenue sync.`);
  }
}

/**
 * Robust date parser supporting ISO strings, Date objects, and Xero's MS JSON date format.
 */
function parseXeroDate_(dateVal) {
  if (!dateVal) return null;
  if (dateVal instanceof Date && !isNaN(dateVal.getTime())) return dateVal;
  const str = String(dateVal).trim();
  const msMatch = str.match(/\/Date\((\d+)([+-]\d+)?\)\//);
  if (msMatch) {
    const ms = parseInt(msMatch[1], 10);
    if (!isNaN(ms)) return new Date(ms);
  }
  const d = new Date(str);
  if (!isNaN(d.getTime())) return d;
  return null;
}

/**
 * Xero Fetcher utilizing server-side date filtering and pagination.
 */
async function fetchXeroRevenueByDate_(startDate, endDate) {
  const accessToken = (await getXeroAccessToken());
  const xeroTenantId = (await getKeyInfoValue('X2'));

  let allInvoices = [];
  let page = 1;
  let keepFetching = true;

  // Format dates for Xero's DateTime(YYYY, MM, DD) syntax
  const startY = startDate.getFullYear();
  const startM = startDate.getMonth() + 1;
  const startD = startDate.getDate();
  const endY = endDate.getFullYear();
  const endM = endDate.getMonth() + 1;
  const endD = endDate.getDate();

  // Server-side date filtering directly in Xero's where query parameter (include draft and submitted for reference)
  const whereClause = `Type=="ACCREC" AND Status!="DELETED" AND Status!="VOIDED" AND Date>=DateTime(${startY},${startM},${startD}) AND Date<=DateTime(${endY},${endM},${endD})`;
  const baseUrl = `https://api.xero.com/api.xro/2.0/Invoices?where=${encodeURIComponent(whereClause)}&statuses=AUTHORISED,PAID,DRAFT,SUBMITTED&order=Date%20DESC`;
  
  const options = {
    'method': 'get',
    'headers': { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': xeroTenantId, 'Accept': 'application/json' },
    'muteHttpExceptions': true
  };

  Logger.log(`Fetching Xero Invoices with server-side date filter: ${whereClause}`);

  while (keepFetching) {
    const response = (await UrlFetchApp.fetch(`${baseUrl}&page=${page}`, options));
    if (response.getResponseCode() !== 200) throw new Error(`Xero API Error on Page ${page}: ${response.getContentText()}`);

    const pageInvoices = JSON.parse(response.getContentText()).Invoices || [];
    if (pageInvoices.length > 0) {
      allInvoices = allInvoices.concat(pageInvoices);
      if (pageInvoices.length < 100) {
        keepFetching = false;
      } else {
        page++;
      }
    } else {
      keepFetching = false;
    }
    
    if (page > 20) keepFetching = false; // Failsafe
  }

  const mappedData = [];

  allInvoices.forEach(inv => {
    const invDate = parseXeroDate_(inv.DateString || inv.Date);
    const rawStatus = String(inv.Status || "").toUpperCase();
    const isApproved = (rawStatus === 'AUTHORISED' || rawStatus === 'PAID');
    const isDraft = (rawStatus === 'DRAFT' || rawStatus === 'SUBMITTED');

    // Strict memory filter for the target month AND valid revenue/draft status
    if (invDate && invDate >= startDate && invDate <= endDate && (isApproved || isDraft)) {
      const originalTotal = parseFloat(inv.Total) || 0;
      const credit = parseFloat(inv.AmountCredited) || 0;
      const effectiveTotal = originalTotal - credit;
      const ratio = (originalTotal > 0) ? (effectiveTotal / originalTotal) : 1;
      
      // Xero provides CurrencyRate (Foreign / Rate = Base). Default to 1 if missing.
      const fxRate = parseFloat(inv.CurrencyRate) || 1;
      const lineAmtType = (inv.LineAmountTypes || 'Exclusive').toUpperCase();

      const statusLabel = isDraft
        ? (rawStatus === 'SUBMITTED' ? 'Awaiting Approval' : 'Draft')
        : (rawStatus === 'PAID' ? 'Paid' : 'Authorised');

      if (inv.LineItems) {
        inv.LineItems.forEach((line, index) => {
          const lineId = `${inv.InvoiceID}-${index + 1}`;
          
          // Extract the Net Amount (exclusive of VAT)
          let rawLineAmt = parseFloat(line.LineAmount) || 0;
          if (lineAmtType === 'INCLUSIVE') {
            rawLineAmt = rawLineAmt - (parseFloat(line.TaxAmount) || 0);
          }
          
          // 1. Scale line values down by the credit ratio (Foreign Currency)
          const effectiveLineAmtForeign = rawLineAmt * ratio;
          
          // 2. Convert to Base Currency (GBP)
          const calculatedBaseAmt = effectiveLineAmtForeign / fxRate;

          // Draft invoices have 0 recognized revenue counted, but their draft amount is retained for display
          const effectiveLineAmtBase = isApproved ? calculatedBaseAmt : 0;
          const draftAmount = isDraft ? calculatedBaseAmt : 0;
          const invNumber = inv.InvoiceNumber || (isDraft ? "[Draft]" : "");

          mappedData.push([
            lineId,
            inv.Contact?.Name || "Unknown",
            invNumber,
            line.Description || (isDraft ? "Draft invoice" : "No Description"),
            effectiveLineAmtBase,
            inv.DateString || Utilities.formatDate(invDate, "UTC", "yyyy-MM-dd HH:mm:ss"),
            statusLabel,
            draftAmount
          ]);
        });
      }
    }
  });

  Logger.log(`Found ${mappedData.length} valid Xero line items (approved & drafts) for the target month.`);
  return mappedData;
}

/**
 * Generates the presentation layer in the RevComp tab.
 */
function presentRevenueComparison_(sheet, targetDate, dashboardData, appData) {
  const lastRow = Math.max(sheet.getLastRow(), 5);
  if (lastRow >= 5) sheet.getRange(5, 1, lastRow, 10).clearContent();
  sheet.clearConditionalFormatRules();
  
  const appTotal = appData.reduce((sum, row) => sum + (parseFloat(row[4]) || 0), 0); 
  const dashTotal = dashboardData.reduce((sum, row) => sum + (parseFloat(row[3]) || 0), 0); 
  const variance = Math.abs(dashTotal - appTotal);
  
  const summaryBlock = [
    ["Target Month", Utilities.formatDate(targetDate, sheet.getParent().getSpreadsheetTimeZone(), "MMMM yyyy")],
    ["Dashboard Revenue", dashTotal],
    ["Accounting App Revenue", appTotal],
    ["Variance", variance]
  ];
  sheet.getRange(5, 1, 4, 2).setValues(summaryBlock).setFontWeight("bold");
  sheet.getRange(8, 2).setFontColor(variance > 0.05 ? "red" : "green");

  const clientMap = new Map();

  const findFuzzyKey = (newClient) => {
    if (!newClient || newClient.trim() === "") return "Unknown Client";
    const clean = (str) => String(str).toLowerCase().replace(/[^a-z0-9]/g, '');
    const s1 = clean(newClient);
    
    for (const existingClient of clientMap.keys()) {
      const s2 = clean(existingClient);
      if (s1.includes(s2) || s2.includes(s1)) return existingClient;
      
      const stripSuffixes = (str) => str.replace(/(ltd|limited|inc|llc|corp|company)$/g, '');
      if (stripSuffixes(s1) === stripSuffixes(s2)) return existingClient;
    }
    return newClient.trim(); 
  };
  
  dashboardData.forEach(row => {
    const rawClient = row[0]; 
    const revenue = parseFloat(row[3]) || 0; 
    const matchedClient = findFuzzyKey(rawClient);
    
    if (!clientMap.has(matchedClient)) clientMap.set(matchedClient, { dashRev: 0, appRev: 0 });
    clientMap.get(matchedClient).dashRev += revenue;
  });

  appData.forEach(row => {
    const rawClient = row[1]; 
    const revenue = parseFloat(row[4]) || 0; 
    const matchedClient = findFuzzyKey(rawClient);
    
    if (!clientMap.has(matchedClient)) clientMap.set(matchedClient, { dashRev: 0, appRev: 0 });
    clientMap.get(matchedClient).appRev += revenue;
  });

  const comparisonOutput = [
    ["Client", "Dashboard Revenue", "App Revenue", "Difference"]
  ];
  
  clientMap.forEach((data, client) => {
    const diff = data.dashRev - data.appRev;
    comparisonOutput.push([client, data.dashRev, data.appRev, diff]);
  });

  const sortedOutput = [comparisonOutput[0]].concat(
    comparisonOutput.slice(1).sort((a, b) => Math.abs(b[3]) - Math.abs(a[3]))
  );

  if (sortedOutput.length > 1) {
    const outRange = sheet.getRange(10, 1, sortedOutput.length, 4);
    outRange.setValues(sanitizeSheetMatrix_(sortedOutput));
    sheet.getRange(10, 1, 1, 4).setFontWeight("bold").setBackground("#f3f3f3");
    
    const diffRules = SpreadsheetApp.newConditionalFormatRule()
      .whenNumberNotBetween(-0.05, 0.05)
      .setBackground("#fce8e6")
      .setFontColor("#c53929")
      .setRanges([sheet.getRange(11, 4, sortedOutput.length - 1, 1)])
      .build();
    
    sheet.setConditionalFormatRules([diffRules]);
  }
  return { dashTotal, appTotal, variance };
}

/**
 * Dedicated writer for the Revenue Comparison tool. 
 * Overwrites the data cleanly without triggering the complex Delta engine.
 */
function writeRevenueData_(ss, sheetName, data) {
  const sheet = ss.getSheetByName(sheetName);
  sheet.clear();
  
  const headers = ["Line ID", "Client Name", "Invoice Number", "Description", "Effective Revenue", "Date", "Status", "Draft Amount"];
  sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight("bold");
  
  if (data.length > 0) {
    // Force Line ID (Column A), Invoice Number (Column C), and Status (Column G) to plain text
    sheet.getRange(2, 1, data.length, 1).setNumberFormat("@");
    sheet.getRange(2, 3, data.length, 1).setNumberFormat("@");
    sheet.getRange(2, 7, data.length, 1).setNumberFormat("@");
    sheet.getRange(2, 1, data.length, data[0].length).setValues(sanitizeSheetMatrix_(data));
  }
}


/**
 * QuickBooks Fetcher utilizing pagination and credit memo mapping.
 */
async function fetchQBRevenueByDate_(startDate, endDate) {
  const accessToken = (await getQBAccessToken());
  const realmId = String((await getKeyInfoValue('X3')) || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
  const baseUrl = "https://quickbooks.api.intuit.com";
  
  const startStr = Utilities.formatDate(startDate, "UTC", "yyyy-MM-dd");
  const endStr = Utilities.formatDate(endDate, "UTC", "yyyy-MM-dd");
  
  const options = {
    'method': 'get',
    'headers': {
      'Authorization': 'Bearer ' + accessToken,
      'Accept': 'application/json'
    },
    'muteHttpExceptions': true
  };

  Logger.log(`Fetching QB Invoices. Target Window: ${startStr} to ${endStr}`);

  let allInvoices = [];
  let startPosition = 1;
  const pageSize = 500;
  
  while (true) {
    const query = encodeURIComponent(`SELECT * FROM Invoice WHERE TxnDate >= '${startStr}' AND TxnDate <= '${endStr}' STARTPOSITION ${startPosition} MAXRESULTS ${pageSize}`);
    const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
    
    const response = (await UrlFetchApp.fetch(url, options));
    if (response.getResponseCode() !== 200) throw new Error('QB API request failed: ' + response.getContentText());
    
    const jsonResponse = JSON.parse(response.getContentText());
    const invoicesOnPage = jsonResponse.QueryResponse.Invoice;
    
    if (invoicesOnPage && invoicesOnPage.length > 0) {
      allInvoices = allInvoices.concat(invoicesOnPage);
      startPosition += invoicesOnPage.length;
      if (invoicesOnPage.length < pageSize) break;
    } else {
      break;
    }
    (await Utilities.sleep(200));
  }

  const mappedData = [];

  allInvoices.forEach(inv => {
    // Credit Note Logic mapped from Part 3 core
    const originalTotal = parseFloat(inv.TotalAmt) || 0;
    let totalCredit = 0;
    
    if (inv.LinkedTxn && Array.isArray(inv.LinkedTxn)) {
      inv.LinkedTxn.forEach(txn => {
        if (txn.TxnType === 'CreditMemo') {
          totalCredit += parseFloat(txn.Amount) || 0;
        }
      });
    }

    const effectiveTotal = originalTotal - totalCredit;
    const ratio = (originalTotal > 0) ? (effectiveTotal / originalTotal) : 1;
    
    // QuickBooks provides ExchangeRate (Foreign * Rate = Base). Default to 1 if missing.
    const fxRate = parseFloat(inv.ExchangeRate) || 1;

    if (inv.Line && Array.isArray(inv.Line)) {
      const validLines = inv.Line.filter(l => l.DetailType === 'SalesItemLineDetail');
      
      validLines.forEach((line, index) => {
        const lineId = `${inv.Id}-${index + 1}`;
        
        // 1. Scale down by credit ratio (Foreign Currency)
        const originalLineAmtForeign = line.Amount || 0;
        const effectiveLineAmtForeign = originalLineAmtForeign * ratio;
        
        // 2. Convert to Base Currency (GBP)
        const effectiveLineAmtBase = effectiveLineAmtForeign * fxRate;
        
        mappedData.push([
          lineId,
          inv.CustomerRef?.name || 'Unknown',
          inv.DocNumber,
          line.Description || "No Description",
          effectiveLineAmtBase,
          inv.TxnDate,
          "Authorised",
          0
        ]);
      });
    }
  });

  Logger.log(`Found ${mappedData.length} valid QB line items for the target month.`);
  return mappedData;
}

/**
 * PART-PAID INVOICES AUTOMATION
 * ============================================================================
 * 
 * Scans InvFromApp and Confirmed to detect:
 * 1. Part-paid invoices (AmountPaid > 0.005 && AmountDue > 0.005):
 *    - Updates primary slot in Confirmed to "Part-paid (received)" with the paid ex-VAT amount.
 *    - Finds the next available slot on the same job (or creates a new child row by moving
 *      the 2nd blank row up from the bottom if all slots are full) and writes the remaining
 *      balance as "Part-paid (balance)" with the due date and 0 days to pay.
 *    - Handles automatic pro-rata allocation if the invoice is split across multiple jobs.
 * 2. Fully-paid invoices that previously had part-payment slots:
 *    - Clears the balance slot and restores the primary slot to full amount with status "Paid".
 */

function normalizeInvoiceRef_(ref, rule) {
  if (!ref && ref !== 0) return "";
  let s = String(ref).trim();
  if (!s) return "";
  s = s.replace(/[\s\u00A0]/g, '');

  if (rule === "Right4") {
    const match = s.match(/\d+/g);
    const digits = match ? match.join("") : s;
    return digits.length >= 4 ? digits.slice(-4) : digits;
  }
  if (rule === "Right5") {
    const match = s.match(/\d+/g);
    const digits = match ? match.join("") : s;
    return digits.length >= 5 ? digits.slice(-5) : digits;
  }
  if (rule === "Right3") {
    const match = s.match(/\d+/g);
    const digits = match ? match.join("") : s;
    return digits.length >= 3 ? digits.slice(-3) : digits;
  }
  if (rule === "StripPre") {
    return s.replace(/^[^-_\s]+[-_\s]/, "").toUpperCase();
  }
  return s.replace(/^[A-Za-z]+[-_\s]/, "").replace(/^INV[-_\s]?/i, "").toUpperCase();
}

function stripInvoiceRefPrefix_(ref) {
  return normalizeInvoiceRef_(ref, "StripPre");
}

function parsePaymentDate_(raw) {
  if (!raw) return null;
  if (raw instanceof Date) return isNaN(raw.getTime()) ? null : raw;
  if (typeof raw === "number" && raw > 20000 && raw < 100000) {
    return new Date(new Date(1899, 11, 30).getTime() + Math.round(raw * 86400000));
  }
  const str = String(raw).trim();
  if (!str) return null;
  const match = str.match(/\/Date\((\d+)/);
  if (match) {
    const ms = parseInt(match[1], 10);
    return new Date(ms);
  }
  if (/^\d{5}(\.\d+)?$/.test(str)) {
    const serial = parseFloat(str);
    if (serial > 20000 && serial < 100000) {
      return new Date(new Date(1899, 11, 30).getTime() + Math.round(serial * 86400000));
    }
  }
  const d = new Date(str);
  return isNaN(d.getTime()) ? null : d;
}

function formatConfirmedDate_(dateVal, timeZone) {
  if (!dateVal) return "";
  const d = (dateVal instanceof Date) ? dateVal : new Date(dateVal);
  if (isNaN(d.getTime())) return "";
  return Utilities.formatDate(d, timeZone, "d-MMM-yy");
}

/**
 * Finds the second blank row after all job data in Confirmed and moves it
 * directly below lastJobRow using moveRows (no row insertions into the data block).
 * Reuses the canonical 4-zone scan from auditInvoiceGaps / findAndMoveBlankRow.
 */
function findAndMoveBlankRowForJob_(sheet, lastJobRow, parentClient, parentJob, parentVat, colClient, colJobName, colVat) {
  const data = sheet.getDataRange().getValues();
  let trueLastRow = 0;
  for (let r = data.length - 1; r >= 0; r--) {
    const row = data[r];
    const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
    const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
    const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
    const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
    if (z1 || z2 || z3 || z4) {
      trueLastRow = r + 1;
      break;
    }
  }

  const currentMax = sheet.getMaxRows();
  const availableEmpty = currentMax - (trueLastRow + 1);
  if (availableEmpty < 2) {
    sheet.insertRowsAfter(currentMax, 5);
  }

  const sourceStartRow = trueLastRow + 2;
  const targetRow = lastJobRow + 1;
  const sourceRange = sheet.getRange(sourceStartRow, 1, 1, sheet.getLastColumn());
  sheet.moveRows(sourceRange, targetRow);
  try {
    const grp = sheet.getRowGroupDepth(targetRow) > 0 ? sheet.getRowGroup(targetRow, 1) : null;
    if (!grp || !grp.isCollapsed()) {
      sheet.unhideRow(sheet.getRange(targetRow, 1, 1, 1));
    }
  } catch (e) {}

  if (colClient !== -1 && parentClient) sheet.getRange(targetRow, colClient + 1).setValue(sanitizeSheetCell_(parentClient));
  if (colJobName !== -1 && parentJob) sheet.getRange(targetRow, colJobName + 1).setValue(sanitizeSheetCell_(parentJob));
  if (colVat !== -1 && parentVat) sheet.getRange(targetRow, colVat + 1).setValue(sanitizeSheetCell_(parentVat));

  return targetRow;
}

async function processPartPaidInvoices(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");

  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  }

  const invSheet = ss.getSheetByName("InvFromApp");
  if (!invSheet) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - 'InvFromApp' sheet not found."], hasError: true, error: "'InvFromApp' sheet not found." };
  }

  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - " + e.message], hasError: true, error: e.message };
  }

  const sheet = clientSs.getSheetByName("Confirmed");
  if (!sheet) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - 'Confirmed' sheet not found in Client Spreadsheet."], hasError: true, error: "'Confirmed' sheet not found in Client Spreadsheet." };
  }

  // Tenant invoice formatting rule from InvAppList!F1 (e.g. Right4, StripPre, Right5, Right3, Full)
  let invFormatRule = "StripPre";
  const invAppListSheet = ss.getSheetByName("InvAppList");
  if (invAppListSheet) {
    const ruleVal = String(invAppListSheet.getRange("F1").getValue() || "").trim();
    if (ruleVal) invFormatRule = ruleVal;
  }

  const invData = invSheet.getDataRange().getValues();
  if (invData.length <= 1) return { count: 0, logs: [] };

  const invHeaders = invData[0].map(h => String(h || "").trim().toLowerCase().replace(/[\s_]+/g, ""));
  const idxInvNum = invHeaders.findIndex(h => h.includes("invoicenumber") || h === "invoiceno");
  const idxDue = invHeaders.findIndex(h => h.includes("amountdue"));
  const idxPaid = invHeaders.findIndex(h => h.includes("amountpaid"));
  const idxTotal = invHeaders.findIndex(h => h === "total");
  const idxSubTotal = invHeaders.findIndex(h => h.includes("subtotal"));
  const idxDueDate = invHeaders.findIndex(h => h.includes("duedate"));
  const idxSentDate = invHeaders.findIndex(h => h === "date" || h.includes("sentdate"));
  const idxStatus = invHeaders.findIndex(h => h === "status");
  const idxPaidDate = invHeaders.findIndex(h => h.includes("fullypaid"));

  if (idxInvNum === -1 || idxDue === -1 || idxPaid === -1 || idxSubTotal === -1) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - Required headers missing in InvFromApp."], hasError: true, error: "Required headers missing in InvFromApp." };
  }

  const partPaidInvs = new Map();
  const fullyPaidInvs = new Map();

  for (let r = 1; r < invData.length; r++) {
    const row = invData[r];
    const rawInvNum = row[idxInvNum];
    if (!rawInvNum) continue;
    const refKey = normalizeInvoiceRef_(rawInvNum, invFormatRule);
    if (!refKey) continue;

    const rawDue = parseFloat(String(row[idxDue]).replace(/,/g, "")) || 0;
    const rawPaid = parseFloat(String(row[idxPaid]).replace(/,/g, "")) || 0;
    const grossTotal = parseFloat(String(row[idxTotal]).replace(/,/g, "")) || (rawDue + rawPaid);
    const subTotal = parseFloat(String(row[idxSubTotal]).replace(/,/g, "")) || 0;
    const status = String(row[idxStatus] || "").trim().toUpperCase();
    const dueDate = row[idxDueDate];
    const sentDate = row[idxSentDate];
    const paidDate = idxPaidDate !== -1 ? row[idxPaidDate] : null;

    const ratio = grossTotal > 0 ? (subTotal / grossTotal) : 1;
    const paidExVat = Math.round(rawPaid * ratio * 100) / 100;
    const dueExVat = Math.round((subTotal - paidExVat) * 100) / 100;

    if (rawPaid > 0.005 && rawDue > 0.005) {
      partPaidInvs.set(refKey, {
        ref: String(rawInvNum).trim(),
        refKey: refKey,
        rawDue,
        rawPaid,
        grossTotal,
        subTotal,
        paidExVat,
        dueExVat,
        dueDate,
        sentDate,
        paidDate,
        status
      });
    } else if (rawDue <= 0.005 && rawPaid > 0.005) {
      fullyPaidInvs.set(refKey, {
        ref: String(rawInvNum).trim(),
        refKey: refKey,
        subTotal,
        sentDate,
        paidDate
      });
    }
  }

  if (partPaidInvs.size === 0 && fullyPaidInvs.size === 0) {
    return { count: 0, logs: [] };
  }

  // Read Confirmed data
  const confirmedData = sheet.getDataRange().getValues();
  if (confirmedData.length <= 1) return { count: 0, logs: [] };

  const cHeaders = confirmedData[0].map(h => String(h || "").trim().toLowerCase().replace(/\s+/g, " "));
  const colClient = cHeaders.indexOf("client");
  const colJobName = cHeaders.indexOf("job name");
  const colVat = cHeaders.indexOf("vat?");
  const colType = cHeaders.indexOf("project / retainer") !== -1 ? cHeaders.indexOf("project / retainer") : cHeaders.indexOf("type");

  const slotCols = {};
  for (let s = 1; s <= 3; s++) {
    const amtHeader = s === 1 ? "project invoice 1 / monthly retainer (excl vat)" : `project invoice ${s} (excl vat)`;
    slotCols[s] = {
      amt: cHeaders.indexOf(amtHeader),
      ref: cHeaders.indexOf(`inv ${s} ref`),
      sendDate: cHeaders.indexOf(`inv ${s} send date`),
      days: cHeaders.indexOf(`inv ${s} days to pay`),
      status: cHeaders.indexOf(`inv ${s} status`)
    };
  }

  if (colClient === -1 || colJobName === -1 || slotCols[1].ref === -1 || slotCols[1].status === -1) {
    return { count: 0, logs: ["Error: Part-Paid Invoices - Required headers missing in Confirmed sheet."], hasError: true, error: "Required headers missing in Confirmed sheet." };
  }

  const timeZone = ss.getSpreadsheetTimeZone();
  const changeLog = [];
  const logDetails = [];
  let updateCount = 0;

  // Track job groups: array of { client, jobName, vat, parentRow, childRows: [], allRows: [] }
  const jobGroups = [];
  let currentGroup = null;

  for (let r = 1; r < confirmedData.length; r++) {
    const row = confirmedData[r];
    const client = String(row[colClient] || "").trim();
    const jobName = String(row[colJobName] || "").trim();

    if (!client && !jobName) continue;

    if (currentGroup && currentGroup.client.toLowerCase() === client.toLowerCase() && currentGroup.jobName.toLowerCase() === jobName.toLowerCase()) {
      currentGroup.childRows.push(r + 1);
      currentGroup.allRows.push(r + 1);
    } else {
      const typeVal = colType !== -1 ? String(row[colType] || "").trim().toLowerCase() : "";
      const isRetainer = typeVal === "retainer";
      currentGroup = {
        client: client,
        jobName: jobName,
        vat: colVat !== -1 ? String(row[colVat] || "").trim() : "",
        isRetainer: isRetainer,
        parentRow: r + 1,
        childRows: [],
        allRows: [r + 1]
      };
      jobGroups.push(currentGroup);
    }
  }

  // Map all existing invoice occurrences by refKey
  const invLocations = new Map();
  for (let r = 1; r < confirmedData.length; r++) {
    const row = confirmedData[r];
    const rowNum = r + 1;
    const client = String(row[colClient] || "").trim();
    const jobName = String(row[colJobName] || "").trim();
    if (!client && !jobName) continue;

    const group = jobGroups.find(g => g.allRows.includes(rowNum));

    for (let s = 1; s <= 3; s++) {
      const refVal = row[slotCols[s].ref];
      if (!refVal) continue;
      const key = normalizeInvoiceRef_(refVal, invFormatRule);
      if (!key) continue;

      const locEntry = {
        rowNumber: rowNum,
        rowIndex: r,
        slot: s,
        ref: String(refVal).trim(),
        amt: parseFloat(String(row[slotCols[s].amt] || "").replace(/[^0-9.-]/g, "")) || 0,
        status: String(row[slotCols[s].status] || "").trim(),
        sendDate: row[slotCols[s].sendDate],
        days: row[slotCols[s].days],
        client: client,
        jobName: jobName,
        jobGroup: group
      };

      if (!invLocations.has(key)) invLocations.set(key, []);
      invLocations.get(key).push(locEntry);

      // Multi-key indexing for robust matching across raw and stripped formats
      const rawClean = String(refVal).trim().toUpperCase().replace(/[\s\u00A0]/g, '');
      if (rawClean && rawClean !== key) {
        if (!invLocations.has(rawClean)) invLocations.set(rawClean, []);
        invLocations.get(rawClean).push(locEntry);
      }
      const strippedPrefix = rawClean.replace(/^[A-Za-z]+[-_\s]/, '').replace(/^INV[-_\s]?/i, '');
      if (strippedPrefix && strippedPrefix !== key && strippedPrefix !== rawClean) {
        if (!invLocations.has(strippedPrefix)) invLocations.set(strippedPrefix, []);
        invLocations.get(strippedPrefix).push(locEntry);
      }
    }
  }

  // Helper to find or provision an empty slot for a part-paid invoice balance
  const findTargetBalanceSlot_ = (primaryLoc) => {
    const group = primaryLoc.jobGroup;
    const isRetainer = group && (group.isRetainer || (group.childRows.length > 0 && colType !== -1 && String(confirmedData[group.parentRow - 1][colType] || "").trim().toLowerCase() === "retainer"));

    // 1. For RETAINER jobs:
    // The balance MUST be placed on the SAME month child row as primaryLoc (primaryLoc.rowNumber).
    // The parent row (group.parentRow) must NEVER be used to store invoices or expenses.
    if (isRetainer) {
      const rNum = primaryLoc.rowNumber;
      const rIdx = rNum - 1;
      const row = confirmedData[rIdx] || [];

      // Check slot 2, then slot 3 on this row (primaryLoc is almost always slot 1)
      for (let s = 1; s <= 3; s++) {
        if (s === primaryLoc.slot) continue;
        const refVal = row[slotCols[s].ref];
        const amtVal = row[slotCols[s].amt];
        const statusVal = row[slotCols[s].status];
        const isEmpty = (!refVal || String(refVal).trim() === "") &&
                        (!amtVal || amtVal === 0 || String(amtVal).trim() === "") &&
                        (!statusVal || String(statusVal).trim() === "");
        if (isEmpty) {
          return { rowNumber: rNum, slot: s, isNewRow: false };
        }
      }

      // If all slots on this month row are full, provision a new child row via canonical logic
      const lastJobRow = Math.max(...group.allRows);
      const newRow = findAndMoveBlankRowForJob_(
        sheet,
        lastJobRow,
        group.client,
        group.jobName,
        group.vat,
        colClient,
        colJobName,
        colVat
      );

      group.childRows.push(newRow);
      group.allRows.push(newRow);

      for (const g of jobGroups) {
        if (g !== group) {
          g.parentRow = g.parentRow >= newRow ? g.parentRow + 1 : g.parentRow;
          g.childRows = g.childRows.map(r => r >= newRow ? r + 1 : r);
          g.allRows = g.allRows.map(r => r >= newRow ? r + 1 : r);
        }
      }

      while (confirmedData.length < newRow) {
        confirmedData.push(new Array(confirmedData[0].length).fill(""));
      }
      const newBlankRow = new Array(confirmedData[0].length).fill("");
      if (colClient !== -1) newBlankRow[colClient] = group.client;
      if (colJobName !== -1) newBlankRow[colJobName] = group.jobName;
      if (colVat !== -1) newBlankRow[colVat] = group.vat;
      confirmedData.splice(newRow - 1, 0, newBlankRow);

      return { rowNumber: newRow, slot: 1, isNewRow: true };
    }

    // 2. For PROJECT jobs:
    // First preference: try an empty slot on the SAME row as primaryLoc (slot 2, then 3)
    const primaryRowNum = primaryLoc.rowNumber;
    const primaryRow = confirmedData[primaryRowNum - 1] || [];
    for (let s = 1; s <= 3; s++) {
      if (s === primaryLoc.slot) continue;
      const refVal = primaryRow[slotCols[s].ref];
      const amtVal = primaryRow[slotCols[s].amt];
      const statusVal = primaryRow[slotCols[s].status];
      const isEmpty = (!refVal || String(refVal).trim() === "") &&
                      (!amtVal || amtVal === 0 || String(amtVal).trim() === "") &&
                      (!statusVal || String(statusVal).trim() === "");
      if (isEmpty) {
        return { rowNumber: primaryRowNum, slot: s, isNewRow: false };
      }
    }

    // Second preference: check other rows in the group, shielding parentRow if multi-row
    const candidateRows = group ? group.allRows.filter(rNum => {
      if (group.childRows.length > 0 && rNum === group.parentRow) return false;
      return rNum !== primaryRowNum;
    }) : [];

    for (let i = 0; i < candidateRows.length; i++) {
      const rNum = candidateRows[i];
      const rIdx = rNum - 1;
      const row = confirmedData[rIdx] || [];
      for (let s = 1; s <= 3; s++) {
        const refVal = row[slotCols[s].ref];
        const amtVal = row[slotCols[s].amt];
        const statusVal = row[slotCols[s].status];
        const isEmpty = (!refVal || String(refVal).trim() === "") &&
                        (!amtVal || amtVal === 0 || String(amtVal).trim() === "") &&
                        (!statusVal || String(statusVal).trim() === "");
        if (isEmpty) {
          return { rowNumber: rNum, slot: s, isNewRow: false };
        }
      }
    }

    // No empty slot on existing rows: move blank row up via canonical logic
    const lastJobRow = group ? Math.max(...group.allRows) : primaryRowNum;
    const newRow = findAndMoveBlankRowForJob_(
      sheet,
      lastJobRow,
      group ? group.client : primaryLoc.client,
      group ? group.jobName : primaryLoc.jobName,
      group ? group.vat : "",
      colClient,
      colJobName,
      colVat
    );

    if (group) {
      group.childRows.push(newRow);
      group.allRows.push(newRow);
      for (const g of jobGroups) {
        if (g !== group) {
          g.parentRow = g.parentRow >= newRow ? g.parentRow + 1 : g.parentRow;
          g.childRows = g.childRows.map(r => r >= newRow ? r + 1 : r);
          g.allRows = g.allRows.map(r => r >= newRow ? r + 1 : r);
        }
      }
    }

    while (confirmedData.length < newRow) {
      confirmedData.push(new Array(confirmedData[0].length).fill(""));
    }
    const newBlankRow = new Array(confirmedData[0].length).fill("");
    if (colClient !== -1) newBlankRow[colClient] = group ? group.client : primaryLoc.client;
    if (colJobName !== -1) newBlankRow[colJobName] = group ? group.jobName : primaryLoc.jobName;
    if (colVat !== -1) newBlankRow[colVat] = group ? group.vat : "";
    confirmedData.splice(newRow - 1, 0, newBlankRow);

    return { rowNumber: newRow, slot: 1, isNewRow: true };
  };

  const getLocationsForInvoice_ = (inv, refKey) => {
    let locs = invLocations.get(refKey);
    if (locs && locs.length > 0) return locs;
    const rawClean = String(inv.ref || "").trim().toUpperCase().replace(/[\s\u00A0]/g, '');
    locs = invLocations.get(rawClean);
    if (locs && locs.length > 0) return locs;
    const stripped = rawClean.replace(/^[A-Za-z]+[-_\s]/, '').replace(/^INV[-_\s]?/i, '');
    return invLocations.get(stripped) || [];
  };

  // ==========================================================================
  // PART 1: PROCESS PART-PAID INVOICES
  // ==========================================================================
  partPaidInvs.forEach((inv, refKey) => {
    const locations = getLocationsForInvoice_(inv, refKey);
    if (!locations || locations.length === 0) return;

    // Group locations by job group
    const jobSlotsMap = new Map();
    locations.forEach(loc => {
      const jobKey = `${loc.client.toLowerCase()} || ${loc.jobName.toLowerCase()}`;
      if (!jobSlotsMap.has(jobKey)) jobSlotsMap.set(jobKey, []);
      jobSlotsMap.get(jobKey).push(loc);
    });

    // Calculate total confirmed amount across all participating jobs for pro-rata weighting
    let totalConfirmedAmt = 0;
    jobSlotsMap.forEach(locs => {
      const primaryLoc = locs.find(l => l.status.toLowerCase().includes("received")) ||
                         locs.find(l => !l.status.toLowerCase().includes("balance")) ||
                         locs[0];
      const balanceLoc = locs.find(l => l.status.toLowerCase().includes("balance")) ||
                         locs.find(l => l !== primaryLoc);
      const jobTotal = primaryLoc.amt + (balanceLoc ? balanceLoc.amt : 0);
      totalConfirmedAmt += jobTotal;
    });

    if (totalConfirmedAmt <= 0) totalConfirmedAmt = inv.subTotal;

    // Process each job group's share
    const jobKeys = Array.from(jobSlotsMap.keys());
    let remainingPaidPool = inv.paidExVat;
    let remainingDuePool = inv.dueExVat;

    jobKeys.forEach((jobKey, kIdx) => {
      const locs = jobSlotsMap.get(jobKey);
      const isLastJob = (kIdx === jobKeys.length - 1);

      // Find primary (received) slot and candidate balance slot
      const primaryLoc = locs.find(l => l.status.toLowerCase().includes("received")) ||
                         locs.find(l => !l.status.toLowerCase().includes("balance")) ||
                         locs[0];
      const client = primaryLoc.client;
      const jobName = primaryLoc.jobName;
      const preferredRef = primaryLoc.ref || inv.ref;

      let balanceLoc = locs.find(l => l.status.toLowerCase().includes("balance"));

      // Self-heal: if no explicit balance slot found, but there is another slot on this job
      // with the same invoice number (which might have been overwritten to 'Sent'), reclaim it!
      if (!balanceLoc && locs.length > 1) {
        balanceLoc = locs.find(l => l !== primaryLoc);
      }

      // Self-heal duplicate balance slots: if multiple secondary/balance slots exist on this job,
      // retain the earliest slot and clean up the redundant ones
      if (locs.length > 2) {
        const otherSlots = locs.filter(l => l !== primaryLoc);
        otherSlots.sort((a, b) => (a.rowNumber - b.rowNumber) || (a.slot - b.slot));
        balanceLoc = otherSlots[0];
        const redundantSlots = otherSlots.slice(1);
        redundantSlots.forEach(extra => {
          changeLog.push({ row: extra.rowNumber, col: slotCols[extra.slot].amt + 1, value: "" });
          changeLog.push({ row: extra.rowNumber, col: slotCols[extra.slot].ref + 1, value: "" });
          changeLog.push({ row: extra.rowNumber, col: slotCols[extra.slot].sendDate + 1, value: "" });
          changeLog.push({ row: extra.rowNumber, col: slotCols[extra.slot].days + 1, value: "" });
          changeLog.push({ row: extra.rowNumber, col: slotCols[extra.slot].status + 1, value: "" });
          if (confirmedData[extra.rowIndex]) {
            confirmedData[extra.rowIndex][slotCols[extra.slot].amt] = "";
            confirmedData[extra.rowIndex][slotCols[extra.slot].ref] = "";
            confirmedData[extra.rowIndex][slotCols[extra.slot].sendDate] = "";
            confirmedData[extra.rowIndex][slotCols[extra.slot].days] = "";
            confirmedData[extra.rowIndex][slotCols[extra.slot].status] = "";
          }
          logDetails.push(`[Confirmed] Cleaned up duplicate balance slot for Invoice ${preferredRef} at Row ${extra.rowNumber} Slot ${extra.slot} on ${client} | ${jobName}`);
        });
      }

      // Shield Retainer Parent rows and enforce local month row for Retainers
      const group = primaryLoc.jobGroup;
      const isRetainerJob = group && (group.isRetainer || (group.childRows.length > 0 && colType !== -1 && String(confirmedData[group.parentRow - 1][colType] || "").trim().toLowerCase() === "retainer"));
      const isMisplacedOnParent = balanceLoc && group && (balanceLoc.rowNumber === group.parentRow) && isRetainerJob;
      const isMisplacedRetainer = balanceLoc && isRetainerJob && (balanceLoc.rowNumber !== primaryLoc.rowNumber);

      if (balanceLoc && (isMisplacedOnParent || isMisplacedRetainer)) {
        changeLog.push({ row: balanceLoc.rowNumber, col: slotCols[balanceLoc.slot].amt + 1, value: "" });
        changeLog.push({ row: balanceLoc.rowNumber, col: slotCols[balanceLoc.slot].ref + 1, value: "" });
        changeLog.push({ row: balanceLoc.rowNumber, col: slotCols[balanceLoc.slot].sendDate + 1, value: "" });
        changeLog.push({ row: balanceLoc.rowNumber, col: slotCols[balanceLoc.slot].days + 1, value: "" });
        changeLog.push({ row: balanceLoc.rowNumber, col: slotCols[balanceLoc.slot].status + 1, value: "" });
        if (confirmedData[balanceLoc.rowIndex]) {
          confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].amt] = "";
          confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].ref] = "";
          confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].sendDate] = "";
          confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].days] = "";
          confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].status] = "";
        }
        logDetails.push(`[Confirmed] Cleaned up misplaced balance slot on Row ${balanceLoc.rowNumber} Slot ${balanceLoc.slot} for Invoice ${preferredRef} (parent row / wrong retainer row shielded)`);
        balanceLoc = null; // Forces assignment into the correct local month row slot
      }

      const currentJobAmt = primaryLoc.amt + (balanceLoc ? balanceLoc.amt : 0);

      let jobPaidShare = 0;
      let jobDueShare = 0;

      if (isLastJob) {
        jobPaidShare = Math.round(remainingPaidPool * 100) / 100;
        jobDueShare = Math.round(remainingDuePool * 100) / 100;
      } else {
        const weight = totalConfirmedAmt > 0 ? (currentJobAmt / totalConfirmedAmt) : (1 / jobKeys.length);
        jobPaidShare = Math.round(inv.paidExVat * weight * 100) / 100;
        jobDueShare = Math.round(inv.dueExVat * weight * 100) / 100;
        remainingPaidPool -= jobPaidShare;
        remainingDuePool -= jobDueShare;
      }

      // Real invoice send date - ALWAYS preserve the date the invoice was actually sent
      const sendDateVal = inv.sentDate || primaryLoc.sendDate;
      const sendDateObj = sendDateVal ? ((sendDateVal instanceof Date) ? sendDateVal : new Date(sendDateVal)) : new Date();
      const formattedSendDate = formatConfirmedDate_(sendDateObj, timeZone);

      // Target payment date calculation:
      // If dueDate is in the future (> today), use dueDate.
      // If dueDate is in the past / overdue (or missing):
      //   - If today is after the 15th: push to the 5th of next month.
      //   - If today is on or before the 15th: push to the 5th of current month.
      const dueDateVal = inv.dueDate;
      const dueDateObj = dueDateVal ? ((dueDateVal instanceof Date) ? dueDateVal : new Date(dueDateVal)) : null;
      const today = new Date();

      let targetDate;
      if (dueDateObj && dueDateObj.getTime() > today.getTime()) {
        targetDate = dueDateObj;
      } else {
        if (today.getDate() > 15) {
          targetDate = new Date(today.getFullYear(), today.getMonth() + 1, 5);
        } else {
          targetDate = new Date(today.getFullYear(), today.getMonth(), 5);
        }
      }

      const calculatedDays = Math.max(0, Math.round((targetDate.getTime() - sendDateObj.getTime()) / (1000 * 60 * 60 * 24)));

      // 1. UPDATE OR VERIFY PRIMARY (RECEIVED) SLOT
      const needsPaidAmtUpdate = Math.abs(primaryLoc.amt - jobPaidShare) >= 0.01;
      const needsPaidStatusUpdate = primaryLoc.status !== "Part-paid (received)";

      // Calculate actual days to pay from send date to payment date
      const paymentDateObj = parsePaymentDate_(inv.paidDate);
      let actualDaysToPay = null;
      if (paymentDateObj && sendDateObj) {
        const diffDays = Math.round((paymentDateObj.getTime() - sendDateObj.getTime()) / (1000 * 60 * 60 * 24));
        if (!isNaN(diffDays)) {
          actualDaysToPay = diffDays;
        }
      }

      const currentPrimaryDays = parseInt(primaryLoc.days, 10);
      const needsPaidDaysUpdate = (actualDaysToPay !== null && currentPrimaryDays !== actualDaysToPay);

      if (needsPaidAmtUpdate || needsPaidStatusUpdate || needsPaidDaysUpdate) {
        if (needsPaidAmtUpdate) {
          changeLog.push({
            row: primaryLoc.rowNumber,
            col: slotCols[primaryLoc.slot].amt + 1,
            value: jobPaidShare
          });
          if (confirmedData[primaryLoc.rowIndex]) {
            confirmedData[primaryLoc.rowIndex][slotCols[primaryLoc.slot].amt] = jobPaidShare;
          }
        }

        if (needsPaidStatusUpdate) {
          changeLog.push({
            row: primaryLoc.rowNumber,
            col: slotCols[primaryLoc.slot].status + 1,
            value: "Part-paid (received)"
          });
          if (confirmedData[primaryLoc.rowIndex]) {
            confirmedData[primaryLoc.rowIndex][slotCols[primaryLoc.slot].status] = "Part-paid (received)";
          }
        }

        if (needsPaidDaysUpdate) {
          changeLog.push({
            row: primaryLoc.rowNumber,
            col: slotCols[primaryLoc.slot].days + 1,
            value: actualDaysToPay
          });
          if (confirmedData[primaryLoc.rowIndex]) {
            confirmedData[primaryLoc.rowIndex][slotCols[primaryLoc.slot].days] = actualDaysToPay;
          }
        }

        updateCount++;
        const daysNote = actualDaysToPay !== null ? `, ${actualDaysToPay} days to pay` : "";
        logDetails.push(`[Confirmed] Updated primary slot for Invoice ${preferredRef}: Row ${primaryLoc.rowNumber} Slot ${primaryLoc.slot} = £${jobPaidShare.toFixed(2)} (Part-paid (received)${daysNote}) on ${client} | ${jobName}`);
      }

      // 2. UPDATE EXISTING BALANCE SLOT OR ASSIGN NEW BALANCE SLOT
      if (balanceLoc) {
        const needsDueAmtUpdate = Math.abs(balanceLoc.amt - jobDueShare) >= 0.01;
        const needsDueStatusUpdate = balanceLoc.status !== "Part-paid (balance)";
        const currentLocSendDate = formatConfirmedDate_(balanceLoc.sendDate, timeZone);
        const needsSendDateUpdate = Boolean(formattedSendDate && (!currentLocSendDate || currentLocSendDate !== formattedSendDate));
        const currentDaysInt = parseInt(balanceLoc.days, 10);
        const needsDaysUpdate = isNaN(currentDaysInt) || currentDaysInt === 0;

        if (needsDueAmtUpdate || needsDueStatusUpdate || needsSendDateUpdate || needsDaysUpdate) {
          if (needsDueAmtUpdate) {
            changeLog.push({
              row: balanceLoc.rowNumber,
              col: slotCols[balanceLoc.slot].amt + 1,
              value: jobDueShare
            });
            if (confirmedData[balanceLoc.rowIndex]) {
              confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].amt] = jobDueShare;
            }
          }
          if (needsDueStatusUpdate) {
            changeLog.push({
              row: balanceLoc.rowNumber,
              col: slotCols[balanceLoc.slot].status + 1,
              value: "Part-paid (balance)"
            });
            if (confirmedData[balanceLoc.rowIndex]) {
              confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].status] = "Part-paid (balance)";
            }
          }
          if (needsSendDateUpdate) {
            changeLog.push({
              row: balanceLoc.rowNumber,
              col: slotCols[balanceLoc.slot].sendDate + 1,
              value: formattedSendDate
            });
            if (confirmedData[balanceLoc.rowIndex]) {
              confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].sendDate] = formattedSendDate;
            }
          }
          if (needsDaysUpdate || needsSendDateUpdate || needsDueStatusUpdate) {
            changeLog.push({
              row: balanceLoc.rowNumber,
              col: slotCols[balanceLoc.slot].days + 1,
              value: calculatedDays
            });
            if (confirmedData[balanceLoc.rowIndex]) {
              confirmedData[balanceLoc.rowIndex][slotCols[balanceLoc.slot].days] = calculatedDays;
            }
          }

          updateCount++;
          logDetails.push(`[Confirmed] Updated part-payment split for Invoice ${preferredRef}: Slot ${primaryLoc.slot} = £${jobPaidShare.toFixed(2)} (Part-paid (received)), Slot ${balanceLoc.slot} = £${jobDueShare.toFixed(2)} (Part-paid (balance), ${calculatedDays} days to pay) on ${client} | ${jobName}`);
        }
      } else {
        const targetSlotInfo = findTargetBalanceSlot_(primaryLoc);
        const targetRowNum = targetSlotInfo.rowNumber;
        const targetSlot = targetSlotInfo.slot;

        changeLog.push({
          row: targetRowNum,
          col: slotCols[targetSlot].amt + 1,
          value: jobDueShare
        });
        changeLog.push({
          row: targetRowNum,
          col: slotCols[targetSlot].ref + 1,
          value: preferredRef,
          isRef: true
        });
        changeLog.push({
          row: targetRowNum,
          col: slotCols[targetSlot].sendDate + 1,
          value: formattedSendDate
        });
        changeLog.push({
          row: targetRowNum,
          col: slotCols[targetSlot].days + 1,
          value: calculatedDays
        });
        changeLog.push({
          row: targetRowNum,
          col: slotCols[targetSlot].status + 1,
          value: "Part-paid (balance)"
        });

        const targetRIdx = targetRowNum - 1;
        if (confirmedData[targetRIdx]) {
          confirmedData[targetRIdx][slotCols[targetSlot].amt] = jobDueShare;
          confirmedData[targetRIdx][slotCols[targetSlot].ref] = preferredRef;
          confirmedData[targetRIdx][slotCols[targetSlot].sendDate] = formattedSendDate;
          confirmedData[targetRIdx][slotCols[targetSlot].days] = calculatedDays;
          confirmedData[targetRIdx][slotCols[targetSlot].status] = "Part-paid (balance)";
        }
        updateCount++;
        const rowNote = targetSlotInfo.isNewRow ? ` (New Child Row ${targetRowNum})` : ` (Row ${targetRowNum})`;
        logDetails.push(`[Confirmed] Applied part-payment split for Invoice ${preferredRef}: Row ${primaryLoc.rowNumber} Slot ${primaryLoc.slot} = £${jobPaidShare.toFixed(2)} (Part-paid (received)), Slot ${targetSlot}${rowNote} = £${jobDueShare.toFixed(2)} (Part-paid (balance), ${calculatedDays} days to pay) on ${client} | ${jobName}`);
      }
    });
  });

  // ==========================================================================
  // PART 2: RESOLVE FULLY-PAID PART-PAYMENT INVOICES
  // ==========================================================================
  fullyPaidInvs.forEach((inv, refKey) => {
    const locations = getLocationsForInvoice_(inv, refKey);
    if (!locations || locations.length === 0) return;

    let balanceLocs = locations.filter(l => l.status.toLowerCase().includes("balance"));
    if (balanceLocs.length === 0) {
      // Self-heal multi-tranche invoices where both slots were already marked Paid,
      // but the balance tranche retained its old projected days-to-pay instead of Xero's final paid date.
      const paidD = parsePaymentDate_(inv.paidDate);
      if (paidD && locations.length > 1) {
        const sameJobTranches = locations.some((l, idx) => idx > 0 && (l.rowNumber === locations[0].rowNumber || (l.jobGroup && l.jobGroup === locations[0].jobGroup)));
        if (sameJobTranches) {
          const anyMatchesFinalDate = locations.some(l => {
            const sendD = parsePaymentDate_(l.sendDate || locations[0].sendDate);
            if (!sendD) return false;
            const targetDays = Math.max(0, calculateDaysBetween(sendD, paidD));
            return parseInt(l.days, 10) === targetDays;
          });
          if (!anyMatchesFinalDate) {
            let latestLoc = locations[locations.length - 1];
            let maxDays = -Infinity;
            locations.forEach(l => {
              if (l.status.toLowerCase().includes("part-paid") && !l.status.toLowerCase().includes("balance")) return;
              const curDays = parseInt(l.days, 10);
              const val = isNaN(curDays) ? -1 : curDays;
              if (val >= maxDays) {
                maxDays = val;
                latestLoc = l;
              }
            });
            if (latestLoc) balanceLocs = [latestLoc];
          }
        }
      }
      if (balanceLocs.length === 0) return;
    }

    let invoiceUpdated = false;

    // 1. Update all balance slots to status "Paid" with final payment date days-to-pay
    balanceLocs.forEach(balLoc => {
      const group = balLoc.jobGroup;
      const isRetainerJob = group && (group.isRetainer || (group.childRows.length > 0 && colType !== -1 && String(confirmedData[group.parentRow - 1][colType] || "").trim().toLowerCase() === "retainer"));
      if (group && balLoc.rowNumber === group.parentRow && isRetainerJob) {
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].amt + 1, value: "" });
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].ref + 1, value: "" });
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].sendDate + 1, value: "" });
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].days + 1, value: "" });
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].status + 1, value: "" });
        if (confirmedData[balLoc.rowIndex]) {
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].amt] = "";
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].ref] = "";
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].sendDate] = "";
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].days] = "";
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].status] = "";
        }
        invoiceUpdated = true;
        logDetails.push(`[Confirmed] Cleaned up misplaced balance slot on Parent Row ${balLoc.rowNumber} Slot ${balLoc.slot} for fully-paid Invoice ${balLoc.ref}`);
        return;
      }

      const currentStatus = balLoc.status;
      if (currentStatus !== "Paid") {
        changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].status + 1, value: "Paid" });
        if (confirmedData[balLoc.rowIndex]) {
          confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].status] = "Paid";
        }
        invoiceUpdated = true;
      }

      // Calculate days to pay from send date to final payment date
      const sendDateVal = balLoc.sendDate || (locations[0] ? locations[0].sendDate : null);
      if (inv.paidDate && sendDateVal) {
        const sendD = parsePaymentDate_(sendDateVal);
        const paidD = parsePaymentDate_(inv.paidDate);
        if (sendD && paidD && !isNaN(sendD.getTime()) && !isNaN(paidD.getTime())) {
          const finalDays = Math.max(0, calculateDaysBetween(sendD, paidD));
          const currentDays = parseInt(balLoc.days, 10);
          if (currentDays !== finalDays) {
            changeLog.push({ row: balLoc.rowNumber, col: slotCols[balLoc.slot].days + 1, value: finalDays });
            if (confirmedData[balLoc.rowIndex]) {
              confirmedData[balLoc.rowIndex][slotCols[balLoc.slot].days] = finalDays;
            }
            invoiceUpdated = true;
          }
        }
      }
    });

    // 2. Ensure all primary/received slots for this invoice also reflect status "Paid"
    const nonBalanceLocs = locations.filter(l => !l.status.toLowerCase().includes("balance"));
    nonBalanceLocs.forEach(primLoc => {
      if (primLoc.status !== "Paid") {
        changeLog.push({ row: primLoc.rowNumber, col: slotCols[primLoc.slot].status + 1, value: "Paid" });
        if (confirmedData[primLoc.rowIndex]) {
          confirmedData[primLoc.rowIndex][slotCols[primLoc.slot].status] = "Paid";
        }
        invoiceUpdated = true;
      }
    });

    if (invoiceUpdated) {
      updateCount++;
      const primaryLoc = nonBalanceLocs[0] || locations[0];
      logDetails.push(`[Confirmed] Resolved fully-paid Invoice ${primaryLoc.ref}: Updated balance slot to Paid (preserving individual payment tranches and cashflow timing).`);
    }
  });

  if (changeLog.length > 0) {
    (await applyPushChanges(sheet, changeLog));
  }

  return { count: updateCount, logs: logDetails };
}


