// --- QUICKBOOKS AUTHENTICATION ---

/**
 * Refreshes the QuickBooks access token.
 */
async function refreshQBAccessToken() {
  const properties = PropertiesService.getScriptProperties();
  const tokenUrl = 'https://oauth.platform.intuit.com/oauth2/v1/tokens/bearer';
  const clientId = (await getKeyInfoValue('U2'));
  const clientSecret = (await getKeyInfoValue('U3'));
  const refreshToken = properties.getProperty('REFRESH_TOKEN');
  if (!refreshToken) {
    throw new Error('QuickBooks credentials (REFRESH_TOKEN) are not configured in Script Properties.');
  }

  const payload = {
    'grant_type': 'refresh_token',
    'refresh_token': refreshToken
  };
  const headers = {
    'Authorization': 'Basic ' + Utilities.base64Encode(`${clientId}:${clientSecret}`),
    'Accept': 'application/json',
    'Content-Type': 'application/x-www-form-urlencoded'
  };
  const options = {
    'method': 'post',
    'headers': headers,
    'payload': payload,
    'muteHttpExceptions': true
  };
  Logger.log('Attempting to refresh the QuickBooks access token...');
  const response = (await UrlFetchApp.fetch(tokenUrl, options));
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();
  if (responseCode === 200) {
    const jsonResponse = JSON.parse(responseText);
    const newAccessToken = jsonResponse.access_token;
    const newRefreshToken = jsonResponse.refresh_token;
    properties.setProperty('ACCESS_TOKEN', newAccessToken);
    properties.setProperty('REFRESH_TOKEN', newRefreshToken);
    // FIXED: Stamp an expiry time (50 minutes into the future) as a plain string
    properties.setProperty('TOKEN_EXPIRY', String(Date.now() + (50 * 60 * 1000)));
    Logger.log(' Successfully refreshed QuickBooks access and refresh tokens.');
    return newAccessToken;
  } else {
    throw new Error(`Failed to refresh QuickBooks token. The server responded: ${responseText}`);
  }
}

async function getQBAccessToken() {
  // 1. Try Central Pulse Vault Token Broker first
  if (typeof getBrokerQBAccessToken === 'function') {
    const brokerToken = (await getBrokerQBAccessToken());
    if (brokerToken) {
      Logger.log('Obtained fresh QuickBooks access token from Central Pulse Vault.');
      return brokerToken;
    }
    Logger.log('Pulse Token Broker returned null. Falling back to local script properties...');
  }

  // 2. Legacy fallback: Check local script properties
  const properties = PropertiesService.getScriptProperties();
  const accessToken = properties.getProperty('ACCESS_TOKEN');
  const tokenExpiry = properties.getProperty('TOKEN_EXPIRY');

  // FIXED: Only refresh if the token is missing OR the 50-minute timer has expired
  if (!accessToken || !tokenExpiry || Date.now() > Number(tokenExpiry)) {
    Logger.log('QB Access token missing or expired, attempting legacy refresh.');
    return (await refreshQBAccessToken());
  }
  
  return accessToken;
}

// --- QUICKBOOKS API FUNCTIONS ---

async function fetchQuickBooksPaymentDates(paymentIds, accessToken, realmId) {
  const dateMap = new Map();
  const uniqueIds = Array.from(new Set(paymentIds)); 
  if (uniqueIds.length === 0) return dateMap;
  const safeRealmId = String(realmId || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(safeRealmId)) throw new Error("Invalid QuickBooks Realm ID.");
  const baseUrl = "https://quickbooks.api.intuit.com";
  const batchSize = 30;
  for (let i = 0; i < uniqueIds.length; i += batchSize) {
    const batch = uniqueIds.slice(i, i + batchSize);
    const idList = batch.map(id => `'${String(id).replace(/[^0-9a-zA-Z_-]/g, "")}'`).join(',');
    const query = encodeURIComponent(`SELECT Id, TxnDate FROM Payment WHERE Id IN (${idList})`);
    const url = `${baseUrl}/v3/company/${safeRealmId}/query?query=${query}`;
    
    const options = {
      'method': 'get',
      'headers': {
        'Authorization': 'Bearer ' + accessToken,
        'Accept': 'application/json'
      },
      'muteHttpExceptions': true
    };
    const response = (await UrlFetchApp.fetch(url, options));
    if (response.getResponseCode() === 200) {
      const json = JSON.parse(response.getContentText());
      const payments = json.QueryResponse.Payment || [];
      payments.forEach(p => {
        if (p.Id && p.TxnDate) {
          dateMap.set(p.Id, p.TxnDate);
        }
      });
    }
    (await Utilities.sleep(100)); 
  }
  return dateMap;
}

let _qbTaxCodeRateMapCache = null;

/**
 * Fetches company TaxCodes from QuickBooks Online and maps taxCodeId -> decimal rate (e.g. 0.20, 0, 0.05).
 * Cached in memory per execution so multiple calls (invoices, costs) don't repeat the API request.
 * 
 * @param {string} accessToken 
 * @param {string} realmId 
 * @returns {Object} Map of taxCodeId to rate (e.g. { "6": 0.20, "10": 0 })
 */
async function fetchQBTaxCodeRateMap_(accessToken, realmId) {
  if (_qbTaxCodeRateMapCache) return _qbTaxCodeRateMapCache;
  const map = {};
  try {
    const baseUrl = "https://quickbooks.api.intuit.com";
    const query = encodeURIComponent("SELECT * FROM TaxCode MAXRESULTS 100");
    const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
    const options = {
      method: "get",
      headers: {
        "Authorization": "Bearer " + accessToken,
        "Accept": "application/json"
      },
      muteHttpExceptions: true
    };
    const resp = (await UrlFetchApp.fetch(url, options));
    if (resp.getResponseCode() === 200) {
      const json = JSON.parse(resp.getContentText());
      const taxCodes = json.QueryResponse?.TaxCode || [];
      taxCodes.forEach(tc => {
        const id = String(tc.Id || "").trim();
        const name = String(tc.Name || "").trim().toLowerCase();
        const desc = String(tc.Description || "").trim().toLowerCase();
        let rate = null;

        // 1. Gather all descriptive text from Name, Description, and TaxRateDetails
        let searchString = `${tc.Name || ""} ${desc}`;
        if (tc.SalesTaxRateList?.TaxRateDetail) {
          tc.SalesTaxRateList.TaxRateDetail.forEach(detail => {
            if (detail.TaxRateRef?.name) searchString += ` ${detail.TaxRateRef.name}`;
          });
        }

        // 2. Check if text explicitly contains a percentage rate (e.g. "20.0%", "5.0%", "0.0%")
        const pctMatch = searchString.match(/(\d+(?:\.\d+)?)%/);
        if (pctMatch) {
          rate = parseFloat(pctMatch[1]) / 100;
        } else if (
          tc.Taxable === false ||
          name === "non" ||
          name === "no vat" ||
          name.includes("no vat") ||
          name.includes("exempt") ||
          name.includes("zero") ||
          desc.includes("exempt") ||
          desc.includes("no vat")
        ) {
          // 3. Explicit non-taxable / exempt / zero indicators without percentage
          rate = 0;
        } else if (
          name === "tax" ||
          name === "standard" ||
          name === "standard rate" ||
          name === "standard vat" ||
          desc.includes("standard")
        ) {
          rate = 0.20;
        }

        if (id && rate !== null) {
          map[id] = rate;
        }
      });
      _qbTaxCodeRateMapCache = map;
      Logger.log(`Loaded ${Object.keys(map).length} QuickBooks TaxCodes into rate cache.`);
    }
  } catch (e) {
    Logger.log("Could not pre-fetch QB TaxCodes: " + e.message);
  }
  return map;
}

/**
 * Fetches invoices from the QuickBooks API.
 * UPDATED: Handles Credit Notes by reducing the Invoice Amount ("Net of Credit").
 * - Fully credited invoices are skipped.
 * - Partially credited invoices are scaled down proportionally.
 * - Preserves all original Lines/Whole mode logic.
 * @param {boolean|object} isHeadless - Suppress UI.
 */
async function getQuickbooksInvoices(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const SHEET_NAME = "InvFromApp";
  try {
    const accessToken = (await getQBAccessToken());
    const realmId = String((await getKeyInfoValue('X3')) || '').trim();
    if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) {
      throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
    }
    const baseUrl = "https://quickbooks.api.intuit.com";
    
    // --- MODE CHECK ---
    let importMode = "Whole";
    try {
       const modeVal = (await getKeyInfoValue('F8'));
       if (String(modeVal).trim().toLowerCase() === 'lines') importMode = "Lines";
    } catch(e) { console.log("Defaulting to Whole mode."); }

    // --- DATE FILTER LOGIC ---
    const rawDate = (await getKeyInfoValue('B2'));
    if (!rawDate || !(rawDate instanceof Date)) {
      throw new Error("Cell B2 in KeyInfo must contain a valid date.");
    }
    const cutoffDate = new Date(rawDate);
    cutoffDate.setMonth(cutoffDate.getMonth() - 12);
    const dateStr = Utilities.formatDate(cutoffDate, "UTC", "yyyy-MM-dd");
    Logger.log(`Fetching QB Invoices on or after: ${dateStr}. Mode: ${importMode}`);
    // -------------------------

    const options = {
      'method': 'get',
      'headers': {
        'Authorization': 'Bearer ' + accessToken,
        'Accept': 'application/json'
      },
      'muteHttpExceptions': true
    };

    // --- FETCH INVOICES ---
    let allInvoices = [];
    let startPosition = 1;
    const pageSize = 500;
    while (true) {
      const query = encodeURIComponent(`SELECT * FROM Invoice WHERE TxnDate >= '${dateStr}' STARTPOSITION ${startPosition} MAXRESULTS ${pageSize}`);
      const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
      
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) throw new Error('API request failed: ' + response.getContentText());
      const jsonResponse = JSON.parse(response.getContentText());
      const invoicesOnPage = jsonResponse.QueryResponse.Invoice;
      
      if (invoicesOnPage && invoicesOnPage.length > 0) {
        allInvoices = allInvoices.concat(invoicesOnPage);
        startPosition += invoicesOnPage.length;
        if (invoicesOnPage.length < pageSize) break;
      } else {
        break;
      }
      (await Utilities.sleep(200));
    }

    if (allInvoices.length === 0) {
      logOrAlert(`No invoices found in QuickBooks after ${dateStr}.`, isHeadless);
      (await writeToGoogleSheet([], SPREADSHEET_ID, SHEET_NAME, importMode));
      return { newInvoices: [], updatedInvoices: [] };
    }

    // --- FETCH PAYMENTS FOR DATES ---
    const paymentIdsToFetch = [];
    allInvoices.forEach(inv => {
      if (inv.LinkedTxn && Array.isArray(inv.LinkedTxn)) {
        inv.LinkedTxn.forEach(txn => {
          if (txn.TxnType === 'Payment' && txn.TxnId) {
            paymentIdsToFetch.push(txn.TxnId);
          }
        });
      }
    });
    const paymentDateMap = (await fetchQuickBooksPaymentDates(paymentIdsToFetch, accessToken, realmId));
    const taxCodeRateMap = (importMode === "Lines") ? (await fetchQBTaxCodeRateMap_(accessToken, realmId)) : {};

    // --- MAP DATA ---
    const mappedData = [];
    allInvoices.forEach(inv => {
      
      // === NEW CREDIT NOTE LOGIC ===
      const originalTotal = parseFloat(inv.TotalAmt) || 0;
      let totalCredit = 0;
      
      if (inv.LinkedTxn && Array.isArray(inv.LinkedTxn)) {
          inv.LinkedTxn.forEach(txn => {
              if (txn.TxnType === 'CreditMemo') {
                  totalCredit += parseFloat(txn.Amount) || 0;
              }
          });
      }

      // FIXED: Allow fully credited invoices to pass through so they import as £0
      // if (totalCredit > 0 && Math.abs(originalTotal - totalCredit) < 0.01) return;

      // Calculate Ratio & Effective Totals
      const effectiveTotal = originalTotal - totalCredit;
      const ratio = (originalTotal > 0) ? (effectiveTotal / originalTotal) : 1;

      // Derived Values for "Net" Calculation
      const originalTax = inv.TxnTaxDetail?.TotalTax || 0;
      const effectiveTax = originalTax * ratio;
      // -----------------------------

      // Common Logic
      const getStatus = (invoice) => {
        const balance = parseFloat(invoice.Balance);
        if (balance <= 0) return 'PAID';
        const dueDate = new Date(invoice.DueDate);
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        if (dueDate < today) return 'OVERDUE';
        return 'AWAITING_PAYMENT';
      };
      
      const status = getStatus(inv);
      const isPaid = (status === 'PAID');

      let fullyPaidDate = '';
      if (inv.LinkedTxn) {
        let latestDate = '';
        inv.LinkedTxn.forEach(txn => {
          if (txn.TxnType === 'Payment' && paymentDateMap.has(txn.TxnId)) {
            const pDate = paymentDateMap.get(txn.TxnId);
            if (pDate > latestDate) latestDate = pDate;
          }
        });
        fullyPaidDate = latestDate;
      }

      // Calculate Cash Paid based on Effective Total
      const currentBalance = Math.max(0, parseFloat(inv.Balance) || 0);
      const cashPaid = Math.max(0, Math.round((effectiveTotal - currentBalance) * 100) / 100);

      if (importMode === "Lines") {
          // === LINES MODE ===
          if (inv.Line && Array.isArray(inv.Line)) {
             const validLines = inv.Line.filter(l => l.DetailType === 'SalesItemLineDetail');
             const invoiceTotalTax = inv.TxnTaxDetail?.TotalTax || 0;
             const totalLineNet = validLines.reduce((sum, line) => sum + (line.Amount || 0), 0);

             // 1. Calculate Line-Level Tax using TaxCode rate if known, or fallback to proportional
             let rawLineTaxes = validLines.map(line => {
                if (effectiveTax === 0) return 0;
                const originalLineAmt = line.Amount || 0;
                const effectiveLineAmt = originalLineAmt * ratio;
                const taxCodeId = String(line.SalesItemLineDetail?.TaxCodeRef?.value || line.TaxCodeRef?.value || "").trim();

                if (taxCodeId && taxCodeRateMap && taxCodeRateMap[taxCodeId] !== undefined) {
                   return Math.round(effectiveLineAmt * taxCodeRateMap[taxCodeId] * 100) / 100;
                }
                // Proportional fallback if rate is unknown
                return (totalLineNet > 0) ? (originalLineAmt / totalLineNet) * effectiveTax : 0;
             });

             // Fail-safe: If invoice has tax (effectiveTax > 0) but line taxes all summed to 0, fallback to proportional
             const initialSum = rawLineTaxes.reduce((sum, t) => sum + t, 0);
             if (effectiveTax > 0 && initialSum === 0 && totalLineNet > 0) {
                Logger.log(`Warning: Line-level tax resolved to 0 for inv #${inv.DocNumber} but effectiveTax is ${effectiveTax}. Falling back to proportional distribution.`);
                rawLineTaxes = validLines.map(line => {
                   const originalLineAmt = line.Amount || 0;
                   return (originalLineAmt / totalLineNet) * effectiveTax;
                });
             }

             // 2. Minor rounding reconciliation: align sum of line taxes with effectiveTax if discrepancy is small (<= 5p)
             const sumLineTaxes = rawLineTaxes.reduce((sum, t) => sum + t, 0);
             const taxDiff = Math.round((effectiveTax - sumLineTaxes) * 100) / 100;
             if (Math.abs(taxDiff) > 0 && Math.abs(taxDiff) <= 0.05 && validLines.length > 0) {
                let maxIdx = 0;
                for (let li = 1; li < rawLineTaxes.length; li++) {
                   if (rawLineTaxes[li] > rawLineTaxes[maxIdx]) maxIdx = li;
                }
                if (rawLineTaxes[maxIdx] + taxDiff >= 0) {
                   rawLineTaxes[maxIdx] = Math.round((rawLineTaxes[maxIdx] + taxDiff) * 100) / 100;
                }
             }

             // 3. Line-level totals & proportional part-payment allocation
             const rawLineTotals = validLines.map((line, idx) => {
                const originalLineAmt = line.Amount || 0;
                const effectiveLineAmt = originalLineAmt * ratio;
                const lineTax = rawLineTaxes[idx] || 0;
                return Math.round((effectiveLineAmt + lineTax) * 100) / 100;
             });

             let rawLinePaids = rawLineTotals.map((lineTotal, idx) => {
                if (isPaid || currentBalance <= 0.005) return lineTotal;
                if (cashPaid <= 0.005) return 0;
                const lineRatio = effectiveTotal > 0 ? (lineTotal / effectiveTotal) : (1 / validLines.length);
                return Math.round(cashPaid * lineRatio * 100) / 100;
             });

             // Minor rounding reconciliation: align sum of line paids with cashPaid if discrepancy is small (<= 5p)
             if (!isPaid && currentBalance > 0.005 && cashPaid > 0.005 && validLines.length > 0) {
                const sumLinePaids = rawLinePaids.reduce((sum, p) => sum + p, 0);
                const paidDiff = Math.round((cashPaid - sumLinePaids) * 100) / 100;
                if (Math.abs(paidDiff) > 0 && Math.abs(paidDiff) <= 0.05) {
                   let maxIdx = 0;
                   for (let li = 1; li < rawLinePaids.length; li++) {
                      if (rawLinePaids[li] > rawLinePaids[maxIdx]) maxIdx = li;
                   }
                   if (rawLinePaids[maxIdx] + paidDiff >= 0) {
                      rawLinePaids[maxIdx] = Math.round((rawLinePaids[maxIdx] + paidDiff) * 100) / 100;
                   }
                }
             }

             validLines.forEach((line, index) => {
                 // 1. Unique IDs
                 const lineId = `${inv.Id}-${index + 1}`;
                 // SAFETY: Format applied at sheet-level
                 const lineInvNumber = `${inv.DocNumber}-${index + 1}`;
                 
                 // 2. Reference (Combine)
                 const parentRef = inv.PrivateNote || "";
                 const lineDesc = line.Description || ""; 
                 const combinedRef = [parentRef, lineDesc].filter(Boolean).join(" - ");

                 // 3. Financials
                 const originalLineAmt = line.Amount || 0;
                 const effectiveLineAmt = originalLineAmt * ratio;
                 const lineTax = rawLineTaxes[index] || 0;

                 const lineSubTotal = effectiveLineAmt;
                 const lineTotal = rawLineTotals[index];

                 // Proportional payment allocation across lines
                 const lineAmountPaid = rawLinePaids[index];
                 const lineAmountDue = Math.max(0, Math.round((lineTotal - lineAmountPaid) * 100) / 100);

                 mappedData.push([
                    lineId,
                    inv.CustomerRef?.name || 'N/A',
                    lineInvNumber,
                    combinedRef,
                    'INVOICE',
                    inv.TxnDate,
                    inv.DueDate,
                    status,
                    lineAmountDue,          // AmountDue (Scaled)
                    lineAmountPaid,         // AmountPaid (Scaled)
                    lineTotal,              // Total (Scaled)
                    fullyPaidDate,
                    (inv.EmailStatus === 'EmailSent'),
                    lineSubTotal,           // SubTotal (Scaled)
                    lineTax,                // TotalTax (Scaled)
                    inv.CurrencyRef?.value,
                    inv.ExchangeRate || 1
                 ]);
             });
          }
      } else {
          // === WHOLE MODE ===
          // SAFETY: Format applied at sheet-level
          const safeDocNumber = inv.DocNumber;
          // Calculate Cash Paid based on Effective Total
          const currentBalance = parseFloat(inv.Balance) || 0;
          const cashPaid = effectiveTotal - currentBalance;

          mappedData.push([
            inv.Id,
            inv.CustomerRef?.name || 'N/A',
            safeDocNumber,
            inv.PrivateNote || '',
            'INVOICE',
            inv.TxnDate,
            inv.DueDate,
            status,
            currentBalance, // Remaining Balance (Actual from QB)
            cashPaid.toFixed(2), // Cash Paid (Effective Total - Balance)
            effectiveTotal, // Adjusted Total
            fullyPaidDate,
            (inv.EmailStatus === 'EmailSent'),
            (effectiveTotal - effectiveTax).toFixed(2), // Adjusted Subtotal
            effectiveTax, // Adjusted Tax
            inv.CurrencyRef?.value,
            inv.ExchangeRate || 1
          ]);
      }
    });

    const pullResult = (await writeToGoogleSheet(mappedData, SPREADSHEET_ID, SHEET_NAME, importMode));
    _updateTimestamp("InvComp", "L2");
    logOrAlert(`Successfully fetched ${mappedData.length} rows from QB (Mode: ${importMode}).`, isHeadless);
    return pullResult;
  } catch (e) {
    logOrAlert('QB Invoice Sync Failed: ' + e.message, isHeadless);
    return { newInvoices: [], updatedInvoices: [] };
  }
}

/**
 * Creates invoices in QuickBooks.
 * @param {boolean|object} isHeadless - Suppress UI.
 */
async function createInvoicesInQuickBooks(isHeadless = false) {
  // If isHeadless is truthy, set ui to null, otherwise get UI
  const ui = isHeadless ? null : SpreadsheetApp.getUi(); 
  
  Logger.log('Starting createInvoicesInQuickBooks script.');
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const discrepancySheet = ss.getSheetByName("InvComp");
    if (!discrepancySheet) { throw new Error('Sheet "InvComp" not found.'); }
    const invCompData = discrepancySheet.getDataRange().getValues();
    const clientSheetId = (await getKeyInfoValue('X28'));
    const clientSpreadsheet = (await SpreadsheetApp.openById(clientSheetId));
    const confirmedSheet = clientSpreadsheet.getSheetByName("Confirmed");
    let confirmedData = confirmedSheet.getDataRange().getValues();

    const headerRowIndex = 5;
    const invCompHeaders = invCompData[headerRowIndex - 1];
    const dashboardIdRow = invCompData[3];

    let dashboardStartIndex = -1;
    for (let i = 0; i < invCompHeaders.length; i++) {
      if (dashboardIdRow[i] === 'Dashboard' && invCompHeaders[i] === 'Client') {
        dashboardStartIndex = i;
        break;
      }
    }

    if (dashboardStartIndex === -1) { throw new Error(`Could not find the starting column for the 'Dashboard list' section.`);
    }

    const landmarkColIndex = invCompHeaders.map(h => h.toString().trim()).indexOf('CellRef');
    if (landmarkColIndex === -1) { throw new Error(`Could not find the landmark "CellRef" header in the "InvComp" sheet.`);
    }

    const invCompHeaderMap = buildQBHeaderMap(invCompHeaders, landmarkColIndex, dashboardStartIndex);
    const confirmedHeaderMap = getHeaderMap(confirmedData[0]);

    if (!validateQBHeaders(invCompHeaderMap, confirmedHeaderMap, ui)) { return;
    }

    const checkboxColumn = invCompHeaderMap['Push inv?'];
    const changeLog = [];
    const checkboxesToClear = [];
    let invoicesCreatedCount = 0;

    for (let i = headerRowIndex; i < invCompData.length; i++) {
      const rowData = invCompData[i];
      if (rowData[checkboxColumn] === true) {
        const rowNumber = i + 1;
        const totalExclVatRaw = rowData[invCompHeaderMap['Total excl VAT']];
        const sentDateRaw = rowData[invCompHeaderMap['Sent date']];
        const cleanedTotalString = totalExclVatRaw ? totalExclVatRaw.toString().replace(/,/g, '') : '';
        const parsedTotal = parseFloat(cleanedTotalString);

        if (isNaN(parsedTotal) || parsedTotal === 0) { throw new Error(`Invalid or zero value in 'Total excl VAT' column for row ${rowNumber}.`);
        }

        let sentDate = new Date(sentDateRaw);
        if (typeof sentDateRaw === 'number' && sentDateRaw > 20000 && sentDateRaw < 70000) {
            sentDate = new Date(new Date(1899, 11, 30).getTime() + Math.round(sentDateRaw * 86400000));
        }

        if (isNaN(sentDate.getTime())) { throw new Error(`Invalid date in 'Sent date' column for row ${rowNumber}.`);
        }

        const invoiceDetails = {
          client: rowData[invCompHeaderMap['Client']],
          job: rowData[invCompHeaderMap['Job']],
          totalExclVat: parsedTotal,
          sentDate: sentDate,
          vatIncluded: rowData[invCompHeaderMap['VAT included']]
        };
        const newInvoiceNumber = (await createQuickBooksInvoice(invoiceDetails));

        if (newInvoiceNumber) {
          invoicesCreatedCount++;
          checkboxesToClear.push(discrepancySheet.getRange(rowNumber, checkboxColumn + 1));
          const targetSlot = findMatchingSlotInConfirmed(invoiceDetails, confirmedData, confirmedHeaderMap);
          if (targetSlot) {
            const { row, invSection } = targetSlot;
            const refHeader = `Inv ${invSection} ref`;
            const refCol = confirmedHeaderMap[refHeader] + 1;
            confirmedData[row - 1][refCol - 1] = "'" + newInvoiceNumber;
            changeLog.push({ row: row, col: refCol });
            const statusHeader = `Inv ${invSection} status`;
            const statusCol = confirmedHeaderMap[statusHeader] + 1;
            confirmedData[row - 1][statusCol - 1] = "Draft";
            changeLog.push({ row: row, col: statusCol });
          } else {
            Logger.log(`Warning: Could not find a matching slot in 'Confirmed' for client "${invoiceDetails.client}".`);
          }
        } else {
          throw new Error(`Failed to create a QuickBooks invoice for row ${rowNumber}.`);
        }
      }
    }

    if (changeLog.length > 0) { applyQBChanges(confirmedSheet, changeLog, confirmedData);
    }
    if (checkboxesToClear.length > 0) {
      checkboxesToClear.forEach(range => range.setValue(false));
    }
    
    logOrAlert(`Process complete. Created ${invoicesCreatedCount} invoice(s) in QuickBooks.`, isHeadless);
  } catch (e) {
    logOrAlert(`A critical error occurred: ${e.message}`, isHeadless);
  }
}

async function createQuickBooksInvoice(details) {
  const accessToken = (await getQBAccessToken());
  const realmId = String((await getKeyInfoValue('X3')) || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
  const baseUrl = "https://quickbooks.api.intuit.com";
  const url = `${baseUrl}/v3/company/${realmId}/invoice`;
  const keyInfoSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("KeyInfo");
  if (!keyInfoSheet) throw new Error("KeyInfo sheet not found.");

  const itemRefName = keyInfoSheet.getRange("X7").getValue();
  const standardTaxCodeId = keyInfoSheet.getRange("X10").getValue();
  const zeroTaxCodeId = keyInfoSheet.getRange("X11").getValue();

  if (!itemRefName || !standardTaxCodeId || !zeroTaxCodeId) {
    throw new Error("Default Item/Tax Code IDs missing in KeyInfo (X7, X10, X11).");
  }

  const vatValue = parseFloat(details.vatIncluded);
  const taxCodeIdToUse = (!isNaN(vatValue) && vatValue !== 0) ? standardTaxCodeId : zeroTaxCodeId;
  Logger.log(`Determined taxCodeId to use: "${taxCodeIdToUse}"`);

  const sentDate = details.sentDate;
  const dueDate = new Date(sentDate);
  dueDate.setDate(sentDate.getDate() + 30);
  const payload = {
    "CustomerRef": { "name": details.client },
    "TxnDate": Utilities.formatDate(sentDate, "UTC", "yyyy-MM-dd"),
    "DueDate": Utilities.formatDate(dueDate, "UTC", "yyyy-MM-dd"),
    "Line": [{
      "Amount": details.totalExclVat,
      "DetailType": "SalesItemLineDetail",
      "SalesItemLineDetail": {
        "ItemRef": { "name": itemRefName },
        "TaxCodeRef": { "value": taxCodeIdToUse.toString() },
        "Qty": 1,
        "UnitPrice": details.totalExclVat
      }
    }]
  };
  
  const options = {
    'method': 'post',
    'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json', 'Content-Type': 'application/json' },
    'payload': JSON.stringify(payload),
    'muteHttpExceptions': true
  };
  const response = (await UrlFetchApp.fetch(url, options));
  if (response.getResponseCode() === 200) {
    const jsonResponse = JSON.parse(response.getContentText());
    Logger.log(`Successfully created QuickBooks invoice ${jsonResponse.Invoice.DocNumber}.`);
    return jsonResponse.Invoice.DocNumber;
  } else {
    Logger.log(`Error creating invoice: ${response.getContentText()}`);
    return null;
  }
}

/**
 * Fetches a 12-month P&L report from QuickBooks.
 * @param {boolean|object} isHeadless - Suppress UI.
 */
async function getQuickBooksProfitAndLossReport(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId(); 
  const SHEET_NAME = "PLFromApp";
  try {
    const accessToken = (await getQBAccessToken());
    const realmId = String((await getKeyInfoValue('X3')) || '').trim();
    if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
    Logger.log('Starting P&L report fetch for QuickBooks Company ID: ' + realmId);
    const reportData = {
      headers: ['Description'],
      rowMap: new Map(),
      rowOrder: []
    };
    const formatDateToYyyyMmDd = (date) => {
      const year = date.getFullYear();
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const day = date.getDate().toString().padStart(2, '0');
      return `${year}-${month}-${day}`;
    };
    for (let i = 0; i < 12; i++) {
      const today = new Date();
      const targetDate = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const fromDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
      const toDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);
      const startDateStr = formatDateToYyyyMmDd(fromDate);
      const endDateStr = formatDateToYyyyMmDd(toDate);
      const monthHeader = fromDate.toLocaleString('default', { month: 'long', year: 'numeric' });
      reportData.headers.splice(1, 0, monthHeader);
      
      const baseUrl = "https://quickbooks.api.intuit.com";
      const url = `${baseUrl}/v3/company/${realmId}/reports/ProfitAndLoss?start_date=${startDateStr}&end_date=${endDateStr}`;
      const options = {
        'method': 'get',
        'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' },
        'muteHttpExceptions': true
      };
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) {
        Logger.log(`Error fetching data for ${monthHeader}: ${response.getContentText()}`);
        continue;
      }
      const monthReport = JSON.parse(response.getContentText());
      const getQBReportStructure = (report) => {
        const structure = [];
        if (!report?.Rows?.Row) return structure;
        const processNode = (r) => {
          if (!r.Header && !r.Summary && !r.ColData) { return; }
          let title = '';
          let type = '';
          if (r.type === 'Section' && r.Header?.ColData && r.Header.ColData.length > 0) {
            type = 'Section';
            title = String(r.Header.ColData[0].value || '').trim();
            structure.push({ title: title, type: type });
            if (r.Rows?.Row) r.Rows.Row.forEach(processNode);
          } else if (r.Summary?.ColData && r.Summary.ColData.length > 0) {
            type = 'SummaryRow';
            title = String(r.Summary.ColData[0].value || '').trim();
            structure.push({ title: title, type: type });
          } else if (r.ColData && r.ColData.length > 0) {
            type = 'Row';
            title = String(r.ColData[0].value || '').trim();
            structure.push({ title: title, type: type });
          }
        };
        report.Rows.Row.forEach(processNode);
        return structure;
      };
      
      const monthRowOrder = getQBReportStructure(monthReport);
      
      if (reportData.rowOrder.length === 0) {
        reportData.rowOrder = monthRowOrder;
      } else {
        const masterTitles = new Set(reportData.rowOrder.map(r => r.title));
        monthRowOrder.forEach((monthRow, index) => {
          if (!masterTitles.has(monthRow.title)) {
            let predecessorIndexInMaster = -1;
            for (let j = index - 1; j >= 0; j--) {
              const predecessorTitle = monthRowOrder[j].title;
              const masterIndex = reportData.rowOrder.findIndex(r => r.title === predecessorTitle);
              if (masterIndex !== -1) {
                predecessorIndexInMaster = masterIndex;
                break;
              }
            }
            if (predecessorIndexInMaster !== -1) {
              reportData.rowOrder.splice(predecessorIndexInMaster + 1, 0, monthRow);
            } else {
              let successorIndexInMaster = -1;
              for (let j = index + 1; j < monthRowOrder.length; j++) {
                const successorTitle = monthRowOrder[j].title;
                const masterIndex = reportData.rowOrder.findIndex(r => r.title === successorTitle);
                if (masterIndex !== -1) {
                  successorIndexInMaster = masterIndex;
                  break;
                }
              }
              if (successorIndexInMaster !== -1) {
                reportData.rowOrder.splice(successorIndexInMaster, 0, monthRow);
              } else {
                reportData.rowOrder.push(monthRow);
              }
            }
            masterTitles.add(monthRow.title);
          }
        });
      }
      const processQBRowData = (row) => {
        if (!row.Header && !row.Summary && !row.ColData) { return; }
        if (row.type === 'Section' && row.Rows?.Row) { 
          row.Rows.Row.forEach(processQBRowData);
        } 
        else if (row.Summary?.ColData && row.Summary.ColData.length > 1) {
          const title = String(row.Summary.ColData[0].value || '').trim();
          const value = row.Summary.ColData[1].value || '0.00';
          if (!reportData.rowMap.has(title)) reportData.rowMap.set(title, {});
          reportData.rowMap.get(title)[monthHeader] = value;
        } else if (row.ColData && row.ColData.length > 1) {
          const title = String(row.ColData[0].value || '').trim();
          const value = row.ColData[1].value || '0.00';
          if (!reportData.rowMap.has(title)) reportData.rowMap.set(title, {});
          reportData.rowMap.get(title)[monthHeader] = value;
        }
      };
      if (monthReport?.Rows?.Row) {
        monthReport.Rows.Row.forEach(processQBRowData);
      }
    }

    if (reportData.rowOrder.length > 0) {
      (await writePLToGoogleSheet(reportData, SPREADSHEET_ID, SHEET_NAME));
      _updateTimestamp("PLComp", "C1"); 
      logOrAlert("Successfully updated QB P&L Report.", isHeadless);
    } else {
      logOrAlert('Failed to fetch any report data.', isHeadless);
    }
  } catch (e) {
    console.error("FULL STACK TRACE: ", e.stack);
    logOrAlert('QB P&L Failed: ' + e.message, isHeadless);
  }
}


// --- "YEAR 0" FUNCTIONS ---

/**
 * Fetches a 12-month Profit and Loss report from Xero for the "Year 0" period.
 * @param {boolean|object} isHeadless - Suppress UI.
 */
async function getYear0PLfromXero(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const SHEET_NAME = "Year0PLFromApp";
  try {
    const accessToken = (await getXeroAccessToken());
    const xeroTenantId = (await getKeyInfoValue('X2'));
    Logger.log('Starting Year0 P&L fetch for Tenant ID: ' + xeroTenantId);
    const reportData = { headers: ['Description'], rowMap: new Map(), rowOrder: [] };
    const formatDateToYyyyMmDd = (date) => `${date.getFullYear()}-${(date.getMonth()+1).toString().padStart(2,'0')}-${date.getDate().toString().padStart(2,'0')}`;

    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const year0DataSheet = ss.getSheetByName("Year0Data");
    const periodStartDate = new Date(year0DataSheet.getRange("AM1").getValue());
    for (let i = 0; i < 12; i++) {
      const targetDate = new Date(periodStartDate.getFullYear(), periodStartDate.getMonth() + i, 1);
      const fromDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
      const toDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);
      const fromDateStr = formatDateToYyyyMmDd(fromDate);
      const toDateStr = formatDateToYyyyMmDd(toDate);
      const monthHeader = fromDate.toLocaleString('default', { month: 'long', year: 'numeric' });
      reportData.headers.splice(1, 0, monthHeader);
      const url = `https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss?fromDate=${fromDateStr}&toDate=${toDateStr}&standardLayout=false`;
      const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': xeroTenantId, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
      const response = (await UrlFetchApp.fetch(url, options));
      
      if (response.getResponseCode() !== 200) continue;
      
      const jsonResponse = JSON.parse(response.getContentText());
      const monthReport = jsonResponse.Reports[0];
      const getReportStructure = (report) => {
        const structure = [];
        if (!report || !report.Rows) return structure;
        const processNode = (r) => {
          let title = '';
          if (r.RowType === 'Section') {
            title = r.Title;
            structure.push({ title: title, type: r.RowType });
            if (r.Rows) r.Rows.forEach(processNode);
          } else if (r.RowType === 'Row' || r.RowType === 'SummaryRow') {
            title = r.Cells[0].Value;
            structure.push({ title: title, type: r.RowType });
          }
        };
        report.Rows.forEach(processNode);
        return structure;
      };
      const monthRowOrder = getReportStructure(monthReport);

      if (reportData.rowOrder.length === 0) {
        reportData.rowOrder = monthRowOrder;
      } else {
        const masterTitles = new Set(reportData.rowOrder.map(r => r.title));
        monthRowOrder.forEach((monthRow, index) => {
          if (!masterTitles.has(monthRow.title)) {
            let predecessorIndexInMaster = -1;
            for (let j = index - 1; j >= 0; j--) {
              const predecessorTitle = monthRowOrder[j].title;
              const masterIndex = reportData.rowOrder.findIndex(r => r.title === predecessorTitle);
              if (masterIndex !== -1) { predecessorIndexInMaster = masterIndex; break; }
            }
            if (predecessorIndexInMaster !== -1) {
              reportData.rowOrder.splice(predecessorIndexInMaster + 1, 0, monthRow);
            } else {
               reportData.rowOrder.push(monthRow);
             }
            masterTitles.add(monthRow.title);
          }
        });
      }

      const processRowData = (row) => {
        if (row.RowType === 'Section' && row.Rows) { row.Rows.forEach(processRowData);
        }
        else if ((row.RowType === 'Row' || row.RowType === 'SummaryRow') && row.Cells.length > 1) {
          const title = row.Cells[0].Value;
          const value = row.Cells[1].Value;
          if (!reportData.rowMap.has(title)) reportData.rowMap.set(title, {});
          reportData.rowMap.get(title)[monthHeader] = value;
        }
      };
      if (monthReport && monthReport.Rows) monthReport.Rows.forEach(processRowData);
    }

    if (reportData.rowOrder.length > 0) {
      (await writePLToGoogleSheet(reportData, SPREADSHEET_ID, SHEET_NAME));
      (await syncYear0DataToClientSheet_());
      logOrAlert("Year 0 Xero Data Updated.", isHeadless);
    } else {
      logOrAlert("No Year 0 data found.", isHeadless);
    }
  } catch (e) {
    logOrAlert("Year 0 Xero Failed: " + e.message, isHeadless);
  }
}

/**
 * Fetches a 12-month P&L report from QuickBooks for the "Year 0" period.
 * @param {boolean|object} isHeadless - Suppress UI.
 */
async function getYear0PLfromQB(isHeadless = false) {
  const SPREADSHEET_ID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const SHEET_NAME = "Year0PLFromApp";
  try {
    const accessToken = (await getQBAccessToken());
    const realmId = String((await getKeyInfoValue('X3')) || '').trim();
    if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
    const reportData = { headers: ['Description'], rowMap: new Map(), rowOrder: [] };
    const formatDateToYyyyMmDd = (date) => `${date.getFullYear()}-${(date.getMonth()+1).toString().padStart(2,'0')}-${date.getDate().toString().padStart(2,'0')}`;
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const year0DataSheet = ss.getSheetByName("Year0Data");
    const periodStartDate = new Date(year0DataSheet.getRange("AM1").getValue());
    for (let i = 0; i < 12; i++) {
      const targetDate = new Date(periodStartDate.getFullYear(), periodStartDate.getMonth() + i, 1);
      const fromDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
      const toDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0);
      const startDateStr = formatDateToYyyyMmDd(fromDate);
      const endDateStr = formatDateToYyyyMmDd(toDate);
      const monthHeader = fromDate.toLocaleString('default', { month: 'long', year: 'numeric' });
      reportData.headers.splice(1, 0, monthHeader);
      const baseUrl = "https://quickbooks.api.intuit.com";
      const url = `${baseUrl}/v3/company/${realmId}/reports/ProfitAndLoss?start_date=${startDateStr}&end_date=${endDateStr}`;
      const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) continue;

      const monthReport = JSON.parse(response.getContentText());
      // Logic from getQuickBooksProfitAndLossReport inline...
      const getQBReportStructure = (report) => {
        const structure = [];
        if (!report?.Rows?.Row) return structure;
        const processNode = (r) => {
          try {
            if (!r.Header && !r.Summary && !r.ColData) { return; }
            let title = '';
            let type = '';
            if (r.type === 'Section' && r.Header?.ColData) {
              type = 'Section';
              title = r.Header.ColData[0].value.trim();
              structure.push({ title: title, type: type });
              if (r.Rows?.Row) r.Rows.Row.forEach(processNode);
            } else if (r.Summary?.ColData) {
              type = 'SummaryRow';
              title = r.Summary.ColData[0].value.trim();
              structure.push({ title: title, type: type });
            } else if (r.ColData) {
              type = 'Row';
              title = r.ColData[0].value.trim();
              structure.push({ title: title, type: type });
            }
          } catch (e) {
            console.log("DIAGNOSTIC CRASH (processNode): " + JSON.stringify(r));
            throw e;
          }
        };
        report.Rows.Row.forEach(processNode);
        return structure;
      };

      const monthRowOrder = getQBReportStructure(monthReport);

      if (reportData.rowOrder.length === 0) {
        reportData.rowOrder = monthRowOrder;
      } else {
        const masterTitles = new Set(reportData.rowOrder.map(r => r.title));
        monthRowOrder.forEach((monthRow, index) => {
          if (!masterTitles.has(monthRow.title)) {
            let predecessorIndexInMaster = -1;
            for (let j = index - 1; j >= 0; j--) {
              const predecessorTitle = monthRowOrder[j].title;
              const masterIndex = reportData.rowOrder.findIndex(r => r.title === predecessorTitle);
              if (masterIndex !== -1) { predecessorIndexInMaster = masterIndex; break; }
            }
            if (predecessorIndexInMaster !== -1) {
              reportData.rowOrder.splice(predecessorIndexInMaster + 1, 0, monthRow);
            } else {
               reportData.rowOrder.push(monthRow);
             }
            masterTitles.add(monthRow.title);
          }
        });
      }

      const processQBRowData = (row) => {
        try {
          if (!row.Header && !row.Summary && !row.ColData) { return; }
          if (row.type === 'Section' && row.Rows?.Row) { 
            row.Rows.Row.forEach(processQBRowData);
          } 
          else if (row.Summary?.ColData) {
            const title = row.Summary.ColData[0].value.trim();
            const value = row.Summary.ColData[1].value;
            if (!reportData.rowMap.has(title)) reportData.rowMap.set(title, {});
            reportData.rowMap.get(title)[monthHeader] = value;
          } else if (row.ColData) {
            const title = row.ColData[0].value.trim();
            const value = row.ColData[1].value;
            if (!reportData.rowMap.has(title)) reportData.rowMap.set(title, {});
            reportData.rowMap.get(title)[monthHeader] = value;
          }
        } catch (e) {
          console.log("DIAGNOSTIC CRASH (processQBRowData): " + JSON.stringify(row));
          throw e;
        }
      };
      if (monthReport?.Rows?.Row) monthReport.Rows.Row.forEach(processQBRowData);
    }

    if (reportData.rowOrder.length > 0) {
      (await writePLToGoogleSheet(reportData, SPREADSHEET_ID, SHEET_NAME));
      (await syncYear0DataToClientSheet_());
      logOrAlert("Year 0 QB Data Updated.", isHeadless);
    } else {
      logOrAlert("No Year 0 data found.", isHeadless);
    }
  } catch (e) {
    logOrAlert("Year 0 QB Failed: " + e.message, isHeadless);
  }
}

/**
 * Syncs Master Year0Data!A1:BZ205 to the Client Sheet's local Year0Data tab,
 * keeping local formulas and resolving Year0PLFromApp / KeyInfo!BA references to values.
 */
async function syncYear0DataToClientSheet_() {
  try {
    (await SpreadsheetApp.flush());
    const masterSs = SpreadsheetApp.getActiveSpreadsheet();
    const masterY0 = masterSs.getSheetByName("Year0Data");
    if (!masterY0) return;

    const clientSheetId = (await getKeyInfoValue('X28'));
    if (!clientSheetId) return;
    const clientSs = (await SpreadsheetApp.openById(clientSheetId));
    let clientY0 = clientSs.getSheetByName("Year0Data");
    if (!clientY0) {
      clientY0 = clientSs.insertSheet("Year0Data");
      clientY0.hideSheet();
    }
    if (clientY0.getMaxColumns() < 78) {
      clientY0.insertColumnsAfter(clientY0.getMaxColumns(), 78 - clientY0.getMaxColumns());
    }

    const range = masterY0.getRange("A1:BZ205");
    const formulas = range.getFormulas();
    const values = range.getValues();
    const out = [];
    for (let r = 0; r < formulas.length; r++) {
      const row = [];
      for (let c = 0; c < formulas[r].length; c++) {
        let f = formulas[r][c];
        if (f) {
          if (/Year0PLFromApp|KeyInfo!\$?B[AE]|CC2:CC502|AZ71/i.test(f)) {
            row.push(values[r][c]);
          } else if (/SUM\(BE\$82:BE\$589\)/i.test(f)) {
            row.push(f.replace(/589/g, "205"));
          } else {
            row.push(f);
          }
        } else {
          row.push(values[r][c]);
        }
      }
      out.push(row);
    }
    clientY0.getRange(1, 1, out.length, out[0].length).setValues(out);
    (await SpreadsheetApp.flush());
  } catch (e) {
    Logger.log("syncYear0DataToClientSheet_ warning: " + e.message);
  }
}

// --- "STARTER" FUNCTIONS (UI ONLY by nature of task) ---

async function StarterPushInvToConfirmed() {
  const STARTER_SHEET_NAME = "StarterInv";
  const CONFIRMED_SHEET_NAME = "Confirmed";
  const CLIENT_SHEET_ID = (await getKeyInfoValue('X28'));
  const ui = SpreadsheetApp.getUi();
  
  Logger.log("=== StarterPushInvToConfirmed: Starting ===");
  Logger.log(`CLIENT_SHEET_ID from KeyInfo!X28: ${CLIENT_SHEET_ID}`);

  if (!CLIENT_SHEET_ID) {
    Logger.log("Error: CLIENT_SHEET_ID is missing or not set in KeyInfo!X28.");
    ui.alert('Error: CLIENT_SHEET_ID is not set in KeyInfo cell X28.');
    return;
  }

  try {
    const sourceSs = SpreadsheetApp.getActiveSpreadsheet();
    const sourceSheet = sourceSs.getSheetByName(STARTER_SHEET_NAME);
    if (!sourceSheet) {
      Logger.log(`Error: Source sheet "${STARTER_SHEET_NAME}" not found in current Master Sheet.`);
      ui.alert(`Error: Source sheet "${STARTER_SHEET_NAME}" not found.`);
      return;
    }

    const targetSs = (await SpreadsheetApp.openById(CLIENT_SHEET_ID));
    const targetSsName = targetSs.getName();
    Logger.log(`Target Spreadsheet Name: "${targetSsName}" | URL: ${targetSs.getUrl()}`);

    const targetSheet = targetSs.getSheetByName(CONFIRMED_SHEET_NAME);
    if (!targetSheet) {
      Logger.log(`Error: Target sheet "${CONFIRMED_SHEET_NAME}" not found in target spreadsheet.`);
      ui.alert(`Error: Target sheet "${CONFIRMED_SHEET_NAME}" not found.`);
      return;
    }

    // --- 1. IDENTIFY INVOICE REF COLUMNS ON CONFIRMED TAB ---
    const targetLastCol = Math.max(targetSheet.getLastColumn(), 96);
    const targetHeaders = targetSheet.getRange(1, 1, 1, targetLastCol).getValues()[0];
    const refColIndices = [];
    targetHeaders.forEach((h, idx) => {
      const str = String(h || '').trim().toLowerCase();
      if (/^inv\s*\d*\s*ref$/i.test(str)) {
        refColIndices.push(idx);
      }
    });
    // Fallback to columns AQ (42), AX (49), BE (56) (0-indexed) if headers not found by regex
    if (refColIndices.length === 0) {
      refColIndices.push(42, 49, 56);
    }
    Logger.log(`Invoice ref column indices on Confirmed: [${refColIndices.join(', ')}]`);

    // --- 2. COLLECT EXISTING INVOICES & FIND TRUE LAST ROW ON CONFIRMED ---
    // Standard ecosystem 96-column Zone Check:
    // ZONE CHECK: A:E (0-4), AG:AM (32-38), AP:BH (41-59), BX:CR (75-95)
    // Excludes columns outside these zones (e.g. column AN formula =if(AL>AM,"Err","") down to row 5002)
    const existingInvoiceRefs = new Set();
    let lastRowWithContent = 0;
    const targetLastRow = targetSheet.getLastRow();
    Logger.log(`Target sheet physical getLastRow(): ${targetLastRow}`);

    if (targetLastRow > 0) {
      const colsToRead = Math.min(Math.max(targetLastCol, 96), targetSheet.getMaxColumns());
      const allTargetData = targetSheet.getRange(1, 1, targetLastRow, colsToRead).getValues();

      // Find the true last row with content using the bottom-up Zone Check
      for (let i = allTargetData.length - 1; i >= 0; i--) {
        const row = allTargetData[i];
        const z1 = row.slice(0, 5).some(c => c !== "" && c !== null && c !== undefined);
        const z2 = row.length > 32 && row.slice(32, 39).some(c => c !== "" && c !== null && c !== undefined);
        const z3 = row.length > 41 && row.slice(41, 60).some(c => c !== "" && c !== null && c !== undefined);
        const z4 = row.length > 75 && row.slice(75, 96).some(c => c !== "" && c !== null && c !== undefined);
        if (z1 || z2 || z3 || z4) {
          lastRowWithContent = i + 1;
          break;
        }
      }

      // Collect existing invoice refs from row 3 downwards up to lastRowWithContent (ignoring header rows 1 & 2)
      for (let i = 2; i < lastRowWithContent; i++) {
        const row = allTargetData[i];
        refColIndices.forEach(colIdx => {
          if (colIdx < row.length) {
            const val = row[colIdx];
            if (val !== null && val !== undefined) {
              const clean = String(val).trim().toLowerCase();
              if (clean !== '' && !clean.startsWith('#')) {
                existingInvoiceRefs.add(clean);
              }
            }
          }
        });
      }
    }

    Logger.log(`True last row with content via Zone Check: ${lastRowWithContent}`);
    Logger.log(`Existing invoice refs collected from Confirmed: ${existingInvoiceRefs.size}`);

    // --- 3. READ SOURCE DATA FROM STARTER SHEET ---
    const lastRow = sourceSheet.getLastRow();
    Logger.log(`Source sheet ("${STARTER_SHEET_NAME}") getLastRow(): ${lastRow}`);
    if (lastRow < 6) {
      Logger.log("No source data found below row 5 in StarterInv.");
      ui.alert("No data to copy.");
      return;
    }

    const SOURCE_START_ROW = 6;
    const SOURCE_START_COL = 1;
    const SOURCE_NUM_COLS = 46;

    // Identify Invoice No column in row 5 headers of StarterInv
    const sourceHeaders = sourceSheet.getRange(5, 1, 1, SOURCE_NUM_COLS).getValues()[0];
    let sourceInvColIdx = sourceHeaders.findIndex(h => String(h || '').trim().toLowerCase() === 'invoice no');
    if (sourceInvColIdx === -1) {
      sourceInvColIdx = 42; // Fallback to column AQ (0-indexed 42)
    }
    Logger.log(`StarterInv "Invoice no" header index: ${sourceInvColIdx}`);

    const numRowsToRead = lastRow - SOURCE_START_ROW + 1;
    const sourceRange = sourceSheet.getRange(SOURCE_START_ROW, SOURCE_START_COL, numRowsToRead, SOURCE_NUM_COLS);
    const allData = sourceRange.getValues();
    Logger.log(`Read ${allData.length} row(s) from StarterInv.`);

    // --- 4. FILTER NEW INVOICES NOT ALREADY ON CONFIRMED ---
    const dataToCopy = [];
    let skippedCount = 0;

    for (let i = 0; i < allData.length; i++) {
      const row = allData[i];
      // Skip blank rows
      if (!row.some(cell => cell !== null && cell !== undefined && String(cell).trim() !== '')) {
        continue;
      }

      // Check invoice number
      const invNoRaw = row[sourceInvColIdx];
      if (invNoRaw === null || invNoRaw === undefined) {
        continue;
      }
      const invNo = String(invNoRaw).trim();

      // Skip rows where invoice number is blank or an error (such as #N/A)
      if (invNo === '' || invNo.startsWith('#')) {
        continue;
      }

      const invNoKey = invNo.toLowerCase();
      if (existingInvoiceRefs.has(invNoKey)) {
        skippedCount++;
        continue;
      }

      // Add to set to avoid duplicates within the source data itself
      existingInvoiceRefs.add(invNoKey);
      dataToCopy.push(row);
    }

    Logger.log(`Filtered dataToCopy count: ${dataToCopy.length}, skipped existing count: ${skippedCount}`);

    if (dataToCopy.length === 0) {
      if (skippedCount > 0) {
        const msg = `No new invoices to copy. All ${skippedCount} invoice(s) already exist on the Confirmed tab.`;
        Logger.log(msg);
        ui.alert(msg);
      } else {
        const msg = "No data to copy.";
        Logger.log(msg);
        ui.alert(msg);
      }
      return;
    }

    // --- 5. APPEND NEW INVOICES TO CONFIRMED TAB ---
    // Start at row 3 minimum (rows 1 and 2 are header / sub-header)
    const newRow = Math.max(3, lastRowWithContent + 1);
    const endRow = newRow + dataToCopy.length - 1;
    const maxRows = targetSheet.getMaxRows();
    Logger.log(`Appending ${dataToCopy.length} rows to Confirmed from row ${newRow} to ${endRow} (Target sheet maxRows: ${maxRows})`);

    if (endRow > maxRows) {
      const rowsToAdd = endRow - maxRows + 10;
      targetSheet.insertRowsAfter(maxRows, rowsToAdd);
      Logger.log(`Expanded target sheet from ${maxRows} to ${targetSheet.getMaxRows()} rows.`);
    }

    const destinationRange = targetSheet.getRange(newRow, 1, dataToCopy.length, dataToCopy[0].length);
    destinationRange.setValues(sanitizeSheetMatrix_(dataToCopy));
    (await SpreadsheetApp.flush());
    Logger.log(`Successfully written ${dataToCopy.length} row(s) to Confirmed!R${newRow}C1:R${endRow}C${dataToCopy[0].length}`);

    const alertMsg = skippedCount > 0
      ? `Successfully copied ${dataToCopy.length} new invoice(s) to Confirmed (Rows ${newRow} to ${endRow}) in "${targetSsName}". (${skippedCount} existing invoice(s) skipped)`
      : `Successfully copied ${dataToCopy.length} invoice(s) to Confirmed (Rows ${newRow} to ${endRow}) in "${targetSsName}".`;

    Logger.log(alertMsg);
    ui.alert(alertMsg);
  } catch (e) {
    Logger.log(`ERROR in StarterPushInvToConfirmed: ${e.message}\n${e.stack}`);
    ui.alert(`An unexpected error occurred: ${e.message}`);
  }
}


async function StarterPushPLToOutgoings() {
  const SOURCE_SHEET_NAME = "StarterPL";
  const TARGET_SHEET_NAME = "Outgoings";
  const CLIENT_SHEET_ID = (await getKeyInfoValue('X28'));
  const ui = SpreadsheetApp.getUi();
  const logs = [];
  
  if (!CLIENT_SHEET_ID) { ui.alert('Error: SHEET_ID_CLIENT is not set.');
  return; }

  try {
    const sourceSs = SpreadsheetApp.getActiveSpreadsheet();
    const sourceSheet = sourceSs.getSheetByName(SOURCE_SHEET_NAME);
    if (!sourceSheet) { ui.alert(`Error: Source sheet "${SOURCE_SHEET_NAME}" not found.`); return; }

    const targetSs = (await SpreadsheetApp.openById(CLIENT_SHEET_ID));
    const targetSheet = targetSs.getSheetByName(TARGET_SHEET_NAME);
    if (!targetSheet) { ui.alert(`Error: Target sheet "${TARGET_SHEET_NAME}" not found.`); return;
    }

    // --- 1. MAP TARGET SHEET STRUCTURE ---
    const targetDataA = targetSheet.getRange("A:A").getValues().flat();
    const contractorsHeaderIndex = targetDataA.indexOf("Contractors");
    const expensesHeaderIndex = targetDataA.indexOf("Other expenses");
    const findTotalIndex = (possibleNames) => targetDataA.findIndex(val => possibleNames.includes(val));
    const totalContractorRowIndex = findTotalIndex(["Total contractor cost", "Total contr. cost - delivery"]);
    const totalExpensesRowIndex = findTotalIndex(["Total other expenses", "Total other expenses - delivery"]);
    if (contractorsHeaderIndex === -1 || totalContractorRowIndex === -1) { ui.alert('Error: Contractor headers missing in Outgoings.'); return;
    }
    if (expensesHeaderIndex === -1 || totalExpensesRowIndex === -1) { ui.alert('Error: Expense headers missing in Outgoings.'); return;
    }

    // Define Ranges
    const contractorStartRow = contractorsHeaderIndex + 3;
    const contractorSectionLastRow = totalContractorRowIndex - 2;
    
    const expenseStartRow = expensesHeaderIndex + 3;
    const expenseSectionLastRow = totalExpensesRowIndex - 1; 

    // Safety Check: Ensure target is empty before writing
    const contractorRangeToCheck = targetSheet.getRange(contractorStartRow, 1, contractorSectionLastRow - contractorStartRow + 1, 4);
    const expenseRangeToCheck = targetSheet.getRange(expenseStartRow, 1, expenseSectionLastRow - expenseStartRow + 1, 4);
    const hasData = (range) => range.getDisplayValues().some(row => row.some(cell => cell !== ''));
    if (hasData(contractorRangeToCheck) || hasData(expenseRangeToCheck)) {
       ui.alert("Outgoings tab contains data in the target range. Please clear it first.");
       return;
    }

    // --- 2. READ SOURCE DATA ---
    const sourceDataP = sourceSheet.getRange("P:P").getValues().flat();
    const overheadsHeaderIndex = sourceDataP.indexOf("Overheads");
    if (overheadsHeaderIndex === -1) { ui.alert('Error: "Overheads" header missing in StarterPL.'); return;
    }
    
    let overheadsEndIndex = sourceDataP.slice(overheadsHeaderIndex + 1).indexOf("");
    overheadsEndIndex = (overheadsEndIndex === -1) ?
    sourceDataP.length : overheadsHeaderIndex + 1 + overheadsEndIndex;

    const sourceCategoryMap = new Map();
    let depreciationCategory = null;
    // Scan Overheads
    for (let i = overheadsHeaderIndex + 1; i < overheadsEndIndex; i++) {
      const category = sourceDataP[i];
      if (category) {
        const trimmed = category.toString().trim();
        sourceCategoryMap.set(trimmed, { row: i + 1, type: 'Overhead' });
        if (trimmed.includes("Depreciation")) depreciationCategory = trimmed;
      }
    }

    // B. Identify Costs of Sale (Scanning Upwards)
    const otherCosTotalIndex = sourceDataP.indexOf("Other costs of sale total");
    const corpTaxTotalIndex = sourceDataP.indexOf("Corporation tax total");

    if (otherCosTotalIndex !== -1 && corpTaxTotalIndex !== -1) {
      for (let i = otherCosTotalIndex - 1; i > corpTaxTotalIndex; i--) {
        const category = sourceDataP[i];
        if (category) {
          const trimmed = category.toString().trim();
          if (!sourceCategoryMap.has(trimmed)) {
            sourceCategoryMap.set(trimmed, { row: i + 1, type: 'CoS' });
          }
        }
      }
    }

    // Prepare List of Categories to Write (Excluding Depreciation which has its own slot)
    const categoriesToWrite = Array.from(sourceCategoryMap.keys()).filter(cat => cat !== depreciationCategory);
    // Identify Staff Costs
    const cosStaffIndex = sourceDataP.indexOf("CoS staff costs total");
    const nonCosStaffIndex = sourceDataP.indexOf("Non-CoS staff costs total");

    // --- 3. BATCH WRITE STRUCTURE & DEFAULTS ---
    
    // Clear Ranges First
    contractorRangeToCheck.clearContent();
    expenseRangeToCheck.clearContent();

    const DEFAULTS_OVERHEAD = ["Yes", "Curr", "Curr", "0%", "100%"];
    const DEFAULTS_COS      = ["No", "Curr", "Curr", "100%", "100%"];
    if (categoriesToWrite.length > 0) {
       // Prepare 2D Array for Names (Col 1)
       const namesValues = categoriesToWrite.map(c => [c]);
       // Prepare 2D Array for Defaults (Cols 2-6)
       const settingsValues = categoriesToWrite.map(cat => {
          const type = sourceCategoryMap.get(cat).type;
          return (type === 'CoS') ? DEFAULTS_COS : DEFAULTS_OVERHEAD;
       });
       // Bulk Write Names
       targetSheet.getRange(expenseStartRow, 1, namesValues.length, 1).setValues(sanitizeSheetMatrix_(namesValues));
       // Bulk Write Settings
       targetSheet.getRange(expenseStartRow, 2, settingsValues.length, 5).setValues(settingsValues);
    }

    // Handle Depreciation (Fixed Row)
    const depreciationTargetRow = expenseSectionLastRow - 1;
    if (depreciationCategory) {
       targetSheet.getRange(depreciationTargetRow, 1).setValue(sanitizeSheetCell_(depreciationCategory));
       targetSheet.getRange(depreciationTargetRow, 2, 1, 5).setValues([DEFAULTS_OVERHEAD]);
    }

    // Handle Staff Totals (Fixed Rows)
    // Note: "Other costs of sale total" row is intentionally REMOVED per instructions.
    targetSheet.getRange(contractorSectionLastRow - 1, 1, 1, 6).setValues([["Non-CoS staff costs total", "Yes", "Curr", "Curr", "0%", "100%"]]);
    targetSheet.getRange(contractorSectionLastRow, 1, 1, 6).setValues([["CoS staff costs total", "Yes", "Curr", "Curr", "100%", "100%"]]);
    
    (await SpreadsheetApp.flush());
    // --- 4. BATCH WRITE MONTHLY DATA ---
    const CHECKBOX_ROW = 82;
    const checkboxes = sourceSheet.getRange(CHECKBOX_ROW, 17, 1, 12).getValues()[0];
    const sourceMonthHeadersRaw = sourceSheet.getRange(1, 17, 1, 12).getValues()[0];
    const targetMonthHeadersRaw = targetSheet.getRange(1, 1, 1, targetSheet.getLastColumn()).getValues()[0];

    const formatDateAsString = (d) => (d instanceof Date) ?
    d.toLocaleString('en-GB', { month: 'long', year: 'numeric' }) : (d ? d.toString().trim() : '');
    const sourceMonthHeaders = sourceMonthHeadersRaw.map(formatDateAsString);
    const targetMonthHeaders = targetMonthHeadersRaw.map(formatDateAsString);

    let monthsProcessed = 0;

    // We need to map where every category ended up in the Target Sheet to write data efficiently
    // Read the names we just wrote to map them back to row numbers
    const writtenCategories = targetSheet.getRange(expenseStartRow, 1, categoriesToWrite.length, 1).getValues().flat();
    const targetRowMap = new Map();
    writtenCategories.forEach((cat, idx) => {
       if (cat) targetRowMap.set(cat.toString().trim(), expenseStartRow + idx);
    });
    checkboxes.forEach((isChecked, i) => {
      if (!isChecked) return;
      monthsProcessed++;

      const sourceColIndex = 17 + i; // 1-based index for Source Column
      const sourceMonth = sourceMonthHeaders[i];
      const targetColIndex = targetMonthHeaders.indexOf(sourceMonth) + 1; // 1-based index for Target Column
      
      if (targetColIndex === 0) { logs.push(`Skipped month ${sourceMonth}`); return; }

      // 1. Prepare Batch Updates for Categories
      const updates = [];
      categoriesToWrite.forEach(cat => {
          const info = sourceCategoryMap.get(cat);
          const targetRow = targetRowMap.get(cat);
          
          if (info && targetRow) {
             const val = sourceSheet.getRange(info.row, sourceColIndex).getValue();
             if (val !== 0 && val !== "") {
                 updates.push({ row: targetRow, col: targetColIndex, val: val });
             }
          }
      });
      // 2. Perform Batch Writes for this Month 
      if (updates.length > 0) {
         // Read current column data for the Expense Section
         const rangeHeight = categoriesToWrite.length;
         const targetRange = targetSheet.getRange(expenseStartRow, targetColIndex, rangeHeight, 1);
         const columnData = targetRange.getValues();

         // Update in memory
         updates.forEach(u => {
             const relativeRow = u.row - expenseStartRow;
             if (relativeRow >= 0 && relativeRow < rangeHeight) {
                 columnData[relativeRow][0] = u.val;
             }
         });

         // Write back column at once
         targetRange.setValues(columnData);
      }

      // 3. Write Staff Totals (Individual writes are fine here as there are only 2)
      const nonCosVal = sourceSheet.getRange(nonCosStaffIndex + 1, sourceColIndex).getValue();
      const cosVal = sourceSheet.getRange(cosStaffIndex + 1, sourceColIndex).getValue();
      
      targetSheet.getRange(contractorSectionLastRow - 1, targetColIndex).setValue(nonCosVal);
      targetSheet.getRange(contractorSectionLastRow, targetColIndex).setValue(cosVal);
    });
    if (monthsProcessed > 0) { ui.alert(`Successfully processed ${monthsProcessed} month(s).`); } 
    else { ui.alert("No months were checked.");
    }

  } catch (e) {
    ui.alert(`An unexpected error occurred: ${e.message}`);
    console.error(e);
  }
}

// --- QB/XERO CREATE INVOICE HELPER FUNCTIONS ---

function buildQBHeaderMap(headers, landmarkColIndex, startIndex) { return buildXeroHeaderMap(headers, landmarkColIndex, startIndex);
}

function validateQBHeaders(invCompMap, confirmedMap, ui) {
  const requiredInvComp = ['Client', 'Job', 'Total excl VAT', 'Sent date', 'VAT included', 'Push inv?'];
  const requiredConfirmed = ['Client', 'Project name', 'Inv 1 ref', 'Inv 2 ref', 'Inv 3 ref', 'Inv 1 status', 'Inv 2 status', 'Inv 3 status'];
  const missingInvComp = requiredInvComp.filter(h => invCompMap[h] === undefined);
  const missingConfirmed = requiredConfirmed.filter(h => confirmedMap[h] === undefined);
  if (missingInvComp.length > 0 || missingConfirmed.length > 0) {
    if (ui) ui.alert(`Script stopped due to missing headers.`);
    return false;
  }
  return true;
}

function applyQBChanges(sheet, changeLog, confirmedData) {
  const rangesToFormat = [];
  changeLog.forEach(change => {
    const { row, col } = change;
    const value = confirmedData[row - 1][col - 1];
    const range = sheet.getRange(row, col);
    range.setValue(sanitizeSheetCell_(value));
    rangesToFormat.push(range.getA1Notation());
  });
  if (rangesToFormat.length > 0) { sheet.getRangeList(rangesToFormat).setFontWeight('bold'); }
}

function buildXeroHeaderMap(headers, landmarkColIndex, startIndex) {
  const map = {};
  const dashboardListHeaders = ['Client', 'Job', 'Total excl VAT', 'Sent date', 'VAT included'];
  const appCompareHeaders = ['Invoice no', 'Push inv?'];
  for (let i = startIndex; i <= landmarkColIndex; i++) {
    const normalizedHeader = headers[i].toString().trim();
    if (dashboardListHeaders.includes(normalizedHeader) && map[normalizedHeader] === undefined) { map[normalizedHeader] = i;
    }
  }
  for (let i = landmarkColIndex + 1; i < headers.length; i++) {
    const normalizedHeader = headers[i].toString().trim();
    if (appCompareHeaders.includes(normalizedHeader) && map[normalizedHeader] === undefined) { map[normalizedHeader] = i; }
  }
  return map;
}

function validateXeroHeaders(invCompMap, confirmedMap, ui) {
  const requiredInvComp = ['Client', 'Job', 'Total excl VAT', 'Sent date', 'VAT included', 'Push inv?'];
  const requiredConfirmed = ['Client', 'Project name', 'Revenue - total / per month (excl VAT)', 'Inv 1 ref', 'Inv 2 ref', 'Inv 3 ref', 'Inv 1 status', 'Inv 2 status', 'Inv 3 status'];
  const missingInvComp = requiredInvComp.filter(h => invCompMap[h] === undefined);
  const missingConfirmed = requiredConfirmed.filter(h => confirmedMap[h] === undefined);
  if (missingInvComp.length > 0 || missingConfirmed.length > 0) {
    if (ui) ui.alert(`Script stopped due to missing headers.`);
    return false;
  }
  return true;
}

function applyXeroChanges(sheet, changeLog, confirmedData) {
  const rangesToFormat = [];
  changeLog.forEach(change => {
    const { row, col } = change;
    const value = confirmedData[row - 1][col - 1];
    const range = sheet.getRange(row, col);
    range.setValue(sanitizeSheetCell_(value));
    rangesToFormat.push(range.getA1Notation());
  });
  if (rangesToFormat.length > 0) { sheet.getRangeList(rangesToFormat).setFontWeight('bold'); }
}

function findMatchingSlotInConfirmed(details, confirmedData, headerMap) {
  const clientIndex = headerMap['Client'];
  const projectIndex = headerMap['Job name'];
  for (let i = 1; i < confirmedData.length; i++) {
    const rowData = confirmedData[i];
    if (rowData[clientIndex] === details.client && rowData[projectIndex] === details.job) {
      for (let j = 1; j <= 3; j++) {
        const amountHeader = j === 1 ?
        'Project invoice 1 / monthly retainer (excl VAT)' : `Project invoice ${j} (excl VAT)`;
        const refHeader = `Inv ${j} ref`;
        const existingAmount = parseFloat(rowData[headerMap[amountHeader]]);
        const newAmount = parseFloat(details.totalExclVat);
        if (!isNaN(existingAmount) && !isNaN(newAmount) && existingAmount === newAmount && isCellEmpty(rowData[headerMap[refHeader]])) {
          return { row: i + 1, invSection: j };
        }
      }
    }
  }
  return null;
}

