async function saveQuickBooksSettings(settings) {
  try {
    if (typeof getKeyInfoValue !== 'function') { throw new Error("Helper function getKeyInfoValue is missing.");
    }
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheetByName("KeyInfo");
    if (!sheet) { throw new Error("Sheet 'KeyInfo' not found."); }
    
    let standardTaxToSave = settings.taxCode;
    let zeroTaxToSave = settings.nonTaxCode;
    const taxRegion = (await getKeyInfoValue('X5'))?.trim().toUpperCase();
    if (taxRegion === 'US') {
        if (settings.taxCode.toLowerCase().includes('sales')) standardTaxToSave = 'TAX';
        if (settings.nonTaxCode.toLowerCase().includes('no tax') || settings.nonTaxCode.toLowerCase().includes('exempt')) zeroTaxToSave = 'NON';
    }
    sheet.getRange("X7").setValue(sanitizeSheetCell_(settings.item));
    sheet.getRange("X10").setValue(sanitizeSheetCell_(standardTaxToSave));
    sheet.getRange("X11").setValue(sanitizeSheetCell_(zeroTaxToSave));
    return "Settings saved successfully!";
  } catch (e) {
    Logger.log("Failed to save settings: " + e.message);
    throw new Error("Failed to save settings.");
  }
}

async function getQuickBooksItems() {
  const accessToken = (await getQBAccessToken()); 
  const realmId = String((await getKeyInfoValue('X3')) || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
  const baseUrl = "https://quickbooks.api.intuit.com";
  const query = encodeURIComponent("SELECT Name FROM Item WHERE Type = 'Service' AND Active = true");
  const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
  const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
  const response = (await UrlFetchApp.fetch(url, options));
  if (response.getResponseCode() !== 200) { throw new Error(`API Error fetching items: ${response.getResponseCode()}`);
  }
  const jsonResponse = JSON.parse(response.getContentText());
  return jsonResponse.QueryResponse && jsonResponse.QueryResponse.Item ? jsonResponse.QueryResponse.Item.map(item => item.Name) : [];
}

async function getQuickBooksTaxCodes() {
  const accessToken = (await getQBAccessToken());
  const realmId = String((await getKeyInfoValue('X3')) || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
  const baseUrl = "https://quickbooks.api.intuit.com";
  const query = encodeURIComponent("SELECT Name FROM TaxCode WHERE Active = true");
  const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
  const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
  const response = (await UrlFetchApp.fetch(url, options));
  if (response.getResponseCode() !== 200) { throw new Error(`API Error fetching tax codes: ${response.getResponseCode()}`);
  }
  const jsonResponse = JSON.parse(response.getContentText());
  return jsonResponse.QueryResponse && jsonResponse.QueryResponse.TaxCode ? jsonResponse.QueryResponse.TaxCode.map(taxCode => taxCode.Name) : [];
}

async function logMyQuickBooksTaxCodesWithIDs() {
  Logger.log('--- Running Tax Code Diagnostic (with IDs) ---');
  try {
    const accessToken = (await getQBAccessToken());
    const realmId = String((await getKeyInfoValue('X3')) || '').trim();
    if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) {
      throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
    }
    const baseUrl = "https://quickbooks.api.intuit.com";
    const query = encodeURIComponent("SELECT Id, Name FROM TaxCode WHERE Active = true");
    const url = `${baseUrl}/v3/company/${realmId}/query?query=${query}`;
    const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
    const response = (await UrlFetchApp.fetch(url, options));
    if (response.getResponseCode() !== 200) { throw new Error(`API Error: ${response.getContentText()}`);
    }
    const jsonResponse = JSON.parse(response.getContentText());
    if (jsonResponse.QueryResponse?.TaxCode?.length > 0) {
      jsonResponse.QueryResponse.TaxCode.forEach(taxCode => Logger.log(`Name: "${taxCode.Name}", ID: "${taxCode.Id}"`));
    } else {
      Logger.log('No active tax codes found.');
    }
  } catch (e) {
    Logger.log('Failed to fetch tax codes with IDs: ' + e.message);
  }
}

