/**
 * =========================================
 * ==      CRM TASKS (CRMComp) LOGIC      ==
 * =========================================
 *
 * v3.05 (Enforce KeyInfo!Q9 stage scope and expectedStageName guard in updateCheckedRows and updateCheckedRowsRight to prevent Confirmed writes on Pipeline-only clients)
 * v3.04 (Ensure newly populated parent rows in Pipeline and Confirmed are unhidden when created by CRM sync)
 * v3.03 (Apply sanitizeSheetCell_ to CRM discrepancy updates, new row creations, child-row cascades, and instant Pipeline/Confirmed copies)
 * v3.02 (Fix out-of-bounds row range crash on 5002 rows, defer 'Copied to confirmed tab?' until Confirmed copy succeeds, add self-healing recovery, and return instantLogs to AutoLog)
 * v3.01 (enforce d-MMM-yy format eg 7-Aug-26 when writing Date conf to Column D of Confirmed tab)
 * v3.00 (preserve pipeline invoices and direct expenses when copying to Confirmed even if dates or revenue changed)
 * 
 */

function findColumnIndexes(sectionHeaders, columnHeaders, config) {
  const VALID_SECTIONS = ['Dashboard compare', 'Actions required', 'CRM compare', 'Actions required 2'];
  const results = {};
  const errors = [];
  const columnToSectionMap = new Array(sectionHeaders.length);
  let currentSection = '';
  for (let i = 0; i < sectionHeaders.length; i++) {
    const sectionName = (sectionHeaders[i] || '').toString().trim();
    if (VALID_SECTIONS.some(validSection => validSection.toLowerCase() === sectionName.toLowerCase())) {
      currentSection = sectionName.toLowerCase();
    }
    columnToSectionMap[i] = currentSection;
  }

  for (const key in config) {
    const sectionToFind = config[key].section.toLowerCase();
    const headersToFind = Array.isArray(config[key].header) ? config[key].header : [config[key].header];
    
    let found = false;
    for (let i = 0; i < columnHeaders.length; i++) {
      const currentColumnHeader = (columnHeaders[i] || '').toString().trim().toLowerCase();
      const mappedSection = columnToSectionMap[i];

      if (mappedSection === sectionToFind && headersToFind.map(h => h.toLowerCase()).includes(currentColumnHeader)) {
        results[key] = i + 1;
        found = true;
        break;
      }
    }
    if (!found) {
      // Optional columns (don't error if missing, just log)
      if (['dateConfCol','leadSrcCol','directCostsCol','prodLineCol'].includes(key)) {
         results[key] = -1;
      } else {
         errors.push(`- Column "${headersToFind.join(' or ')}" under section "${config[key].section}" was not found.`);
         results[key] = -1;
      }
    }
  }
  results.errorList = errors;
  return results;
}

function valuesAreDifferent(val1, val2) {
  const v1 = (val1 === null || val1 === undefined) ? "" : val1;
  const v2 = (val2 === null || val2 === undefined) ? "" : val2;
  if (v1 === v2) return false;
  
  // STRICT DATE GUARD: Normalize dates to YYYY-MM-DD
  const toSafeYmd = (v) => {
    if (v === null || v === undefined || v === "") return null;
    if (typeof normalizeDateToYmd_ === 'function') {
      const res = normalizeDateToYmd_(v);
      if (res) return res;
    }
    if (v instanceof Date) {
      if (isNaN(v.getTime())) return null;
      const y = v.getFullYear();
      const m = String(v.getMonth() + 1).padStart(2, '0');
      const d = String(v.getDate()).padStart(2, '0');
      return `${y}-${m}-${d}`;
    }
    if (typeof v === 'number' && v > 20000 && v < 70000) {
      const epoch = new Date(1899, 11, 30);
      const d = new Date(epoch.getTime() + Math.round(v * 86400000));
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}`;
    }
    if (typeof v === 'string') {
      const s = v.trim();
      if (!s) return null;
      const isoMatch = s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[T\s].*)?$/);
      if (isoMatch) {
        return `${isoMatch[1]}-${isoMatch[2].padStart(2, '0')}-${isoMatch[3].padStart(2, '0')}`;
      }
      const dmyMatch = s.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})$/);
      if (dmyMatch) {
        let y = dmyMatch[3];
        if (y.length === 2) y = (parseInt(y, 10) > 50 ? '19' : '20') + y;
        return `${y}-${dmyMatch[2].padStart(2, '0')}-${dmyMatch[1].padStart(2, '0')}`;
      }
      if (/^\d/.test(s)) {
        const d = new Date(s);
        if (!isNaN(d.getTime())) {
          const y = d.getFullYear();
          const m = String(d.getMonth() + 1).padStart(2, '0');
          const day = String(d.getDate()).padStart(2, '0');
          return `${y}-${m}-${day}`;
        }
      }
    }
    return null;
  };

  const ymd1 = toSafeYmd(v1);
  const ymd2 = toSafeYmd(v2);

  // If BOTH resolve to calendar dates, compare their Y-M-D
  if (ymd1 && ymd2) {
    return ymd1 !== ymd2;
  }

  // If ONLY ONE is a date (and the other isn't completely blank), they are definitely different
  if (ymd1 || ymd2) {
    if (String(v1).trim() === "" || String(v2).trim() === "") return true;
    return true;
  }

  // Standard numeric check with penny tolerance
  const n1 = (typeof v1 === 'number') ? v1 : (typeof v1 === 'string' && v1.trim() !== '' && !isNaN(Number(v1)) ? Number(v1) : NaN);
  const n2 = (typeof v2 === 'number') ? v2 : (typeof v2 === 'string' && v2.trim() !== '' && !isNaN(Number(v2)) ? Number(v2) : NaN);
  if (!isNaN(n1) && !isNaN(n2)) {
    return Math.abs(n1 - n2) > 0.005;
  }

  // Fallback to strict string comparison
  const s1 = String(v1).replace(/[\u00A0\s]+/g, ' ').trim();
  const s2 = String(v2).replace(/[\u00A0\s]+/g, ' ').trim();
  return s1 !== s2;
}

async function updateCheckedRows(isHeadless, expectedStageName) {
  const ui = isHeadless ? null : SpreadsheetApp.getUi();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const alertSheet = ss.getSheetByName("DataChgAlert");
  const keyInfoSheet = ss.getSheetByName("KeyInfo");
  
  const invoiceGenMode = alertSheet ? alertSheet.getRange("B50").getValue() : "None";
  const retainerDay = alertSheet ? (parseInt(alertSheet.getRange("B51").getValue()) || 0) : 0;
  
  // --- NEW: Default Days ---
  const defaultDays = alertSheet ? (parseInt(alertSheet.getRange("B52").getValue()) || 30) : 30;

  const pipelineMode = keyInfoSheet ? keyInfoSheet.getRange("Q9").getValue() : "";
  const copyToConfFlag = alertSheet ? alertSheet.getRange("B82").getValue() : "No";
  
  const COLUMN_CONFIG = {
    checkboxCol:        { section: 'Dashboard compare', header: 'Update?' },
    dataStartCol:       { section: 'Actions required',  header: 'Client' },
    idCol:              { section: 'Actions required',  header: 'Project code' },
    copiedStatusColSrc: { section: 'Actions required',  header: 'Copied to confirmed tab?' },
    jobCol:             { section: 'Actions required',  header: ['Job name', 'Job'] },
    revenueCol:         { section: 'Actions required',  header: 'Revenue' },
    startDateCol:       { section: 'Actions required',  header: 'Start date' },
    endDateCol:         { section: 'Actions required',  header: 'End date' },
    jobTypeCol:         { section: 'Actions required',  header: ['Project / retainer', 'Type'] },
    dateConfCol:        { section: 'Actions required',  header: 'Date conf' },
    leadSrcCol:         { section: 'Actions required',  header: 'Lead src' },
    directCostsCol:     { section: 'Actions required',  header: 'Direct costs' },
    prodLineCol:        { section: 'Actions required',  header: 'Prod. line' }
  };
  
  const sourceSpreadsheetId = (await getKeyInfoValue('X28'));
  const sourceIdCol = 3;
  const sourceDataStartCol = 1;
  const discrepancyDataNumCols = 40;
  const result = { count: 0, jobsToCheck: [], revertedJobs: [], deletedJobs: [], logs: [] };
  
  if (!sourceSpreadsheetId) return result;
  const discrepancySheet = ss.getSheetByName('CRMComp');
  if (!discrepancySheet) return result;
  
  const sectionHeaders = discrepancySheet.getRange('4:4').getValues()[0];
  const columnHeaders = discrepancySheet.getRange('5:5').getValues()[0];
  const foundColumns = findColumnIndexes(sectionHeaders, columnHeaders, COLUMN_CONFIG);
  
  if (foundColumns.errorList.length > 0) { 
    if (ui) ui.alert('Error: Columns not found.\n' + foundColumns.errorList.join('\n'));
  }

  const { checkboxCol, dataStartCol, idCol, copiedStatusColSrc, revenueCol, startDateCol, endDateCol, jobCol, jobTypeCol, dateConfCol, leadSrcCol, directCostsCol, prodLineCol } = foundColumns;
  const sourceSheetName = String(discrepancySheet.getRange('B2').getValue() || '').trim();
  const modeCleanGuard = String(pipelineMode || '').trim().toLowerCase();

  if (expectedStageName && sourceSheetName !== expectedStageName) {
    const msg = `Blocked CRM Dashboard Compare write: CRMComp!B2 ("${sourceSheetName}") does not match expected stage ("${expectedStageName}").`;
    console.warn(msg);
    if (checkboxCol > 0) discrepancySheet.getRange(6, checkboxCol, 1001, 1).setValue(false);
    return result;
  }
  if (sourceSheetName === 'Confirmed' && modeCleanGuard !== 'pipeandconf' && modeCleanGuard !== 'confirmed') {
    const msg = `Blocked CRM Dashboard Compare write to Confirmed tab because KeyInfo!Q9 is "${pipelineMode}" (Pipeline-only).`;
    console.warn(msg);
    if (checkboxCol > 0) discrepancySheet.getRange(6, checkboxCol, 1001, 1).setValue(false);
    if (ui) ui.alert(msg);
    return result;
  }

// --- TRANSLATION DICTIONARY ---
  const SETTINGS_TO_HEADERS_MAP = {
      "Client mismatch?":       ["client"],
      "Job name mismatch?":     ["job name", "job"],
      "Revenue mismatch?":      ["revenue", "revenue (proj total / ongoing pm) - excl vat"],
      "Direct costs mismatch?": ["direct costs", "direct costs (proj total / ongoing pm) - excl vat"],
      "Start date mismatch?":   ["start date"],
      "End date mismatch?":     ["end date"],
      "% likel. mismatch":      ["% likel."]
  };

  const dashRange = sourceSheetName === 'Pipeline' ? 'A59:B66' : 'D59:E66';
  const dashSettings = getDiscrepancySettings(alertSheet, dashRange);
  
  // --- BULLETPROOF HEADER NORMALIZER ---
  // Strips ALL spaces, dashes, brackets, and invisible characters so matches never fail.
  const normalizeHdr = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");

  // Combine exclude AND ignore for column masking ONLY
  const excludedDataHeaders = [];
  const itemsToStrip = [...(dashSettings.exclude || []), ...(dashSettings.ignore || [])];
  
  // Actually populate the array using the dictionary, heavily normalized
  itemsToStrip.forEach(setting => {
      const cleanSetting = String(setting).trim();
      if (SETTINGS_TO_HEADERS_MAP[cleanSetting]) {
          SETTINGS_TO_HEADERS_MAP[cleanSetting].forEach(h => {
              excludedDataHeaders.push(normalizeHdr(h));
          });
      }
  });

  let sourceSs;
  try {
    sourceSs = (await SpreadsheetApp.openById(sourceSpreadsheetId));
  } catch (e) {
    result.logs.push(`Error: CRM Workflow - Could not open Client Sheet: ${e.message}`);
    result.hasError = true;
    result.error = e.message;
    return result;
  }
  const sourceSheet = sourceSs.getSheetByName(sourceSheetName);
  if (!sourceSheet) {
    result.logs.push(`Error: CRM Workflow - Sheet '${sourceSheetName}' not found in Client Spreadsheet.`);
    result.hasError = true;
    result.error = `Sheet '${sourceSheetName}' not found in Client Spreadsheet.`;
    return result;
  }

  let copiedStatusColDest = -1;
  const sourceHeaders = sourceSheet.getRange(1, 1, 1, sourceSheet.getLastColumn()).getValues()[0];

  // FIXED: Bulletproof header search ignores spaces, question marks, and casing
  if (sourceSheetName === 'Pipeline') {
    const destIdx = sourceHeaders.findIndex(h => String(h || "").toLowerCase().replace(/[^a-z0-9]/g, '') === 'copiedtoconfirmedtab');
    copiedStatusColDest = destIdx !== -1 ? destIdx + 1 : -1;
  }
  
  // FIXED: Dynamically find the Project Code column instead of hardcoding '3'
  let actualSourceIdCol = sourceHeaders.findIndex(h => String(h || "").toLowerCase().replace(/[^a-z0-9]/g, '') === 'projectcode') + 1;
  if (actualSourceIdCol === 0) actualSourceIdCol = 3;

  const discrepancyRange = discrepancySheet.getRange(6, 1, 1001, discrepancySheet.getLastColumn());
  const discrepancyData = discrepancyRange.getValues();
  // NEW: Normalize existing IDs
  const sourceIds = sourceSheet.getRange(2, actualSourceIdCol, Math.max(1, sourceSheet.getMaxRows() - 1), 1)
    .getValues()
    .flat()
    .map(id => String(id || "").trim().toUpperCase());
  
  // Find next available row
  let trueLastRow = 0;
  const rowsToRead = Math.min(Math.max(1, sourceSheet.getLastRow() + 1), sourceSheet.getMaxRows());
  const allSourceData = sourceSheet.getRange(1, 1, rowsToRead, 96).getValues();
  for (let i = allSourceData.length - 1; i >= 0; i--) {
    const row = allSourceData[i];
    // ZONE CHECK: A:E (0-4), AG:AM (32-38), AP:BH (41-59), BX:CR (75-95)
    const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
    const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
    const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
    const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
    if (z1 || z2 || z3 || z4) { 
      trueLastRow = i + 1; 
      break; 
    }
  }
  // FIXED: Ensure the earliest row used is Row 3 (leaving Row 2 permanently blank)
  let nextAvailableRow = Math.max(3, trueLastRow + 1);
  for (let i = 0; i < discrepancyData.length; i++) {
    const isChecked = discrepancyData[i][checkboxCol - 1];
    if (isChecked === true) {
      const rawUniqueId = discrepancyData[i][idCol - 1];
      if (!rawUniqueId || String(rawUniqueId).trim() === "") {
        discrepancySheet.getRange(i + 6, checkboxCol).setValue(false);
        continue;
      }
      // FIXED: Immediately cast incoming ID to a string and normalize it to stop type-mismatches
      const uniqueIdToFind = String(rawUniqueId).trim().toUpperCase();

      const clientName = (dataStartCol > 0) ? discrepancyData[i][dataStartCol - 1] : "Unknown";
      const jobName = (jobCol > 0) ? discrepancyData[i][jobCol - 1] : "Unknown";
      const dataToCopy = discrepancyData[i].slice(dataStartCol - 1, dataStartCol - 1 + discrepancyDataNumCols);
      const sourceValue = String(discrepancyData[i][copiedStatusColSrc - 1]);
      let isDeletion = false;
      let wasUpdated = false;
      let datesChanged = false;

      // --- DELETION LOGIC ---
      if (sourceSheetName === 'Confirmed' && sourceValue === 'DELETE') {
         // Normalize the search ID to ensure it matches the normalized master list
          const searchId = String(uniqueIdToFind || "").trim().toUpperCase();
          const targetRowIndex = sourceIds.indexOf(searchId);
         if (targetRowIndex !== -1) {
             const targetRow = targetRowIndex + 2;
             sourceSheet.getRange(targetRow, 1, 1, 39).clearContent();
             sourceSheet.getRange(targetRow, 42, 1, 19).clearContent();
             sourceSheet.getRange(targetRow, 76, 1, 20).clearContent();
             result.deletedJobs.push(uniqueIdToFind);
             result.logs.push(`Deleted Confirmed Job: Row ${targetRow}, ${clientName} (ID: ${uniqueIdToFind})`);
             isDeletion = true;
             wasUpdated = true;
         }
      }

      if (!isDeletion) {
          // Normalize the search ID to ensure it matches the normalized master list
          const searchId = String(uniqueIdToFind || "").trim().toUpperCase();
          const targetRowIndex = sourceIds.indexOf(searchId);
          if (targetRowIndex !== -1) {
            // --- UPDATE EXISTING ROW ---
            const targetRow = targetRowIndex + 2;
            const targetRange = sourceSheet.getRange(targetRow, sourceDataStartCol, 1, discrepancyDataNumCols);
            const existingValues = targetRange.getValues()[0];
            const rowChanges = [];
            
            // CASCADE PREP: Identify if Client or Job Name is changing
            const jobIndexOffset = (jobCol > 0) ? (jobCol - dataStartCol) : -1;
            const revIndexOffset = (revenueCol > 0) ? (revenueCol - dataStartCol) : -1;
            const startIndexOffset = (startDateCol > 0) ? (startDateCol - dataStartCol) : -1;
            
            const endDateIndexOffset = (endDateCol > 0) ? (endDateCol - dataStartCol) : -1;
            
            const oldClient = String(existingValues[0] || "").trim().toLowerCase();
            const oldJob = (jobIndexOffset >= 0) ? String(existingValues[jobIndexOffset] || "").trim().toLowerCase() : "";
            const newClient = String(dataToCopy[0] || "").trim();
            const newJob = (jobIndexOffset >= 0) ? String(dataToCopy[jobIndexOffset] || "").trim() : "";
            
            const clientChanged = valuesAreDifferent(existingValues[0], dataToCopy[0]) && newClient.toUpperCase() !== "IGNORE" && newClient.toUpperCase() !== "<IGNORE>";
            const jobChanged = (jobIndexOffset >= 0) && valuesAreDifferent(existingValues[jobIndexOffset], dataToCopy[jobIndexOffset]) && newJob.toUpperCase() !== "IGNORE" && newJob.toUpperCase() !== "<IGNORE>";

            // CLEAN SLATE PREP: Check if start or end dates are changing
            const newStart = (startIndexOffset >= 0) ? String(dataToCopy[startIndexOffset]).toUpperCase() : "IGNORE";
            const newEnd = (endDateIndexOffset >= 0) ? String(dataToCopy[endDateIndexOffset]).toUpperCase() : "IGNORE";
            const startDateChanged = (startIndexOffset >= 0) && valuesAreDifferent(existingValues[startIndexOffset], dataToCopy[startIndexOffset]) && newStart !== "IGNORE" && newStart !== "<IGNORE>";
            const endDateChanged = (endDateIndexOffset >= 0) && valuesAreDifferent(existingValues[endDateIndexOffset], dataToCopy[endDateIndexOffset]) && newEnd !== "IGNORE" && newEnd !== "<IGNORE>";
            datesChanged = startDateChanged || endDateChanged;

            for (let j = 0; j < discrepancyDataNumCols; j++) {
              const headerIndex = (dataStartCol - 1) + j;
              // Normalize both headers before checking the array
              const crmHeader = normalizeHdr(columnHeaders[headerIndex]);
              const destHeader = normalizeHdr(sourceHeaders[j]);
              
              const shouldExclude = excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader);

              // --- INJECTED JOB NAME X-RAY ---
              const crmValueStr = String(dataToCopy[j] || "");
              const destValueStr = String(existingValues[j] || "");
              
              if (crmValueStr.includes("HiCarer") || destValueStr.includes("HiCarer")) {
                  console.log(`[JOB NAME X-RAY] Target Row: ${targetRow}`);
                  console.log(`CRM Header: "${crmHeader}" | Dest Header: "${destHeader}"`);
                  console.log(`Excluded by Settings? ${shouldExclude}`);
                  console.log(`Existing Confirmed Value: "${destValueStr}"`);
                  console.log(`Incoming CRM Value: "${crmValueStr}"`);
                  console.log(`Did the script think they were different? ${valuesAreDifferent(existingValues[j], dataToCopy[j])}`);
              }
              // ------------------------------
              
              // Only print to log when evaluating the Direct Costs columns to avoid spam
              if (crmHeader.includes('direct') || destHeader.includes('direct')) {
                  console.log(`[DEBUG 4] Col ${j} | CRM Header: "${crmHeader}" | Dest Header: "${destHeader}" | Was Excluded? ${shouldExclude}`);
              }

              if (shouldExclude) continue;

              const incomingVal = String(dataToCopy[j]).trim().toUpperCase();
                // NEW LOGIC (OPTION A): Update the cell UNLESS it's ignored OR completely blank
                if (valuesAreDifferent(existingValues[j], dataToCopy[j]) && incomingVal !== "IGNORE" && incomingVal !== "<IGNORE>" && incomingVal !== "") {
                    const colToUpdate = sourceDataStartCol + j;
                sourceSheet.getRange(targetRow, colToUpdate).setValue(sanitizeSheetCell_(dataToCopy[j])).setFontStyle('italic');
                wasUpdated = true;
                
                const oldVal = existingValues[j] instanceof Date ? Utilities.formatDate(existingValues[j], ss.getSpreadsheetTimeZone(), "dd/MM/yy") : existingValues[j];
                let newVal = dataToCopy[j];
                
                // FIXED: Convert raw Google Sheets serial numbers back into readable dates for the AutoLog
                if (newVal instanceof Date) {
                    newVal = Utilities.formatDate(newVal, ss.getSpreadsheetTimeZone(), "dd/MM/yy");
                } else if (existingValues[j] instanceof Date && typeof newVal === 'number') {
                    const epoch = new Date(1899, 11, 30);
                    const convertedDate = new Date(epoch.getTime() + Math.round(newVal * 86400000));
                    newVal = Utilities.formatDate(convertedDate, ss.getSpreadsheetTimeZone(), "dd/MM/yy");
                }
                
                // FIXED: Inject a warning if the CRM wipes a previously populated text field blank
                const headerName = destHeader;
                let logString = `${headerName}: '${oldVal}' -> '${newVal}'`;
                if (String(oldVal).trim() !== "" && String(newVal).trim() === "") {
                    logString = `⚠️ WARNING: CRM wiped data blank! ${logString}`;
                }
                rowChanges.push(logString);
              }
            }

            // CASCADE EXECUTION: Update all attached child rows instantly
            if (clientChanged || jobChanged) {
                let cascadeCount = 0;
                let r = targetRow + 1;
                const lastRow = sourceSheet.getLastRow();
                while (r <= lastRow) {
                    const childVals = sourceSheet.getRange(r, sourceDataStartCol, 1, discrepancyDataNumCols).getValues()[0];
                    const childClient = String(childVals[0] || "").trim().toLowerCase();
                    const childJob = (jobIndexOffset >= 0) ? String(childVals[jobIndexOffset] || "").trim().toLowerCase() : "";
                    
                    if (childClient !== oldClient || childJob !== oldJob) break; 
                    
                    // SAFETY GUARD: Ensure it's a true child row (No revenue, no start date)
                    const childRevRaw = (revIndexOffset >= 0) ? childVals[revIndexOffset] : "";
                    const childRev = parseFloat(String(childRevRaw).replace(/[^0-9.-]/g, '')) || 0;
                    const childStart = (startIndexOffset >= 0) ? childVals[startIndexOffset] : "";
                    
                    if (childRev > 0 || (childStart && String(childStart).trim() !== '')) break; // Hit a new distinct project, stop cascading!
                    
                    if (clientChanged) sourceSheet.getRange(r, sourceDataStartCol).setValue(sanitizeSheetCell_(newClient)).setFontStyle('italic');
                    if (jobChanged && jobIndexOffset >= 0) sourceSheet.getRange(r, sourceDataStartCol + jobIndexOffset).setValue(sanitizeSheetCell_(newJob)).setFontStyle('italic');
                    
                    cascadeCount++;
                    r++;
                }
                if (cascadeCount > 0) rowChanges.push(`Cascaded name updates to ${cascadeCount} child row(s)`);
            }

            if (sourceSheetName === 'Pipeline' && copiedStatusColDest > 0 && copiedStatusColSrc > 0) {
              const destCell = sourceSheet.getRange(targetRow, copiedStatusColDest);
              const destValue = String(destCell.getValue());
              if (valuesAreDifferent(sourceValue, destValue)) {
                destCell.setValue(sourceValue).setFontStyle('italic');
                wasUpdated = true;
                let changeReason = "";
                if (destValue === 'Yes' && sourceValue === 'No') changeReason = " (Reverted by Source)";
                rowChanges.push(`Copied Status: '${destValue}' -> '${sourceValue}'${changeReason}`);
                if (sourceValue === 'Yes') result.jobsToCheck.push(uniqueIdToFind);
                if (destValue === 'Yes' && sourceValue === 'No') result.revertedJobs.push(uniqueIdToFind);
              }
            }
            if (wasUpdated) {
                result.logs.push(`Updated ${sourceSheetName}: Row ${targetRow}, ${clientName} | ${jobName} - ${rowChanges.join(", ")}`);
            }

          } else {
            // --- CREATE NEW ROW ---
            if (nextAvailableRow > sourceSheet.getMaxRows()) sourceSheet.insertRowsAfter(sourceSheet.getMaxRows(), 5);
            
            for (let j = 0; j < discrepancyDataNumCols; j++) {
               const headerIndex = (dataStartCol - 1) + j;
               const crmHeader = typeof normalizeHdr === "function" ? normalizeHdr(columnHeaders[headerIndex]) : String(columnHeaders[headerIndex] || "").trim().toLowerCase();
               const destHeader = typeof normalizeHdr === "function" ? normalizeHdr(sourceHeaders[j]) : String(sourceHeaders[j] || "").trim().toLowerCase();
               
               // If excluded, literally skip the cell so underlying formulas/defaults survive
               if (excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader)) continue;

               const val = dataToCopy[j];
               const str = String(val).trim().toUpperCase();
                
               // Do not touch columns marked <IGNORE>, blank, or excluded to protect underlying formulas
               if (str !== "IGNORE" && str !== "<IGNORE>" && str !== "") {
                   sourceSheet.getRange(nextAvailableRow, sourceDataStartCol + j).setValue(sanitizeSheetCell_(val)).setFontStyle('italic');
               }
            }

            wasUpdated = true; 
            try { sourceSheet.unhideRow(sourceSheet.getRange(nextAvailableRow, 1, 1, 1)); } catch (e) {}
            
            // NATIVE DATE CONF INJECTION: Stamp today's date exclusively on the parent row when copying to Confirmed
            if (sourceSheetName === 'Confirmed') {
               const destDateConfCol = sourceHeaders.findIndex(h => String(h||'').trim().toLowerCase() === 'date conf');
               if (destDateConfCol !== -1) {
                   sourceSheet.getRange(nextAvailableRow, destDateConfCol + 1).setValue(new Date()).setNumberFormat("d-MMM-yy").setFontStyle('italic');
               }
            }

            result.logs.push(`Created New ${sourceSheetName} Job: Row ${nextAvailableRow}, ${clientName} | ${jobName}`);
            
            // FIX: Add the new ID to the master list immediately to prevent duplicates in the same run
            sourceIds.push(uniqueIdToFind);
            
            nextAvailableRow++;
          }

          // === COPY TO CONFIRMED LOGIC ===
          const isPipeline = sourceSheetName === 'Pipeline';
          const modeClean = String(pipelineMode).trim().toLowerCase();
          const isPipelineMode = modeClean === 'pipeline' || modeClean === 'pipeandconf';
          const isCopyEnabled = String(copyToConfFlag).trim().toLowerCase() === 'yes';
          const isReadyToCopy = String(sourceValue).trim().toLowerCase() === 'yes';
          if (isPipeline && isPipelineMode && isCopyEnabled && isReadyToCopy) {
              
              // 1. Build the Dynamic Payload
              const dynamicData = {};
              for (let j = 0; j < discrepancyDataNumCols; j++) {
                  const headerIndex = (dataStartCol - 1) + j;
                  const crmHeaderRaw = String(columnHeaders[headerIndex] || "").trim();
                  const destHeaderRaw = String(sourceHeaders[j] || "").trim();
                  
                  const crmHeader = typeof normalizeHdr === "function" ? normalizeHdr(crmHeaderRaw) : crmHeaderRaw.toLowerCase().replace(/[^a-z0-9]/g, "");
                  const destHeader = typeof normalizeHdr === "function" ? normalizeHdr(destHeaderRaw) : destHeaderRaw.toLowerCase().replace(/[^a-z0-9]/g, "");

                  // Respect Dashboard Exclusions
                  const shouldExclude = excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader);
                  if (shouldExclude || !crmHeaderRaw) continue;

                  const val = dataToCopy[j];
                  const str = String(val).trim().toUpperCase();
                  
                  // Respect <IGNORE> tags
                  if (str !== "IGNORE" && str !== "<IGNORE>") {
                      dynamicData[crmHeaderRaw] = val;
                  }
              }

     const sanitizeIgnore = (val) => {
         const str = String(val).trim().toUpperCase();
         // FIXED: Return a special token instead of an empty string to protect formulas
         return (str === "IGNORE" || str === "<IGNORE>") ? "_SKIP_THIS_CELL_" : val;
     };

     // 2. Map the Core Payload + Dynamic Payload
     const jobDetails = {
         client: sanitizeIgnore(clientName),
         jobName: sanitizeIgnore(jobName),
         projCode: uniqueIdToFind,
         revenue: (revenueCol > 0) ? sanitizeIgnore(discrepancyData[i][revenueCol - 1]) : '',
         startDate: (startDateCol > 0) ? sanitizeIgnore(discrepancyData[i][startDateCol - 1]) : '',
         endDate: (endDateCol > 0) ? sanitizeIgnore(discrepancyData[i][endDateCol - 1]) : '',
         jobType: (jobTypeCol > 0) ? sanitizeIgnore(String(discrepancyData[i][jobTypeCol - 1])) : 'Project',
         dateConf: new Date(), 
         dynamicPayload: dynamicData // <-- The new dynamic package
     };
             let pipelineInvoiceData = null;
             let pipelineExpenseData = null;

             if (targetRowIndex !== -1) {
                const pipeRow = targetRowIndex + 2;
                const normalize = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                const map = {};
                sourceHeaders.forEach((h, idx) => map[normalize(h)] = idx);
                const rowValues = sourceSheet.getRange(pipeRow, 1, 1, sourceSheet.getLastColumn()).getValues()[0];
                const getVal = (key) => (map[key] !== undefined) ? rowValues[map[key]] : '';
                
                // Extract manual Pipeline columns
                jobDetails.revUnevenSplit = getVal('revunevensplit');
                
                pipelineInvoiceData = {
                   inv1: { amt: getVal('projectinvoice1monthlyretainerexclvat'), date: getVal('inv1senddate'), status: getVal('inv1status'), ref: getVal('inv1ref'), days: getVal('inv1daystopay') },
                   inv2: { amt: getVal('projectinvoice2exclvat'), date: getVal('inv2senddate'), status: getVal('inv2status'), ref: getVal('inv2ref'), days: getVal('inv2daystopay') },
                   inv3: { amt: getVal('projectinvoice3exclvat'), date: getVal('inv3senddate'), status: getVal('inv3status'), ref: getVal('inv3ref'), days: getVal('inv3daystopay') }
                };
                pipelineExpenseData = {
                   exp1: { amt: getVal('directinv1amt'), date: getVal('directinv1recdate'), desc: getVal('directinv1descr'), id: getVal('dirinv1appid') || getVal('directinv1appid'), status: getVal('dirinv1status'), days: getVal('dirinv1daystopay'), vat: getVal('dirinv1vat') },
                   exp2: { amt: getVal('directinv2amt'), date: getVal('directinv2recdate'), desc: getVal('directinv2descr'), id: getVal('dirinv2appid') || getVal('directinv2appid'), status: getVal('dirinv2status'), days: getVal('dirinv2daystopay'), vat: getVal('dirinv2vat') },
                   exp3: { amt: getVal('directinv3amt'), date: getVal('directinv3recdate'), desc: getVal('directinv3descr'), id: getVal('dirinv3appid') || getVal('directinv3appid'), status: getVal('dirinv3status'), days: getVal('dirinv3daystopay'), vat: getVal('dirinv3vat') }
                };

                // PRESERVE INVOICES: Keep existing pipeline invoices and expenses even if dates changed so they copy across to Confirmed
                if (datesChanged) {
                    console.log(`[Diagnostic] Start or End Date changed for ${clientName} | ${jobName}. Preserving pipeline invoices and expenses for Confirmed copy.`);
                }
             }

             // FIXED: Removed strict client name check. Jobs with blank clients will now copy safely.
             if (true) {
                // --- DETECT CHILD ROWS IN PIPELINE (PROJECTS & RETAINERS) ---
                let pipelineChildRows = null;
                if (targetRowIndex !== -1) {
                    pipelineChildRows = _getProjectChildRows(sourceSheet, sourceHeaders, targetRowIndex + 2, clientName, jobName);
                }
                // --- PASS NEW DEFAULT DAYS VARIABLE + CHILD ROWS ---
                const copyLog = _copyPipelineJobToConfirmed(sourceSs, jobDetails, pipelineInvoiceData, pipelineExpenseData, invoiceGenMode, retainerDay, defaultDays, pipelineChildRows);
                
                // FIXED: Force a fresh ID scan to find the exact row for the "Yes" lock
                if (!copyLog.includes("Error") && !copyLog.includes("Skipped")) {
                    
                    // FLAG FOR GAP AUDIT: If there are no pipeline invoices (Brand new job or Clean Slate), trigger immediate gap scan
                    if (!pipelineInvoiceData) {
                        result.needsGapAudit = true;
                    }

                    if (copiedStatusColDest > 0) {
                        const freshIdsRows = Math.min(sourceSheet.getLastRow(), sourceSheet.getMaxRows() - 1);
                        const freshIds = (freshIdsRows > 0) ? sourceSheet.getRange(2, sourceIdCol, freshIdsRows, 1).getValues().flat().map(id => String(id || "").trim().toUpperCase()) : [];
                        const actualRowIndex = freshIds.indexOf(String(uniqueIdToFind).trim().toUpperCase());
                        
                        if (actualRowIndex !== -1) {
                            sourceSheet.getRange(actualRowIndex + 2, copiedStatusColDest).setValue("Yes").setFontStyle("italic");
                            result.jobsToCheck.push(uniqueIdToFind); // <-- FIX: This triggers AN2 = Yes
                        } else {
                            console.error("Locking Failure: Could not find Job ID " + uniqueIdToFind + " in Pipeline Column C.");
                        }
                    } else {
                        console.error("Locking Failure: Column 'Copied to confirmed tab?' not found in Pipeline.");
                    }
                }
                
                result.logs.push(copyLog);
                wasUpdated = true;
             }
          }
      }
      
      if (wasUpdated) result.count++;
      discrepancySheet.getRange(i + 6, checkboxCol).setValue(false);
    }
  }
  
  let summaryMessage = `Process complete.\n${result.count} records processed.`;
  if (ui && result.deletedJobs.length > 0) {
    summaryMessage += `\n\nDeleted Jobs: ${result.deletedJobs.join(', ')}`;
  }
  if (ui) ui.alert(summaryMessage);
  else Logger.log(summaryMessage);

  return result;
}

async function updateCheckedRowsRight(isHeadless, expectedStageName) {
  const ui = isHeadless ? null : SpreadsheetApp.getUi();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const alertSheet = ss.getSheetByName("DataChgAlert");
  const keyInfoSheet = ss.getSheetByName("KeyInfo");
  // --- CONFIGURATION ---
  const invoiceGenMode = alertSheet ? alertSheet.getRange("B50").getValue() : "None";
  const retainerDay = alertSheet ? (parseInt(alertSheet.getRange("B51").getValue()) || 0) : 0;
  
  // --- NEW: Default Days Variable ---
  const defaultDays = alertSheet ? (parseInt(alertSheet.getRange("B52").getValue()) || 30) : 30;

  const pipelineMode = keyInfoSheet ? keyInfoSheet.getRange("Q9").getValue() : "";
  const copyToConfFlag = alertSheet ? alertSheet.getRange("B82").getValue() : "No";

  // --- EXPANDED COLUMN CONFIG (Mirrors Left Side) ---
  const COLUMN_CONFIG = {
    checkboxCol:        { section: 'CRM compare',          header: 'Push?' },
    dataStartCol:       { section: 'Actions required 2',   header: 'Client' },
    idCol:              { section: 'Actions required 2',   header: 'Project code' },
    copiedStatusColSrc: { section: 'Actions required 2',   header: 'Copied to confirmed tab?' },
    jobCol:             { section: 'Actions required 2',   header: ['Job name', 'Job'] },
    revenueCol:         { section: 'Actions required 2',   header: 'Revenue' },
    startDateCol:       { section: 'Actions required 2',   header: 'Start date' },
    endDateCol:         { section: 'Actions required 2',   header: 'End date' },
    jobTypeCol:         { section: 'Actions required 2',   header: ['Project / retainer', 'Type'] },
    dateConfCol:        { section: 'Actions required 2',   header: 'Date conf' },
    leadSrcCol:         { section: 'Actions required 2',   header: 'Lead src' },
    directCostsCol:     { section: 'Actions required 2',   header: 'Direct costs' },
    prodLineCol:        { section: 'Actions required 2',   header: 'Prod. line' }
  };
  
  const sourceSpreadsheetId = (await getKeyInfoValue('X28')); 
  const sourceIdCol = 3; 
  const sourceDataStartCol = 1;
  const discrepancyDataNumCols = 40;
  const result = { count: 0, jobsToCheck: [], revertedJobs: [], deletedJobs: [], logs: [] };
  
  if (!sourceSpreadsheetId) return result;
  const activeSs = SpreadsheetApp.getActiveSpreadsheet();
  const discrepancySheet = activeSs.getSheetByName('CRMComp');
  if (!discrepancySheet) return result;
  
  const sectionHeaders = discrepancySheet.getRange('4:4').getValues()[0];
  const columnHeaders = discrepancySheet.getRange('5:5').getValues()[0];
  const foundColumns = findColumnIndexes(sectionHeaders, columnHeaders, COLUMN_CONFIG);
  
  if (foundColumns.errorList.length > 0) { 
    if (ui) ui.alert('Error: Columns not found in Right Side (Actions required 2).\n' + foundColumns.errorList.join('\n'));
    return result;
  }

  const { checkboxCol, dataStartCol, idCol, copiedStatusColSrc, revenueCol, startDateCol, endDateCol, jobCol, jobTypeCol, dateConfCol, leadSrcCol, directCostsCol, prodLineCol } = foundColumns;
  const sourceSheetName = String(discrepancySheet.getRange('B2').getValue() || '').trim();
  const modeCleanGuard = String(pipelineMode || '').trim().toLowerCase();

  if (expectedStageName && sourceSheetName !== expectedStageName) {
    const msg = `Blocked CRM Compare (Right) write: CRMComp!B2 ("${sourceSheetName}") does not match expected stage ("${expectedStageName}").`;
    console.warn(msg);
    if (checkboxCol > 0) discrepancySheet.getRange(6, checkboxCol, 1001, 1).setValue(false);
    return result;
  }
  if (sourceSheetName === 'Confirmed' && modeCleanGuard !== 'pipeandconf' && modeCleanGuard !== 'confirmed') {
    const msg = `Blocked CRM Compare (Right) write to Confirmed tab because KeyInfo!Q9 is "${pipelineMode}" (Pipeline-only).`;
    console.warn(msg);
    if (checkboxCol > 0) discrepancySheet.getRange(6, checkboxCol, 1001, 1).setValue(false);
    if (ui) ui.alert(msg);
    return result;
  }

  // --- TRANSLATION DICTIONARY ---
  const SETTINGS_TO_HEADERS_MAP = {
      "Client mismatch?":       ["client"],
      "Job name mismatch?":     ["job name", "job"],
      "Revenue mismatch?":      ["revenue", "revenue (proj total / ongoing pm) - excl vat"],
      "Direct costs mismatch?": ["direct costs", "direct costs (proj total / ongoing pm) - excl vat"],
      "Start date mismatch?":   ["start date"],
      "End date mismatch?":     ["end date"],
      "% likel. mismatch":      ["% likel."]
  };

  const appRange = sourceSheetName === 'Pipeline' ? 'A72:B79' : 'D72:E79';
  const appSettings = getDiscrepancySettings(alertSheet, appRange);
  
  // --- BULLETPROOF HEADER NORMALIZER ---
  const normalizeHdr = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");

  // Combine exclude AND ignore for column masking ONLY
  const excludedDataHeaders = [];
  const itemsToStrip = [...(appSettings.exclude || []), ...(appSettings.ignore || [])];
  
  itemsToStrip.forEach(setting => {
      const cleanSetting = String(setting).trim();
      if (SETTINGS_TO_HEADERS_MAP[cleanSetting]) {
          SETTINGS_TO_HEADERS_MAP[cleanSetting].forEach(h => {
              excludedDataHeaders.push(normalizeHdr(h));
          });
      }
  });

  let sourceSs;
  try {
    sourceSs = (await SpreadsheetApp.openById(sourceSpreadsheetId));
  } catch (e) {
    result.logs.push(`Error: CRM Workflow - Could not open Client Sheet: ${e.message}`);
    result.hasError = true;
    result.error = e.message;
    return result;
  }
  const sourceSheet = sourceSs.getSheetByName(sourceSheetName);
  if (!sourceSheet) {
    result.logs.push(`Error: CRM Workflow - Sheet '${sourceSheetName}' not found in Client Spreadsheet.`);
    result.hasError = true;
    result.error = `Sheet '${sourceSheetName}' not found in Client Spreadsheet.`;
    return result;
  }
  
  const discrepancyRange = discrepancySheet.getRange(6, 1, 1001, discrepancySheet.getLastColumn());
  const discrepancyData = discrepancyRange.getValues();
  
  let copiedStatusColDest = -1;
  const sourceHeaders = sourceSheet.getRange(1, 1, 1, sourceSheet.getLastColumn()).getValues()[0];
  if (sourceSheetName === 'Pipeline') {
    const destIdx = sourceHeaders.findIndex(h => String(h || "").toLowerCase().replace(/[^a-z0-9]/g, '') === 'copiedtoconfirmedtab');
    copiedStatusColDest = destIdx !== -1 ? destIdx + 1 : -1;
  }

  // FIXED: Dynamically find the Project Code column
  let actualSourceIdCol = sourceHeaders.findIndex(h => String(h || "").toLowerCase().replace(/[^a-z0-9]/g, '') === 'projectcode') + 1;
  if (actualSourceIdCol === 0) actualSourceIdCol = 3;

  // NEW: Normalize Right Side existing IDs
  const sourceIds = sourceSheet.getRange(2, actualSourceIdCol, Math.max(1, sourceSheet.getMaxRows() - 1), 1)
    .getValues()
    .flat()
    .map(id => String(id || "").trim().toUpperCase());

  // Find next available row
  let trueLastRow = 0;
  // EXPANDED to 96 columns to accommodate the Zone 4 check
  const rowsToRead = Math.min(Math.max(1, sourceSheet.getLastRow() + 1), sourceSheet.getMaxRows());
  const allSourceData = sourceSheet.getRange(1, 1, rowsToRead, 96).getValues();
  for (let i = allSourceData.length - 1; i >= 0; i--) {
    const row = allSourceData[i];
    // ZONE CHECK: A:E (0-4), AG:AM (32-38), AP:BH (41-59), BX:CR (75-95)
    const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
    const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
    const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
    const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
    if (z1 || z2 || z3 || z4) { 
      trueLastRow = i + 1; 
      break; 
    }
  }
  let nextAvailableRow = trueLastRow + 1;
  for (let i = 0; i < discrepancyData.length; i++) {
    const isChecked = discrepancyData[i][checkboxCol - 1];
    if (isChecked === true) {
      const rawUniqueId = discrepancyData[i][idCol - 1];
      if (!rawUniqueId || String(rawUniqueId).trim() === "") {
        discrepancySheet.getRange(i + 6, checkboxCol).setValue(false);
        continue;
      }
      // FIXED: Immediately cast incoming ID to a string and normalize it to stop type-mismatches
      const uniqueIdToFind = String(rawUniqueId).trim().toUpperCase();

      // FIX: Grab Client and Job directly
      const clientName = (dataStartCol > 0) ? discrepancyData[i][dataStartCol - 1] : "Unknown";
      const jobName = (jobCol > 0) ? discrepancyData[i][jobCol - 1] : "Unknown";
      const dataToCopy = discrepancyData[i].slice(dataStartCol - 1, dataStartCol - 1 + discrepancyDataNumCols);
      const sourceValue = String(discrepancyData[i][copiedStatusColSrc - 1]);
      let isDeletion = false;
      let wasUpdated = false;
      let datesChanged = false;
      let targetRowIndex = -1;
      // --- DELETION LOGIC ---
      if (sourceSheetName === 'Confirmed' && sourceValue === 'DELETE') {
         targetRowIndex = sourceIds.indexOf(uniqueIdToFind);
         if (targetRowIndex !== -1) {
             const targetRow = targetRowIndex + 2;
             sourceSheet.getRange(targetRow, 1, 1, 39).clearContent();
             sourceSheet.getRange(targetRow, 42, 1, 19).clearContent();
             sourceSheet.getRange(targetRow, 76, 1, 20).clearContent();
             result.deletedJobs.push(uniqueIdToFind);
             result.logs.push(`[${sourceSheetName}] Deleted Job: Row ${targetRow}, ${clientName} | ${jobName} (ID: ${uniqueIdToFind})`);

             isDeletion = true;
             wasUpdated = true;
         }
      }

      if (!isDeletion) {
          targetRowIndex = sourceIds.indexOf(uniqueIdToFind);
          if (targetRowIndex !== -1) {
            // --- UPDATE EXISTING ROW ---
            const targetRow = targetRowIndex + 2;
            const targetRange = sourceSheet.getRange(targetRow, sourceDataStartCol, 1, discrepancyDataNumCols);
            const existingValues = targetRange.getValues()[0];
            const rowChanges = [];

            // CASCADE PREP: Identify if Client or Job Name is changing
            const jobIndexOffset = (jobCol > 0) ? (jobCol - dataStartCol) : -1;
            const revIndexOffset = (revenueCol > 0) ? (revenueCol - dataStartCol) : -1;
            const startIndexOffset = (startDateCol > 0) ? (startDateCol - dataStartCol) : -1;
            
            const endDateIndexOffset = (endDateCol > 0) ? (endDateCol - dataStartCol) : -1;
            
            const oldClient = String(existingValues[0] || "").trim().toLowerCase();
            const oldJob = (jobIndexOffset >= 0) ? String(existingValues[jobIndexOffset] || "").trim().toLowerCase() : "";
            const newClient = String(dataToCopy[0] || "").trim();
            const newJob = (jobIndexOffset >= 0) ? String(dataToCopy[jobIndexOffset] || "").trim() : "";
            
            const clientChanged = valuesAreDifferent(existingValues[0], dataToCopy[0]) && newClient.toUpperCase() !== "IGNORE" && newClient.toUpperCase() !== "<IGNORE>";
            const jobChanged = (jobIndexOffset >= 0) && valuesAreDifferent(existingValues[jobIndexOffset], dataToCopy[jobIndexOffset]) && newJob.toUpperCase() !== "IGNORE" && newJob.toUpperCase() !== "<IGNORE>";

            // CLEAN SLATE PREP: Check if start or end dates are changing
            const newStart = (startIndexOffset >= 0) ? String(dataToCopy[startIndexOffset]).toUpperCase() : "IGNORE";
            const newEnd = (endDateIndexOffset >= 0) ? String(dataToCopy[endDateIndexOffset]).toUpperCase() : "IGNORE";
            const startDateChanged = (startIndexOffset >= 0) && valuesAreDifferent(existingValues[startIndexOffset], dataToCopy[startIndexOffset]) && newStart !== "IGNORE" && newStart !== "<IGNORE>";
            const endDateChanged = (endDateIndexOffset >= 0) && valuesAreDifferent(existingValues[endDateIndexOffset], dataToCopy[endDateIndexOffset]) && newEnd !== "IGNORE" && newEnd !== "<IGNORE>";
            datesChanged = startDateChanged || endDateChanged;

            for (let j = 0; j < discrepancyDataNumCols; j++) {
              const headerIndex = (dataStartCol - 1) + j;
               const crmHeader = normalizeHdr(columnHeaders[headerIndex]);
               const destHeader = normalizeHdr(sourceHeaders[j]);
               
               if (excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader)) continue;

              const incomingVal = String(dataToCopy[j]).trim().toUpperCase();
              // NEW LOGIC (OPTION A): Update the cell UNLESS it's ignored OR completely blank
              if (valuesAreDifferent(existingValues[j], dataToCopy[j]) && incomingVal !== "IGNORE" && incomingVal !== "<IGNORE>" && incomingVal !== "") {
             const colToUpdate = sourceDataStartCol + j;

                sourceSheet.getRange(targetRow, colToUpdate).setValue(sanitizeSheetCell_(dataToCopy[j])).setFontStyle('italic');
                wasUpdated = true;
                
                const oldVal = existingValues[j] instanceof Date ? Utilities.formatDate(existingValues[j], ss.getSpreadsheetTimeZone(), "dd/MM/yy") : existingValues[j];
                let newVal = dataToCopy[j];
                
                // FIXED: Convert raw Google Sheets serial numbers back into readable dates for the AutoLog
                if (newVal instanceof Date) {
                    newVal = Utilities.formatDate(newVal, ss.getSpreadsheetTimeZone(), "dd/MM/yy");
                } else if (existingValues[j] instanceof Date && typeof newVal === 'number') {
                    const epoch = new Date(1899, 11, 30);
                    const convertedDate = new Date(epoch.getTime() + Math.round(newVal * 86400000));
                    newVal = Utilities.formatDate(convertedDate, ss.getSpreadsheetTimeZone(), "dd/MM/yy");
                }
                
                // FIXED: Inject a warning if the CRM wipes a previously populated text field blank
                const headerName = destHeader;
                let logString = `${headerName}: '${oldVal}' -> '${newVal}'`;
                if (String(oldVal).trim() !== "" && String(newVal).trim() === "") {
                    logString = `⚠️ WARNING: CRM wiped data blank! ${logString}`;
                }
                rowChanges.push(logString);
              }
            }

            // CASCADE EXECUTION: Update all attached child rows instantly
            if (clientChanged || jobChanged) {
                let cascadeCount = 0;
                let r = targetRow + 1;
                const lastRow = sourceSheet.getLastRow();
                while (r <= lastRow) {
                    const childVals = sourceSheet.getRange(r, sourceDataStartCol, 1, discrepancyDataNumCols).getValues()[0];
                    const childClient = String(childVals[0] || "").trim().toLowerCase();
                    const childJob = (jobIndexOffset >= 0) ? String(childVals[jobIndexOffset] || "").trim().toLowerCase() : "";
                    
                    if (childClient !== oldClient || childJob !== oldJob) break; 
                    
                    // SAFETY GUARD: Ensure it's a true child row (No revenue, no start date)
                    const childRevRaw = (revIndexOffset >= 0) ? childVals[revIndexOffset] : "";
                    const childRev = parseFloat(String(childRevRaw).replace(/[^0-9.-]/g, '')) || 0;
                    const childStart = (startIndexOffset >= 0) ? childVals[startIndexOffset] : "";
                    
                    if (childRev > 0 || (childStart && String(childStart).trim() !== '')) break; // Hit a new distinct project, stop cascading!
                    
                    if (clientChanged) sourceSheet.getRange(r, sourceDataStartCol).setValue(sanitizeSheetCell_(newClient)).setFontStyle('italic');
                    if (jobChanged && jobIndexOffset >= 0) sourceSheet.getRange(r, sourceDataStartCol + jobIndexOffset).setValue(sanitizeSheetCell_(newJob)).setFontStyle('italic');
                    
                    cascadeCount++;
                    r++;
                }
                if (cascadeCount > 0) rowChanges.push(`Cascaded name updates to ${cascadeCount} child row(s)`);
            }

            // --- COPIED STATUS TOGGLE ---
            if (sourceSheetName === 'Pipeline' && copiedStatusColDest > 0 && copiedStatusColSrc > 0) {
              const destCell = sourceSheet.getRange(targetRow, copiedStatusColDest);
              const destValue = String(destCell.getValue());
              if (valuesAreDifferent(sourceValue, destValue)) {
                destCell.setValue(sourceValue).setFontStyle('italic');
                wasUpdated = true;
                
                // FIX: Reason context
                let changeReason = "";
                if (destValue === 'Yes' && sourceValue === 'No') changeReason = " (Reverted by Source)";

                rowChanges.push(`Copied Status: '${destValue}' -> '${sourceValue}'${changeReason}`);
                if (sourceValue === 'Yes') result.jobsToCheck.push(uniqueIdToFind);
                if (destValue === 'Yes' && sourceValue === 'No') result.revertedJobs.push(uniqueIdToFind);
              }
            }

            if (wasUpdated) {
                result.logs.push(`[${sourceSheetName}] Updated: Row ${targetRow}, ${clientName} | ${jobName} - ${rowChanges.join(", ")}`);
            }

          } else {
            // --- CREATE NEW ROW ---
            if (nextAvailableRow > sourceSheet.getMaxRows()) sourceSheet.insertRowsAfter(sourceSheet.getMaxRows(), 5);
            
            for (let j = 0; j < discrepancyDataNumCols; j++) {
               const headerIndex = (dataStartCol - 1) + j;
               const crmHeader = typeof normalizeHdr === "function" ? normalizeHdr(columnHeaders[headerIndex]) : String(columnHeaders[headerIndex] || "").trim().toLowerCase();
               const destHeader = typeof normalizeHdr === "function" ? normalizeHdr(sourceHeaders[j]) : String(sourceHeaders[j] || "").trim().toLowerCase();
               
               if (excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader)) continue;

               const val = dataToCopy[j];
               const str = String(val).trim().toUpperCase();
                
               // Do not touch columns marked <IGNORE>, blank, or excluded to protect underlying formulas
               if (str !== "IGNORE" && str !== "<IGNORE>" && str !== "") {
                   sourceSheet.getRange(nextAvailableRow, sourceDataStartCol + j).setValue(sanitizeSheetCell_(val)).setFontStyle('italic');
               }
            }

            wasUpdated = true; 
            try { sourceSheet.unhideRow(sourceSheet.getRange(nextAvailableRow, 1, 1, 1)); } catch (e) {}
            
            // NATIVE DATE CONF INJECTION: Stamp today's date exclusively on the parent row when copying to Confirmed
            if (sourceSheetName === 'Confirmed') {
               const destDateConfCol = sourceHeaders.findIndex(h => String(h||'').trim().toLowerCase() === 'date conf');
               if (destDateConfCol !== -1) {
                   sourceSheet.getRange(nextAvailableRow, destDateConfCol + 1).setValue(new Date()).setNumberFormat("d-MMM-yy").setFontStyle('italic');
               }
            }
            
            result.logs.push(`[${sourceSheetName}] Created New Job: Row ${nextAvailableRow}, ${clientName} | ${jobName}`);
            
            // FIX: Add the new ID to the master list immediately to prevent duplicates in the same run
            sourceIds.push(uniqueIdToFind);
            
            nextAvailableRow++;
          }

          // === COPY TO CONFIRMED LOGIC ===
          const isPipeline = sourceSheetName === 'Pipeline';
          const modeClean = String(pipelineMode).trim().toLowerCase();
          const isPipelineMode = modeClean === 'pipeline' || modeClean === 'pipeandconf';
          const isCopyEnabled = String(copyToConfFlag).trim().toLowerCase() === 'yes';
          const isReadyToCopy = String(sourceValue).trim().toLowerCase() === 'yes';
          if (isPipeline && isPipelineMode && isCopyEnabled && isReadyToCopy) {
              
              // 1. Build the Dynamic Payload
              const dynamicData = {};
              for (let j = 0; j < discrepancyDataNumCols; j++) {
                  const headerIndex = (dataStartCol - 1) + j;
                  const crmHeaderRaw = String(columnHeaders[headerIndex] || "").trim();
                  const destHeaderRaw = String(sourceHeaders[j] || "").trim();
                  
                  const crmHeader = typeof normalizeHdr === "function" ? normalizeHdr(crmHeaderRaw) : crmHeaderRaw.toLowerCase().replace(/[^a-z0-9]/g, "");
                  const destHeader = typeof normalizeHdr === "function" ? normalizeHdr(destHeaderRaw) : destHeaderRaw.toLowerCase().replace(/[^a-z0-9]/g, "");

                  // Respect Dashboard Exclusions
                  const shouldExclude = excludedDataHeaders.includes(crmHeader) || excludedDataHeaders.includes(destHeader);
                  if (shouldExclude || !crmHeaderRaw) continue;

                  const val = dataToCopy[j];
                  const str = String(val).trim().toUpperCase();
                  
                  // Respect <IGNORE> tags
                  if (str !== "IGNORE" && str !== "<IGNORE>") {
                      dynamicData[crmHeaderRaw] = val;
                  }
              }

              const sanitizeIgnore = (val) => {
         const str = String(val).trim().toUpperCase();
         // FIXED: Return a special token instead of an empty string to protect formulas
         return (str === "IGNORE" || str === "<IGNORE>") ? "_SKIP_THIS_CELL_" : val;
     };

              // 2. Map the Core Payload + Dynamic Payload
              const jobDetails = {
                  client: sanitizeIgnore(clientName),
                  jobName: sanitizeIgnore(jobName),
                  projCode: uniqueIdToFind,
                  revenue: (revenueCol > 0) ? sanitizeIgnore(discrepancyData[i][revenueCol - 1]) : '',
                  startDate: (startDateCol > 0) ? sanitizeIgnore(discrepancyData[i][startDateCol - 1]) : '',
                  endDate: (endDateCol > 0) ? sanitizeIgnore(discrepancyData[i][endDateCol - 1]) : '',
                  jobType: (jobTypeCol > 0) ? sanitizeIgnore(String(discrepancyData[i][jobTypeCol - 1])) : 'Project',
                  dateConf: new Date(), 
                  dynamicPayload: dynamicData // <-- The new dynamic package
              };
             let pipelineInvoiceData = null;
             let pipelineExpenseData = null;

             if (targetRowIndex !== -1) {
                const pipeRow = targetRowIndex + 2;
                const normalize = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                const map = {};
                sourceHeaders.forEach((h, idx) => map[normalize(h)] = idx);
                const rowValues = sourceSheet.getRange(pipeRow, 1, 1, sourceSheet.getLastColumn()).getValues()[0];
                const getVal = (key) => (map[key] !== undefined) ? rowValues[map[key]] : '';
                
                // Extract manual Pipeline columns
                jobDetails.revUnevenSplit = getVal('revunevensplit');
                
                pipelineInvoiceData = {
                   inv1: { amt: getVal('projectinvoice1monthlyretainerexclvat'), date: getVal('inv1senddate'), status: getVal('inv1status'), ref: getVal('inv1ref'), days: getVal('inv1daystopay') },
                   inv2: { amt: getVal('projectinvoice2exclvat'), date: getVal('inv2senddate'), status: getVal('inv2status'), ref: getVal('inv2ref'), days: getVal('inv2daystopay') },
                   inv3: { amt: getVal('projectinvoice3exclvat'), date: getVal('inv3senddate'), status: getVal('inv3status'), ref: getVal('inv3ref'), days: getVal('inv3daystopay') }
                };
                pipelineExpenseData = {
                   exp1: { amt: getVal('directinv1amt'), date: getVal('directinv1recdate'), desc: getVal('directinv1descr'), id: getVal('dirinv1appid') || getVal('directinv1appid'), status: getVal('dirinv1status'), days: getVal('dirinv1daystopay'), vat: getVal('dirinv1vat') },
                   exp2: { amt: getVal('directinv2amt'), date: getVal('directinv2recdate'), desc: getVal('directinv2descr'), id: getVal('dirinv2appid') || getVal('directinv2appid'), status: getVal('dirinv2status'), days: getVal('dirinv2daystopay'), vat: getVal('dirinv2vat') },
                   exp3: { amt: getVal('directinv3amt'), date: getVal('directinv3recdate'), desc: getVal('directinv3descr'), id: getVal('dirinv3appid') || getVal('directinv3appid'), status: getVal('dirinv3status'), days: getVal('dirinv3daystopay'), vat: getVal('dirinv3vat') }
                };

                // PRESERVE INVOICES: Keep existing pipeline invoices and expenses even if dates changed so they copy across to Confirmed
                if (datesChanged) {
                    console.log(`[Diagnostic] Start or End Date changed for ${clientName} | ${jobName}. Preserving pipeline invoices and expenses for Confirmed copy.`);
                }
             }

             // FIXED: Removed strict client name check. Jobs with blank clients will now copy safely.
             if (true) {
                // --- DETECT CHILD ROWS IN PIPELINE (PROJECTS & RETAINERS) ---
                let pipelineChildRows = null;
                if (targetRowIndex !== -1) {
                    pipelineChildRows = _getProjectChildRows(sourceSheet, sourceHeaders, targetRowIndex + 2, clientName, jobName);
                }
                // --- PASS NEW DEFAULT DAYS VARIABLE + CHILD ROWS ---
                const copyLog = _copyPipelineJobToConfirmed(sourceSs, jobDetails, pipelineInvoiceData, pipelineExpenseData, invoiceGenMode, retainerDay, defaultDays, pipelineChildRows);
                
                // FIXED: Force a fresh ID scan and ADD TO jobsToCheck for AN2 Dashboard
                if (!copyLog.includes("Error") && !copyLog.includes("Skipped")) {
                    
                    // FLAG FOR GAP AUDIT: If there are no pipeline invoices (Brand new job or Clean Slate), trigger immediate gap scan
                    if (!pipelineInvoiceData) {
                        result.needsGapAudit = true;
                    }

                    // DIAGNOSTIC: Print the column index so we know if the header search is failing
                    console.log(`Diagnostic [Right Side]: Target Column Index for DD is ${copiedStatusColDest}`);

                    if (copiedStatusColDest > 0) {
                        const freshIdsRows = Math.min(sourceSheet.getLastRow(), sourceSheet.getMaxRows() - 1);
                        const freshIds = (freshIdsRows > 0) ? sourceSheet.getRange(2, sourceIdCol, freshIdsRows, 1).getValues().flat().map(id => String(id || "").trim().toUpperCase()) : [];
                        const actualRowIndex = freshIds.indexOf(String(uniqueIdToFind).trim().toUpperCase());
                        
                        console.log(`Diagnostic [Right Side]: Job ID ${uniqueIdToFind} found at Row Index ${actualRowIndex}`);

                        if (actualRowIndex !== -1) {
                            sourceSheet.getRange(actualRowIndex + 2, copiedStatusColDest).setValue("Yes").setFontStyle("italic");
                            result.jobsToCheck.push(uniqueIdToFind); // <--- THIS IS THE MISSING PIECE THAT TURNS AN2 TO 'YES'
                        } else {
                            console.error("Locking Failure: Could not find Job ID " + uniqueIdToFind + " to mark as 'Yes'.");
                        }
                    } else {
                        console.error("Locking Failure: Column 'Copied to confirmed tab?' not found in Pipeline headers.");
                    }
                }
                
                // The full detail remains in copyLog and is pushed here for the AutoLog
                result.logs.push(copyLog);
                wasUpdated = true;
             }
          }
      }
      
      if (wasUpdated) result.count++;
      const sheetRow = i + 6;
      discrepancySheet.getRange(sheetRow, checkboxCol).setValue(false);
    }
  }
  
  let summaryMessage = `Process complete.\n${result.count} records processed.`;
  if (ui && result.deletedJobs.length > 0) {
    summaryMessage += `\n\nDeleted Jobs: ${result.deletedJobs.join(', ')}`;
  }
  
  if (ui) ui.alert(summaryMessage);
  else Logger.log(summaryMessage);

  return result;
}


/**
 * HELPER: Detects and extracts Pipeline child rows for a Project parent.
 * Child rows are identified as: same client + same job name, no revenue, no start/end dates,
 * appearing directly below the parent row.
 * Returns an array of { invoices: {inv1,inv2,inv3}, expenses: {exp1,exp2,exp3} } per child row.
 */
function _getProjectChildRows(sourceSheet, sourceHeaders, parentRowIndex, clientName, jobName) {
    const normalize = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const map = {};
    sourceHeaders.forEach((h, idx) => { map[normalize(h)] = idx; });
    
    const getVal = (rowValues, key) => (map[key] !== undefined) ? rowValues[map[key]] : '';
    const colClient = map[normalize('Client')];
    const colJob = map[normalize('Job name')] !== undefined ? map[normalize('Job name')] : map[normalize('Job')];
    const colRevenue = map[normalize('Revenue (Proj total / Ongoing pm) - excl VAT')] !== undefined 
        ? map[normalize('Revenue (Proj total / Ongoing pm) - excl VAT')]
        : map[normalize('Revenue')];
    const colStart = map[normalize('Start date')];
    
    const children = [];
    const lastRow = sourceSheet.getLastRow();
    
    // Read rows below parent
    for (let r = parentRowIndex + 1; r <= lastRow; r++) {
        const rowValues = sourceSheet.getRange(r, 1, 1, sourceSheet.getLastColumn()).getValues()[0];
        
        const childClient = String(rowValues[colClient] || '').trim().toLowerCase();
        const childJob = String(rowValues[colJob] || '').trim().toLowerCase();
        const parentClient = String(clientName).trim().toLowerCase();
        const parentJob = String(jobName).trim().toLowerCase();
        
        // Stop if different client/job (children must be directly underneath)
        if (childClient !== parentClient || childJob !== parentJob) break;
        
        // Stop if this row has its own revenue or start date (it's a new parent, not a child)
        const childRevenue = parseFloat(String(rowValues[colRevenue] || '').replace(/[^0-9.-]/g, '')) || 0;
        const childStart = rowValues[colStart];
        if (childRevenue > 0 || (childStart && String(childStart).trim() !== '')) break;
        
        // This is a child row — extract invoice and expense data
        children.push({
            revUnevenSplit: getVal(rowValues, 'revunevensplit'),
            invoices: {
                inv1: { amt: getVal(rowValues, 'projectinvoice1monthlyretainerexclvat'), date: getVal(rowValues, 'inv1senddate'), status: getVal(rowValues, 'inv1status'), ref: getVal(rowValues, 'inv1ref'), days: getVal(rowValues, 'inv1daystopay') },
                inv2: { amt: getVal(rowValues, 'projectinvoice2exclvat'), date: getVal(rowValues, 'inv2senddate'), status: getVal(rowValues, 'inv2status'), ref: getVal(rowValues, 'inv2ref'), days: getVal(rowValues, 'inv2daystopay') },
                inv3: { amt: getVal(rowValues, 'projectinvoice3exclvat'), date: getVal(rowValues, 'inv3senddate'), status: getVal(rowValues, 'inv3status'), ref: getVal(rowValues, 'inv3ref'), days: getVal(rowValues, 'inv3daystopay') }
            },
            expenses: {
                exp1: { amt: getVal(rowValues, 'directinv1amt'), date: getVal(rowValues, 'directinv1recdate'), desc: getVal(rowValues, 'directinv1descr'), id: getVal(rowValues, 'dirinv1appid') || getVal(rowValues, 'directinv1appid'), status: getVal(rowValues, 'dirinv1status'), days: getVal(rowValues, 'dirinv1daystopay'), vat: getVal(rowValues, 'dirinv1vat') },
                exp2: { amt: getVal(rowValues, 'directinv2amt'), date: getVal(rowValues, 'directinv2recdate'), desc: getVal(rowValues, 'directinv2descr'), id: getVal(rowValues, 'dirinv2appid') || getVal(rowValues, 'directinv2appid'), status: getVal(rowValues, 'dirinv2status'), days: getVal(rowValues, 'dirinv2daystopay'), vat: getVal(rowValues, 'dirinv2vat') },
                exp3: { amt: getVal(rowValues, 'directinv3amt'), date: getVal(rowValues, 'directinv3recdate'), desc: getVal(rowValues, 'directinv3descr'), id: getVal(rowValues, 'dirinv3appid') || getVal(rowValues, 'directinv3appid'), status: getVal(rowValues, 'dirinv3status'), days: getVal(rowValues, 'dirinv3daystopay'), vat: getVal(rowValues, 'dirinv3vat') }
            }
        });
    }
    
    return children;
}


/**
 * COPIES A JOB FROM PIPELINE TO CONFIRMED
 * V7.1 - UPDATED: Type-safe 'days to pay' handling for Invoices & Expenses.
 */
function _copyPipelineJobToConfirmed(ss, details, pipelineInvoices, pipelineExpenses, genMode, retainerDay, defaultDays, pipelineChildRows) {
  const targetSheet = ss.getSheetByName("Confirmed");
  if (!targetSheet) return "Error: Confirmed sheet not found";

  const daysVal = (defaultDays && defaultDays > 0) ? defaultDays : 30;
  const headers = targetSheet.getRange(1, 1, 1, targetSheet.getLastColumn()).getValues()[0];
  const map = {};
  headers.forEach((h, i) => map[String(h || '').trim().toLowerCase()] = i + 1);

  // --- DUPLICATE CHECK ---
  const codeCol = map['project code'];
  if (codeCol && details.projCode) {
      const lastRow = targetSheet.getLastRow();
      if (lastRow > 0) {
          const existingCodes = targetSheet.getRange(1, codeCol, lastRow, 1).getValues().flat();
          const targetCode = String(details.projCode).trim().toUpperCase();
          if (existingCodes.some(c => String(c).trim().toUpperCase() === targetCode)) {
              return `Skipped Copy: Job with Project Code "${details.projCode}" already exists in Confirmed.`;
          }
      }
  }

  // Find the first truly empty row
  const rowsToRead = Math.min(Math.max(1, targetSheet.getLastRow() + 1), targetSheet.getMaxRows());
  const allData = targetSheet.getRange(1, 1, rowsToRead, 96).getValues();
  let lastRowWithContent = 0;
  for (let i = allData.length - 1; i >= 0; i--) {
    const row = allData[i];
    // ZONE CHECK: A:E (0-4), AG:AM (32-38), AP:BH (41-59), BX:CR (75-95)
    const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
    const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
    const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
    const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
    if (z1 || z2 || z3 || z4) { 
      lastRowWithContent = i + 1; 
      break; 
    }
  }
  const newRow = lastRowWithContent + 1;

  // FIXED: Prevent out-of-bounds crash. Ensure Confirmed tab has enough physical rows for parent + all children
  const rowsNeeded = 1 + (String(details.jobType).trim().toLowerCase() === 'retainer' ? 18 : (pipelineChildRows ? pipelineChildRows.length : 0));
  if (newRow + rowsNeeded > targetSheet.getMaxRows()) {
      targetSheet.insertRowsAfter(targetSheet.getMaxRows(), rowsNeeded + 5);
  }

  // --- HELPER TO WRITE VALUES ---
  const setVal = (row, header, val) => {
 if (val === "_SKIP_THIS_CELL_") return; // Respect <IGNORE> tags

 let col = map[header.toLowerCase()];
        if (!col && header === 'Job name') col = map['job'];
        if (!col && header === 'Revenue') col = map['revenue (proj total / ongoing pm) - excl vat'];
        if (!col && header === 'Direct costs') col = map['direct costs (proj total / ongoing pm) - excl vat'];
        
        // FIXED: Only map the main job VAT column, preventing expense VAT columns from being overridden
        if (!col && (header.toLowerCase() === 'vat' || header.toLowerCase() === 'vat?')) col = map['vat?']; 
        
        // BULLETPROOF ALIAS: Hunt for any variation of "Date conf" regardless of hidden spaces or punctuation
        if (!col && header === 'Date conf') {
            const foundKey = Object.keys(map).find(k => {
                const clean = k.replace(/[^a-z]/g, '');
                return clean.includes('dateconf') || clean.includes('confdate') || (clean.includes('date') && clean.includes('conf'));
            });
            if (foundKey) col = map[foundKey];
        }

        if (!col) {
 const cleanHeader = String(header).toLowerCase().replace(/[^a-z0-9]/g, '');
 const foundIdx = headers.findIndex(h => String(h).toLowerCase().replace(/[^a-z0-9]/g, '') === cleanHeader);
 if (foundIdx !== -1) col = foundIdx + 1;
 }
 
 if (col) {
 const hStr = String(header).toLowerCase();
 const cell = targetSheet.getRange(row, col);
 
 // Safely intercept and reformat ugly text dates that snuck in from the CRM
 let finalVal = val;
 if (typeof val === 'string') {
   if (val.includes('GMT') && val.match(/^[A-Z][a-z]{2} [A-Z][a-z]{2} \d{2}/)) {
     const parsed = new Date(val);
     if (!isNaN(parsed.getTime())) finalVal = parsed;
   } else if (hStr.includes('date') || hStr.includes('conf') || (map['date conf'] && col === map['date conf'])) {
     const parsed = new Date(val);
     if (!isNaN(parsed.getTime())) finalVal = parsed;
   }
 } else if (typeof val === 'number' && val > 20000 && val < 70000 && (hStr.includes('date') || hStr.includes('conf') || (map['date conf'] && col === map['date conf']))) {
   finalVal = new Date(new Date(1899, 11, 30).getTime() + Math.round(val * 86400000));
 }

 // Strict word boundaries prevent "ongoing" from matching "no", or "paid" from matching "id"
 const isTextField = /\b(code|ref|id|no\b|client|job)\b/i.test(hStr) || hStr === "invoice no";

 if (finalVal instanceof Date) {
 // Write real date objects natively and apply simple formatting
 cell.setValue(finalVal).setNumberFormat("d-MMM-yy").setFontStyle('italic');
 } else if (isTextField && finalVal !== "" && finalVal != null) {
 cell.setNumberFormat("@").setValue(sanitizeSheetCell_(String(finalVal))).setFontStyle('italic');
 } else {
 cell.setValue(sanitizeSheetCell_(finalVal)).setFontStyle('italic');
 }
 }
 };

  // --- WRITE PARENT ROW ---
  try { targetSheet.unhideRow(targetSheet.getRange(newRow, 1, 1, 1)); } catch (e) {}
 // 1. Dump everything from the dynamic payload first
 if (details.dynamicPayload) {
     for (const header in details.dynamicPayload) {
         setVal(newRow, header, details.dynamicPayload[header]);
     }
 }
 
 // 2. Enforce explicit core logic properties over the top
     setVal(newRow, 'Client', details.client);
     setVal(newRow, 'Job name', details.jobName);
     setVal(newRow, 'Project code', details.projCode);
     setVal(newRow, 'Date conf', details.dateConf); // Always stamps today's date
     setVal(newRow, 'Revenue', details.revenue);
     setVal(newRow, 'Project / retainer', details.jobType);
     setVal(newRow, 'Start date', details.startDate);
     setVal(newRow, 'End date', details.endDate);
     
     // Transfer manual Pipeline columns
     if (details.revUnevenSplit) setVal(newRow, 'RevUnevenSplit', details.revUnevenSplit);

  // --- EXPENSE CLONING (PARENT) ---
  if (pipelineExpenses) {
     ['exp1', 'exp2', 'exp3'].forEach((k, idx) => {
         const i = idx + 1;
         if ((parseFloat(pipelineExpenses[k].amt) || 0) > 0 || pipelineExpenses[k].desc) {
             setVal(newRow, `Direct inv ${i} amt`, pipelineExpenses[k].amt);
             setVal(newRow, `Direct inv ${i} descr.`, pipelineExpenses[k].desc);
             setVal(newRow, `Direct inv ${i} rec date`, pipelineExpenses[k].date);
             setVal(newRow, `Direct inv ${i} app id`, pipelineExpenses[k].id);
             setVal(newRow, `Direct inv ${i} status`, pipelineExpenses[k].status);
             setVal(newRow, `Dir inv ${i} VAT?`, pipelineExpenses[k].vat);
             
             // Fix Expense Days
             const expDays = safeParseDays_(pipelineExpenses[k].days, `Parent Exp ${i}`);
             setVal(newRow, `Dir inv ${i} days to pay`, expDays || daysVal);
         }
     });
  }

  // --- RETAINER LOGIC ---
  const isRetainer = String(details.jobType).trim().toLowerCase() === 'retainer';
  const targetDayVal = (retainerDay && retainerDay > 0) ? retainerDay : 28;

  // NEW LOGIC: Only use Generative Mode if the retainer has NO child rows in the Pipeline
  if (isRetainer && (!pipelineChildRows || pipelineChildRows.length === 0) && details.startDate && details.endDate && details.revenue) {
    // FIXED: Safely convert Google Sheets serial dates (like 46089) into JS Dates to prevent the 1970 glitch
    const parseDateSafe = (d) => {
        if (d instanceof Date) return d;
        if (typeof d === 'number' && d > 20000 && d < 70000) {
            return new Date(new Date(1899, 11, 30).getTime() + Math.round(d * 86400000));
        }
        return new Date(d);
    };
    
    const startDate = parseDateSafe(details.startDate);
    const endDate = parseDateSafe(details.endDate);
    
    // FIXED: Use the actual Monthly Revenue from the CRM payload as the absolute source of truth
    let recurringAmt = parseFloat(String(details.revenue).replace(/[^0-9.-]/g, '')) || 0;
    let recurringDaysRaw = daysVal;
    
    // Still capture specific days-to-pay if it was customized in the Pipeline
    if (pipelineInvoices && pipelineInvoices.inv1.days) {
        recurringDaysRaw = pipelineInvoices.inv1.days;
    }
    
    // Fallback to the Pipeline Inv 1 amount ONLY if the CRM Revenue is 0 or completely blank
    if (recurringAmt === 0 && pipelineInvoices && (parseFloat(pipelineInvoices.inv1.amt) || 0) > 0) {
        recurringAmt = parseFloat(pipelineInvoices.inv1.amt);
    }
    
    const recurringDays = safeParseDays_(recurringDaysRaw, "Retainer Template");
    
    // FIXED: Calculate true duration using elapsed days instead of crude calendar months
    const diffTime = Math.abs(endDate.getTime() - startDate.getTime());
    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
    const totalMonthsActual = Math.max(1, Math.round(diffDays / 30.4375));
    
    const rowsToCreate = Math.min(totalMonthsActual, 18);

    if (totalMonthsActual >= 1) {
       for (let m = 0; m < rowsToCreate; m++) {
         const childRow = newRow + 1 + m;
         const invDate = new Date(startDate.getFullYear(), startDate.getMonth() + m, targetDayVal); 
         setVal(childRow, 'Client', details.client);
         setVal(childRow, 'Job name', details.jobName);
         if (recurringAmt > 0) {
             setVal(childRow, 'VAT?', 'Yes');
             setVal(childRow, 'Project invoice 1 / monthly retainer (excl VAT)', recurringAmt);
             setVal(childRow, 'Inv 1 SEND date', invDate);
             setVal(childRow, 'Inv 1 days to pay', recurringDays || daysVal);
         } else {
             setVal(childRow, 'VAT?', 'No');
         }
       }
       const rangeToGroup = targetSheet.getRange(newRow + 1, 1, rowsToCreate, 1);
       try { rangeToGroup.shiftRowGroupDepth(1); targetSheet.getRowGroup(newRow + 1, 1).collapse(); } catch (e) {}
       return `Converted Pipeline Job to Confirmed Retainer: ${details.client}`;
    }
  }

  // --- PROJECT CHILD ROW COPY ---
  const isProject = !isRetainer;
  if (isProject && pipelineChildRows && pipelineChildRows.length > 0) {
      if (pipelineInvoices) {
         [1, 2, 3].forEach(slot => {
            const k = `inv${slot}`;
            if ((parseFloat(pipelineInvoices[k].amt) || 0) > 0) {
                setVal(newRow, slot === 1 ? 'Project invoice 1 / monthly retainer (excl VAT)' : `Project invoice ${slot} (excl VAT)`, pipelineInvoices[k].amt);
                setVal(newRow, `Inv ${slot} SEND date`, pipelineInvoices[k].date);
                setVal(newRow, `Inv ${slot} status`, pipelineInvoices[k].status);
                setVal(newRow, `Inv ${slot} ref`, pipelineInvoices[k].ref);
                
                // Fix Parent Project Invoice Days
                const invDays = safeParseDays_(pipelineInvoices[k].days, `Parent Inv ${slot}`);
                setVal(newRow, `Inv ${slot} days to pay`, invDays || daysVal);
            }
         });
      }
      
      for (let c = 0; c < pipelineChildRows.length; c++) {
          const childRow = newRow + 1 + c;
          const child = pipelineChildRows[c];
          setVal(childRow, 'Client', details.client);
          setVal(childRow, 'Job name', details.jobName);
          
          // Transfer manual Pipeline columns for child rows
          if (child.revUnevenSplit) setVal(childRow, 'RevUnevenSplit', child.revUnevenSplit);
          
          if (child.invoices) {
              [1, 2, 3].forEach(slot => {
                  const ck = `inv${slot}`;
                  if ((parseFloat(child.invoices[ck].amt) || 0) > 0) {
                      setVal(childRow, 'VAT?', 'Yes');
                      setVal(childRow, slot === 1 ? 'Project invoice 1 / monthly retainer (excl VAT)' : `Project invoice ${slot} (excl VAT)`, child.invoices[ck].amt);
                      setVal(childRow, `Inv ${slot} SEND date`, child.invoices[ck].date);
                      setVal(childRow, `Inv ${slot} status`, child.invoices[ck].status);
                      setVal(childRow, `Inv ${slot} ref`, child.invoices[ck].ref);
                      
                      // Fix Child Invoice Days
                      const cInvDays = safeParseDays_(child.invoices[ck].days, `Child ${c+1} Inv ${slot}`);
                      setVal(childRow, `Inv ${slot} days to pay`, cInvDays || daysVal);
                  }
              });
          }
          
          if (child.expenses) {
              ['exp1', 'exp2', 'exp3'].forEach((k, idx) => {
                  const ei = idx + 1;
                  if ((parseFloat(child.expenses[k].amt) || 0) > 0 || child.expenses[k].desc) {
                      setVal(childRow, `Direct inv ${ei} amt`, child.expenses[k].amt);
                      setVal(childRow, `Direct inv ${ei} descr.`, child.expenses[k].desc);
                      setVal(childRow, `Direct inv ${ei} rec date`, child.expenses[k].date);
                      setVal(childRow, `Direct inv ${ei} app id`, child.expenses[k].id);
                      setVal(childRow, `Direct inv ${ei} status`, child.expenses[k].status);
                      setVal(childRow, `Dir inv ${ei} VAT?`, child.expenses[k].vat);
                      
                      // Fix Child Expense Days
                      const cExpDays = safeParseDays_(child.expenses[k].days, `Child ${c+1} Exp ${ei}`);
                      setVal(childRow, `Dir inv ${ei} days to pay`, cExpDays || daysVal);
                  }
              });
          }
      }
      if (pipelineChildRows.length > 0) {
          const rangeToGroup = targetSheet.getRange(newRow + 1, 1, pipelineChildRows.length, 1);
          try { rangeToGroup.shiftRowGroupDepth(1); targetSheet.getRowGroup(newRow + 1, 1).collapse(); } catch (e) {}
      }
      return `Copied Pipeline Project (with ${pipelineChildRows.length} child rows) to Confirmed: ${details.client}`;
  }

  // --- MANUAL INVOICE COPY (FALLBACK) ---
  if (pipelineInvoices) {
     [1, 2, 3].forEach(slot => {
        const k = `inv${slot}`;
        if ((parseFloat(pipelineInvoices[k].amt) || 0) > 0) {
           setVal(newRow, slot === 1 ? 'Project invoice 1 / monthly retainer (excl VAT)' : `Project invoice ${slot} (excl VAT)`, pipelineInvoices[k].amt);
           setVal(newRow, `Inv ${slot} SEND date`, pipelineInvoices[k].date);
           setVal(newRow, `Inv ${slot} status`, pipelineInvoices[k].status);
           setVal(newRow, `Inv ${slot} ref`, pipelineInvoices[k].ref);
           
           // Fix Fallback Invoice Days
           const fInvDays = safeParseDays_(pipelineInvoices[k].days, `Fallback Inv ${slot}`);
           setVal(newRow, `Inv ${slot} days to pay`, fInvDays || daysVal);
        }
     });
  }

  return `Copied Pipeline Project to Confirmed: ${details.client} | ${details.jobName}`;
}

function _applyInvoiceSchedule(sheet, row, headers, mode, revenueRaw, start, end, jobType, retainerDay) {
  // DEPRECATED / DISABLED
  // Logic has moved to Lazy Creation (leave blank) + Agent Receiver (Fill Gap).
  // Kept here only if needed for fallback, but effectively unused by main flow.
}

/**
 * Helper: Safely parses a 'Days to Pay' value. 
 * Converts accidentally date-formatted cells back to numbers.
 */
function safeParseDays_(val, context) {
    if (val instanceof Date) {
        console.warn(`[Days Format Warning] ${context}: Cell is formatted as a Date. Converting to serial.`);
        const epoch = new Date(1899, 11, 30);
        const serial = Math.round((val.getTime() - epoch.getTime()) / (24 * 60 * 60 * 1000));
        if (serial > 0 && serial < 366) return serial;
        return NaN;
    }
    return parseFloat(val);
}


/**
 * Scans the raw CRM data (Columns A-M) to catch jobs that arrived at 100% 
 * and bypassed the Pipeline dashboard view.
 */
async function processInstantConfirmedJobs_(ss) {
    Logger.log("--- STARTING processInstantConfirmedJobs_ ---");
    const instantLogs = [];
    const crmCompSheet = ss.getSheetByName('CRMComp');
    const crmListSheet = ss.getSheetByName('CRMList');
    const alertSheet = ss.getSheetByName('DataChgAlert');
    
    // Calculate cutoff date based on the number of months stored in DataChgAlert!B55
    const monthsBack = alertSheet ? (parseInt(alertSheet.getRange("B55").getValue()) || 0) : 0;
    let cutoffDate = null;
    if (monthsBack > 0) {
        cutoffDate = new Date();
        cutoffDate.setMonth(cutoffDate.getMonth() - monthsBack);
        cutoffDate.setHours(0, 0, 0, 0);
    }
    
    // Connect to the external Client Spreadsheet for Pipeline and Confirmed tabs
    const clientSheetId = (await getKeyInfoValue('X28'));
    if (!clientSheetId) {
        Logger.log("ERROR: Client Sheet ID (X28) not found.");
        return { needsGapAudit: false, logs: instantLogs };
    }
    
    let clientSs;
    try {
        clientSs = (await SpreadsheetApp.openById(clientSheetId));
    } catch (e) {
        Logger.log(`ERROR: Could not open Client Spreadsheet: ${e.message}`);
        return { needsGapAudit: false, logs: instantLogs };
    }

    const pipelineSheet = clientSs.getSheetByName('Pipeline');
    const confSheet = clientSs.getSheetByName('Confirmed');
    
    if (!crmCompSheet || !pipelineSheet || !confSheet || !crmListSheet) {
        Logger.log("ERROR: One or more sheets could not be found.");
        return { needsGapAudit: false, logs: instantLogs };
    }
    
    // --- DYNAMIC CONFIRMATION RULES (from CRMList) ---
    const rawLike = String(crmListSheet.getRange("DD2").getValue()).trim();
    const rawIncl = String(crmListSheet.getRange("DF2").getValue()).trim();
    const logicType = String(crmListSheet.getRange("DH2").getValue()).trim().toLowerCase();

    // Parse Operator
    let op = "=";
    const opMatch = rawLike.match(/^[<>=]+/);
    if (opMatch) op = opMatch[0];

    // Parse Value
    let val = 0;
    const valMatch = rawLike.match(/[\d\.]+/);
    if (valMatch) {
        val = parseFloat(valMatch[0]);
        if (rawLike.includes('%')) val = val / 100;
    }

    // Parse Statuses
    const inclStatuses = rawIncl ? rawIncl.toLowerCase().split(',').map(s => s.trim()).filter(String) : [];
    const hasStatusRule = rawIncl !== "";
    // -------------------------------------------------

    const lastRow = crmCompSheet.getLastRow();
    Logger.log(`CRMComp Last Row: ${lastRow}`);
    if (lastRow < 2) return { needsGapAudit: false, logs: instantLogs };
    
    const rawData = crmCompSheet.getRange(2, 1, lastRow - 1, 13).getValues();
    Logger.log(`Fetched ${rawData.length} rows from CRMComp raw data.`);
    
    // Helper to get an array of existing Project Codes from a sheet
    const getCodes = (sheet, sheetName) => {
        const data = sheet.getDataRange().getValues();
        if (data.length < 2) return [];
        const headers = data[0].map(h => String(h).trim().toLowerCase());
        let codeColIdx = headers.findIndex(h => h === 'project code');
        if (codeColIdx === -1) codeColIdx = headers.findIndex(h => h.includes('code') || h.includes('id'));
        if (codeColIdx === -1) {
            Logger.log(`WARNING: Code column not found in ${sheetName}.`);
            return [];
        }
        return data.map((r, i) => i === 0 ? null : String(r[codeColIdx]).trim()).filter(String);
    };
    
    const pipeCodes = getCodes(pipelineSheet, 'Pipeline');
    const confCodes = getCodes(confSheet, 'Confirmed');
    
    Logger.log(`Loaded ${pipeCodes.length} codes from Pipeline.`);
    Logger.log(`Loaded ${confCodes.length} codes from Confirmed.`);
    
    const pipeHeadersRow = pipelineSheet.getRange(1, 1, 1, pipelineSheet.getLastColumn()).getValues()[0];
    
    // Use bulletproof normalization to map complex headers
    const normalizeHdr = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const pipeHeadersNorm = pipeHeadersRow.map(normalizeHdr);
    
    // Replicate the strict 96-column Zone Check to find the true last non-blank row
    let trueLastRow = 0;
    const rowsToRead = Math.min(Math.max(1, pipelineSheet.getLastRow() + 1), pipelineSheet.getMaxRows());
    const allPipeData = pipelineSheet.getRange(1, 1, rowsToRead, 96).getValues();
    for (let i = allPipeData.length - 1; i >= 0; i--) {
        const row = allPipeData[i];
        const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
        const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
        const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
        const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
        if (z1 || z2 || z3 || z4) { 
            trueLastRow = i + 1; 
            break; 
        }
    }
    let nextAvailableRow = Math.max(3, trueLastRow + 1);

    let candidateCount = 0;
    let createdJobsCount = 0;
    
    rawData.forEach((row, idx) => {
        const [client, job, projCode, revenue, directCosts, startDate, endDate, likelihood, status, jobType, leadSrc, dateAdded, prodLine] = row;
        
        const codeStr = String(projCode).trim();
        if (!codeStr) return;
        
        // Filter out jobs with a start date older than the rolling window defined in DataChgAlert!B55
        if (cutoffDate && startDate) {
            const parseDateSafe = (d) => {
                if (d instanceof Date) return d;
                if (typeof d === 'number' && d > 20000 && d < 70000) {
                    return new Date(new Date(1899, 11, 30).getTime() + Math.round(d * 86400000));
                }
                const parsed = new Date(d);
                return isNaN(parsed.getTime()) ? null : parsed;
            };
            const startObj = parseDateSafe(startDate);
            if (startObj && startObj < cutoffDate) {
                return; // Skip jobs outside the allowed history window
            }
        }
        
        // --- EVALUATE DYNAMIC RULES ---
        // 1. Likelihood (fb)
        let fb = parseFloat(likelihood) || 0;
        if (String(likelihood).includes('%')) fb = fb / 100;

        let likeCond = false;
        if (op === "<") likeCond = fb < val;
        else if (op === "<=") likeCond = fb <= val;
        else if (op === ">") likeCond = fb > val;
        else if (op === ">=") likeCond = fb >= val;
        else likeCond = fb === val;

        // 2. Status
        const statStr = String(status).trim().toLowerCase();
        let statCond = true;
        if (hasStatusRule) {
            statCond = inclStatuses.some(s => statStr.includes(s));
        }

        // 3. Combined Result
        const isConfirmed = (logicType === "or") ? (likeCond || statCond) : (likeCond && statCond);
        // ------------------------------
        
        if (isConfirmed) {
            candidateCount++;
            Logger.log(`Candidate ${candidateCount} Found -> Row: ${idx + 2} | Code: ${codeStr} | Likel: ${likelihood} | Status: ${status}`);
            
            const inPipe = pipeCodes.includes(codeStr);
            const inConf = confCodes.includes(codeStr);
            
            if (!inPipe && !inConf) {
                Logger.log(`   -> TRIGGERING CREATION FOR: ${codeStr}`);
                
                // Build new Pipeline Row
                const newRowArr = new Array(pipeHeadersRow.length).fill("");
                
                const setPipeVal = (possibleHeaders, insertVal) => {
                    for (const ph of possibleHeaders) {
                        const colIdx = pipeHeadersNorm.indexOf(normalizeHdr(ph));
                        if (colIdx !== -1) {
                            newRowArr[colIdx] = insertVal;
                            break;
                        }
                    }
                };
                
                // Calculate VAT purely for this interceptor since it's missing from raw A-M data
                const cleanRevenue = parseFloat(String(revenue).replace(/[^0-9.-]/g, '')) || 0;
                const vatStatus = (cleanRevenue > 0) ? 'Yes' : 'No';

                // Included explicit aliases for complex destination headers
                setPipeVal(['Client'], client);
                setPipeVal(['Job name', 'Job'], job);
                setPipeVal(['Project code', 'Code', 'Job ID'], projCode);
                setPipeVal(['Revenue', 'Revenue (Proj total / Ongoing pm) - excl VAT'], revenue);
                setPipeVal(['Direct costs', 'Direct costs (proj total / ongoing pm) - excl vat'], directCosts);
                setPipeVal(['Start date'], startDate);
                setPipeVal(['End date'], endDate);
                setPipeVal(['% likel.', 'Likelihood', 'Probability'], 1); // Forces 1 to resolve to 100%
                setPipeVal(['Status'], status);
                setPipeVal(['Project / retainer', 'Job Type', 'Type'], jobType);
                setPipeVal(['Lead src', 'Lead source'], leadSrc);
                setPipeVal(['Date added', 'Date added to pipeline', 'Date originally added to pipeline'], dateAdded);
                setPipeVal(['Prod. line', 'Product line'], prodLine);
                // NOTE: Do NOT stamp 'Copied to conf. tab?' to 'Yes' until the Confirmed copy actually succeeds!
                setPipeVal(['VAT', 'VAT?'], vatStatus); 
                
                // Write specifically to the next available row using the safe Zone math
                if (nextAvailableRow > pipelineSheet.getMaxRows()) {
                    pipelineSheet.insertRowsAfter(pipelineSheet.getMaxRows(), 5);
                }
                
                // FIXED: Only write to cells that actually have mapped data to protect formulas and defaults in all other columns
                newRowArr.forEach((val, colIndex) => {
                    const str = String(val).trim().toUpperCase();
                    if (val !== "" && str !== "IGNORE" && str !== "<IGNORE>") {
                        pipelineSheet.getRange(nextAvailableRow, colIndex + 1).setValue(sanitizeSheetCell_(val)).setFontStyle('italic');
                    }
                });
                try { pipelineSheet.unhideRow(pipelineSheet.getRange(nextAvailableRow, 1, 1, 1)); } catch (e) {}
                
                Logger.log(`   -> Successfully injected row to Pipeline sheet at Row ${nextAvailableRow}.`);
                const insertedPipelineRow = nextAvailableRow;
                
                // Build the dynamic payload for the Confirmed Tab
                const dynamicPayload = {};
                pipeHeadersRow.forEach((h, i) => {
                    if (h && newRowArr[i] !== "") dynamicPayload[h] = newRowArr[i];
                });
                
                const jobDetails = {
                    client: client,
                    jobName: job,
                    projCode: codeStr,
                    revenue: revenue,
                    startDate: startDate,
                    endDate: endDate,
                    jobType: jobType || 'Project',
                    dateConf: new Date(),
                    dynamicPayload: dynamicPayload
                };
                
                // Push securely to Confirmed Tab
                let copyLog = "";
                let copySuccess = false;
                try {
                    if (typeof _copyPipelineJobToConfirmed === 'function') {
                        copyLog = _copyPipelineJobToConfirmed(clientSs, jobDetails, null, null, null);
                        Logger.log(`   -> _copyPipelineJobToConfirmed result: ${copyLog}`);
                        if (copyLog && !copyLog.toLowerCase().includes("error")) {
                            copySuccess = true;
                        }
                    } else {
                        copyLog = "ERROR: _copyPipelineJobToConfirmed function not found.";
                        Logger.log(`   -> ${copyLog}`);
                    }
                } catch (copyErr) {
                    copyLog = `Error copying to Confirmed: ${copyErr.message}`;
                    Logger.log(`   -> ${copyLog}`);
                }
                
                if (copySuccess) {
                    // Find Copied to Confirmed column in Pipeline
                    let copiedCol = pipeHeadersNorm.findIndex(h => h.includes('copiedtoconf'));
                    if (copiedCol === -1) copiedCol = 15; // default column 16 (0-indexed 15)
                    pipelineSheet.getRange(insertedPipelineRow, copiedCol + 1).setValue('Yes').setFontStyle('italic');
                    
                    instantLogs.push(`[CRM Pipeline -> Confirmed] Auto-copied 100% Won Job: ${client} | ${job} (${codeStr})`);
                    confCodes.push(codeStr);
                    createdJobsCount++;
                } else {
                    instantLogs.push(`[CRM Error] Added Pipeline Job ${codeStr} but failed to copy to Confirmed: ${copyLog}`);
                }
                
                // Track so we don't accidentally process it twice in this loop
                pipeCodes.push(codeStr);
                
                // Increment so the next trapped job goes directly beneath this one
                nextAvailableRow++; 
            } else if (inPipe && !inConf) {
                Logger.log(`   -> Job ${codeStr} exists in Pipeline but MISSING from Confirmed. Attempting recovery...`);
                let codeColIdx = pipeHeadersNorm.findIndex(h => h === 'projectcode');
                if (codeColIdx === -1) codeColIdx = pipeHeadersNorm.findIndex(h => h.includes('code') || h.includes('id'));
                if (codeColIdx !== -1) {
                    const pipeRowsCount = Math.min(pipelineSheet.getLastRow(), pipelineSheet.getMaxRows());
                    const existingPipeCodes = pipelineSheet.getRange(1, codeColIdx + 1, pipeRowsCount, 1).getValues().flat();
                    const targetPipeRow = existingPipeCodes.findIndex(c => String(c || '').trim().toUpperCase() === codeStr) + 1;
                    if (targetPipeRow > 1) {
                        const pipeRowVals = pipelineSheet.getRange(targetPipeRow, 1, 1, pipelineSheet.getLastColumn()).getValues()[0];
                        const dynamicPayload = {};
                        pipeHeadersRow.forEach((h, i) => {
                            if (h && pipeRowVals[i] !== "") dynamicPayload[h] = pipeRowVals[i];
                        });
                        
                        const getPipeVal = (possibleHeaders) => {
                            for (const ph of possibleHeaders) {
                                const idx = pipeHeadersNorm.indexOf(normalizeHdr(ph));
                                if (idx !== -1 && pipeRowVals[idx] !== "") return pipeRowVals[idx];
                            }
                            return "";
                        };

                        const jobDetails = {
                            client: getPipeVal(['Client']) || client,
                            jobName: getPipeVal(['Job name', 'Job']) || job,
                            projCode: codeStr,
                            revenue: getPipeVal(['Revenue', 'Revenue (Proj total / Ongoing pm) - excl VAT']) || revenue,
                            startDate: getPipeVal(['Start date']) || startDate,
                            endDate: getPipeVal(['End date']) || endDate,
                            jobType: getPipeVal(['Project / retainer', 'Job Type', 'Type']) || jobType || 'Project',
                            dateConf: new Date(),
                            dynamicPayload: dynamicPayload
                        };

                        let copyLog = "";
                        let copySuccess = false;
                        try {
                            if (typeof _copyPipelineJobToConfirmed === 'function') {
                                copyLog = _copyPipelineJobToConfirmed(clientSs, jobDetails, null, null, null);
                                Logger.log(`   -> Recovery _copyPipelineJobToConfirmed result: ${copyLog}`);
                                if (copyLog && !copyLog.toLowerCase().includes("error")) {
                                    copySuccess = true;
                                }
                            } else {
                                copyLog = "ERROR: _copyPipelineJobToConfirmed function not found.";
                            }
                        } catch (copyErr) {
                            copyLog = `Error copying to Confirmed: ${copyErr.message}`;
                            Logger.log(`   -> ${copyLog}`);
                        }

                        if (copySuccess) {
                            let copiedCol = pipeHeadersNorm.findIndex(h => h.includes('copiedtoconf'));
                            if (copiedCol === -1) copiedCol = 15;
                            pipelineSheet.getRange(targetPipeRow, copiedCol + 1).setValue('Yes').setFontStyle('italic');
                            confCodes.push(codeStr);
                            createdJobsCount++;
                            instantLogs.push(`[CRM Pipeline -> Confirmed] Auto-copied missing 100% Won Job: ${jobDetails.client} | ${jobDetails.jobName} (${codeStr})`);
                        } else {
                            instantLogs.push(`[CRM Error] Recovery copy to Confirmed failed for ${codeStr}: ${copyLog}`);
                        }
                    }
                }
            } else {
                Logger.log(`   -> Skipped. Job already exists in the system.`);
            }
        }
    });
    
    Logger.log(`--- FINISHED processInstantConfirmedJobs_ (Candidates evaluated: ${candidateCount}) ---`);
    return { needsGapAudit: createdJobsCount > 0, logs: instantLogs };
}


