function installAgentCheck() {
  ScriptApp.newTrigger('checkForAgentSignal')
    .timeBased()
    .everyMinutes(30)
    .create();
  SpreadsheetApp.getUi().alert("Agent set to check for orders every 30 mins.");
}

function installAgentFinancePull() {
  _removeTrigger('PullInvoicesBasedOn');
  _removeTrigger('PullPLBasedOn');
  console.log('Success: Old daily Finance triggers removed (Now managed by Agent).');
}

function installAgentCRMpull() {
  _removeTrigger('PullCRMBasedOn');
  console.log('Success: Old daily CRM trigger removed (Now managed by Agent).');
}

function _removeTrigger(funcName) {
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(trigger => {
    if (trigger.getHandlerFunction() === funcName) {
      ScriptApp.deleteTrigger(trigger);
    }
  });
}

function isPlaceholderInvoice_(ref) {
  if (!ref) return false;
  const s = String(ref).toUpperCase();
  return s.includes("PLACE-INV") || s.includes("MANUAL-INV");
}

function isPlaceholderExpense_(ref) {
  if (!ref) return false;
  const s = String(ref).toUpperCase();
  return s.includes("PLACE-EXP") || s.includes("MANUAL-ENTRY") || s.includes("UNRECON-GAP") || s.includes("PLACE-GAP") || s.includes("MANUAL-GAP");
}

const AUTOMATOR_MAX_LEASE_MS_ = 8 * 60 * 1000; // 8 minutes (safely above GAS 6-minute hard execution limit)

/**
 * Detects and self-heals orphaned automation runs that were killed by hard GAS
 * execution timeouts (which bypass JS catch/finally blocks).
 * Logs an explicit "Error: ... Timeout" entry to AutoLog and updates DataChgAlert
 * rolling history so PMA triage alerts surface hard timeouts reliably.
 */
async function healStaleAutomatorLocks_(ss, alertSheet, props, callerHoldsLock = false) {
  if (!alertSheet || !props) return { isActivelyRunning: false, healedCount: 0 };
  const nowTs = Date.now();
  const activeStartTs = Number(props.getProperty('ACTIVE_AUTOMATOR_START') || 0);
  const activeCat = String(props.getProperty('ACTIVE_AUTOMATOR_CATEGORY') || '').trim().toUpperCase();
  const lastAuditTs = Number(props.getProperty('LAST_STALE_LOCK_AUDIT_TS') || 0);

  // If an execution is within its normal 8-minute window and caller doesn't already hold the lock, do not disturb it
  if (!callerHoldsLock && activeStartTs > 0 && (nowTs - activeStartTs) < AUTOMATOR_MAX_LEASE_MS_) {
    return { isActivelyRunning: true, healedCount: 0 };
  }

  // Fast-path for idle 1-minute triggers when no run was tracked and we audited within the last 5 minutes
  if (!callerHoldsLock && activeStartTs === 0 && lastAuditTs > 0 && (nowTs - lastAuditTs) < 5 * 60 * 1000) {
    return { isActivelyRunning: false, healedCount: 0 };
  }

  let lockRow = [];
  try {
    lockRow = (alertSheet.getRange("B4:I4").getValues()[0]) || [];
    props.setProperty('LAST_STALE_LOCK_AUDIT_TS', String(nowTs));
  } catch (e) {
    console.warn("healStaleAutomatorLocks_: Failed to read DataChgAlert!B4:I4: " + e.message);
    return { isActivelyRunning: false, healedCount: 0 };
  }

  const slots = [
    { category: "INVOICES", label: "Invoice Sequence", flagIdx: 0, tsIdx: 1, flagCell: "B4", lastRunCell: "AB2", statusCell: "AC2", jsonCell: "BM2" },
    { category: "EXPENSES", label: "Expenses Sequence", flagIdx: 4, tsIdx: 5, flagCell: "F4", lastRunCell: "AB4", statusCell: "AC4", jsonCell: "BM4" },
    { category: "CRM",      label: "CRM Sequence",      flagIdx: 6, tsIdx: 7, flagCell: "H4", lastRunCell: "AB3", statusCell: "AC3", jsonCell: "BM3" }
  ];

  const staleSlots = [];
  for (let i = 0; i < slots.length; i++) {
    const slot = slots[i];
    const flagVal = String(lockRow[slot.flagIdx] || "").trim().toUpperCase();
    const rawTs = lockRow[slot.tsIdx];
    const cellTsMs = (rawTs instanceof Date && !isNaN(rawTs.getTime())) ? rawTs.getTime() : 0;
    const effectiveStartMs = cellTsMs || (activeCat === slot.category ? activeStartTs : 0);

    if (flagVal === "YES") {
      if (effectiveStartMs > 0 && (nowTs - effectiveStartMs) < AUTOMATOR_MAX_LEASE_MS_ && !callerHoldsLock) {
        return { isActivelyRunning: true, healedCount: 0 };
      }
      if (effectiveStartMs === 0 || (nowTs - effectiveStartMs) >= AUTOMATOR_MAX_LEASE_MS_) {
        staleSlots.push({ slot: slot, startMs: effectiveStartMs });
      }
    } else if (activeStartTs > 0 && (nowTs - activeStartTs) >= AUTOMATOR_MAX_LEASE_MS_ && activeCat === slot.category) {
      staleSlots.push({ slot: slot, startMs: activeStartTs });
    }
  }

  if (staleSlots.length === 0) {
    if (activeStartTs > 0 && (nowTs - activeStartTs) >= AUTOMATOR_MAX_LEASE_MS_) {
      props.deleteProperty('ACTIVE_AUTOMATOR_START');
      props.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    }
    return { isActivelyRunning: false, healedCount: 0 };
  }

  let healLock = null;
  if (!callerHoldsLock) {
    healLock = LockService.getScriptLock();
    if (!healLock.tryLock(2000)) {
      return { isActivelyRunning: true, healedCount: 0 };
    }
  }

  try {
    const tz = ss ? ss.getSpreadsheetTimeZone() : "GMT";
    for (let j = 0; j < staleSlots.length; j++) {
      const item = staleSlots[j];
      const slot = item.slot;
      const startedStr = item.startMs > 0
        ? Utilities.formatDate(new Date(item.startMs), tz, "HH:mm")
        : "";
      const errSummary = "Error: " + slot.label + " Timeout";
      const errDetails = "Error: " + slot.label + " - Execution timed out or terminated unexpectedly (exceeded GAS 6-minute execution limit" + (startedStr ? "; started at " + startedStr : "") + ").";

      console.warn("Agent Self-Heal: " + errDetails);
      alertSheet.getRange(slot.flagCell).setValue("NO");
      if (slot.category === "CRM") {
        const crmSheet = ss ? ss.getSheetByName("CRMComp") : null;
        if (crmSheet) crmSheet.getRange("U4").setValue("No");
      }
      if (typeof writeToAutoLog === 'function') {
        writeToAutoLog(slot.category, errSummary, errDetails);
      }
      if (typeof updateRollingLog === 'function') {
        updateRollingLog(alertSheet, slot.statusCell, slot.jsonCell, 0, false, errDetails);
      }
      alertSheet.getRange(slot.lastRunCell).setValue(new Date());
      if (typeof postAgentProgress_ === 'function') {
        (await postAgentProgress_("error", errDetails, true));
      }
    }
    props.deleteProperty('ACTIVE_AUTOMATOR_START');
    props.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    (await SpreadsheetApp.flush());
    return { isActivelyRunning: false, healedCount: staleSlots.length };
  } finally {
    if (healLock) {
      healLock.releaseLock();
    }
  }
}

/// --- THE GATEKEEPER ---
async function checkForAgentSignal() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const signalSheet = ss.getSheetByName("DataChgAlert");
    if (!signalSheet) return;
    const props = PropertiesService.getScriptProperties();
    
    // 0. CLEANUP DAISY-CHAIN TRIGGER
    const chainTriggerId = props.getProperty('CHAIN_TRIGGER_ID');
    if (chainTriggerId) {
        const allTriggers = ScriptApp.getProjectTriggers();
        for (const t of allTriggers) {
            if (t.getUniqueId() === chainTriggerId) {
                ScriptApp.deleteTrigger(t);
                break;
            }
        }
        props.deleteProperty('CHAIN_TRIGGER_ID');
        console.log("Agent: Cleanup - Deleted used daisy-chain trigger.");
    }

    // 0b. SELF-HEAL ANY ORPHANED / TIMED-OUT RUNS & DEFER IF ACTIVE
    const lockCheck = (await healStaleAutomatorLocks_(ss, signalSheet, props, false));
    if (lockCheck && lockCheck.isActivelyRunning) {
      console.log("Agent: Another automation sequence is actively running. Deferring signal check until next tick.");
      return;
    }

    // 1. READ ALL SIGNALS
    const lastSignalInv = signalSheet.getRange("Z2").getValue();
    const lastSignalCrm = signalSheet.getRange("Z3").getValue();
    const lastSignalExp = signalSheet.getRange("Z4").getValue();

    const storedInvTime = Number(props.getProperty('LAST_SIG_TIMESTAMP_INV') || 0);
    const storedCrmTime = Number(props.getProperty('LAST_SIG_TIMESTAMP_CRM') || 0);
    const storedExpTime = Number(props.getProperty('LAST_SIG_TIMESTAMP_EXP') || 0);

    // 2. DETERMINE WHICH TASKS ARE PENDING
    const isInvPending = (lastSignalInv instanceof Date && lastSignalInv.getTime() > storedInvTime);
    const isCrmPending = (lastSignalCrm instanceof Date && lastSignalCrm.getTime() > storedCrmTime);
    const isExpPending = (lastSignalExp instanceof Date && lastSignalExp.getTime() > storedExpTime);
    // Helper to create chain trigger
    const createChainTrigger = () => {
        console.log("Agent: Creating daisy-chain trigger (15s)...");
        const newTrigger = ScriptApp.newTrigger("checkForAgentSignal")
           .timeBased()
           .after(15000) 
           .create();
        props.setProperty('CHAIN_TRIGGER_ID', newTrigger.getUniqueId());
    };
    // 3. EXECUTE WITH PRIORITY (One at a time to prevent timeouts)
    
    // --- PRIORITY 1: INVOICES ---
    if (isInvPending) {
      console.log("Agent: Detected INVOICE signal. Starting batch...");
      props.setProperty('LAST_SIG_TIMESTAMP_INV', lastSignalInv.getTime().toString());
      const invRes = (await runAgencyAutomator(true, false, false)); 
      if (invRes && invRes.skippedLock) {
        props.setProperty('LAST_SIG_TIMESTAMP_INV', String(storedInvTime));
        return;
      }

      if (isCrmPending || isExpPending) {
         console.log("Agent: CRM or Expenses also pending. Daisy-chaining restart in 15s...");
         createChainTrigger();
      } else {
         (await postAgentProgress_("done", "All requested sequences complete.", true));
      }
      return; 
    }

    // --- PRIORITY 2: CRM ---
    if (isCrmPending) {
      console.log("Agent: Detected CRM signal. Starting batch...");
      props.setProperty('LAST_SIG_TIMESTAMP_CRM', lastSignalCrm.getTime().toString());
      const crmRes = (await runAgencyAutomator(false, true, false));
      if (crmRes && crmRes.skippedLock) {
        props.setProperty('LAST_SIG_TIMESTAMP_CRM', String(storedCrmTime));
        return;
      }

      if (isExpPending) {
         console.log("Agent: Expenses also pending. Daisy-chaining restart in 15s...");
         createChainTrigger();
      } else {
         (await postAgentProgress_("done", "All requested sequences complete.", true));
      }
      return; 
    }

    // --- PRIORITY 3: EXPENSES ---
    if (isExpPending) {
      console.log("Agent: Detected EXPENSE signal. Starting batch...");
      props.setProperty('LAST_SIG_TIMESTAMP_EXP', lastSignalExp.getTime().toString());
      const expRes = (await runAgencyAutomator(false, false, true));
      if (expRes && expRes.skippedLock) {
        props.setProperty('LAST_SIG_TIMESTAMP_EXP', String(storedExpTime));
        return;
      }
      console.log("Agent: All pending batches complete.");
      (await postAgentProgress_("done", "All requested sequences complete.", true));
      return; 
    }
  } catch (e) {
    console.error("Gatekeeper Error: " + e.message);
    if (typeof writeToAutoLog === 'function') {
      writeToAutoLog("SYSTEM", "Error: Gatekeeper", "Error: Gatekeeper - " + e.message);
    }
  }
}

/**
 * THE WORKER
 * V11.1 - Corrected Syntax: Added enhanced logging for Retainers and CRM Deletions/Skips.
 */
async function runAgencyAutomator(runInv = false, runCrm = false, runExp = false) {
  // NEW: Strict Concurrency Lock + ScriptProperties lease guard (protects runs > 5-6m where GAS LockService lease may expire)
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(10000)) {
    console.log("Agent: Sequence is already running. Aborting to prevent data collision.");
    if (typeof writeToAutoLog === 'function') {
      writeToAutoLog("SYSTEM", "Skipped: System Lock", "Error: System Lock - Another sequence was actively running. Aborted to prevent data collision.");
    }
    return { skippedLock: true };
  }

  const runProps = PropertiesService.getScriptProperties();
  const activeStartTs = Number(runProps.getProperty('ACTIVE_AUTOMATOR_START') || 0);
  const nowTs = Date.now();
  if (activeStartTs > 0 && (nowTs - activeStartTs) < AUTOMATOR_MAX_LEASE_MS_) {
    console.log("Agent: Active sequence lease still within 8m window. Aborting to prevent overlapping execution.");
    lock.releaseLock();
    return { skippedLock: true };
  }
  
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const alertSheet = ss.getSheetByName("DataChgAlert");
    const crmSheet = ss.getSheetByName("CRMComp");
    const runStart = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "HH:mm");

    // Self-heal any prior run that timed out (>= 8m old) before starting the new sequence
    if (alertSheet) {
      (await healStaleAutomatorLocks_(ss, alertSheet, runProps, true));
    }
    runProps.setProperty('ACTIVE_AUTOMATOR_START', String(Date.now()));

  // --- PART 1: INVOICES ---
  if (runInv) {
    console.log("Agent: Starting Invoice Sequence...");
    (await postAgentProgress_("invoice", "Starting invoice sequence...", false));
    runProps.setProperty('ACTIVE_AUTOMATOR_CATEGORY', 'INVOICES');
    
    let updateCount = 0;
    let isSuccess = true;
    let msg = "";
    let logs = [];
    let summaryText = "";
    let hasInvErrors = false;
    let firstError = "";

    alertSheet.getRange("B4").setValue("YES");
    alertSheet.getRange("C4").setValue(new Date());
    (await SpreadsheetApp.flush());

    try {
      console.log("Agent: Pulling fresh invoices via PullInvoicesBasedOn(true)...");
      if (typeof clearLastConnectorError === 'function') clearLastConnectorError();
      let invPullResult = null;
      try {
        invPullResult = (await PullInvoicesBasedOn(true));
      } catch (pullErr) {
        if (typeof setLastConnectorError === 'function') setLastConnectorError(pullErr.message);
      }
      const pullConnErr = (typeof getLastConnectorError === 'function') ? getLastConnectorError() : null;

      console.log("Agent: invPullResult received:", invPullResult ? {
        newCount: invPullResult.newInvoices?.length,
        updatedCount: invPullResult.updatedInvoices?.length
      } : "FALSY/UNDEFINED", "pullConnErr:", pullConnErr || "NONE");

      const newInvCount = invPullResult?.newInvoices?.length || 0;
      const updInvCount = invPullResult?.updatedInvoices?.length || 0;
      (await postAgentProgress_("invoice", "Invoices pulled: " + newInvCount + " new, " + updInvCount + " updated", false));

      // 2. RETAINER AUDIT
      const runRetainerFix = alertSheet.getRange("B48").getValue() === "Yes";
      if (runRetainerFix) {
         console.log("Agent: Running Retainer Audit & Fix...");
         (await postAgentProgress_("invoice", "Auditing retainer schedules...", false));
         const retainerRes = (await processRetainerAudit(ss, alertSheet));
         if (retainerRes.hasError || retainerRes.error) {
           logs.push(`Error: Retainer Audit - ${retainerRes.error}`);
           hasInvErrors = true;
           if (!firstError) firstError = `Error: Retainer Audit - ${retainerRes.error}`;
         } else {
           const rCount = retainerRes.count || 0; 
           updateCount += rCount;
           const retStatus = (rCount > 0) ? "Yes" : "No";
           alertSheet.getRange("AQ2").setValue(retStatus);

           if (rCount > 0) {
                   msg += ` | Ret: ${rCount}`;
                   if (retainerRes.logs && retainerRes.logs.length > 0) {
                       logs.push(`[Retainers] Action taken on ${rCount} retainer job(s):\n` + retainerRes.logs.join("\n"));
                   }
           }
         }
      } else {
         alertSheet.getRange("AQ2").setValue("No");
      }

      (await SpreadsheetApp.flush());
      (await Utilities.sleep(2000));

      // 3. INVOICE GAP AUDIT
      console.log("Agent: Auditing Invoice Gaps...");
      (await postAgentProgress_("invoice", "Auditing invoice gaps across pipeline and confirmed jobs...", false));
      const gapRes = (await auditInvoiceGaps(true, true)); 
      if (gapRes.hasError || gapRes.error) {
        logs.push(`Error: Audit Invoice Gaps - ${gapRes.error}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Audit Invoice Gaps - ${gapRes.error}`;
      } else {
        updateCount += gapRes.count;
        if (gapRes.count > 0) {
            msg += ` | Gaps: ${gapRes.count}`;
            logs.push(`Created/Adjusted ${gapRes.count} Invoice Gaps:\n` + gapRes.logs.join("\n"));
        }
      }

      // 3b. PRE-MATCH PART-PAID INVOICES
      // Resolve any existing part-paid balances that have now been paid (or newly part-paid) in Xero
      // before InvComp evaluates discrepancies for standard invoice matching.
      let prePartPaidRes = null;
      try {
        prePartPaidRes = (await processPartPaidInvoices(ss, alertSheet));
        if (prePartPaidRes && !prePartPaidRes.hasError && !prePartPaidRes.error && (prePartPaidRes.count || 0) > 0) {
          updateCount += prePartPaidRes.count;
          msg += ` | Part-paid: ${prePartPaidRes.count}`;
          logs.push(`Updated ${prePartPaidRes.count} Part-Paid Invoices:\n` + (prePartPaidRes.logs ? prePartPaidRes.logs.join("\n") : ""));
        }
      } catch (prePpErr) {
        console.warn("Pre-match Part-Paid Invoices warning: " + prePpErr.message);
      }

      // 4. INVOICE MATCHING
      console.log("Agent: Matching and reconciling invoices...");
      (await postAgentProgress_("invoice", "Matching and reconciling invoices against Confirmed jobs...", false));
      let invStats = { updated: 0, dashDisc: 0, appDisc: 0, logs: [] };
      try {
        invStats = (await processInvoices(ss, alertSheet));
        updateCount += (invStats.updated || 0);
        alertSheet.getRange("AF2").setValue(invStats.dashDisc);
        alertSheet.getRange("AG2").setValue(invStats.appDisc);
        if (invStats.updated > 0) {
            logs.push(`Matched/Updated ${invStats.updated} Invoices from Xero:\n` + (invStats.logs ? invStats.logs.join("\n") : ""));
        }
      } catch (matchErr) {
        console.error("Error: Invoice Matching - " + matchErr.message);
        logs.push(`Error: Invoice Matching - ${matchErr.message}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Invoice Matching - ${matchErr.message}`;
      }

      // 5. STALE UNSENT
      console.log("Agent: Sweeping Stale Unsent Invoices...");
      (await postAgentProgress_("invoice", "Sweeping stale unsent and overdue invoices...", false));
      const staleRes = (await updateStaleUnsentInvoices(ss, alertSheet));
      if (staleRes.hasError || staleRes.error) {
        logs.push(`Error: Stale Invoices - ${staleRes.error}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Stale Invoices - ${staleRes.error}`;
      } else {
        // FIXED: Raise the flag by writing the update count directly to DataChgAlert
        alertSheet.getRange("BG2").setValue(staleRes.count);
        updateCount += staleRes.count;
        if (staleRes.count > 0) {
            msg += ` | Stale: ${staleRes.count}`;
            logs.push(`Updated ${staleRes.count} Stale Invoices:\n` + staleRes.logs.join("\n"));
        }
      }

      // 6. OVERDUE
      const overdueRes = (await updateOverdueInvoicesInConfirmed(ss, alertSheet));
      if (overdueRes.hasError || overdueRes.error) {
        logs.push(`Error: Overdue Invoices - ${overdueRes.error}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Overdue Invoices - ${overdueRes.error}`;
      } else {
        updateCount += overdueRes.count;
        if (overdueRes.count > 0) {
            logs.push(`Updated ${overdueRes.count} Overdue Invoices:\n` + overdueRes.logs.join("\n"));
        }
      }

      // 7. PART-PAID INVOICES
      console.log("Agent: Processing Part-Paid Invoices...");
      (await postAgentProgress_("invoice", "Processing part-paid invoices in Confirmed...", false));
      const partPaidRes = (await processPartPaidInvoices(ss, alertSheet));
      if (partPaidRes.hasError || partPaidRes.error) {
        logs.push(`Error: Part-Paid Invoices - ${partPaidRes.error}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Part-Paid Invoices - ${partPaidRes.error}`;
      } else {
        updateCount += partPaidRes.count;
        if (partPaidRes.count > 0) {
            msg += ` | Part-paid: ${partPaidRes.count}`;
            logs.push(`Updated ${partPaidRes.count} Part-Paid Invoices:\n` + partPaidRes.logs.join("\n"));
        }
      }

      // 7b. POST-MATCH INVOICE GAP RE-AUDIT
      // If invoices were matched or part-paid, re-audit invoice gaps immediately so
      // remaining placeholder slots on Confirmed/Pipeline jobs re-balance without waiting for next cycle.
      const shouldReAuditInvGaps = (typeof invStats !== 'undefined' && (invStats.updated || 0) > 0) || (prePartPaidRes && (prePartPaidRes.count || 0) > 0) || (partPaidRes && (partPaidRes.count || 0) > 0);
      if (shouldReAuditInvGaps) {
        console.log("Agent: Re-auditing invoice gaps following invoice matches/part-paid updates...");
        (await postAgentProgress_("invoice", "Re-auditing invoice gaps to balance placeholders...", false));
        const postGapRes = (await auditInvoiceGaps(true, true));
        if (postGapRes.hasError || postGapRes.error) {
          logs.push(`Error: Post-Match Invoice Gaps - ${postGapRes.error}`);
          hasInvErrors = true;
          if (!firstError) firstError = `Error: Post-Match Invoice Gaps - ${postGapRes.error}`;
        } else if (postGapRes.count > 0) {
          updateCount += postGapRes.count;
          msg += ` | Re-gap: ${postGapRes.count}`;
          logs.push(`Post-Match Re-Audited ${postGapRes.count} Invoice Gaps:\n` + postGapRes.logs.join("\n"));
        }
      }

      // 8. ACCOUNTING DOWNLOAD LOG (New & Updated Invoices from Fresh Pull)
      if (pullConnErr) {
        logs.unshift(`Error: Accounting Download - ${pullConnErr}`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Accounting Download - ${pullConnErr}`;
      } else if (invPullResult) {
        const pullSection = [];
        const newInvs = invPullResult.newInvoices || [];
        const updatedInvs = invPullResult.updatedInvoices || [];

        if (newInvs.length > 0) {
          let text = `• New Invoices (${newInvs.length}):\n` + newInvs.slice(0, 20).map(s => `  - ${s}`).join("\n");
          if (newInvs.length > 20) text += `\n  ...and ${newInvs.length - 20} more`;
          pullSection.push(text);
        }
        if (updatedInvs.length > 0) {
          let text = `• Updated Invoices (${updatedInvs.length}):\n` + updatedInvs.slice(0, 20).map(s => `  - ${s}`).join("\n");
          if (updatedInvs.length > 20) text += `\n  ...and ${updatedInvs.length - 20} more`;
          pullSection.push(text);
        }

        if (pullSection.length > 0) {
          logs.unshift(`[Accounting Download]\n` + pullSection.join("\n\n"));
        } else {
          logs.unshift(`[Accounting Download]\n• No new or updated invoices.`);
        }
      } else {
        console.warn("Agent: invPullResult was null or undefined.");
        logs.unshift(`Error: Accounting Download - Invoice pull returned no data (verify KeyInfo Q4 configuration).`);
        hasInvErrors = true;
        if (!firstError) firstError = `Error: Accounting Download - Invoice pull returned no data`;
      }

      const hasRealAdjustments = updateCount > 0 || (invPullResult && ((invPullResult.newInvoices && invPullResult.newInvoices.length > 0) || (invPullResult.updatedInvoices && invPullResult.updatedInvoices.length > 0)));
      if (hasInvErrors) {
        isSuccess = false;
        msg = firstError || "Error during run";
        if (hasRealAdjustments) {
          summaryText = "Adjustments made with errors.";
        } else {
          summaryText = firstError || "Error during run";
        }
      } else if (!hasRealAdjustments) {
        summaryText = "No changes required.";
        logs.push("No invoices matched, no gaps found, no dates updated.");
        if (msg === "") msg = "Run OK";
      } else {
        summaryText = "Adjustments made to Invoices.";
        if (msg === "") msg = "Run OK";
      }
      
      // SINGLE CONSOLIDATED LOG ENTRY
      writeToAutoLog("INVOICES", summaryText, logs.join("\n\n"));
      (await postAgentProgress_("invoice", summaryText, false));

    } catch (e) {
      console.log("Agent Inv Error: " + e.message);
      isSuccess = false;
      msg = "Error: Invoice Sequence - " + e.message;
      writeToAutoLog("INVOICES", "Error: Invoice Sequence", "Error: Invoice Sequence - " + e.message);
      (await postAgentProgress_("invoice", "Error: " + e.message, false));
      alertSheet.getRange("B4").setValue("NO");
      (await SpreadsheetApp.flush());
    }

    updateRollingLog(alertSheet, "AC2", "BM2", updateCount, isSuccess, msg);
    alertSheet.getRange("AB2").setValue(new Date());
    alertSheet.getRange("B4").setValue("NO");
    runProps.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    (await SpreadsheetApp.flush());
  }

  // --- PART 2: CRM ---
  if (runCrm) {
    console.log("Agent: Starting CRM Sequence...");
    (await postAgentProgress_("crm", "Starting CRM sequence...", false));
    runProps.setProperty('ACTIVE_AUTOMATOR_CATEGORY', 'CRM');
    runProps.setProperty('ACTIVE_AUTOMATOR_START', String(Date.now()));
    
    let updateCount = 0;
    let isSuccess = true;
    let msg = "";
    let hasCrmErrors = false;
    let firstCrmError = "";

    alertSheet.getRange("H4").setValue("YES");
    alertSheet.getRange("I4").setValue(new Date());
    (await SpreadsheetApp.flush());

    try {
      const keyInfoSheet = ss.getSheetByName("KeyInfo");
      const crmMode = keyInfoSheet.getRange("Q9").getValue();

      // PRE-PULL SNAPSHOT: Capture existing DataFromCRM rows
      const crmDataSheet = ss.getSheetByName("DataFromCRM");
      const beforeCrmMap = new Map();
      let crmHeaders = [];
      let crmColIndices = { idIdx: 0, clientIdx: -1, jobIdx: -1, valueIdx: -1, statusIdx: -1 };

      if (crmDataSheet) {
        (await SpreadsheetApp.flush());
        const lastRowBefore = crmDataSheet.getLastRow();
        const lastColBefore = crmDataSheet.getLastColumn();
        if (lastRowBefore > 1 && lastColBefore > 0) {
          const allDataBefore = crmDataSheet.getRange(1, 1, lastRowBefore, lastColBefore).getValues();
          crmHeaders = allDataBefore[0];
          crmColIndices = getCrmColumnIndices_(crmHeaders);
          for (let i = 1; i < allDataBefore.length; i++) {
            const r = allDataBefore[i];
            const id = String(r[crmColIndices.idIdx] || "").trim();
            if (id) beforeCrmMap.set(id, r);
          }
        } else if (lastRowBefore === 1 && lastColBefore > 0) {
          crmHeaders = crmDataSheet.getRange(1, 1, 1, lastColBefore).getValues()[0];
          crmColIndices = getCrmColumnIndices_(crmHeaders);
        }
      }

      if (crmSheet) {
        crmSheet.getRange("U4").setValue("Yes"); 
        (await SpreadsheetApp.flush());
      }

      if (typeof clearLastConnectorError === 'function') clearLastConnectorError();
      (await postAgentProgress_("crm", "Downloading fresh opportunities from CRM...", false));
      try {
        (await PullCRMBasedOn(true));
      } catch (crmPullErr) {
        if (typeof setLastConnectorError === 'function') setLastConnectorError(crmPullErr.message);
      }
      const crmPullError = (typeof getLastConnectorError === 'function') ? getLastConnectorError() : null;
      (await postAgentProgress_("crm", "Reconciling pipeline jobs against CRM...", false));

      let pipeStats = { updated: 0, logs: [], deletedJobs: [], skippedRows: 0 };
      let confStats = { updated: 0, logs: [], deletedJobs: [], skippedRows: 0 };

      pipeStats = (await processCRMWorkflow(ss, alertSheet, "Pipeline"));
      if (pipeStats.hasError || pipeStats.error) {
        hasCrmErrors = true;
        if (!firstCrmError) firstCrmError = `Error: CRM Workflow - ${pipeStats.error}`;
      }

      if (crmMode === "PipeAndConf") {
          (await postAgentProgress_("crm", "Reconciling confirmed jobs against CRM...", false));
          confStats = (await processCRMWorkflow(ss, alertSheet, "Confirmed"));
          if (confStats.hasError || confStats.error) {
            hasCrmErrors = true;
            if (!firstCrmError) firstCrmError = `Error: CRM Workflow - ${confStats.error}`;
          }
      }
      
      // NEW LOGIC: Intercept "Instant 100%" jobs when in Pipeline-only mode but Copy to Confirmed is enabled
      const copyToConfFlag = String(alertSheet.getRange("B82").getValue()).trim().toUpperCase();
      let instantStats = { needsGapAudit: false, logs: [] };
      try {
        if (crmMode === "Pipeline" && copyToConfFlag === "YES") {
            (await postAgentProgress_("crm", "Processing instant 100% confirmed jobs...", false));
            instantStats = (await processInstantConfirmedJobs_(ss)) || { needsGapAudit: false, logs: [] };
        }
      } catch (instErr) {
        console.error("Error: Instant Confirmed Jobs - " + instErr.message);
        hasCrmErrors = true;
        if (!firstCrmError) firstCrmError = `Error: Instant Confirmed Jobs - ${instErr.message}`;
        if (!instantStats.logs) instantStats.logs = [];
        instantStats.logs.push(`[CRM Error] Instant Confirmed Jobs: ${instErr.message}`);
      }

      if (crmSheet) {
        crmSheet.getRange("U4").setValue("No");
        (await SpreadsheetApp.flush());
        (await Utilities.sleep(2000));
        crmSheet.getRange("A1").getValue(); // force formula recalculation
        (await SpreadsheetApp.flush());
      }

      // POST-PULL COMPARISON: Read DataFromCRM after fresh pull
      const newCrmOpps = [];
      const updatedCrmOpps = [];
      if (crmDataSheet) {
        const lastRowAfter = crmDataSheet.getLastRow();
        const lastColAfter = crmDataSheet.getLastColumn();
        if (lastRowAfter > 1 && lastColAfter > 0) {
          const allDataAfter = crmDataSheet.getRange(1, 1, lastRowAfter, lastColAfter).getValues();
          if (crmHeaders.length === 0) {
            crmHeaders = allDataAfter[0];
            crmColIndices = getCrmColumnIndices_(crmHeaders);
          }
          const afterCrmMap = new Map();
          for (let i = 1; i < allDataAfter.length; i++) {
            const r = allDataAfter[i];
            const id = String(r[crmColIndices.idIdx] || "").trim();
            if (id) afterCrmMap.set(id, r);
          }

          const timeZone = ss.getSpreadsheetTimeZone();

          afterCrmMap.forEach((newRow, id) => {
            if (!beforeCrmMap.has(id)) {
              // Entirely new opportunity
              newCrmOpps.push(formatNewCrmLogEntry_(newRow, crmHeaders, crmColIndices, timeZone));
            } else {
              // Existing opportunity - check for updates
              const oldRow = beforeCrmMap.get(id);
              const changes = getCrmFieldChanges_(oldRow, newRow, crmHeaders, crmColIndices, timeZone);
              if (changes.length > 0) {
                const client = (crmColIndices.clientIdx !== -1 && (newRow[crmColIndices.clientIdx] || oldRow[crmColIndices.clientIdx]))
                  ? String(newRow[crmColIndices.clientIdx] || oldRow[crmColIndices.clientIdx]).trim() : "";
                const job = (crmColIndices.jobIdx !== -1 && (newRow[crmColIndices.jobIdx] || oldRow[crmColIndices.jobIdx]))
                  ? String(newRow[crmColIndices.jobIdx] || oldRow[crmColIndices.jobIdx]).trim() : "";
                let title = "";
                if (client && job) title = `${client} | ${job}`;
                else title = client || job || "Opportunity";
                updatedCrmOpps.push(`[ID: ${id}] ${title} - ${changes.join(", ")}`);
              }
            }
          });
        }
      }

      // INSTANT GAP AUDIT: If clean slate or new jobs were copied without invoices/expenses, run auditors immediately
      const requiresGapAudit = pipeStats.needsGapAudit || confStats.needsGapAudit || instantStats.needsGapAudit;
      const cleanSlateLogs = [];
      if (requiresGapAudit) {
          console.log("Agent: CRM Updates required a Clean Slate. Triggering immediate Invoice and Expense Gap Audits...");
          (await postAgentProgress_("crm", "Auditing invoice and expense gaps for updated jobs...", false));
          
          // FIXED: Force Sheets to calculate the *Calcs tab formulas before the gap auditors read them
          (await SpreadsheetApp.flush());
          (await Utilities.sleep(2000));
          
          const invGapRes = (await auditInvoiceGaps(true, true));
          if (invGapRes.hasError || invGapRes.error) {
            cleanSlateLogs.push(`Error: Audit Invoice Gaps - ${invGapRes.error}`);
            hasCrmErrors = true;
            if (!firstCrmError) firstCrmError = `Error: Audit Invoice Gaps - ${invGapRes.error}`;
          } else if (invGapRes.count > 0) {
              msg += ` | Inv Gaps: ${invGapRes.count}`;
              cleanSlateLogs.push(`[CRM Automation] Auto-generated ${invGapRes.count} new invoices for Clean Slate jobs.`);
          }
          
          const expGapRes = (await auditAllOutgoingsGaps(true, false));
          if (expGapRes.hasError || expGapRes.error) {
            cleanSlateLogs.push(`Error: Audit Expense Gaps - ${expGapRes.error}`);
            hasCrmErrors = true;
            if (!firstCrmError) firstCrmError = `Error: Audit Expense Gaps - ${expGapRes.error}`;
          } else if (expGapRes.count > 0 || expGapRes.strictCount > 0) {
              msg += ` | Exp Gaps: ${expGapRes.count}`;
              let csMsg = `[CRM Automation] Auto-generated/Adjusted ${expGapRes.count} expense entries for Clean Slate jobs.`;
              if (expGapRes.logs && expGapRes.logs.length > 0) {
                  csMsg += "\n" + expGapRes.logs.map(l => l.startsWith("•") ? l : `• ${l}`).join("\n");
              }
              cleanSlateLogs.push(csMsg);
          }
      }

      updateCount = (pipeStats.updated || 0) + (confStats.updated || 0);
      if (msg === "") msg = "Run OK";

      alertSheet.getRange("AH2").setValue(pipeStats.dashDisc || 0);
      alertSheet.getRange("AI2").setValue(pipeStats.appDisc || 0);
      alertSheet.getRange("AJ2").setValue(confStats.dashDisc || 0);
      alertSheet.getRange("AK2").setValue(confStats.appDisc || 0);
      updateCRMWarningFlags(alertSheet, pipeStats, confStats);
      
      // Combine Logs
      let crmLogs = [];

      // Prepend CRM fresh download log section
      const crmPullSection = [];
      if (newCrmOpps.length > 0) {
        let text = `• New Opportunities (${newCrmOpps.length}):\n` + newCrmOpps.slice(0, 20).map(s => `  - ${s}`).join("\n");
        if (newCrmOpps.length > 20) text += `\n  ...and ${newCrmOpps.length - 20} more`;
        crmPullSection.push(text);
      }
      if (updatedCrmOpps.length > 0) {
        let text = `• Updated Opportunities (${updatedCrmOpps.length}):\n` + updatedCrmOpps.slice(0, 20).map(s => `  - ${s}`).join("\n");
        if (updatedCrmOpps.length > 20) text += `\n  ...and ${updatedCrmOpps.length - 20} more`;
        crmPullSection.push(text);
      }

      if (crmPullError) {
        crmLogs.push(`Error: CRM Download - ${crmPullError}`);
        hasCrmErrors = true;
        if (!firstCrmError) firstCrmError = `Error: CRM Download - ${crmPullError}`;
      } else if (crmPullSection.length > 0) {
        crmLogs.push(`[CRM Download]\n` + crmPullSection.join("\n\n"));
      } else if (crmSheet) {
        crmLogs.push(`[CRM Download]\n• No new or updated opportunities.`);
      }

      if (cleanSlateLogs.length > 0) crmLogs = crmLogs.concat(cleanSlateLogs);
      if (pipeStats.logs && pipeStats.logs.length > 0) crmLogs = crmLogs.concat(pipeStats.logs);
      if (confStats.logs && confStats.logs.length > 0) crmLogs = crmLogs.concat(confStats.logs);
      if (instantStats.logs && instantStats.logs.length > 0) crmLogs = crmLogs.concat(instantStats.logs);

      // Extract specific IDs for the AutoLog before the dashboard flags are simplified
      const allReverted = [...(pipeStats.revertedJobs || []), ...(confStats.revertedJobs || [])];
      const allDeleted = [...(pipeStats.deletedJobs || []), ...(confStats.deletedJobs || [])];

      if (allReverted.length > 0) crmLogs.push(`[CRM] Pipeline 'Yes' reverted to 'No' for Job IDs: ${[...new Set(allReverted)].join(', ')}`);
      if (allDeleted.length > 0) crmLogs.push(`[CRM] Permanent Deletions performed for Job IDs: ${[...new Set(allDeleted)].join(', ')}`);

      // Visibility for Deletions and Skips
      const totalDeleted = (pipeStats.deletedJobs?.length || 0) + (confStats.deletedJobs?.length || 0);
      const totalSkipped = (pipeStats.skippedRows || 0) + (confStats.skippedRows || 0);
      
      if (totalDeleted > 0) crmLogs.push(`[CRM] Deleted ${totalDeleted} job(s) from Confirmed.`);
      if (totalSkipped > 0) crmLogs.push(`[CRM] Skipped ${totalSkipped} rows due to matching logic or missing IDs.`);

      const hasOtherCrmChanges = (cleanSlateLogs.length > 0) ||
        (pipeStats.logs && pipeStats.logs.length > 0) ||
        (confStats.logs && confStats.logs.length > 0) ||
        (instantStats.logs && instantStats.logs.length > 0) ||
        (allReverted.length > 0) ||
        (allDeleted.length > 0) ||
        (totalDeleted > 0);
      const hasRealCrmChanges = (newCrmOpps.length > 0) || (updatedCrmOpps.length > 0) || hasOtherCrmChanges;

      // SINGLE CONSOLIDATED LOG ENTRY
      if (hasCrmErrors) {
        isSuccess = false;
        msg = firstCrmError || "Error in CRM";
        const crmSummary = hasRealCrmChanges ? "CRM Updates with errors" : (firstCrmError || "Error in CRM");
        writeToAutoLog("CRM", crmSummary, crmLogs.join("\n"));
        (await postAgentProgress_("crm", crmSummary, false));
      } else if (hasRealCrmChanges) {
          writeToAutoLog("CRM", "CRM Updates Applied", crmLogs.join("\n"));
          (await postAgentProgress_("crm", "CRM Updates Applied", false));
      } else {
          crmLogs.push("No updates found in Pipeline or Confirmed.");
          writeToAutoLog("CRM", "No changes required", crmLogs.join("\n"));
          (await postAgentProgress_("crm", "No changes required", false));
      }

    } catch (e) {
      console.log("Agent CRM Error: " + e.message);
      if (crmSheet) crmSheet.getRange("U4").setValue("No");
      isSuccess = false;
      msg = "Error: CRM Sequence - " + e.message;
      writeToAutoLog("CRM", "Error: CRM Sequence", "Error: CRM Sequence - " + e.message);
      (await postAgentProgress_("crm", "Error: " + e.message, false));
      alertSheet.getRange("H4").setValue("NO");
      (await SpreadsheetApp.flush());
    }

    updateRollingLog(alertSheet, "AC3", "BM3", updateCount, isSuccess, msg);
    alertSheet.getRange("AB3").setValue(new Date());
    alertSheet.getRange("H4").setValue("NO");
    runProps.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    (await SpreadsheetApp.flush());
  }

  // --- PART 3: EXPENSES ---
  if (runExp) {
    console.log("Agent: Starting Expense Sequence...");
    (await postAgentProgress_("expense", "Starting expense sequence...", false));
    runProps.setProperty('ACTIVE_AUTOMATOR_CATEGORY', 'EXPENSES');
    runProps.setProperty('ACTIVE_AUTOMATOR_START', String(Date.now()));
    
    let updateCount = 0;
    let isSuccess = true;
    let msg = "";
    let logs = [];
    let summaryText = "";
    let hasExpErrors = false;
    let firstExpError = "";

    alertSheet.getRange("F4").setValue("YES");
    alertSheet.getRange("G4").setValue(new Date());
    (await SpreadsheetApp.flush());

    try {
      // 1. RETAINER AUDIT (CRITICAL: Must run before Gap Check to ensure child rows exist)
      const runRetainerFix = alertSheet.getRange("B48").getValue() === "Yes";
      if (runRetainerFix) {
          console.log("Agent (Exp): Running Retainer Audit pre-check...");
          (await postAgentProgress_("expense", "Auditing retainer schedules for expenses...", false));
          const retainerRes = (await processRetainerAudit(ss, alertSheet));
          if (retainerRes.hasError || retainerRes.error) {
            logs.push(`Error: Retainer Audit - ${retainerRes.error}`);
            hasExpErrors = true;
            if (!firstExpError) firstExpError = `Error: Retainer Audit - ${retainerRes.error}`;
          } else {
            const rCount = retainerRes.count || 0;
            if (rCount > 0) {
                updateCount += rCount;
                msg += ` | Ret: ${rCount}`;
                if (retainerRes.logs && retainerRes.logs.length > 0) {
                    logs.push(`[Retainers] Built/Updated ${rCount} child row(s) prior to Expense Audit:\n` + retainerRes.logs.join("\n"));
                }
            }
          }
      }

      // Pre-Match Gaps
      (await postAgentProgress_("expense", "Auditing pre-match expense gaps in Outgoings...", false));
      const gaps1 = (await auditAllOutgoingsGaps(true, false));
      (await postAgentProgress_("expense", "Audited expenses: " + (gaps1?.count || 0) + " gap items checked", false));
      if (gaps1.hasError || gaps1.error) {
        logs.push(`Error: Audit Expense Gaps - ${gaps1.error}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Audit Expense Gaps - ${gaps1.error}`;
      } else if (gaps1.count > 0) {
          let g1Strict = gaps1.strictCount || 0;
          let g1Manual = gaps1.count - g1Strict;
          
          let g1Msg = "Pre-Match:";
          if (g1Strict > 0) g1Msg += ` Created ${g1Strict} Unreconciled Gaps.`;
          if (g1Manual > 0) g1Msg += ` Adjusted/Refreshed ${g1Manual} Placeholder Entries.`;
          if (gaps1.logs && gaps1.logs.length > 0) {
              const formattedLogs = gaps1.logs.map(l => l.startsWith("•") ? l : `• ${l}`).join("\n");
              g1Msg += "\n" + formattedLogs;
          }
          logs.push(g1Msg);
      }

      (await SpreadsheetApp.flush());
      (await Utilities.sleep(1000)); 

      console.log("Agent (Exp): Syncing accounting cost data via syncAccountingDataToSheet(true)...");
      (await postAgentProgress_("expense", "Downloading fresh expenses from accounting software...", false));
      if (typeof clearLastConnectorError === 'function') clearLastConnectorError();
      let expPullResult = null;
      try {
        expPullResult = (await syncAccountingDataToSheet(true));
      } catch (expErr) {
        if (typeof setLastConnectorError === 'function') setLastConnectorError(expErr.message);
      }
      const expPullError = (typeof getLastConnectorError === 'function') ? getLastConnectorError() : null;
      console.log("Agent (Exp): expPullResult received:", expPullResult ? {
        newCount: expPullResult.newExpenses?.length,
        updatedCount: expPullResult.updatedExpenses?.length
      } : "FALSY/UNDEFINED", "expPullError:", expPullError || "NONE");

      const expNewCount = expPullResult?.newExpenses?.length || 0;
      const expUpdCount = expPullResult?.updatedExpenses?.length || 0;
      (await postAgentProgress_("expense", "Expenses pulled: " + expNewCount + " new, " + expUpdCount + " updated", false));

      // Pre-match Part-Paid Expenses: resolve any newly paid part-payment balances or splits in Outgoings and Confirmed
      // BEFORE pullOutgoingsNotes() syncs OutgNotes to the Master Sheet for DirComp evaluation.
      let prePartPaidExpRes = null;
      try {
        prePartPaidExpRes = (await processPartPaidExpenses(ss, alertSheet));
        if (prePartPaidExpRes && !prePartPaidExpRes.hasError && !prePartPaidExpRes.error && (prePartPaidExpRes.count || 0) > 0) {
          updateCount += prePartPaidExpRes.count;
          msg += ` | Part-paid: ${prePartPaidExpRes.count}`;
          logs.push(`Updated ${prePartPaidExpRes.count} part-paid expenses:\n` + (prePartPaidExpRes.logs ? prePartPaidExpRes.logs.join("\n") : ""));
        }
      } catch (prePpExpErr) {
        console.warn("Pre-match Part-Paid Expenses warning: " + prePpExpErr.message);
      }

      try {
        (await pullOutgoingsNotes());
      } catch (notesErr) {
        console.error("Error: Pull Outgoings Notes - " + notesErr.message);
        logs.push(`Error: Pull Outgoings Notes - ${notesErr.message}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Pull Outgoings Notes - ${notesErr.message}`;
      }
     
      const viewComparison = alertSheet.getRange("B101").getValue();
      const dirCompSheet = ss.getSheetByName("DirComp");
      
      const currentE2 = dirCompSheet.getRange("E2").getValue();
      const currentA2 = dirCompSheet.getRange("A2").getValue();
      let needsDelay = false;

      if (currentE2 !== true) { dirCompSheet.getRange("E2").setValue(true); needsDelay = true; }
      if (currentA2 !== viewComparison) { dirCompSheet.getRange("A2").setValue(viewComparison); needsDelay = true; }

      if (needsDelay) {
        (await SpreadsheetApp.flush());
        (await Utilities.sleep(15000));
      } else {
        console.log("Agent (Exp): DirComp switch already ON and A2 correct. Skipping 15s delay.");
      }

      (await postAgentProgress_("expense", "Matching and pushing expenses to Confirmed and Outgoings...", false));
      (await autoTickExpenseRows(true));
      const pushRes = (await PushExpDetails(true));
      let pushCount = 0;
      if (pushRes.hasError || pushRes.error) {
        logs.push(`Error: Expense Matching - ${pushRes.error}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Expense Matching - ${pushRes.error}`;
      } else {
        pushCount = pushRes.count || pushRes;
        if (pushCount > 0) {
            let pMsg = `Pushed ${pushCount} Expense Updates from Xero.`;
            if (pushRes.logs && pushRes.logs.length > 0) pMsg += "\n" + pushRes.logs.join("\n");
            logs.push(pMsg);
        }
      }
      
      (await SpreadsheetApp.flush());
      (await Utilities.sleep(2000));

      // Post-Match Gaps
      (await postAgentProgress_("expense", "Auditing post-match expense gaps in Outgoings...", false));
      const gaps2 = (await auditAllOutgoingsGaps(true, false));
      if (gaps2.hasError || gaps2.error) {
        logs.push(`Error: Audit Expense Gaps - ${gaps2.error}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Audit Expense Gaps - ${gaps2.error}`;
      } else if (gaps2.count > 0) {
          let g2Strict = gaps2.strictCount || 0;
          let g2Manual = gaps2.count - g2Strict;
          
          let g2Msg = "Post-Match:";
          if (g2Strict > 0) g2Msg += ` Created ${g2Strict} Unreconciled Gaps.`;
          if (g2Manual > 0) g2Msg += ` Adjusted/Refreshed ${g2Manual} Placeholder Entries.`;
          if (gaps2.logs && gaps2.logs.length > 0) {
              const formattedLogs = gaps2.logs.map(l => l.startsWith("•") ? l : `• ${l}`).join("\n");
              g2Msg += "\n" + formattedLogs;
          }
          logs.push(g2Msg);
      }

      const totalStrictGaps = (gaps1.strictCount || 0) + (gaps2.strictCount || 0);
      alertSheet.getRange("BD2").setValue(totalStrictGaps);

      // Overdue Expenses
      (await postAgentProgress_("expense", "Sweeping overdue expenses in Confirmed and Outgoings...", false));
      const overdueConf = (await updateStaleExpensesInConfirmed(ss, alertSheet));
      if (overdueConf.hasError || overdueConf.error) {
        logs.push(`Error: Overdue Expenses - ${overdueConf.error}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Overdue Expenses - ${overdueConf.error}`;
      } else if (overdueConf.count > 0) {
        logs.push(`Fixed ${overdueConf.count} overdue expenses in Confirmed:\n` + overdueConf.logs.join("\n"));
      }

      const overdueOut = (await updateOverdueExpensesInOutgoings(ss, alertSheet));
      if (overdueOut.hasError || overdueOut.error) {
        logs.push(`Error: Overdue Expenses - ${overdueOut.error}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Overdue Expenses - ${overdueOut.error}`;
      } else if (overdueOut.count > 0) {
        logs.push(`Fixed ${overdueOut.count} overdue expenses in Outgoings:\n` + overdueOut.logs.join("\n"));
      }

      // Part-Paid Expenses
      console.log("Agent (Exp): Processing Part-Paid Expenses...");
      (await postAgentProgress_("expense", "Processing part-paid expenses in Outgoings and Confirmed...", false));
      let partPaidExpRes = null;
      try {
        partPaidExpRes = (await processPartPaidExpenses(ss, alertSheet));
        if (partPaidExpRes.hasError || partPaidExpRes.error) {
          logs.push(`Error: Part-Paid Expenses - ${partPaidExpRes.error}`);
          hasExpErrors = true;
          if (!firstExpError) firstExpError = `Error: Part-Paid Expenses - ${partPaidExpRes.error}`;
        } else if (partPaidExpRes.count > 0) {
          updateCount += partPaidExpRes.count;
          msg += ` | Part-paid: ${partPaidExpRes.count}`;
          logs.push(`Updated ${partPaidExpRes.count} part-paid expenses:\n` + partPaidExpRes.logs.join("\n"));
        }
      } catch (ppExpErr) {
        console.error("Error: Part-Paid Expenses - " + ppExpErr.message);
        logs.push(`Error: Part-Paid Expenses - ${ppExpErr.message}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Part-Paid Expenses - ${ppExpErr.message}`;
      }

      const viewReport = alertSheet.getRange("B102").getValue();
      if (dirCompSheet.getRange("A2").getValue() !== viewReport) {
          dirCompSheet.getRange("A2").setValue(viewReport);
          (await SpreadsheetApp.flush());
          (await Utilities.sleep(15000));
      }

      // Re-audit Outgoings & Making up CoS gaps post-match & post-part-paid before notes pull
      if (pushCount > 0 || (prePartPaidExpRes && (prePartPaidExpRes.count || 0) > 0) || (partPaidExpRes && (partPaidExpRes.count || 0) > 0)) {
        (await postAgentProgress_("expense", "Synchronizing outgoings notes and making up CoS...", false));
        try {
          const finalGapAudit = (await auditAllOutgoingsGaps(true, false));
          if (finalGapAudit && finalGapAudit.count > 0) {
            updateCount += finalGapAudit.count;
            logs.push(`Re-audited ${finalGapAudit.count} Outgoings/CoS notes post-match.`);
          }
        } catch (postAuditErr) {
          console.warn("Post-match outgoings audit warning:", postAuditErr.message);
        }
      }

      try {
        (await pullOutgoingsNotes());
      } catch (notesErr2) {
        console.error("Error: Pull Outgoings Notes - " + notesErr2.message);
        logs.push(`Error: Pull Outgoings Notes - ${notesErr2.message}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Pull Outgoings Notes - ${notesErr2.message}`;
      }

      // Master switch E2 left permanently ON per optimization
      // FIXED: Calculate Dashboard discrepancies now that data is fully synced
      (await postAgentProgress_("expense", "Calculating dashboard expense discrepancies...", false));
      try {
        (await calculateFinalExpenseDiscrepancies());
      } catch (discErr) {
        console.error("Error: Expense Discrepancies - " + discErr.message);
        logs.push(`Error: Expense Discrepancies - ${discErr.message}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Expense Discrepancies - ${discErr.message}`;
      }
      
      updateCount += pushCount;
      if (msg === "") msg = "Run OK";

      // ACCOUNTING EXPENSES DOWNLOAD LOG (New & Updated Expenses from Fresh Pull)
      if (expPullError) {
        logs.unshift(`Error: Expenses Download - ${expPullError}`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Expenses Download - ${expPullError}`;
      } else if (expPullResult) {
        const expPullSection = [];
        const newExps = expPullResult.newExpenses || [];
        const updatedExps = expPullResult.updatedExpenses || [];

        if (newExps.length > 0) {
          let text = `• New Expenses (${newExps.length}):\n` + newExps.slice(0, 20).map(s => `  - ${s}`).join("\n");
          if (newExps.length > 20) text += `\n  ...and ${newExps.length - 20} more`;
          expPullSection.push(text);
        }
        if (updatedExps.length > 0) {
          let text = `• Updated Expenses (${updatedExps.length}):\n` + updatedExps.slice(0, 20).map(s => `  - ${s}`).join("\n");
          if (updatedExps.length > 20) text += `\n  ...and ${updatedExps.length - 20} more`;
          expPullSection.push(text);
        }

        if (expPullSection.length > 0) {
          logs.unshift(`[Expenses Download]\n` + expPullSection.join("\n\n"));
        } else {
          logs.unshift(`[Expenses Download]\n• No new or updated expenses.`);
        }
      } else {
        console.warn("Agent (Exp): expPullResult was null or undefined.");
        logs.unshift(`Error: Expenses Download - Expenses pull returned no delta data.`);
        hasExpErrors = true;
        if (!firstExpError) firstExpError = `Error: Expenses Download - Expenses pull returned no delta data`;
      }

      const hasRealExpChanges = pushCount > 0 || (partPaidExpRes && partPaidExpRes.count > 0) || (gaps1 && gaps1.count > 0) || (gaps2 && gaps2.count > 0) || (overdueConf && overdueConf.count > 0) || (overdueOut && overdueOut.count > 0) || (expPullResult && ((expPullResult.newExpenses && expPullResult.newExpenses.length > 0) || (expPullResult.updatedExpenses && expPullResult.updatedExpenses.length > 0)));
      if (hasExpErrors) {
        isSuccess = false;
        msg = firstExpError || "Error during run";
        if (hasRealExpChanges) {
          summaryText = "Adjustments made with errors.";
        } else {
          summaryText = firstExpError || "Error during run";
        }
      } else if (!hasRealExpChanges) {
        summaryText = "No changes required.";
        logs.push("No new expenses matched or created.");
      } else {
        summaryText = "Adjustments made to expenses.";
      }
      
      // SINGLE CONSOLIDATED LOG ENTRY
      writeToAutoLog("EXPENSES", summaryText, logs.join("\n\n"));
      (await postAgentProgress_("expense", summaryText, false));

   } catch (e) {
      console.log("Agent Exp Error: " + e.message);
      isSuccess = false;
      msg = "Error: Expenses Sequence - " + e.message;
      writeToAutoLog("EXPENSES", "Error: Expenses Sequence", "Error: Expenses Sequence - " + e.message);
      (await postAgentProgress_("expense", "Error: " + e.message, false));
      alertSheet.getRange("F4").setValue("NO");
      (await SpreadsheetApp.flush());
   }
    
    updateRollingLog(alertSheet, "AC4", "BM4", updateCount, isSuccess, msg);
    alertSheet.getRange("AB4").setValue(new Date());
    alertSheet.getRange("F4").setValue("NO");
    runProps.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    (await SpreadsheetApp.flush());
  }
  
  } finally {
    // NEW: Always clear the active lease property and release the lock when the script finishes or crashes
    try {
      const p = PropertiesService.getScriptProperties();
      p.deleteProperty('ACTIVE_AUTOMATOR_START');
      p.deleteProperty('ACTIVE_AUTOMATOR_CATEGORY');
    } catch (e) {}
    lock.releaseLock();
  }
}


async function processCRMWorkflow(ss, alertSheet, stageName) {
  const keyInfoSheet = ss.getSheetByName("KeyInfo");
  const configuredCrmMode = keyInfoSheet ? String(keyInfoSheet.getRange("Q9").getValue() || "").trim() : "";
  const configuredCrmModeLower = configuredCrmMode.toLowerCase();
  if (stageName === "Confirmed" && configuredCrmModeLower !== "pipeandconf" && configuredCrmModeLower !== "confirmed") {
    console.warn(`Agent (CRM-${stageName}): Skipping Confirmed CRM workflow because KeyInfo!Q9 is "${configuredCrmMode}".`);
    return { updated: 0, dashDisc: 0, appDisc: 0, jobsToCheck: [], revertedJobs: [], deletedJobs: [], skippedRows: 0, logs: [] };
  }

  const sheet = ss.getSheetByName("CRMComp");
  const valB51 = alertSheet.getRange("B55").getValue(); 
  const valB52 = alertSheet.getRange("B56").getValue();
  const CONFIG_RANGES = {
    "Pipeline": {
      "Dashboard": "A59:B66",
      "App": "A72:B79"
    },
    "Confirmed": {
      "Dashboard": "D59:E66",
      "App": "D72:E79"
    }
  };
  const ensureStageMode = async (contextLabel) => {
    const liveB2 = String(sheet.getRange("B2").getValue() || "").trim();
    if (liveB2 !== stageName) {
      console.warn(`Agent (CRM-${stageName}): CRMComp!B2 drifted to "${liveB2}" before ${contextLabel}; restoring "${stageName}" and recalculating.`);
      sheet.getRange("B2").setValue(stageName);
      (await SpreadsheetApp.flush());
      (await Utilities.sleep(2000));
      sheet.getRange("A1").getValue();
      (await SpreadsheetApp.flush());
    }
  };

  const currentB2 = sheet.getRange("B2").getValue();
  const currentE2 = sheet.getRange("E2").getValue();
  const currentA2 = sheet.getRange("A2").getValue();
  let needsDelay = false;

  if (currentB2 !== stageName) { sheet.getRange("B2").setValue(stageName); needsDelay = true; }
  if (currentE2 !== true) { sheet.getRange("E2").setValue(true); needsDelay = true; }
  if (currentA2 !== valB51) { sheet.getRange("A2").setValue(valB51); needsDelay = true; }

  if (needsDelay) {
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(2000));
    sheet.getRange("A1").getValue(); 
    (await SpreadsheetApp.flush());
    console.log(`Agent (CRM-${stageName}): Initial recalc complete.`);
  } else {
    console.log(`Agent (CRM-${stageName}): Master switch already ON and filters correct. Skipping delay.`);
  }

  const sectionHeaders = sheet.getRange("4:4").getValues()[0];
  const colHeaders = sheet.getRange("5:5").getValues()[0];
  const VALID_SECTIONS = ['Dashboard compare', 'Actions required', 'CRM compare', 'Actions required 2'];
  const colToSectionMap = new Array(sectionHeaders.length);
  for (let i = 0; i < sectionHeaders.length; i++) {
    const sec = (sectionHeaders[i] || '').toString().trim();
    if (VALID_SECTIONS.some(vs => vs.toLowerCase() === sec.toLowerCase())) {
      colToSectionMap[i] = sec.toLowerCase();
    } else {
      colToSectionMap[i] = (i > 0) ? colToSectionMap[i - 1] : '';
    }
  }

  const getIndexesInSec = (targetSection, targetHeaders) => {
    const indexes = [];
    for (let i = 0; i < colHeaders.length; i++) {
      if (colToSectionMap[i] === targetSection.toLowerCase()) {
        const h = colHeaders[i].toString().trim();
        if (targetHeaders.includes(h)) indexes.push(i);
      }
    }
    return indexes;
  };

  let totalUpdatedThisRun = 0;
  const jobsToCheckList = [];
  const revertedJobsList = [];
  const deletedJobsList = [];
  const logsList = [];
  let needsGapAuditFlag = false;

  const dashRange = CONFIG_RANGES[stageName]["Dashboard"];
  const dashSettings = getDiscrepancySettings(alertSheet, dashRange);
  const dashIncIdx = getIndexesInSec("dashboard compare", dashSettings.include);
  const dashExcIdx = getIndexesInSec("dashboard compare", dashSettings.exclude);
  const dashPushIndexes = getIndexesInSec("dashboard compare", ["Update?", "Push?"]);
  const dashPushIndex = dashPushIndexes.length > 0 ? dashPushIndexes[0] : -1;
  if (dashPushIndex !== -1) {
    (await ensureStageMode("Dashboard Compare evaluation"));
    const data = sheet.getDataRange().getValues();
    const checkboxes = [];
    for (let i = 5; i < data.length; i++) {
      const row = data[i];
      if (dashExcIdx.some(idx => row[idx] === 1)) continue;
      if (dashIncIdx.some(idx => row[idx] === 1)) {
        checkboxes.push(sheet.getRange(i + 1, dashPushIndex + 1));
      }
    }
    if (checkboxes.length > 0) {
      sheet.getRangeList(checkboxes.map(r => r.getA1Notation())).setValue(true);
      (await SpreadsheetApp.flush());
      sheet.getRange("A1").getValue();
      (await SpreadsheetApp.flush());

      const result = (await updateCheckedRows(true, stageName));
      if (result) {
        totalUpdatedThisRun += (result.count || 0);
        if (result.jobsToCheck) jobsToCheckList.push(...result.jobsToCheck);
        if (result.revertedJobs) revertedJobsList.push(...result.revertedJobs);
        if (result.deletedJobs) deletedJobsList.push(...result.deletedJobs);
        if (result.logs && result.logs.length > 0) logsList.push(...result.logs);
        if (result.needsGapAudit) needsGapAuditFlag = true;
      }
    }
  }

  if (totalUpdatedThisRun > 0) {
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(1500));
    sheet.getRange("A1").getValue();
    (await SpreadsheetApp.flush());
    console.log(`Agent (CRM-${stageName}): Mid-point recalc complete.`);
  } else {
    console.log(`Agent (CRM-${stageName}): No Dashboard changes; skipping mid-point delay.`);
  }

  const appRange = CONFIG_RANGES[stageName]["App"];
  const appSettings = getDiscrepancySettings(alertSheet, appRange);
  const crmIncIdx = getIndexesInSec("crm compare", appSettings.include);
  const crmExcIdx = getIndexesInSec("crm compare", appSettings.exclude);
  const crmPushIndexes = getIndexesInSec("crm compare", ["Push?"]);
  const crmPushIndex = crmPushIndexes.length > 0 ?
    crmPushIndexes[0] : -1;
  if (crmPushIndex !== -1) {
    (await ensureStageMode("CRM Compare evaluation"));
    const data = sheet.getDataRange().getValues();
    const checkboxes = [];
    for (let i = 5; i < data.length; i++) {
      const row = data[i];
      if (crmExcIdx.some(idx => row[idx] === 1)) continue;
      if (crmIncIdx.some(idx => row[idx] === 1)) {
        checkboxes.push(sheet.getRange(i + 1, crmPushIndex + 1));
      }
    }
    if (checkboxes.length > 0) {
      sheet.getRangeList(checkboxes.map(r => r.getA1Notation())).setValue(true);
      (await SpreadsheetApp.flush());
      sheet.getRange("A1").getValue();
      (await SpreadsheetApp.flush());

      const result = (await updateCheckedRowsRight(true, stageName));
      if (result) {
        totalUpdatedThisRun += (result.count || 0);
        if (result.jobsToCheck) jobsToCheckList.push(...result.jobsToCheck);
        if (result.revertedJobs) revertedJobsList.push(...result.revertedJobs);
        if (result.deletedJobs) deletedJobsList.push(...result.deletedJobs);
        if (result.logs && result.logs.length > 0) logsList.push(...result.logs);
        if (result.needsGapAudit) needsGapAuditFlag = true;
      }
    }
  }

  const skippedCount = sheet.getRange("V4").getValue() || 0;
  
  if (totalUpdatedThisRun > 0 && valB51 !== valB52) {
    sheet.getRange("A2").setValue(valB52);
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(1500));
    sheet.getRange("A1").getValue();
    (await SpreadsheetApp.flush());
    console.log(`Agent (CRM-${stageName}): Final recalc complete.`);
  } else {
    console.log(`Agent (CRM-${stageName}): No updates made or filters identical; skipping final recalc delay.`);
  }

  const finalData = sheet.getDataRange().getValues();
  const dashMismatchHeaders = ["Missing job?", "Missing job", "Client mismatch?", "Job name mismatch?", "Revenue mismatch?", "Start date mismatch?", "End date mismatch?", "% likel. mismatch"];
  const crmMismatchHeaders = ["Client mismatch?", "Job name mismatch?", "Revenue mismatch?", "Start date mismatch?", "End date mismatch?", "% likel. mismatch"];
  const allDashIdx = getIndexesInSec("dashboard compare", dashMismatchHeaders);
  const allAppIdx = getIndexesInSec("crm compare", crmMismatchHeaders);

  const dashDiscCount = countRowsWithFlags(finalData, 5, allDashIdx);
  const appDiscCount = countRowsWithFlags(finalData, 5, allAppIdx);

  if (totalUpdatedThisRun > 0 && valB51 !== valB52) {
    sheet.getRange("A2").setValue(valB51);
    (await SpreadsheetApp.flush());
  }
  // FIXED: Force unique ID sets to ensure nothing is lost between Left and Right side processing
  return {
    updated: totalUpdatedThisRun,
    dashDisc: dashDiscCount,
    appDisc: appDiscCount,
    jobsToCheck: [...new Set(jobsToCheckList)],
    revertedJobs: [...new Set(revertedJobsList)],
    deletedJobs: [...new Set(deletedJobsList)],
    skippedRows: skippedCount,
    logs: logsList,
    needsGapAudit: needsGapAuditFlag
  };
}

async function processRetainerAudit(ss, alertSheet) {
  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) {
    console.log("Error: Client Sheet ID (X28) not found.");
    return { count: 0, logs: ["Error: Retainer Audit - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  }
  
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");
  const retainerDayVal = alertSheet.getRange("B51").getValue();
  const targetDay = (parseInt(retainerDayVal) > 0) ? parseInt(retainerDayVal) : 28;
  const defaultDays = parseInt(alertSheet.getRange("B52").getValue()) || 30;

  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    console.log("Error: Could not open Client Spreadsheet: " + e.message);
    return { count: 0, logs: ["Error: Retainer Audit - " + e.message], hasError: true, error: e.message };
  }
  (await SpreadsheetApp.flush());

  let totalFixes = 0;
  let allLogs = [];

  // 1. Audit Confirmed
  const confSheet = clientSs.getSheetByName("Confirmed");
  if (confSheet) {
     const res = runRetainerSheetAudit_(confSheet, alertSheet, targetDay, defaultDays);
     totalFixes += res.count;
     if (res.logs.length > 0) allLogs.push(...res.logs);
  } else {
     console.log("Error: 'Confirmed' sheet not found.");
     return { count: 0, logs: ["Error: Retainer Audit - 'Confirmed' sheet not found in Client Spreadsheet."], hasError: true, error: "'Confirmed' sheet not found in Client Spreadsheet." };
  }

  // 2. Audit Pipeline
  // DISABLED: Retainer child-row generation is no longer permitted on the Pipeline tab.
  /*
  const pipeSheet = clientSs.getSheetByName("Pipeline");
  if (pipeSheet) {
     const res = runRetainerSheetAudit_(pipeSheet, alertSheet, targetDay, defaultDays);
     totalFixes += res.count;
     if (res.logs.length > 0) allLogs.push(...res.logs);
  }
  */

  return { count: totalFixes, logs: allLogs };
}

function runRetainerSheetAudit_(sheet, alertSheet, targetDay, defaultDays) {
  const sheetName = sheet.getName();
  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h || "").trim().toLowerCase());
  
  // FIXED: Cache the regex normalization array to eliminate millions of CPU cycles per run
  const normHeaders = headers.map(h => h.replace(/[^a-z0-9]/g, ''));
  const getIdx = (name) => {
     let idx = headers.indexOf(name.toLowerCase());
     if (idx !== -1) return idx;
     const cleanName = name.toLowerCase().replace(/[^a-z0-9]/g, '');
     return normHeaders.indexOf(cleanName);
  };
  const colClient = getIdx("Client");
  const colJob = getIdx("Job name");
  const colRevenue = getIdx("Revenue (Proj total / Ongoing pm) - excl VAT");
  const colVAT = getIdx("VAT?");
  const colType = getIdx("Project / retainer");
  const colStart = getIdx("Start date");
  const colEnd = getIdx("End date");
  const colInv1Amt = getIdx("Project invoice 1 / monthly retainer (excl VAT)");
  const colInv1Date = getIdx("Inv 1 SEND date");
  
  const parseMoney = (val) => {
    if (typeof val === 'number') return val;
    if (!val) return 0;
    const clean = String(val).replace(/[^0-9.-]/g, '');
    return parseFloat(clean) || 0;
  };
  
  if (colType === -1 || colRevenue === -1 || colStart === -1 || colEnd === -1) {
     console.log(`Agent Retainer Audit: Missing critical columns in ${sheetName}.`);
     return { count: 0, logs: ["Error: Missing critical columns in " + sheetName] };
  }

  const maxRows = sheet.getMaxRows();
  let trueLastRow = 0;
  for (let r = data.length - 1; r >= 0; r--) {
      const row = data[r];
      const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
      const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
      const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
      const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
      if (z1 || z2 || z3 || z4) {
          trueLastRow = r + 1;
          break;
      }
  }

  let fixesApplied = 0;
  const jobsToExpand = [];
  const logs = [];
  
  // FIXED: Array to batch API calls so the script doesn't hit execution limits
  const rangesToClear = [];
  let flagAlertSheet = false;
  
  for (let i = 1; i < data.length; i++) {
     const row = data[i];
     if (!row[colClient] && !row[colJob]) continue;

     const rawType = String(row[colType]);
     
     if (rawType.trim().toLowerCase().includes("retainer")) {
        const parseDateSafe = (d, fallback) => {
            if (!d) return fallback;
            if (d instanceof Date) return d;
            if (typeof d === 'number' && d > 20000 && d < 70000) return new Date(new Date(1899, 11, 30).getTime() + Math.round(d * 86400000));
            const parsed = new Date(d);
            return isNaN(parsed.getTime()) ? fallback : parsed;
        };
        
        const monthlyFee = parseMoney(row[colRevenue]);
        const start = parseDateSafe(row[colStart], null);
        const end = parseDateSafe(row[colEnd], new Date(2050, 11, 31));

        if (monthlyFee <= 0 || !start || isNaN(start.getTime())) continue;
        const parentInvAmt = parseMoney(row[colInv1Amt]);
        if (parentInvAmt > 0) continue;

        const fuzzy = (str) => String(str || '').toLowerCase().replace(/&/g, 'and').replace(/\s+/g, '');
        const parentJobFuzzy = fuzzy(row[colJob]);

        let childCount = 0;
        let totalInvoiced = parentInvAmt; 
        let lastDate = new Date(start);
        let childDates = [];

        for (let j = i + 1; j < data.length; j++) {
            const nextRow = data[j];
            if (nextRow[colStart] || parseMoney(nextRow[colRevenue]) > 0) break; 
            
            if (fuzzy(nextRow[colJob]) === parentJobFuzzy) {
                childCount++;
                const amt = parseMoney(nextRow[colInv1Amt]);
                totalInvoiced += amt;

                const rowDate = nextRow[colInv1Date] ? new Date(nextRow[colInv1Date]) : null;
                if (rowDate && !isNaN(rowDate.getTime())) {
                    lastDate = rowDate;
                    childDates.push(rowDate);
                }
            } else {
                break;
            }
        }

        if (childDates.length === 0) {
            const prevMonth = new Date(start.getFullYear(), start.getMonth() - 1, 1);
            const maxDayPrev = new Date(prevMonth.getFullYear(), prevMonth.getMonth() + 1, 0).getDate();
            lastDate = new Date(prevMonth.getFullYear(), prevMonth.getMonth(), Math.min(targetDay, maxDayPrev));
        }

        // FIXED: Calculate true duration using elapsed days instead of crude calendar months
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
        const durationMonths = Math.round(diffDays / 30.4375);
        
        const safeDuration = Math.max(1, durationMonths);
        const totalContractValue = safeDuration * monthlyFee;
        const remainingValue = totalContractValue - totalInvoiced;

        let intervalMonths = 1;
        if (childDates.length >= 2) {
            const d1 = childDates[childDates.length - 2];
            const d2 = childDates[childDates.length - 1];
            const diffTime = Math.abs(d2 - d1);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
            
            const calcInterval = Math.round(diffDays / 30);
            if (calcInterval > 0) intervalMonths = calcInterval;
        }

        let timingMonthAdjust = 0;
        if (childDates.length > 0 && !isNaN(start.getTime())) {
            const firstSent = childDates[0];
            const firstWindowStart = new Date(start.getFullYear(), start.getMonth() - intervalMonths, 1);
            const firstWindowEnd = new Date(start.getFullYear(), start.getMonth() + (2 * intervalMonths), 0, 23, 59, 59);
            // Only evaluate advance/arrears offset if the first child row falls within +/-1 billing interval of the start date
            // (prevents mid-contract onboarded retainers missing early pre-Pulse months from falsely voting arrears)
            if (firstSent.getTime() >= firstWindowStart.getTime() && firstSent.getTime() <= firstWindowEnd.getTime()) {
                let beforeVotes = 0, duringVotes = 0, afterVotes = 0;
                for (let di = 0; di < childDates.length; di++) {
                    const sent = childDates[di];
                    const prevStart = new Date(start.getFullYear(), start.getMonth() + ((di - 1) * intervalMonths), 1);
                    const prevEnd = new Date(start.getFullYear(), start.getMonth() + (di * intervalMonths), 0, 23, 59, 59);
                    const pStart = new Date(start.getFullYear(), start.getMonth() + (di * intervalMonths), 1);
                    const pEnd = new Date(start.getFullYear(), start.getMonth() + ((di + 1) * intervalMonths), 0, 23, 59, 59);
                    const nextStart = new Date(start.getFullYear(), start.getMonth() + ((di + 1) * intervalMonths), 1);
                    const nextEnd = new Date(start.getFullYear(), start.getMonth() + ((di + 2) * intervalMonths), 0, 23, 59, 59);
                    if (sent.getTime() >= prevStart.getTime() && sent.getTime() <= prevEnd.getTime()) beforeVotes++;
                    else if (sent.getTime() >= nextStart.getTime() && sent.getTime() <= nextEnd.getTime()) afterVotes++;
                    else if (sent.getTime() >= pStart.getTime() && sent.getTime() <= pEnd.getTime()) duringVotes++;
                }
                const totalVotes = beforeVotes + duringVotes + afterVotes;
                if (totalVotes > 0) {
                    if (beforeVotes / totalVotes >= 2 / 3) timingMonthAdjust = 1;
                    else if (afterVotes / totalVotes >= 2 / 3) timingMonthAdjust = -1;
                }
            }
        }

        // --- EXCESS CHILD ROW TRIMMING LOGIC ---
        if (childCount > 0) {
            let stopTrimming = false;
            let trimCount = 0;
            const endVal = end.getFullYear() * 12 + end.getMonth();

            for (let c = childCount - 1; c >= 0; c--) {
                if (stopTrimming) break;

                const childDataIdx = i + 1 + c;
                
                let childMonthVal = 0;
                const rowDateRaw = data[childDataIdx][colInv1Date];
                if (rowDateRaw instanceof Date) {
                    childMonthVal = rowDateRaw.getFullYear() * 12 + rowDateRaw.getMonth();
                } else if (rowDateRaw && !isNaN(new Date(rowDateRaw).getTime())) {
                    const d = new Date(rowDateRaw);
                    childMonthVal = d.getFullYear() * 12 + d.getMonth();
                } else {
                    const childStart = new Date(start);
                    childStart.setMonth(childStart.getMonth() + (c * intervalMonths));
                    childMonthVal = childStart.getFullYear() * 12 + childStart.getMonth();
                }

                // FIXED: Trim if it spills past the end date (accounting for advance/arrears timing offset) OR if the number of child rows exceeds the true contract length
                if ((childMonthVal + timingMonthAdjust) > endVal || c >= safeDuration) {
                    let hasActual = false;
                    for (let s = 1; s <= 3; s++) {
                        const possibleInvRefs = [`Inv ${s} no`, `Invoice ${s} number`, `Inv ${s} id`, `Inv ${s} ref`];
                        let invRefCol = -1;
                        for (const pr of possibleInvRefs) {
                            const idx = getIdx(pr);
                            if (idx !== -1) { invRefCol = idx; break; }
                        }
                        const invRef = invRefCol !== -1 ? String(data[childDataIdx][invRefCol] || "").toUpperCase() : "";
                        if (invRef && invRef !== "0" && !isPlaceholderInvoice_(invRef)) hasActual = true;

                        const possibleExpRefs = [`Direct inv ${s} app id`, `Dir inv ${s} app id`];
                        let expRefCol = -1;
                        for (const pr of possibleExpRefs) {
                            const idx = getIdx(pr);
                            if (idx !== -1) { expRefCol = idx; break; }
                        }
                        const expRef = expRefCol !== -1 ? String(data[childDataIdx][expRefCol] || "").toUpperCase() : "";
                        if (expRef && expRef !== "0" && !isPlaceholderExpense_(expRef)) hasActual = true;
                    }

                    if (hasActual) {
                        stopTrimming = true;
                        logs.push(`⚠️ WARNING: Retainer shrunk, but unable to trim excess child row ${childDataIdx + 1} for ${row[colClient]} | ${row[colJob]} due to actuals in row.`);
                        flagAlertSheet = true;
                    } else {
                        const rowNum = childDataIdx + 1;
                        
                        // FIXED: Push to batched array instead of making synchronous API calls
                        rangesToClear.push(`A${rowNum}:AM${rowNum}`);
                        rangesToClear.push(`AP${rowNum}:BH${rowNum}`);
                        rangesToClear.push(`BX${rowNum}:CR${rowNum}`);
                        
                        try { sheet.getRange(rowNum, 1).shiftRowGroupDepth(-1); } catch(e) {}
                        try { sheet.unhideRow(sheet.getRange(rowNum, 1, 1, 1)); } catch(e) {}
                        
                        trimCount++;
                        flagAlertSheet = true;
                    }
                } else {
                    stopTrimming = true;
                }
            }
            if (trimCount > 0) {
                logs.push(`[Retainers - ${sheetName}] Trimmed ${trimCount} excess child row(s) (Parent Row: ${i+1}) for ${row[colClient]} | ${row[colJob]}`);
                fixesApplied++;
            }
        }

        if (remainingValue < 0.05) continue;

        // FIXED: Calculate how many child rows are in the past to ensure a rolling 18-month FUTURE runway
        const today = new Date();
        const currentMonthVal = today.getFullYear() * 12 + today.getMonth();
        const endVal = end.getFullYear() * 12 + end.getMonth();
        let pastCount = 0;
        childDates.forEach(d => {
             // FIXED: Changed to <= so the current month is considered "consumed", ensuring a full 18 future rows are built
             if ((d.getFullYear() * 12 + d.getMonth() + timingMonthAdjust) <= currentMonthVal) pastCount++;
        });
        if (childDates.length === 0) {
             let probeIdx = 1;
             while (true) {
                 const probeDate = new Date(lastDate.getFullYear(), lastDate.getMonth() + (probeIdx * intervalMonths), 1);
                 const probeVal = probeDate.getFullYear() * 12 + probeDate.getMonth();
                 if (probeVal > currentMonthVal || probeVal > endVal) break;
                 pastCount++;
                 probeIdx++;
             }
        }
        
        const targetCount = pastCount + 18;

        if (childCount < targetCount) {
            let rowsToAdd = 0;
            let simulatedTotal = totalInvoiced;

            for (let k = 0; k < (targetCount - childCount); k++) {
                const nextTestDate = new Date(lastDate.getFullYear(), lastDate.getMonth() + ((k + 1) * intervalMonths), 1);
                const testVal = nextTestDate.getFullYear() * 12 + nextTestDate.getMonth();
                if ((testVal + timingMonthAdjust) > endVal) break;
                if ((simulatedTotal + monthlyFee) > (totalContractValue + 1.00)) break;
                
                simulatedTotal += monthlyFee; 
                rowsToAdd++;
            }

            if (rowsToAdd > 0) {
                jobsToExpand.push({
                    parentRow: i + 1,
                    insertAfter: i + 1 + childCount,
                    count: rowsToAdd,
                    baseDate: lastDate,
                    sendDay: (childDates.length > 0) ? lastDate.getDate() : targetDay,
                    client: row[colClient],
                    job: row[colJob],
                    fee: monthlyFee,
                    vat: (colVAT !== -1) ? row[colVAT] : "",
                    interval: intervalMonths 
                });
                logs.push(`[Retainers - ${sheetName}] Added ${rowsToAdd} child row(s) (Parent Row: ${i+1}) for ${row[colClient]} | ${row[colJob]}`);
            }
        }
     }
  }

  if (jobsToExpand.length === 0 && fixesApplied === 0) return { count: 0, logs: [] };
  console.log(`Found ${jobsToExpand.length} retainer(s) requiring child rows. Applying sheet updates...`);
  jobsToExpand.sort((a, b) => b.insertAfter - a.insertAfter);

  const isRowPopulatedInZones_ = (row) => {
      const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
      const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
      const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
      const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
      return z1 || z2 || z3 || z4;
  };

  const colInv1SendDate = getIdx("Inv 1 SEND date");
  const colInv1Days = getIdx("Inv 1 days to pay");
  const lastColCount = sheet.getLastColumn();
  const zoneScanCols = Math.min(96, lastColCount);
  
  jobsToExpand.forEach((job, index) => {
      console.log(`Updating retainer ${index + 1}/${jobsToExpand.length}: ${job.client} | ${job.job} (Adding ${job.count} rows)`);
      const rowsToCreate = job.count;
      let currentMax = sheet.getMaxRows();
      let availableEmpty = currentMax - (trueLastRow + 1); 
      
      if (availableEmpty < rowsToCreate) {
          const rowsToAdd = rowsToCreate - availableEmpty + 5;
          sheet.insertRowsAfter(currentMax, rowsToAdd);
          currentMax = sheet.getMaxRows();
      }
      
      let sourceStartRow = trueLastRow + 2;
      // SAFETY GUARD: Verify the source rows are genuinely blank before moving (prevents ever stealing populated rows at the bottom of the sheet)
      const checkVals = sheet.getRange(sourceStartRow, 1, rowsToCreate, zoneScanCols).getValues();
      if (checkVals.some(isRowPopulatedInZones_)) {
          const freshData = sheet.getRange(1, 1, currentMax, zoneScanCols).getValues();
          for (let r = freshData.length - 1; r >= 0; r--) {
              if (isRowPopulatedInZones_(freshData[r])) {
                  trueLastRow = r + 1;
                  break;
              }
          }
          availableEmpty = currentMax - (trueLastRow + 1);
          if (availableEmpty < rowsToCreate) {
              const rowsToAdd = rowsToCreate - availableEmpty + 5;
              sheet.insertRowsAfter(currentMax, rowsToAdd);
          }
          sourceStartRow = trueLastRow + 2;
      }

      const sourceRange = sheet.getRange(sourceStartRow, 1, rowsToCreate, lastColCount);
      
      sheet.moveRows(sourceRange, job.insertAfter + 1);
      trueLastRow += rowsToCreate;
      
      const startWriteRow = job.insertAfter + 1;
      const cleanClient = sanitizeSheetCell_(job.client);
      const cleanJob = sanitizeSheetCell_(job.job);
      const cleanVat = colVAT !== -1 ? sanitizeSheetCell_(job.vat) : "";

      const clientVals = [];
      const jobVals = [];
      const clientJobVals = [];
      const vatVals = [];
      const feeVals = [];
      const dateVals = [];
      const daysVals = [];
      const dateDaysVals = [];
      
      for (let m = 0; m < rowsToCreate; m++) {
          const monthOffset = (m + 1) * job.interval;
          const desiredDay = job.sendDay || targetDay;
          const targetMonthFirst = new Date(job.baseDate.getFullYear(), job.baseDate.getMonth() + monthOffset, 1);
          const maxDaysInMonth = new Date(targetMonthFirst.getFullYear(), targetMonthFirst.getMonth() + 1, 0).getDate();
          const invDate = new Date(targetMonthFirst.getFullYear(), targetMonthFirst.getMonth(), Math.min(desiredDay, maxDaysInMonth));
          
          clientVals.push([cleanClient]);
          jobVals.push([cleanJob]);
          clientJobVals.push([cleanClient, cleanJob]);
          vatVals.push([cleanVat]);
          feeVals.push([job.fee]);
          dateVals.push([invDate]);
          daysVals.push([defaultDays]);
          dateDaysVals.push([invDate, defaultDays]);
      }

      if (colClient !== -1 && colJob === colClient + 1) {
          sheet.getRange(startWriteRow, colClient + 1, rowsToCreate, 2).setValues(clientJobVals);
      } else {
          if (colClient !== -1) sheet.getRange(startWriteRow, colClient + 1, rowsToCreate, 1).setValues(clientVals);
          if (colJob !== -1) sheet.getRange(startWriteRow, colJob + 1, rowsToCreate, 1).setValues(jobVals);
      }
      if (colVAT !== -1) {
          sheet.getRange(startWriteRow, colVAT + 1, rowsToCreate, 1).setValues(vatVals);
      }
      if (colInv1Amt !== -1) {
          sheet.getRange(startWriteRow, colInv1Amt + 1, rowsToCreate, 1).setValues(feeVals);
      }
      if (colInv1SendDate !== -1 && colInv1Days === colInv1SendDate + 1) {
          sheet.getRange(startWriteRow, colInv1SendDate + 1, rowsToCreate, 2).setValues(dateDaysVals);
      } else {
          if (colInv1SendDate !== -1) sheet.getRange(startWriteRow, colInv1SendDate + 1, rowsToCreate, 1).setValues(dateVals);
          if (colInv1Days !== -1) sheet.getRange(startWriteRow, colInv1Days + 1, rowsToCreate, 1).setValues(daysVals);
      }
      
      try {
         if (sheet.getRowGroupDepth(startWriteRow) === 0) {
             const rangeToGroup = sheet.getRange(startWriteRow, 1, rowsToCreate, 1);
             rangeToGroup.shiftRowGroupDepth(1);
         }
         const groupControl = sheet.getRowGroup(startWriteRow, 1);
         if (groupControl) groupControl.collapse();
      } catch (e) {
         console.log("Grouping skip/error: " + e.message);
      }
      
      fixesApplied++;
  });
  
  // FIXED: Execute the batched API calls once at the very end
  if (rangesToClear.length > 0) {
      sheet.getRangeList(rangesToClear).clearContent();
  }
  if (flagAlertSheet && alertSheet) {
      alertSheet.getRange("AR2").setValue(true);
  }
  
  return { count: fixesApplied, logs: logs };
}

async function RetainerInvoiceFix() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const alertSheet = ss.getSheetByName("DataChgAlert");
  console.log("--- Starting Manual Retainer Fix Test ---");
  const res = (await processRetainerAudit(ss, alertSheet));
  const count = res.count || 0;
  if (count > 0) {
    SpreadsheetApp.getUi().alert(`Success: Fixed ${count} retainer jobs. Check logs for details.`);
  } else {
    SpreadsheetApp.getUi().alert("No retainer jobs matched the criteria. View Execution Logs to see why.");
  }
}

/**
 * HELPER: Manages a 7-day rolling log of activities.
 * UPDATED: Sanitizes history data to fix "[object Object]" errors.
 */
function updateRollingLog(sheet, displayCellA1, storageCellA1, count, isSuccess, runMsg) {
  const now = new Date();
  const dayMillis = 24 * 60 * 60 * 1000;
  const weekMillis = 7 * dayMillis;
  const weekCutoff = now.getTime() - weekMillis;
  const dayCutoff = now.getTime() - dayMillis;

  const storageRange = sheet.getRange(storageCellA1);
  let rawHistory = storageRange.getValue();
  let history = [];
  
  try {
    if (rawHistory && rawHistory !== "") {
      history = JSON.parse(rawHistory);
    }
  } catch (e) {
    console.log("Error parsing rolling log history. Resetting log.");
    history = [];
  }

  // --- SANITIZE INPUTS ---
  // Ensure 'count' is a pure number. If an object was passed, try to extract .count
  let cleanCount = 0;
  if (typeof count === 'number') {
      cleanCount = count;
  } else if (typeof count === 'object' && count !== null && count.count !== undefined) {
      cleanCount = Number(count.count) || 0;
  }

  // 2. Add new entry
  history.push({
    ts: now.getTime(), 
    c: cleanCount,         
    s: isSuccess,      
    m: String(runMsg) // Force string
  });

  // 3. Filter: Keep entries for the last 7 DAYS
  history = history.filter(entry => entry.ts > weekCutoff);

  // 4. Calculate Totals
  let totalDayUpdates = 0;
  let totalWeekUpdates = 0;
  let totalFailures = 0;
  let lastError = "";

  history.forEach(entry => {
    // --- DATA CLEANUP ON READ ---
    // If historical data is corrupt (e.g. "object Object"), sanitize it here too
    let val = entry.c;
    if (typeof val === 'object') val = (val.count) ? Number(val.count) : 0;
    if (isNaN(val)) val = 0;

    // Weekly Total
    totalWeekUpdates += val;

    // Daily Total (Only entries < 24 hours)
    if (entry.ts > dayCutoff) {
       totalDayUpdates += val;
       if (!entry.s) {
         totalFailures++;
         lastError = entry.m; 
       }
    }
  });

  // 5. Build Compact Summary String
  let summary = `L: ${cleanCount} D: ${totalDayUpdates} W: ${totalWeekUpdates}`;
  
  if (totalFailures > 0) {
    summary += ` | ${totalFailures} Failures`;
    if (lastError) summary += ` (Last: ${lastError.substring(0, 10)}...)`;
  } else {
    if (runMsg && runMsg !== "Run OK") {
       summary += runMsg.startsWith(" |") ? runMsg : ` | ${runMsg}`;
    } else {
       summary += ` | OK`;
    }
  }

  // 6. Save (This overwrites the corrupted data with clean data)
  storageRange.setValue(JSON.stringify(history)); 
  sheet.getRange(displayCellA1).setValue(summary);
}

function updateCRMWarningFlags(alertSheet, pipeStats, confStats) {
  const allJobsToCheck = [...(pipeStats.jobsToCheck || []), ...(confStats.jobsToCheck || [])];
  const allReverted = [...(pipeStats.revertedJobs || []), ...(confStats.revertedJobs || [])];
  const allDeleted = [...(pipeStats.deletedJobs || []), ...(confStats.deletedJobs || [])];
  
  // FIXED: Strictly Yes/No for Dashboard uniformity
  const warnMsg = (allJobsToCheck.length > 0) ? "Yes" : "No";
  const revertMsg = (allReverted.length > 0) ? "Yes" : "No";
  const deleteMsg = (allDeleted.length > 0) ? "Yes" : "No";

  alertSheet.getRange("AN2").setValue(warnMsg);
  alertSheet.getRange("AO2").setValue(revertMsg);
  alertSheet.getRange("AP2").setValue(deleteMsg);
}

async function processInvoices(ss, alertSheet) {
  const sheet = ss.getSheetByName("InvComp");
  const valB32 = alertSheet.getRange("B32").getValue();
  const valB33 = alertSheet.getRange("B33").getValue();
  const allowDupOverride = alertSheet.getRange("B46").getValue() === "Yes";

  const currentA2 = sheet.getRange("A2").getValue();
  const currentE2 = sheet.getRange("E2").getValue();
  let needsDelay = false;

  if (currentA2 !== valB32) { sheet.getRange("A2").setValue(valB32); needsDelay = true; }
  if (currentE2 !== true) { sheet.getRange("E2").setValue(true); needsDelay = true; }

  if (needsDelay) {
    // --- DOUBLE FLUSH OPTIMIZATION ---
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(2000));
    // 2s buffer
    sheet.getRange("A1").getValue(); // Dummy read to force calc
    (await SpreadsheetApp.flush());
    console.log("Agent (Inv): Recalculation complete.");
    // ---------------------------------
  } else {
    console.log("Agent (Inv): Master switch already ON and A2 correct. Skipping delay.");
  }

  const settings = getDiscrepancySettings(alertSheet, "A40:B45");
  const valB39 = alertSheet.getRange("B39").getValue();
  const missingInvoiceAction = String(valB39).trim().toLowerCase();
  if (missingInvoiceAction === 'include') {
    settings.include.push('Missing invoice?');
  } else if (missingInvoiceAction === 'exclude') {
    settings.exclude.push('Missing invoice?');
  }

  const data = sheet.getDataRange().getValues();
  const headers = data[4];
  const currencyIndex = headers.map(h => h.toString().trim().replace(/\s+/g, ' ')).indexOf('Currency');
  if (currencyIndex === -1) throw new Error('InvComp: "Currency" column not found.');
  const h = {};
  for (let i = currencyIndex + 1; i < headers.length; i++) {
    const normalizedHeader = headers[i].toString().trim().replace(/\s+/g, ' ');
    if (h[normalizedHeader] === undefined) h[normalizedHeader] = i;
  }

  let colPush = h['Push?'];
  if (colPush === undefined) colPush = h['Push inv?'];
  if (colPush === undefined) throw new Error("Agent: Could not find 'Push?' column.");
  const getIndices = (headerList) => headerList.map(name => h[name]).filter(idx => idx !== undefined);
  const includeIndices = getIndices(settings.include);
  const excludeIndices = getIndices(settings.exclude);
  const colAmtMismatch = h['Inv amt mismatch?'];
  const colDuplicate = h['Duplicate inv no ?'];
  const colDBAmt = h['DB Inv Amt'];
  const colXeroAmt = h['Xero Inv Amt'];

  const checkboxes = [];
  for (let i = 5; i < data.length; i++) {
    const row = data[i];
    let isExcluded = false;
    for (const idx of excludeIndices) {
      if (row[idx] === 1) {
        if (allowDupOverride && idx === colAmtMismatch && colDuplicate !== undefined && row[colDuplicate] === 1) {
          continue;
        }
        isExcluded = true;
        break;
      }
    }

    if (isExcluded) continue;
    let shouldUpdate = false;
    if (includeIndices.some(idx => row[idx] === 1)) {
      shouldUpdate = true;
    }

    if (settings.include.includes('Inv amt mismatch?') && colAmtMismatch !== undefined && row[colAmtMismatch] === 1) {
      const otherFlags = includeIndices.filter(idx => idx !== colAmtMismatch).some(idx => row[idx] === 1);
      if (colDBAmt !== undefined && colXeroAmt !== undefined) {
        const diff = Math.abs(row[colDBAmt] - row[colXeroAmt]);
        if (diff >= 0.05 && !otherFlags) {
          shouldUpdate = false;
        }
      }
    }

    if (shouldUpdate) checkboxes.push(sheet.getRange(i + 1, colPush + 1));
  }

  let updatedCount = 0;
  let logDetails = [];
  if (checkboxes.length > 0) {
    // FIXED: Batched checkbox ticking to save execution time
    sheet.getRangeList(checkboxes.map(r => r.getA1Notation())).setValue(true);
    // --- DOUBLE FLUSH BEFORE PUSH ---
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(1000));
    // Short 1s buffer to register checkboxes
    sheet.getRange("A1").getValue();
    (await SpreadsheetApp.flush());
    // --------------------------------

    const result = (await PushInvDetailsToConfirmed(true));
    updatedCount = result.count || 0;
    logDetails = result.logs || [];
  }

  sheet.getRange("A2").setValue(valB33);
  // --- DOUBLE FLUSH BEFORE FINAL REPORT ---
  (await SpreadsheetApp.flush());
  (await Utilities.sleep(2000)); 
  sheet.getRange("A1").getValue(); 
  (await SpreadsheetApp.flush());
  // ----------------------------------------

  const finalData = sheet.getDataRange().getValues();
  const allDashHeaders = ['Missing invoice?', 'Client mismatch', 'Inv amt mismatch?', 'Duplicate inv no ?'];
  const allAppHeaders = ['Sent date mismatch?', 'Fully paid on mismatch?', 'Status mismatch?'];

  const allDashIdx = getIndices(allDashHeaders);
  const allAppIdx = getIndices(allAppHeaders);
  const dashStat = countRowsWithFlags(finalData, 5, allDashIdx);
  const appStat = countRowsWithFlags(finalData, 5, allAppIdx);

  sheet.getRange("A2").setValue(valB32);
  // Master switch E2 left permanently ON per optimization
  (await SpreadsheetApp.flush());
  return {
    updated: updatedCount,
    dashDisc: dashStat,
    appDisc: appStat,
    logs: logDetails
  };
}

function countRowsWithFlags(data, startRow, colIndexes) {
  let count = 0;
  for (let i = startRow; i < data.length; i++) {
    let hasFlag = false;
    for (const idx of colIndexes) {
      if (data[i][idx] === 1) {
        hasFlag = true;
        break;
      }
    }
    if (hasFlag) count++;
  }
  return count;
}

function getDiscrepancySettings(sheet, rangeAddr) {
  const values = sheet.getRange(rangeAddr).getValues();
  const settings = {
    include: [],
    exclude: [],
    ignore: [] // NEW: Track ignore separately
  };
  values.forEach(row => {
    const headerName = (row[0] || '').toString().trim().replace(/\s+/g, ' ');
    const action = (row[1] || '').toString().toLowerCase().trim();

    if (headerName) {
      if (action === 'include') {
        settings.include.push(headerName);
      } else if (action === 'exclude') {
        settings.exclude.push(headerName);
      } else if (action === 'ignore') { // NEW
        settings.ignore.push(headerName);
      }
    }
  });
  return settings;
}


/**
 * Installs a time-based trigger for the Manual Entry & Gap Scan.
 * Runs every 30 minutes.
 * - First removes any existing triggers for this function to prevent duplicates.
 */
function installGapScanTrigger() {
  const funcName = 'runManualEntryAndGapScan';

  // 1. Remove existing triggers for this function to avoid duplicates
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(trigger => {
    if (trigger.getHandlerFunction() === funcName) {
      ScriptApp.deleteTrigger(trigger);
    }
  });
  // 2. Create the new trigger
  ScriptApp.newTrigger(funcName)
    .timeBased()
    .everyMinutes(30)
    .create();
  // 3. Confirm to user
  SpreadsheetApp.getUi().alert("Success: Manual Entry & Gap Scan set to run every 30 minutes.");
}

/**
 * Scans 'Confirmed' sheet for revenue gaps.
 * UPDATED: Reads Default Days from DataChgAlert!B52.
 */
async function auditInvoiceGaps(isHeadless, writeToSheet = false) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const alertSheet = ss.getSheetByName("DataChgAlert");
  
  // 1. CONFIGURATION
  const projLogicMode = alertSheet.getRange("B50").getValue() || "50-50";
  const retainerDayVal = parseInt(alertSheet.getRange("B51").getValue()) || 1;
  
  // --- NEW: Default Days ---
  const defaultDays = parseInt(alertSheet.getRange("B52").getValue()) || 30;

  let totalUpdateCount = 0;
  console.log(`[Diagnostic] Starting Invoice Audit. Mode: ${projLogicMode}, Retainer Day: ${retainerDayVal}, Def Days: ${defaultDays}`);

  // *** CLIENT SHEET CONNECTION ***
  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) {
      console.error("[Diagnostic] Error: Client Sheet ID (X28) not found.");
      return { count: 0, logs: ["Error: Audit Invoice Gaps - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  }
  let clientSs;
  try {
      clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
      console.error(`[Diagnostic] Error opening Client Spreadsheet: ${e.message}`);
      return { count: 0, logs: ["Error: Audit Invoice Gaps - " + e.message], hasError: true, error: e.message };
  }

  const allLogs = [];
  
  // 2. RUN AUDIT
  const confSheet = clientSs.getSheetByName("Confirmed");
  if (confSheet) {
      // Pass defaultDays to helper
      const res = runInvoiceSheetAudit_(confSheet, projLogicMode, retainerDayVal, defaultDays);
      totalUpdateCount += res.count;
      if (res.logs.length > 0) allLogs.push(...res.logs);
  } else {
      console.warn("[Diagnostic] 'Confirmed' sheet not found in Client Spreadsheet.");
  }

  const pipeSheet = clientSs.getSheetByName("Pipeline");
  if (pipeSheet) {
      const res = runInvoiceSheetAudit_(pipeSheet, projLogicMode, retainerDayVal, defaultDays);
      totalUpdateCount += res.count;
      if (res.logs.length > 0) allLogs.push(...res.logs);
  } else {
      console.warn("[Diagnostic] 'Pipeline' sheet not found in Client Spreadsheet.");
  }

  if (!confSheet && !pipeSheet) {
    return { count: 0, logs: ["Error: Audit Invoice Gaps - Neither 'Confirmed' nor 'Pipeline' sheet found in Client Spreadsheet."], hasError: true, error: "Neither 'Confirmed' nor 'Pipeline' sheet found in Client Spreadsheet." };
  }

  if (writeToSheet && alertSheet) {
      console.log(`[Diagnostic] Total Invoice Gaps Fixed: ${totalUpdateCount}`);
  }
  return { count: totalUpdateCount, logs: allLogs };
}

// --- HELPER: SHEET ITERATOR (V15.0 - PROJECT PARENT/CHILD SUPPORT) ---
function runInvoiceSheetAudit_(sheet, logicMode, retainerDay, defaultDays) {
  const sheetName = sheet.getName();
  console.log(`[Diagnostic] Scanning Sheet: ${sheetName}...`);
  
  const data = sheet.getDataRange().getValues();
  if (data.length < 1) return { count: 0, logs: [] };
  const headers = data[0].map(h => String(h || "").trim().toLowerCase());
  
  // FIXED: Load the corresponding *Calcs tab into memory to grab the calculated dates
  const calcSheetName = sheetName === "Confirmed" ? "ConfCalcs" : "PipeCalcs";
  const calcSheet = sheet.getParent().getSheetByName(calcSheetName);
  const calcData = calcSheet ? calcSheet.getDataRange().getValues() : [];
  const calcHeaders = calcData.length > 0 ? calcData[0].map(h => String(h || "").trim().toLowerCase()) : [];
  
  const calcStartCol = calcHeaders.indexOf("start month");
  const calcEndCol = calcHeaders.indexOf("end month");
  const spreadsheetTimeZone = sheet.getParent().getSpreadsheetTimeZone();
  let updates = 0;
  const logs = [];
  
  // FIXED: Batch arrays to minimize synchronous API calls
  const rangesToClear = [];
  const rangesToFormat = [];
  
  // Fallback if not passed
  const daysVal = (defaultDays && defaultDays > 0) ? defaultDays : 30;
  
  // Setup Helpers
  const parseMoney_ = (val) => {
      if (typeof val === 'number') return val;
      if (!val) return 0;
      const clean = String(val).replace(/[^0-9.-]/g, '');
      return parseFloat(clean) || 0;
  };
  
  // FIXED: Cache the regex normalization array to eliminate millions of CPU cycles per run
  const normHeaders = headers.map(h => h.replace(/[^a-z0-9]/g, ''));
  const getIdx = (input, isCritical = false) => {
     const names = Array.isArray(input) ? input : [input];
     for (const name of names) {
         const lower = name.toLowerCase();
         let idx = headers.indexOf(lower);
         if (idx !== -1) return idx;
         const clean = lower.replace(/[^a-z0-9]/g, '');
         idx = normHeaders.indexOf(clean);
         if (idx !== -1) return idx;
     }
     if (isCritical) console.warn(`[Diagnostic] CRITICAL: Could not find header for: ${names.join(" OR ")}`);
     return -1;
  };
  
  // Map Columns
  const colType = getIdx(["Project / retainer", "Type"], true);
  const colRevenue = getIdx(["Revenue (Proj total / Ongoing pm) - excl VAT", "Revenue", "Est. Revenue", "Fee"], true);
  const colStart = getIdx("Start date");
  const colEnd = getIdx("End date");
  const colJobName = getIdx(["Job name", "Job", "Project name"]);
  const colClient = getIdx(["Client"]);
  const colInvSend = getIdx(["Inv 1 SEND date", "Inv 1 date", "Est. inv 1 date"]);
  const colVAT = getIdx(["VAT?"]);
  const colLikelihood = getIdx(["% likel.", "Likelihood", "Probability"]);
  const colCopied = getIdx(["Copied to confirmed tab?", "Copied to conf. tab?", "Copied to conf tab?"]);

  const slots = [1, 2, 3].map(i => ({
      index: i - 1, 
      amt: getIdx([`Inv ${i} amt`, `Invoice ${i} amount`, `Inv ${i} amount`, `Project invoice ${i} (excl VAT)`, `Project invoice ${i} / monthly retainer (excl VAT)`]),
      date: getIdx([`Inv ${i} SEND date`, `Inv ${i} date`, `Invoice ${i} date`]),
      desc: getIdx([`Inv ${i} descr.`, `Invoice ${i} description`, `Inv ${i} details`]),
      id: getIdx([`Inv ${i} no`, `Invoice ${i} number`, `Inv ${i} id`, `Inv ${i} ref`]),
      status: getIdx([`Inv ${i} status`, `Invoice ${i} status`]),
      days: getIdx([`Inv ${i} days to pay`, `Invoice ${i} days to pay`, `Project invoice ${i} days to pay`]),
      dueDate: getIdx([`Inv ${i} due date`, `Invoice ${i} due date`])
  }));
  
  if (colRevenue === -1) {
      console.error(`[Diagnostic] Skipping ${sheetName}: Revenue column missing.`);
      return { count: 0, logs: [] };
  }

  // --- CONFIGURATION ---
  const today = new Date(); today.setHours(0,0,0,0);
  const targetFifth = new Date(today.getFullYear(), today.getMonth(), 5);

  const getModeWeights = (mode) => {
      const m = String(mode).toLowerCase();
      if (m.includes("50-25-25")) return [0.5, 0.25, 0.25];
      if (m.includes("25-25-50")) return [0.25, 0.25, 0.5];
      if (m.includes("50-50")) return [0.5, 0.5, 0];
      if (m.includes("25-75")) return [0.25, 0.75, 0];
      return [1, 0, 0]; 
  };
  const fuzzy = (str) => String(str || '').toLowerCase().replace(/&/g, 'and').replace(/\s+/g, '');

  // --- HELPER: Detect if a row is a parent with children below ---
  const isParentWithChildren_ = (dataIdx) => {
      const row = data[dataIdx];
      const jn = String(row[colJobName] || "");
      const cn = String(row[colClient] || "");
      const rawRev = parseMoney_(row[colRevenue]);
      if (!jn || rawRev <= 0) return false;
      if (dataIdx + 1 >= data.length) return false;
      const nextRow = data[dataIdx + 1];
      const nextJob = String(nextRow[colJobName] || "");
      const nextClient = String(nextRow[colClient] || "");
      const nextRev = parseMoney_(nextRow[colRevenue]);
      const nextStart = nextRow[colStart];
      return (fuzzy(nextClient) === fuzzy(cn) && fuzzy(nextJob) === fuzzy(jn) && 
              (isNaN(nextRev) || nextRev === 0) &&
              (!nextStart || String(nextStart).trim() === ''));
  };

  // --- HELPER: Count consecutive child rows below a parent ---
  const countChildRows_ = (parentIdx) => {
      const parentJob = fuzzy(data[parentIdx][colJobName]);
      const parentClient = fuzzy(data[parentIdx][colClient]);
      let count = 0;
      for (let j = parentIdx + 1; j < data.length; j++) {
          const childJob = fuzzy(data[j][colJobName]);
          const childClient = fuzzy(data[j][colClient]);
          const childRev = parseMoney_(data[j][colRevenue]);
          const childStart = data[j][colStart];
          if (childClient !== parentClient || childJob !== parentJob) break;
          if (childRev > 0 || (childStart && String(childStart).trim() !== '')) break;
          count++;
      }
      return count;
  };
  
  // --- HELPER: Analyse slots for a single row ---
  const analyseRowSlots_ = (row) => {
      let realFilled = 0;
      let realCount = 0;
      let autoSlots = [];
      let emptySlots = [];
      slots.forEach((s) => {
          if (s.amt === -1) return;
          const val = parseMoney_(row[s.amt]);
          const idVal = String(row[s.id] || "").trim();
          const isAutoPlaceholder = isPlaceholderInvoice_(idVal);
          
          const isRealApp = idVal !== "" && !isAutoPlaceholder;
          const hasVal = !isNaN(val) && val > 0.01;
          
          if (isAutoPlaceholder) {
              autoSlots.push(s);
          } else if (hasVal || isRealApp) {
              realFilled += val;
              realCount++;
          } else {
              emptySlots.push(s);
          }
      });
      return { realFilled, realCount, autoSlots, emptySlots, availableSlots: [...autoSlots, ...emptySlots] };
  };

  // --- HELPER: Write a gap allocation to a specific row/slot ---
  const applyGapAllocation_ = (dataIdx, s, amountToWrite, dateToWrite, descType) => {
      const sheetRow = dataIdx + 1;
      const rowData = data[dataIdx];
      const jn = String(rowData[colJobName] || "");
      if (dateToWrite instanceof Date && dateToWrite < today) dateToWrite = targetFifth;

      const currentVal = parseMoney_(rowData[s.amt]);
      const currentDateVal = rowData[s.date];
      let dateChanged = false;
      if (dateToWrite instanceof Date) {
          if (currentDateVal instanceof Date) {
              if (dateToWrite < currentDateVal && dateToWrite <= targetFifth) {
                  dateChanged = false;
              } else {
                   if (Math.abs(dateToWrite.getTime() - currentDateVal.getTime()) > 172800000) dateChanged = true;
              }
          } else {
              dateChanged = true;
          }
      }

      const idVal = String(rowData[s.id] || "").trim();
      const isManualSlot = isPlaceholderInvoice_(idVal);
      
      const isRealApp = idVal !== "" && !isManualSlot;
      if (isRealApp) return false;
      
      const isNewCreation = !isManualSlot && currentVal === 0;
      
      if (Math.abs(currentVal - amountToWrite) > 0.01 || (isManualSlot && dateChanged) || isNewCreation) {
          // FIXED: Pass rangesToFormat and rowData so styling and unchanged checks can be batched
          writeInvoiceManualEntry_(sheet, sheetRow, s, amountToWrite, dateToWrite, descType, daysVal, rangesToFormat, rowData);
          const client = rowData[colClient] || "Unknown";
          
          const isRetainer = descType.includes("Retainer");
          const createTxt = isRetainer ? "Created Retainer Invoice" : "Created Placeholder Invoice";
          const adjustTxt = isRetainer ? "Adjusted Retainer Invoice" : "Adjusted Placeholder Invoice";

          if (isNewCreation) {
              logs.push(`[${sheetName}] ${createTxt}: Row ${sheetRow}, ${client}, ${jn}, £${amountToWrite.toFixed(2)}, Slot ${s.index+1}`);
          } else {
              const changes = [];
              if (Math.abs(currentVal - amountToWrite) > 0.01) {
                  changes.push(`Amt: £${currentVal.toFixed(2)} -> £${amountToWrite.toFixed(2)}`);
              }
              if (dateChanged) {
                  const d1 = (currentDateVal instanceof Date) ? Utilities.formatDate(currentDateVal, spreadsheetTimeZone, "dd-MMM") : "Blank";
                  const d2 = Utilities.formatDate(dateToWrite, spreadsheetTimeZone, "dd-MMM");
                  changes.push(`Date: ${d1} -> ${d2}`);
              }
              logs.push(`[${sheetName}] ${adjustTxt}: Row ${sheetRow}, ${client} - ${changes.join(", ")}`);
          }
          return true;
      }
      return false;
  };

  // --- HELPER: Process a single row for gap filling (retainers and standalone projects) ---
  const processRowGap_ = (i, targetRevenue, isParentRow, isRetainerRow = false) => {
      const row = data[i];
      const rawRowType = String(row[colType] || "").toLowerCase();
      const isRetainer = isRetainerRow || rawRowType.includes("retainer");
      const jobName = String(row[colJobName] || "");
      const { realFilled, realCount, availableSlots } = analyseRowSlots_(row);
      
      // FIXED: Pull Start and End dates exclusively from the *Calcs tab (Fallback to raw dates if missing)
      const rawCalcStart = (calcData[i] && calcStartCol !== -1) ? calcData[i][calcStartCol] : row[colStart];
      const rawCalcEnd = (calcData[i] && calcEndCol !== -1) ? calcData[i][calcEndCol] : row[colEnd];
      
      const hasDates = rawCalcStart && String(rawCalcStart).trim() !== "" && rawCalcEnd && String(rawCalcEnd).trim() !== "";
      
      // For retainers: If the row already has a real invoice (realCount > 0), the row is considered invoiced.
      // Retainers never split gaps across slots 2 or 3 to fill minor invoice discrepancies (e.g. currency diffs).
      const gapNeeded = (isParentRow || !hasDates || (isRetainer && realCount > 0)) ? 0 : (targetRevenue - realFilled);
      
      const sheetRow = i + 1;
      let rowUpdated = false;

      const startDate = rawCalcStart ? new Date(rawCalcStart) : new Date();
      const endDate = rawCalcEnd ? new Date(rawCalcEnd) : new Date();
      
      let anchorDate;
      const slot1Id = (slots[0] && slots[0].id !== -1) ? String(row[slots[0].id] || "").trim() : "";
      const isPlaceholderSlot1 = isPlaceholderInvoice_(slot1Id);
      
      const invSendVal = row[colInvSend];
      const hasInvSend = invSendVal && (invSendVal instanceof Date || String(invSendVal).trim() !== "");
      const parsedInvSend = hasInvSend ? new Date(invSendVal) : null;
      const isValidInvSend = parsedInvSend && !isNaN(parsedInvSend.getTime());
      
      const startMonthVal = (startDate instanceof Date && !isNaN(startDate.getTime())) 
          ? (startDate.getFullYear() * 12 + startDate.getMonth()) 
          : -1;
      const sendMonthVal = isValidInvSend ? (parsedInvSend.getFullYear() * 12 + parsedInvSend.getMonth()) : -1;
      
      // FIXED: If there is an existing send date, only keep it if it is a real invoice or
      // if its placeholder date falls on/after the contract start month.
      // Otherwise, anchor on startDate's month using retainerDay.
      if (isValidInvSend && (!isPlaceholderSlot1 || (startMonthVal !== -1 && sendMonthVal >= startMonthVal))) {
          anchorDate = parsedInvSend;
      } else {
          const baseDate = (startDate instanceof Date && !isNaN(startDate.getTime())) ? startDate : today;
          const maxDaysInMonth = new Date(baseDate.getFullYear(), baseDate.getMonth() + 1, 0).getDate();
          const safeDay = Math.min(retainerDay || 1, maxDaysInMonth);
          anchorDate = new Date(baseDate.getFullYear(), baseDate.getMonth(), safeDay);
      }
      
      if (gapNeeded > 0.05 && !isParentRow) {
          const allocations = [];
          if (isRetainer) {
              if (slots[0] && slots[0].amt !== -1) {
                  allocations.push({ amt: gapNeeded, date: anchorDate, targetSlotIndex: 0 });
              }
          } else {
              const isReal_ = (s) => (parseMoney_(row[s.amt]) > 0 || String(row[s.id] || "").trim() !== "") && !isPlaceholderInvoice_(row[s.id]);
              const s1_real = isReal_(slots[0]);
              const s2_real = isReal_(slots[1]);
              const s3_real = isReal_(slots[2]);
              const xeroCount = (s1_real ? 1 : 0) + (s2_real ? 1 : 0) + (s3_real ? 1 : 0);

              const splitRules = calculateRevenueSplit_(gapNeeded, logicMode, startDate, endDate, retainerDay, xeroCount);
              
              const maxSlotsOnThisRow = Math.max(0, 3 - xeroCount);
              const currentInvRules = splitRules.slice(0, maxSlotsOnThisRow);
              let remainingRulesAmt = splitRules.slice(maxSlotsOnThisRow).reduce((sum, r) => sum + r.amt, 0);
              
              currentInvRules.forEach((rule, i) => {
                  if (i < availableSlots.length) {
                      allocations.push({ amt: rule.amt, date: rule.date, targetSlotIndex: availableSlots[i].index });
                  } else {
                      remainingRulesAmt += rule.amt;
                  }
              });

              if (remainingRulesAmt > 0.05) {
                  projectGroupsNeedingRows.push({
                     insertAfter: i,
                     client: row[colClient],
                     job: jobName,
                     vat: (colVAT !== -1) ? row[colVAT] : "",
                     gapAmount: remainingRulesAmt,
                     date: endDate,
                     startDate: startDate
                  });
              }
          }

          allocations.forEach(alloc => {
              if (alloc.date < today) alloc.date = targetFifth;
              const s = slots[alloc.targetSlotIndex];
              if (!s) return;
              if (applyGapAllocation_(i, s, alloc.amt, alloc.date, isRetainer ? "Retainer Invoice" : "Project Invoice")) {
                  rowUpdated = true;
              }
          });

          if (availableSlots.length > allocations.length) {
              const allocatedIndices = allocations.map(a => a.targetSlotIndex);
              availableSlots.forEach(s => {
                  if (!allocatedIndices.includes(s.index) && isPlaceholderInvoice_(row[s.id])) {
                      clearInvoiceSlot_(sheet, sheetRow, s, rangesToClear);
                      rowUpdated = true;
                      const client = row[colClient] || "Unknown";
                      const logAction = isRetainer ? "Removed Retainer Invoice" : "Removed Placeholder Invoice";
                      logs.push(`[${sheetName}] ${logAction}: Row ${sheetRow}, ${client} | ${jobName}, Slot ${s.index+1}`);
                  }
              });
          }
      } else {
          slots.forEach(s => {
              if (isPlaceholderInvoice_(row[s.id])) {
                  clearInvoiceSlot_(sheet, sheetRow, s, rangesToClear);
                  rowUpdated = true;
                  const client = row[colClient] || "Unknown";
                  const logAction = isRetainer ? "Removed Retainer Invoice" : "Removed Placeholder Invoice";
                  logs.push(`[${sheetName}] ${logAction}: Row ${sheetRow}, ${client} | ${jobName}, Slot ${s.index+1}`);
              }
          });
      }
      if (rowUpdated) updates++;
  };

  // ====================================================================
  // MAIN LOOP
  // ====================================================================
  const projectGroupsNeedingRows = [];

  let i = 1;
  while (i < data.length) {
      const row = data[i];
      const rowType = String(row[colType] || "").toLowerCase();
      const jobName = String(row[colJobName] || "");
      const clientName = String(row[colClient] || "");
      const rawRevenue = parseMoney_(row[colRevenue]);

      if (sheetName === "Pipeline") {
          const likelihood = parseFloat(String(row[colLikelihood]).replace(/[^0-9.-]/g, ''));
          const isZeroLikelihood = colLikelihood !== -1 && likelihood === 0 && String(row[colLikelihood]).trim() !== "";
          const isCopied = colCopied !== -1 && String(row[colCopied]).trim().toLowerCase() === "yes";
          
          if (isZeroLikelihood || isCopied) {
              const childCount = isParentWithChildren_(i) ? countChildRows_(i) : 0;
              i += 1 + childCount;
              continue;
          }
      }

      if (rowType.includes("retainer")) {
          if (isParentWithChildren_(i)) {
              const childCount = countChildRows_(i);

              // 1. Clear any placeholder invoices on the parent row
              slots.forEach(s => {
                  if (isPlaceholderInvoice_(row[s.id])) {
                      clearInvoiceSlot_(sheet, i + 1, s, rangesToClear);
                      updates++;
                      const client = row[colClient] || "Unknown";
                      logs.push(`[${sheetName}] Removed Retainer Invoice: Row ${i + 1}, ${client} | ${jobName}, Slot ${s.index+1}`);
                  }
              });

              // 2. Clear any placeholder invoices on all child rows (retainer child rows should NEVER have placeholders)
              for (let c = 1; c <= childCount; c++) {
                  const childRow = data[i + c];
                  slots.forEach(s => {
                      if (isPlaceholderInvoice_(childRow[s.id])) {
                          clearInvoiceSlot_(sheet, i + c + 1, s, rangesToClear);
                          updates++;
                          const client = childRow[colClient] || "Unknown";
                          logs.push(`[${sheetName}] Removed Placeholder Invoice (Retainer Child): Row ${i + c + 1}, ${client} | ${jobName}, Slot ${s.index+1}`);
                      }
                  });
              }

              // Advance past the parent and all child rows - NEVER gap-fill child rows of a retainer
              i += 1 + childCount;
              continue;
          } else {
              // Standalone retainer (no children)
              const targetRevenue = !isNaN(rawRevenue) ? rawRevenue : 0;
              processRowGap_(i, targetRevenue, false, true);
              i++;
              continue;
          }
      }

      if (isParentWithChildren_(i)) {
          const childCount = countChildRows_(i);
          const parentRevenue = rawRevenue;
          
          // FIXED: Pull Parent Start and End dates exclusively from the *Calcs tab
          const rawCalcStart = (calcData[i] && calcStartCol !== -1) ? calcData[i][calcStartCol] : row[colStart];
          const rawCalcEnd = (calcData[i] && calcEndCol !== -1) ? calcData[i][calcEndCol] : row[colEnd];
          
          const parentStartDate = rawCalcStart ? new Date(rawCalcStart) : new Date();
          const parentEndDate = rawCalcEnd ? new Date(rawCalcEnd) : new Date();
          
          const hasDates = rawCalcStart && String(rawCalcStart).trim() !== "" && rawCalcEnd && String(rawCalcEnd).trim() !== "";
          
          const parentSlotAnalysis = analyseRowSlots_(row);
          const parentHasInvoices = parentSlotAnalysis.realCount > 0;

          let totalInvoiced = parentSlotAnalysis.realFilled;
          for (let c = 1; c <= childCount; c++) {
              const childAnalysis = analyseRowSlots_(data[i + c]);
              totalInvoiced += childAnalysis.realFilled;
          }

          const groupGap = hasDates ? (parentRevenue - totalInvoiced) : 0;
          if (groupGap > 0.05) {
              let groupXeroCount = parentHasInvoices ? parentSlotAnalysis.realCount : 0;
              for (let c = 1; c <= childCount; c++) groupXeroCount += analyseRowSlots_(data[i + c]).realCount;
              
              const allocations = calculateRevenueSplit_(groupGap, logicMode, parentStartDate, parentEndDate, retainerDay, groupXeroCount);
              const groupAutoSlots = [];
              const groupEmptySlots = [];
              
              if (parentHasInvoices || true) {
                  parentSlotAnalysis.autoSlots.forEach(s => groupAutoSlots.push({ dataIdx: i, slot: s }));
                  parentSlotAnalysis.emptySlots.forEach(s => groupEmptySlots.push({ dataIdx: i, slot: s }));
              }
              for (let c = 1; c <= childCount; c++) {
                  const childAnalysis = analyseRowSlots_(data[i + c]);
                  childAnalysis.autoSlots.forEach(s => groupAutoSlots.push({ dataIdx: i + c, slot: s }));
                  childAnalysis.emptySlots.forEach(s => groupEmptySlots.push({ dataIdx: i + c, slot: s }));
              }
              const groupAvailableSlots = [...groupAutoSlots, ...groupEmptySlots];

              const isRowFull = parentSlotAnalysis.realCount >= 3;
              const currentFilledCount = parentSlotAnalysis.realCount; 
              
              if (groupAvailableSlots.length >= allocations.length) {
                  allocations.forEach((alloc, idx) => {
                      const entry = groupAvailableSlots[idx];
                      if (applyGapAllocation_(entry.dataIdx, entry.slot, alloc.amt, alloc.date, "Project Invoice")) {
                          updates++;
                      }
                  });

                  for (let g = allocations.length; g < groupAvailableSlots.length; g++) {
                      const ge = groupAvailableSlots[g];
                      if (isPlaceholderInvoice_(data[ge.dataIdx][ge.slot.id])) {
                          clearInvoiceSlot_(sheet, ge.dataIdx + 1, ge.slot, rangesToClear);
                          const client = data[ge.dataIdx][colClient] || "Unknown";
                          logs.push(`[${sheetName}] Removed Placeholder Invoice (Project Group): Row ${ge.dataIdx + 1}, ${client} | ${jobName}, Slot ${ge.slot.index+1}`);
                      }
                  }
              } else {
                  projectGroupsNeedingRows.push({
                    insertAfter: i + childCount,
                    client: clientName,
                    job: jobName,
                    vat: (colVAT !== -1) ? row[colVAT] : "",
                    gapAmount: groupGap,
                    date: parentEndDate,
                    startDate: parentStartDate
                  });
              }
          } else {
              if (parentHasInvoices || true) {
                  parentSlotAnalysis.availableSlots.forEach(s => {
                      const idVal = String(row[s.id] || "");
                      if (isPlaceholderInvoice_(idVal)) {
                          clearInvoiceSlot_(sheet, i + 1, s, rangesToClear);
                          updates++;
                          const client = row[colClient] || "Unknown";
                          logs.push(`[${sheetName}] Removed Placeholder Invoice: Row ${i + 1}, ${client} | ${jobName}, Slot ${s.index+1}`);
                      }
                  });
              }
              for (let c = 1; c <= childCount; c++) {
                  const childAnalysis = analyseRowSlots_(data[i + c]);
                  childAnalysis.availableSlots.forEach(s => {
                      const idVal = String(data[i + c][s.id] || "");
                      if (isPlaceholderInvoice_(idVal)) {
                          clearInvoiceSlot_(sheet, i + c + 1, s, rangesToClear);
                          updates++;
                          const client = data[i + c][colClient] || "Unknown";
                          logs.push(`[${sheetName}] Removed Placeholder Invoice: Row ${i + c + 1}, ${client} | ${jobName}, Slot ${s.index+1}`);
                      }
                  });
              }
          }

          i += 1 + childCount;
          continue;
      }

      const targetRevenue = !isNaN(rawRevenue) ? rawRevenue : 0;
      processRowGap_(i, targetRevenue, false);
      i++;
  }

  // ====================================================================
  // POST-LOOP: Create new child rows for Project groups via moveRows
  // ====================================================================
  if (projectGroupsNeedingRows.length > 0) {
      let trueLastRow = 0;
      for (let r = data.length - 1; r >= 0; r--) {
          const row = data[r];
          const z1 = row.slice(0, 5).some(c => c !== "" && c !== null);
          const z2 = row.slice(32, 39).some(c => c !== "" && c !== null);
          const z3 = row.slice(41, 60).some(c => c !== "" && c !== null);
          const z4 = row.slice(75, 96).some(c => c !== "" && c !== null);
          
          if (z1 || z2 || z3 || z4) {
              trueLastRow = r + 1;
              break;
          }
      }

      projectGroupsNeedingRows.sort((a, b) => b.insertAfter - a.insertAfter);
      projectGroupsNeedingRows.forEach(job => {
      const currentMax = sheet.getMaxRows();
      const availableEmpty = currentMax - (trueLastRow + 1);
      if (availableEmpty < 1) {
          sheet.insertRowsAfter(currentMax, 5);
      }

      const sourceStartRow = trueLastRow + 2;
      const sourceRange = sheet.getRange(sourceStartRow, 1, 1, sheet.getLastColumn());
      sheet.moveRows(sourceRange, job.insertAfter + 2);
      trueLastRow += 1;

      const newChildRow = job.insertAfter + 2;
      const pStart = job.startDate || today;
      const fourthMonthStart = new Date(pStart.getFullYear(), pStart.getMonth() + 3, retainerDay);

      sheet.getRange(newChildRow, colClient + 1).setValue(sanitizeSheetCell_(job.client));
      sheet.getRange(newChildRow, colJobName + 1).setValue(sanitizeSheetCell_(job.job));
      if (colVAT !== -1) sheet.getRange(newChildRow, colVAT + 1).setValue(sanitizeSheetCell_(job.vat));

      const overflowRules = calculateRevenueSplit_(job.gapAmount, logicMode, fourthMonthStart, job.date, retainerDay);
      overflowRules.forEach((rule, idx) => {
          if (idx < 3) { 
              writeInvoiceManualEntry_(sheet, newChildRow, slots[idx], rule.amt, rule.date, "Project Invoice", daysVal, rangesToFormat);
          }
      });

      updates++;
      logs.push(`[${sheetName}] MOVING ROW: Source [${sourceStartRow}] -> Destination [${newChildRow}] for ${job.client} | ${job.job}. (Overflow handling)`);
      try {
          const rangeToGroup = sheet.getRange(newChildRow, 1, 1, 1);
          rangeToGroup.shiftRowGroupDepth(1);
          const grp = sheet.getRowGroup(newChildRow, 1);
          if (!grp || !grp.isCollapsed()) {
              sheet.unhideRow(rangeToGroup);
          }
      } catch (e) {
          console.log("Grouping skip/error: " + e.message);
      }
  });
  }

  // FIXED: Execute all clearing and formatting safely using massive batched payloads
  if (rangesToClear.length > 0) {
      sheet.getRangeList(rangesToClear)
           .clearContent()
           .setFontWeight(null)
           .setFontLine(null)
           .setFontStyle(null)
           .setFontColor(null);
  }
  
  if (rangesToFormat.length > 0) {
      sheet.getRangeList(rangesToFormat)
           .setFontWeight("bold")
           .setFontLine("underline")
           .setFontColor("black");
  }

  return { count: updates, logs: logs };
}


// --- HELPER: LOGIC SPLITTER ---
function calculateRevenueSplit_(amount, mode, start, end, retainerDay, xeroCount = 0) {
    const mid = new Date(start.getTime() + (end.getTime() - start.getTime()) / 2);
    const modeClean = String(mode).trim().toLowerCase();

    if (modeClean === "even-split") {
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
        const totalMonths = Math.round(diffDays / 30.4375);
        const slotsNeeded = Math.max(1, totalMonths - xeroCount); // Subtract existing Xero data
        const amtPerMonth = amount / slotsNeeded;
        const allocations = [];
        for (let m = 0; m < slotsNeeded; m++) {
            const invDate = new Date(start.getFullYear(), start.getMonth() + xeroCount + m, retainerDay || 1);
            allocations.push({ amt: amtPerMonth, date: invDate });
        }
        return allocations;
    }

    // FIXED: Smart Logic adjusts remaining weights based on existing Xero invoices
    let weights = [1];
    let dates = [end];

    if (modeClean.includes("50-50")) {
        if (xeroCount === 0) { weights = [0.5, 0.5]; dates = [start, end]; }
        else { weights = [1]; dates = [end]; } 
    }
    else if (modeClean.includes("33-33-33")) {
        if (xeroCount === 0) { weights = [1/3, 1/3, 1/3]; dates = [start, mid, end]; }
        else if (xeroCount === 1) { weights = [0.5, 0.5]; dates = [mid, end]; } 
        else { weights = [1]; dates = [end]; }
    }
    else if (modeClean.includes("50-25-25")) {
        if (xeroCount === 0) { weights = [0.5, 0.25, 0.25]; dates = [start, mid, end]; }
        else if (xeroCount === 1) { weights = [0.5, 0.5]; dates = [mid, end]; } 
        else { weights = [1]; dates = [end]; }
    }
    else if (modeClean.includes("25-25-50")) {
        if (xeroCount === 0) { weights = [0.25, 0.25, 0.5]; dates = [start, mid, end]; }
        else if (xeroCount === 1) { weights = [1/3, 2/3]; dates = [mid, end]; } 
        else { weights = [1]; dates = [end]; }
    }
    else if (modeClean.includes("25-75")) {
        if (xeroCount === 0) { weights = [0.25, 0.75]; dates = [start, end]; }
        else { weights = [1]; dates = [end]; }
    }
    else if (modeClean.includes("100 at start")) {
        weights = [1]; dates = [start];
    }
    else { 
        weights = [1]; dates = [end];
    }

    const allocations = [];
    for (let i = 0; i < weights.length; i++) {
        allocations.push({ amt: amount * weights[i], date: dates[i] });
    }
    return allocations;
}

/**
 * Internal Helper: Writes a placeholder invoice entry.
 * UPDATED: Batches formatting calls into a global array to prevent API exhaustion.
 */
function writeInvoiceManualEntry_(sheet, row, slot, amount, dateObj, descType, defaultDays, rangesToFormatArray, existingRow) {
    const ms = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    const dateStr = (dateObj instanceof Date) ? `${ms[dateObj.getMonth()]}-${String(dateObj.getFullYear()).slice(-2)}` : "UNK";
    const rand = Math.floor(1000 + Math.random() * 9000);
    const manualID = `PLACE-INV-${dateStr}-${rand}`;

    // Fast helper to convert column index to A1 letter natively
    const getColLetter = (colIdx) => {
        let temp, letter = '';
        let idx = colIdx + 1;
        while (idx > 0) {
            temp = (idx - 1) % 26;
            letter = String.fromCharCode(temp + 65) + letter;
            idx = (idx - temp - 1) / 26;
        }
        return letter;
    };

    const writeAndTrack = (colIdx, value, isText = false) => {
        if (colIdx !== -1) {
            if (existingRow && existingRow[colIdx] !== undefined) {
                const existingVal = existingRow[colIdx];
                if (existingVal === value || (typeof value === 'number' && Math.abs(existingVal - value) < 0.001)) {
                    // Value is already identical; skip remote write
                    return;
                }
            }
            const cell = sheet.getRange(row, colIdx + 1);
            if (isText) cell.setNumberFormat("@");
            cell.setValue(sanitizeSheetCell_(value));
            // Push A1 Notation cleanly to the array for the batched formatting sweep
            if (rangesToFormatArray) rangesToFormatArray.push(`${getColLetter(colIdx)}${row}`);
        }
    };

    if (slot.desc !== -1) writeAndTrack(slot.desc, `Placeholder - ${descType}`);
    if (slot.amt !== -1) writeAndTrack(slot.amt, amount);
    if (slot.date !== -1 && dateObj instanceof Date) writeAndTrack(slot.date, dateObj);
    if (slot.id !== -1) {
        const currentId = (existingRow && existingRow[slot.id] !== undefined) ? String(existingRow[slot.id] || "") : "";
        if (!isPlaceholderInvoice_(currentId)) {
            writeAndTrack(slot.id, String(manualID), true);
        }
    }
    if (slot.status !== -1) {
        const currentStatus = (existingRow && existingRow[slot.status] !== undefined) ? String(existingRow[slot.status] || "") : "";
        if (currentStatus !== "") {
            sheet.getRange(row, slot.status + 1).setValue("");
        }
    }
    
    if (slot.days !== -1) {
        const daysToUse = (defaultDays && defaultDays > 0) ? defaultDays : 30;
        writeAndTrack(slot.days, daysToUse);
    }

    if (slot.dueDate !== -1 && dateObj instanceof Date) {
        const dueObj = new Date(dateObj);
        const daysToUse = (defaultDays && defaultDays > 0) ? defaultDays : 30;
        dueObj.setDate(dateObj.getDate() + daysToUse); 
        writeAndTrack(slot.dueDate, dueObj);
    }
}

// --- HELPER: CLEAR INVOICE SLOT ---
function clearInvoiceSlot_(sheet, row, slot, rangesToClearArray) {
    // FIXED: Construct A1 notation mathematically to avoid slow getRange().getA1Notation() API calls
    const getColLetter = (colIdx) => {
        let temp, letter = '';
        let idx = colIdx + 1;
        while (idx > 0) {
            temp = (idx - 1) % 26;
            letter = String.fromCharCode(temp + 65) + letter;
            idx = (idx - temp - 1) / 26;
        }
        return letter;
    };
    
    const add = (colIdx) => {
        if (colIdx !== -1 && rangesToClearArray) {
            rangesToClearArray.push(`${getColLetter(colIdx)}${row}`);
        }
    };
    
    add(slot.desc); add(slot.amt); add(slot.date);
    add(slot.id); add(slot.status); add(slot.days); add(slot.dueDate);
}

/**
 * GLOBAL HELPER: Determines how many invoice slots are required.
 */
function getTargetInvoiceCount(mode, start, end) {
    const m = String(mode).toLowerCase();
    if (m === "even-split" && start instanceof Date && end instanceof Date) {
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
        const totalMonths = Math.round(diffDays / 30.4375);
        return Math.max(1, totalMonths);
    }
    if (m.includes("50-25-25") || m.includes("25-25-50") || m.includes("33-33-33")) return 3;
    if (m.includes("50-50") || m.includes("25-75")) return 2;
    return 1; 
}

/**
 * Menu-ready wrapper for manually triggering the Invoice Gap Audit.
 */
async function runManualInvoiceGapScan() {
  const ui = SpreadsheetApp.getUi();
  try {
    console.log("--- Starting Standalone Manual Invoice Gap Scan ---");
    
    // Call the worker function and tell it to write its counts to the sheet
    const gapRes = (await auditInvoiceGaps(true, true)); 
    
    // Build the popup message
    let msg = "Invoice Scan Complete.\n\n";
    if (gapRes.count > 0) {
        msg += `⚠️ Created or adjusted ${gapRes.count} Invoice Gap(s).\n`;
        msg += "Check the Apps Script Execution Logs for detailed row-by-row changes.";
    } else {
        msg += "✅ No invoice gaps found or adjusted.";
    }
    
    ui.alert(msg);
    
  } catch (e) {
    console.error("Error running manual invoice scan: " + e.message);
    ui.alert("Error running scan: " + e.message);
  }
}


/**
 * ----------------------------------------------------------------
 * WEB APP ENTRY POINT — lets the Pulse triage app trigger this
 * client's automation on demand, instead of waiting for the
 * 30-minute checkForAgentSignal poll or a manual run.
 *
 * ONE-TIME SETUP (per client sheet):
 *   1. Project Settings > Script Properties > add a property named
 *      AGENT_TRIGGER_SECRET with the shared secret value (same
 *      value used across every client sheet).
 *   2. Deploy > New deployment > select type "Web app" >
 *      Execute as: Me, Who has access: Anyone > Deploy.
 *   3. Copy the resulting Web app URL into column N of this
 *      client's row on the AutoUpdates tab in Automation Commander.
 *
 * Request body (JSON): { "secret": "...", "types": ["invoice"],
 *   "clientName": "...", "runId": "..." }
 *   types: any combination of "invoice", "crm", "expense".
 *   clientName/runId: optional — if provided, this run's progress is
 *   reported back to the triage app as it executes (see postAgentProgress_
 *   below); if omitted, the automation still runs, just without live
 *   progress reporting.
 *
 * NOTE: Apps Script Web Apps always return HTTP 200 regardless of
 * outcome — there's no way to set a different status code from
 * here. Callers must check the "success" field in the JSON body,
 * not the HTTP status, to tell success from failure.
 * ----------------------------------------------------------------
 */
async function doPost(e) {
  const respond = (body) => ContentService
    .createTextOutput(JSON.stringify(body))
    .setMimeType(ContentService.MimeType.JSON);

  try {
    if (!e || !e.postData || !e.postData.contents) {
      return respond({ success: false, error: "No request body" });
    }

    let payload;
    try {
      payload = JSON.parse(e.postData.contents);
    } catch (parseErr) {
      return respond({ success: false, error: "Invalid JSON body" });
    }

    // 1. AUTH — reject anything without the matching shared secret
    const props = PropertiesService.getScriptProperties();
    const expectedSecret = props.getProperty('AGENT_TRIGGER_SECRET');
    const cronSecret = props.getProperty('CRON_SECRET');
    const isAuthed = Boolean(payload.secret) && (
      (expectedSecret && payload.secret === expectedSecret) ||
      (cronSecret && payload.secret === cronSecret)
    );
    if (!isAuthed) {
      if (!expectedSecret && !cronSecret) {
        console.error("doPost: AGENT_TRIGGER_SECRET not set in Script Properties — rejecting all requests.");
        return respond({ success: false, error: "Not configured" });
      }
      return respond({ success: false, error: "Invalid secret" });
    }

    // 1a. ONE-OFF / ADMIN SECRET MIGRATION HANDLER (sync_script_secrets)
    if (payload.action === 'sync_script_secrets') {
      const canSyncSecrets = expectedSecret
        ? (payload.secret === expectedSecret)
        : Boolean(cronSecret && payload.secret === cronSecret);
      if (!canSyncSecrets) {
        return respond({ success: false, error: "Invalid secret for secret sync" });
      }
      try {
        const configuredKeys = [];
        if (payload.newAgentTriggerSecret) {
          props.setProperty('AGENT_TRIGGER_SECRET', String(payload.newAgentTriggerSecret));
          configuredKeys.push('AGENT_TRIGGER_SECRET');
        } else if (expectedSecret) {
          configuredKeys.push('AGENT_TRIGGER_SECRET');
        }
        if (payload.pulseInternalSecret) {
          props.setProperty('PULSE_INTERNAL_SECRET', String(payload.pulseInternalSecret));
          configuredKeys.push('PULSE_INTERNAL_SECRET');
        }
        if (payload.cronSecret) {
          props.setProperty('CRON_SECRET', String(payload.cronSecret));
          configuredKeys.push('CRON_SECRET');
        }
        if (payload.vercelBypassToken) {
          props.setProperty('VERCEL_BYPASS_TOKEN', String(payload.vercelBypassToken));
          configuredKeys.push('VERCEL_BYPASS_TOKEN');
        }
        let pulseClientSecret = '';
        if (typeof getOrCreatePulseClientSecret_ === 'function') {
          pulseClientSecret = getOrCreatePulseClientSecret_();
          if (pulseClientSecret) configuredKeys.push('PULSE_CLIENT_SECRET');
        }
        return respond({
          success: true,
          message: 'Successfully synchronized ScriptProperties secrets.',
          configuredKeys: configuredKeys,
          hasPulseClientSecret: Boolean(pulseClientSecret)
        });
      } catch (err) {
        console.error("doPost sync_script_secrets error: " + err.message);
        return respond({ success: false, error: 'Sync script secrets failed.' });
      }
    }

    // 1b. ACTION HANDLERS (pull_pl, push_outgoings)
    if (payload.action === 'pull_pl') {
      try {
        (await PullPLBasedOn(true));
        return respond({ success: true, message: 'Successfully updated P&L data.' });
      } catch (err) {
        console.error("doPost pull_pl error: " + err.message);
        return respond({ success: false, error: 'Pull P&L failed.' });
      }
    }

    if (payload.action === 'run_revenue_comparison') {
      try {
        const res = (await runRevenueComparison(true, payload.targetMonth));
        return respond({
          success: true,
          message: 'Successfully completed revenue comparison.',
          targetMonth: res ? res.targetMonth : null,
          targetMonthLabel: res ? res.targetMonthLabel : null,
          dashboardTotal: res ? res.dashboardTotal : 0,
          accountingTotal: res ? res.accountingTotal : 0,
          variance: res ? res.variance : 0
        });
      } catch (err) {
        console.error("doPost run_revenue_comparison error: " + err.message);
        return respond({ success: false, error: 'Revenue comparison failed: ' + err.message });
      }
    }

    if (payload.action === 'refresh_chart_of_accounts') {
      try {
        (await refreshAccountingToolChartOfAccounts(true));
        return respond({ success: true, message: 'Successfully refreshed Chart of Accounts.' });
      } catch (err) {
        console.error("doPost refresh_chart_of_accounts error: " + err.message);
        return respond({ success: false, error: 'Refresh Chart of Accounts failed.' });
      }
    }

    if (payload.action === 'push_outgoings' || payload.action === 'push_outgoings_with_pl_adds' || payload.action === 'pushOutgoingsWithPLAddsToClientSheet') {
      try {
        const withAdds = payload.action === 'push_outgoings_with_pl_adds' || payload.action === 'pushOutgoingsWithPLAddsToClientSheet' || payload.includeUnreconciled === true;
        const res = withAdds
          ? (await pushOutgoingsWithPLAddsToClientSheet(true))
          : (await pushOutgoingsToClientSheet(true));
        return respond({
          success: true,
          message: res?.message || (withAdds ? 'Successfully pushed outgoings (with unreconciled items) to client sheet.' : 'Successfully pushed outgoings to client sheet.'),
          warnings: res?.warnings || []
        });
      } catch (err) {
        console.error("doPost push_outgoings error: " + err.message);
        return respond({ success: false, error: 'Push outgoings failed.' });
      }
    }

    if (payload.action === 'sync_expense_breakdown') {
      try {
        const res = (await syncExpenseTransactionBreakdownToClientSheet_(true));
        return respond({
          success: true,
          message: 'Successfully synced expense breakdown and Outgoings.',
          updated: res?.updated || 0,
          skipped: res?.skipped || 0
        });
      } catch (err) {
        console.error("doPost sync_expense_breakdown error: " + err.message);
        return respond({ success: false, error: 'Sync expense breakdown failed.' });
      }
    }

    if (payload.action === 'process_part_paid_invoices') {
      try {
        const ss = SpreadsheetApp.getActiveSpreadsheet();
        const alertSheet = ss.getSheetByName("DataChgAlert");
        const res = (await processPartPaidInvoices(ss, alertSheet));
        return respond({
          success: true,
          message: `Processed part-paid invoices: ${res?.count || 0} update(s).`,
          count: res?.count || 0,
          logs: res?.logs || []
        });
      } catch (err) {
        console.error("doPost process_part_paid_invoices error: " + err.message);
        return respond({ success: false, error: 'Process part-paid invoices failed.' });
      }
    }

    if (payload.action === 'process_part_paid_expenses') {
      try {
        const ss = SpreadsheetApp.getActiveSpreadsheet();
        const alertSheet = ss.getSheetByName("DataChgAlert");
        const res = (await processPartPaidExpenses(ss, alertSheet));
        return respond({
          success: true,
          message: `Processed part-paid expenses: ${res?.count || 0} update(s).`,
          count: res?.count || 0,
          logs: res?.logs || []
        });
      } catch (err) {
        console.error("doPost process_part_paid_expenses error: " + err.message);
        return respond({ success: false, error: 'Process part-paid expenses failed.' });
      }
    }

    // 2. VALIDATE requested types
    const validTypes = ["invoice", "crm", "expense"];
    const requestedTypes = Array.isArray(payload.types) ? payload.types : (payload.type ? [payload.type] : []);
    const types = requestedTypes.filter(t => validTypes.includes(t));
    if (types.length === 0) {
      return respond({ success: false, error: "No valid types requested — expected one or more of: invoice, crm, expense" });
    }

    // 2b. STORE RUN INFO — so that whenever the automation actually executes
    // (via the trigger scheduled below, possibly a couple of minutes from
    // now), it knows which run to report progress against. Optional: if not
    // provided, progress reporting is simply skipped later — postAgentProgress_
    // no-ops without these.
    if (payload.runId)     props.setProperty('CURRENT_RUN_ID', String(payload.runId));
    if (payload.clientName) props.setProperty('CURRENT_RUN_CLIENT', String(payload.clientName));

    // 3. WRITE SIGNALS — the same cells onInteractiveEdit already writes
    // from the Automation Commander checkbox flow.
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const signalSheet = ss.getSheetByName("DataChgAlert");
    if (!signalSheet) {
      return respond({ success: false, error: "'DataChgAlert' tab missing" });
    }
    const cellByType = { invoice: "Z2", crm: "Z3", expense: "Z4" };
    const now = new Date();
    types.forEach(t => signalSheet.getRange(cellByType[t]).setValue(now));
    (await SpreadsheetApp.flush());

    // 4. ON-DEMAND EXECUTION
    // Rather than queuing into Google's 1-5 min time-based trigger queue,
    // execute requested sequences directly and synchronously in this Web App execution.
    // Update script properties so routine triggers know these have been processed:
    if (types.includes("invoice")) props.setProperty('LAST_SIG_TIMESTAMP_INV', now.getTime().toString());
    if (types.includes("crm"))     props.setProperty('LAST_SIG_TIMESTAMP_CRM', now.getTime().toString());
    if (types.includes("expense")) props.setProperty('LAST_SIG_TIMESTAMP_EXP', now.getTime().toString());

    (await postAgentProgress_("init", "Starting automation run for [" + types.join(", ") + "]...", false));

    (await runAgencyAutomator(types.includes("invoice"), types.includes("crm"), types.includes("expense")));

    (await postAgentProgress_("done", "All requested sequences complete.", true));

    console.log(`doPost: Direct run completed for [${types.join(", ")}].`);
    return respond({ success: true, triggered: types, runId: payload.runId || null, executedAt: now.toISOString() });

  } catch (err) {
    console.error("doPost error: " + (err && err.stack ? err.stack : err.message));
    return respond({ success: false, error: "Internal agent receiver error." });
  }
}


/**
 * ----------------------------------------------------------------
 * Reports run progress back to the Pulse triage app, so the UI can show
 * live status instead of just "triggered, check back later".
 *
 * Best-effort only: wrapped so ANY failure here — network error, wrong
 * config, Vercel unreachable — is swallowed and logged, never thrown.
 * This must never be able to interrupt the actual automation run.
 *
 * Reads the current run's ID/client from Script Properties, set by doPost
 * when the run was triggered. If neither is set — e.g. this execution came
 * from the normal 30-min poll, or a manual click inside the Apps Script
 * editor, rather than the triage app — this is a silent no-op, since
 * there's no run for anyone to be watching.
 *
 * Same Vercel deployment/bypass token already used by triagePrecompute.gs's
 * callVercel_ for store_precomputed — this is a separate script project
 * (bound per-client, not central), so it needs its own copy of these
 * rather than being able to call that helper directly.
 * ----------------------------------------------------------------
 */
function getPulseInternalSecret_() {
  try {
    const fromProps = PropertiesService.getScriptProperties().getProperty('PULSE_INTERNAL_SECRET');
    if (fromProps && String(fromProps).trim()) return String(fromProps).trim();
  } catch (e) {}
  return "";
}

var AGENT_PROGRESS_CONFIG = {
  vercelUrl: "https://app.pulsedashboard.co.uk"
};

async function postAgentProgress_(stage, message, done) {
  try {
    const props = PropertiesService.getScriptProperties();
    const runId = props.getProperty('CURRENT_RUN_ID');
    const clientName = props.getProperty('CURRENT_RUN_CLIENT');
    if (!runId || !clientName) return; // no active triage-app-triggered run to report to

    const secret = props.getProperty('AGENT_TRIGGER_SECRET') || props.getProperty('CRON_SECRET') || "";
    const bypassToken = props.getProperty('VERCEL_BYPASS_TOKEN') || "";
    const payload = {
      action: "agent_progress", secret: secret,
      clientName: clientName, runId: runId,
      stage: stage, message: message, done: !!done,
    };
    const payloadJson = JSON.stringify(payload);
    const fetchOpts = {
      method: "post",
      contentType: "application/json",
      headers: bypassToken ? { "x-vercel-protection-bypass": bypassToken } : {},
      payload: payloadJson,
      muteHttpExceptions: true,
      followRedirects: false,
    };

    var response = (await UrlFetchApp.fetch(AGENT_PROGRESS_CONFIG.vercelUrl + "/api/triage", fetchOpts));
    var code = response.getResponseCode();
    if (code === 301 || code === 302 || code === 307 || code === 308) {
      var location = response.getHeaders()["Location"] || response.getHeaders()["location"];
      if (location) {
        if (location.indexOf("http") !== 0) location = AGENT_PROGRESS_CONFIG.vercelUrl + location;
        (await UrlFetchApp.fetch(location, fetchOpts));
      }
    }

    // Once completion is reported, clear the run so a later, unrelated
    // execution (the normal 30-min poll, or a manual run) doesn't
    // silently inherit and report against a stale run ID.
    if (done) {
      props.deleteProperty('CURRENT_RUN_ID');
      props.deleteProperty('CURRENT_RUN_CLIENT');
    }
  } catch (e) {
    console.log("postAgentProgress_ failed (non-fatal): " + e.message);
  }
}

/**
 * Helper to dynamically discover key column indices from DataFromCRM headers.
 */
function getCrmColumnIndices_(headers) {
  const normHeaders = (headers || []).map(h => String(h || "").trim());
  
  // ID column
  let idIdx = normHeaders.findIndex(h => /^(?:system\s*id(?:\s*\(do\s*not\s*edit\))?|opportunity\s*id|deal\s*id|task\s*id|id)$/i.test(h));
  if (idIdx === -1) idIdx = normHeaders.findIndex(h => /id$/i.test(h));
  if (idIdx === -1) idIdx = 0;

  // Client Name column
  let clientIdx = normHeaders.findIndex(h => /^(?:client(?:\s*name)?|lead\s*name|organization|organisation|client\s*\(party\)|company|customer)$/i.test(h));
  if (clientIdx === -1) clientIdx = normHeaders.findIndex(h => /(?:client|lead|org|party|company)/i.test(h));

  // Job Name column (exclude client, user, owner)
  let jobIdx = normHeaders.findIndex((h, i) => i !== clientIdx && !/^(?:user\s*name|owner|assignees?|client|lead|org)/i.test(h) && /^(?:job(?:\s*name)?|opportunity(?:\s*name)?|deal(?:\s*name)?|task(?:\s*name)?|title)$/i.test(h));
  if (jobIdx === -1) {
    jobIdx = normHeaders.findIndex((h, i) => i !== clientIdx && !/^(?:user|owner|assignees?|client|lead)/i.test(h) && /^name$/i.test(h));
  }
  if (jobIdx === -1) {
    jobIdx = normHeaders.findIndex((h, i) => i !== clientIdx && !/^(?:user|owner|assignees?|client|lead)/i.test(h) && /(?:job|deal|task|title)/i.test(h));
  }

  // Value / Revenue column
  let valueIdx = normHeaders.findIndex(h => /^(?:value|amount|revenue|total)$/i.test(h));
  if (valueIdx === -1) valueIdx = normHeaders.findIndex(h => /(?:value|amount|revenue)/i.test(h));

  // Status column
  let statusIdx = normHeaders.findIndex(h => /^(?:status|stage|milestone)$/i.test(h));
  if (statusIdx === -1) statusIdx = normHeaders.findIndex(h => /(?:status|stage|milestone)/i.test(h));

  return { idIdx, clientIdx, jobIdx, valueIdx, statusIdx };
}

/**
 * Helper to format an entirely new CRM opportunity log line from DataFromCRM.
 */
function formatNewCrmLogEntry_(row, headers, colIndices, timeZone) {
  const id = String(row[colIndices.idIdx] || 'N/A').trim();
  const client = (colIndices.clientIdx !== -1 && row[colIndices.clientIdx]) ? String(row[colIndices.clientIdx]).trim() : '';
  const job = (colIndices.jobIdx !== -1 && row[colIndices.jobIdx]) ? String(row[colIndices.jobIdx]).trim() : '';
  let title = '';
  if (client && job) title = `${client} | ${job}`;
  else title = client || job || 'New Opportunity';

  const parts = [];
  if (colIndices.valueIdx !== -1 && row[colIndices.valueIdx] !== undefined && row[colIndices.valueIdx] !== null && String(row[colIndices.valueIdx]).trim() !== '') {
    const val = (typeof formatLogAmount_ === 'function') ? formatLogAmount_(row[colIndices.valueIdx]) : String(row[colIndices.valueIdx]).trim();
    parts.push(`Value: £${val}`);
  }
  if (colIndices.statusIdx !== -1 && row[colIndices.statusIdx] !== undefined && row[colIndices.statusIdx] !== null && String(row[colIndices.statusIdx]).trim() !== '') {
    parts.push(`Status: ${String(row[colIndices.statusIdx]).trim()}`);
  }

  return `[ID: ${id}] ${title}${parts.length > 0 ? ' - ' + parts.join(', ') : ''}`;
}

/**
 * Helper to detect and format field-level changes for an updated CRM opportunity.
 */
function getCrmFieldChanges_(oldRow, newRow, headers, colIndices, timeZone) {
  const changes = [];
  const maxCols = Math.max(oldRow.length, newRow.length, (headers || []).length);
  const IGNORE_HEADERS = [
    "updated date", "updated time", "updated at", "date updated", "last modified", "update time",
    "system id (do not edit)", "opportunity id", "deal id", "task id", "id"
  ];

  for (let c = 0; c < maxCols; c++) {
    if (c === colIndices.idIdx) continue; // Skip ID column
    const headerName = String((headers && headers[c]) || `Col ${c}`).trim();
    if (IGNORE_HEADERS.includes(headerName.toLowerCase())) continue; // Skip internal timestamps

    const oldVal = oldRow[c];
    const newVal = newRow[c];

    // Date columns: header contains date, time, close, won, created, start, due
    if (/(?:date|time|close|won|created|start|due)/i.test(headerName)) {
      const oldYmd = (typeof normalizeDateToYmd_ === 'function') ? normalizeDateToYmd_(oldVal, timeZone) : "";
      const newYmd = (typeof normalizeDateToYmd_ === 'function') ? normalizeDateToYmd_(newVal, timeZone) : "";
      if (oldYmd && newYmd && oldYmd === newYmd) continue;
      const oldFormatted = (typeof formatLogDate_ === 'function') ? (formatLogDate_(oldVal, timeZone) || (oldVal ? String(oldVal).trim() : 'Blank')) : String(oldVal);
      const newFormatted = (typeof formatLogDate_ === 'function') ? (formatLogDate_(newVal, timeZone) || (newVal ? String(newVal).trim() : 'Blank')) : String(newVal);
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
      continue;
    }

    // Amount / Value columns: header contains value, amount, revenue, cost
    if (/(?:value|amount|revenue|cost)/i.test(headerName)) {
      const n1 = (oldVal === null || oldVal === undefined || oldVal === '') ? 0 : Number(String(oldVal).replace(/[^0-9.-]/g, ''));
      const n2 = (newVal === null || newVal === undefined || newVal === '') ? 0 : Number(String(newVal).replace(/[^0-9.-]/g, ''));
      if (!isNaN(n1) && !isNaN(n2) && Math.abs(n1 - n2) < 0.005) continue;
      const oldFormatted = (typeof formatLogAmount_ === 'function') ? formatLogAmount_(oldVal) : String(oldVal);
      const newFormatted = (typeof formatLogAmount_ === 'function') ? formatLogAmount_(newVal) : String(newVal);
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
      continue;
    }

    // Likelihood / Probability columns
    if (/(?:confidence|likelihood|probability)/i.test(headerName)) {
      const oldFormatted = formatLogLikelihood_(oldVal);
      const newFormatted = formatLogLikelihood_(newVal);
      if (oldFormatted === newFormatted) continue;
      changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      continue;
    }

    // General text columns (Client, Job, Status, Stage, Pipeline, etc.)
    const isDiff = (typeof valuesAreDifferent === 'function') ? valuesAreDifferent(oldVal, newVal) : (oldVal !== newVal);
    if (isDiff) {
      const oldFormatted = (oldVal === null || oldVal === undefined || String(oldVal).trim() === '') ? 'Blank' : String(oldVal).trim();
      const newFormatted = (newVal === null || newVal === undefined || String(newVal).trim() === '') ? 'Blank' : String(newVal).trim();
      if (oldFormatted !== newFormatted) {
        changes.push(`${headerName}: '${oldFormatted}' -> '${newFormatted}'`);
      }
    }
  }
  return changes;
}

/**
 * Helper to format likelihood percentages.
 */
function formatLogLikelihood_(val) {
  if (val === null || val === undefined || val === "") return "N/A";
  let s = String(val).trim();
  if (s.includes('%')) return s;
  const num = parseFloat(s);
  if (!isNaN(num)) {
    if (num <= 1 && num > 0) return `${Math.round(num * 100)}%`;
    return `${num}%`;
  }
  return s;
}

