// --- ACCOUNTING WRAPPERS ---

async function PullInvoicesBasedOn(isHeadless) {
  const toolName = (await getKeyInfoValue('Q4'));
  const funcName = _lookupFunctionName('Accounting', toolName, 'R14:V18', 1);
  return (await _executeDynamicFunction(funcName, isHeadless));
}

async function PullPLBasedOn(isHeadless) {
  const safeHeadless = (typeof isHeadless === 'object') || (isHeadless === true);
  try {
    if (typeof clearLastConnectorError === 'function') clearLastConnectorError();
    const toolName = (await getKeyInfoValue('Q4'));
    const funcName = _lookupFunctionName('Accounting', toolName, 'R14:V18', 2);
    (await _executeDynamicFunction(funcName, isHeadless));
    const connErr = (typeof getLastConnectorError === 'function') ? getLastConnectorError() : null;
    if (connErr && safeHeadless && typeof writeToAutoLog === 'function') {
      writeToAutoLog("SYSTEM", "Error: P&L Pull", "Error: P&L Pull - " + connErr);
    }
  } catch (e) {
    if (safeHeadless && typeof writeToAutoLog === 'function') {
      writeToAutoLog("SYSTEM", "Error: P&L Pull", "Error: P&L Pull - " + e.message);
    }
    throw e;
  }
}

