// --- ROUTING HELPERS ---

function _lookupFunctionName(category, toolName, rangeA1, returnColIndex) {
  if (!toolName || toolName === 'None' || toolName === '') {
    console.log(`Router: No ${category} tool selected. Skipping.`);
    Logger.log(`Router: No ${category} tool selected. Skipping.`);
    return null;
  }
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('KeyInfo');
  if (!sheet) throw new Error("KeyInfo sheet not found.");
  
  const data = sheet.getRange(rangeA1).getValues();
  const cleanTool = String(toolName).trim().toLowerCase();
  const row = data.find(r => String(r[0] || '').trim().toLowerCase() === cleanTool);
  
  if (!row) {
    console.log(`Router: Tool "${toolName}" not found in mapping table ${rangeA1}.`);
    Logger.log(`Router: Tool "${toolName}" not found in mapping table ${rangeA1}.`);
    return null;
  }
  return String(row[returnColIndex] || '').trim();
}

const ALLOWED_ROUTING_FUNCTIONS_ = {
  getXeroInvoices: () => (typeof getXeroInvoices === 'function' ? getXeroInvoices : null),
  getQuickbooksInvoices: () => (typeof getQuickbooksInvoices === 'function' ? getQuickbooksInvoices : null),
  getXeroProfitAndLossReport: () => (typeof getXeroProfitAndLossReport === 'function' ? getXeroProfitAndLossReport : null),
  getQuickBooksProfitAndLossReport: () => (typeof getQuickBooksProfitAndLossReport === 'function' ? getQuickBooksProfitAndLossReport : null),
  syncAccountingDataToSheet: () => (typeof syncAccountingDataToSheet === 'function' ? syncAccountingDataToSheet : null),
  getYear0PLfromXero: () => (typeof getYear0PLfromXero === 'function' ? getYear0PLfromXero : null),
  getYear0PLfromQB: () => (typeof getYear0PLfromQB === 'function' ? getYear0PLfromQB : null),
  PullFromGoogleSheet_: () => (typeof PullFromGoogleSheet_ === 'function' ? PullFromGoogleSheet_ : null),
  PullFromExcelSheet_: () => (typeof PullFromExcelSheet_ === 'function' ? PullFromExcelSheet_ : null),
  exportMondayBoardToSheet: () => (typeof exportMondayBoardToSheet === 'function' ? exportMondayBoardToSheet : null),
  exportClickUpListToSheet: () => (typeof exportClickUpListToSheet === 'function' ? exportClickUpListToSheet : null),
  exportCloseOpportunitiesToSheet: () => (typeof exportCloseOpportunitiesToSheet === 'function' ? exportCloseOpportunitiesToSheet : null),
  exportCapsuleOpportunitiesToSheet: () => (typeof exportCapsuleOpportunitiesToSheet === 'function' ? exportCapsuleOpportunitiesToSheet : null),
  exportHubSpotDealsToSheet: () => (typeof exportHubSpotDealsToSheet === 'function' ? exportHubSpotDealsToSheet : null),
  exportPipeDriveDealsToSheet: () => (typeof exportPipeDriveDealsToSheet === 'function' ? exportPipeDriveDealsToSheet : null)
};

async function _executeDynamicFunction(funcName, isHeadless) {
  if (!funcName) {
    console.warn("Router: No funcName provided to _executeDynamicFunction.");
    return null;
  }
  const cleanFuncName = String(funcName).trim().replace(/\(\s*\)$/, '');
  console.log(`Router: Executing "${cleanFuncName}"...`);
  Logger.log(`Router: Executing "${cleanFuncName}"...`);
  
  // CRITICAL FIX: Sanitize isHeadless. 
  const safeHeadless = (typeof isHeadless === 'object') || (isHeadless === true);

  let fn = null;
  if (Object.prototype.hasOwnProperty.call(ALLOWED_ROUTING_FUNCTIONS_, cleanFuncName)) {
    fn = ALLOWED_ROUTING_FUNCTIONS_[cleanFuncName]();
  } else {
    console.error(`Router Error: Function "${cleanFuncName}" is not in ALLOWED_ROUTING_FUNCTIONS_.`);
    logOrAlert(`Router Error: Function "${cleanFuncName}" is not an authorized routing target.`, safeHeadless);
    return null;
  }

  if (fn) {
    try {
      const result = (await fn(safeHeadless)); 
      console.log(`Router: "${cleanFuncName}" completed. Returned:`, result ? Object.keys(result) : typeof result);
      return result; 
    } catch (e) {
      console.error(`Router Error: "${cleanFuncName}" failed: ${e.message}`);
      Logger.log(`Router Error: "${cleanFuncName}" failed. ${e.message}`);
      throw e; 
    }
  } else {
    console.error(`Router Error: Function "${cleanFuncName}" not found on globalThis, this, or via scope lookup. Check KeyInfo table spelling.`);
    logOrAlert(`Router Error: Function "${cleanFuncName}" not found in script. Check KeyInfo table spelling.`, safeHeadless);
    return null;
  }
}

/**
 * Fetches data from a client's Google Sheet (read-only), reconciles row identities
 * via an internal CRMGoogleBridge sheet, and pushes deltas to 'DataFromCRM'.
 * The client's remote spreadsheet is never modified.
 */
async function PullFromGoogleSheet_(isHeadless) {
  try {
    logOrAlert("Starting Google Sheet 'CRM' sync...", isHeadless);

    // 1. Get configuration from KeyInfo (X11: URL, X12: Tab, X13: Key Headers, X14: Header Row)
    let url = (await getKeyInfoValue('X11'));
    let tabName = (await getKeyInfoValue('X12'));
    const matchColsStr = (await getKeyInfoValue('X13'));
    let headerRowNum = parseInt((await getKeyInfoValue('X14'))) || 1;

    // Backwards-compatibility fallback if X11 is empty but legacy X14 has URL
    if (!url && (await getKeyInfoValue('X14')) && String((await getKeyInfoValue('X14'))).includes('http')) {
      url = (await getKeyInfoValue('X14'));
      tabName = (await getKeyInfoValue('X15'));
      headerRowNum = 1;
    }

    if (!url || !tabName) {
      throw new Error("Missing URL (X11) or Tab Name (X12) in KeyInfo for Google Sheet sync.");
    }

    // 2. Fetch raw data from remote client sheet (REST API with OAuth token or native openByUrl)
    let rawData = null;
    const token = (await getBrokerGoogleSheetAccessToken_());
    const sheetIdMatch = String(url).match(/\/d\/([a-zA-Z0-9-_]+)/);
    const targetSheetId = sheetIdMatch ? sheetIdMatch[1] : (/^[a-zA-Z0-9-_]{20,}$/.test(String(url).trim()) ? String(url).trim() : null);

    if (token && targetSheetId) {
      try {
        console.log("Fetching Google Sheet data via Google Sheets REST API with OAuth token...");
        const apiUrl = `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(targetSheetId)}/values/${encodeURIComponent(tabName)}?valueRenderOption=FORMATTED_VALUE`;
        const res = (await UrlFetchApp.fetch(apiUrl, {
          headers: { 'Authorization': `Bearer ${token}` },
          muteHttpExceptions: true
        }));
        if (res.getResponseCode() === 200) {
          const json = JSON.parse(res.getContentText());
          rawData = json.values || [];
        } else {
          console.warn(`Token Broker Google Sheets API returned HTTP ${res.getResponseCode()}: ${res.getContentText()}. Falling back to native open.`);
        }
      } catch (apiErr) {
        console.warn(`REST API fetch failed: ${apiErr.message}. Falling back to native open.`);
      }
    } else if (!token) {
      console.warn("No active OAuth token returned from Token Broker for Google Sheets. Attempting native open...");
    }

    if (!rawData) {
      try {
        const remoteSs = (await SpreadsheetApp.openByUrl(url));
        const remoteSheet = remoteSs.getSheetByName(tabName);
        if (!remoteSheet) {
          throw new Error(`Tab "${tabName}" not found in the target Google Sheet.`);
        }
        rawData = remoteSheet.getDataRange().getValues();
      } catch (nativeErr) {
        if (!token) {
          throw new Error("Missing Google Sheets authorization. Please connect Google Sheet via PMA Integrations (or ensure sheet is shared). Details: " + nativeErr.message);
        }
        throw nativeErr;
      }
    }

    if (!rawData || rawData.length === 0) {
      logOrAlert("The target Google Sheet is empty.", isHeadless);
      return;
    }

    const localSs = SpreadsheetApp.getActiveSpreadsheet();
    const scriptTimeZone = localSs.getSpreadsheetTimeZone();

    // 3. Rectangularize & normalize date formats
    const maxCols = Math.max(...rawData.map(r => r.length));
    const normalizedData = rawData.map(r => {
      const row = [...r];
      while (row.length < maxCols) row.push("");
      return row.map(cell => {
        if (Object.prototype.toString.call(cell) === '[object Date]') {
          return Utilities.formatDate(cell, scriptTimeZone, "d-MMM-yy");
        }
        if (typeof cell === 'string' && cell.includes('GMT') && cell.match(/^[A-Z][a-z]{2} [A-Z][a-z]{2} \d{2}/)) {
          const parsed = new Date(cell);
          if (!isNaN(parsed.getTime())) return Utilities.formatDate(parsed, scriptTimeZone, "d-MMM-yy");
        }
        return cell;
      });
    });

    // 4. Extract Headers and Rows based on Header Row Number (X14)
    const headerIdx = Math.max(0, headerRowNum - 1);
    if (headerIdx >= normalizedData.length) throw new Error("Header Row Number (X14) is out of bounds.");

    const rawHeaders = normalizedData[headerIdx];
    const googleRows = normalizedData.slice(headerIdx + 1).filter(r => r.join('').trim() !== '');

    // 5. Ensure UUID column exists in local data array
    let uuidColIdx = rawHeaders.findIndex(h => String(h).trim() === 'System ID (Do Not Edit)');
    if (uuidColIdx === -1) {
      uuidColIdx = rawHeaders.length;
      rawHeaders.push('System ID (Do Not Edit)');
      googleRows.forEach(r => r.push(''));
    } else {
      googleRows.forEach(r => { while (r.length <= uuidColIdx) r.push(''); });
    }

    // 6. Map Key Column Indices for Reconciliations
    const normHead = (h) => String(h || "").toLowerCase().replace(/[^a-z0-9]/g, '');
    let idxClient = -1, idxJob = -1, idxRev = -1, idxStart = -1, idxEnd = -1, idxLike = -1;

    if (matchColsStr && String(matchColsStr).trim() !== '') {
      const matchColNames = matchColsStr.split(',').map(s => s.trim());
      const keyIndices = matchColNames.map(name => {
        if (!name || name.toLowerCase() === 'none' || name.toLowerCase() === 'n/a') return -1;
        const cleanName = normHead(name);
        return rawHeaders.findIndex(h => normHead(h) === cleanName);
      });
      [idxClient, idxJob, idxRev, idxStart, idxEnd, idxLike] = keyIndices;
    }

    // Fallback heuristic keyword detection if columns were unmapped
    if (idxClient === -1) idxClient = rawHeaders.findIndex(h => /^(?:client|lead|org|company|customer)/i.test(normHead(h)));
    if (idxJob === -1) idxJob = rawHeaders.findIndex((h, i) => i !== idxClient && /^(?:job|deal|opportunity|task|title|name|nature)/i.test(normHead(h)));
    if (idxRev === -1) idxRev = rawHeaders.findIndex(h => /^(?:value|amount|revenue|total|deal|fee)/i.test(normHead(h)));
    if (idxStart === -1) idxStart = rawHeaders.findIndex(h => /^(?:start|month|target|live|date)/i.test(normHead(h)));
    if (idxEnd === -1) idxEnd = rawHeaders.findIndex((h, i) => i !== idxStart && /^(?:end|close|completion)/i.test(normHead(h)));
    if (idxLike === -1) idxLike = rawHeaders.findIndex(h => /^(?:status|stage|milestone|prob|likelihood)/i.test(normHead(h)));

    if (idxClient === -1) idxClient = 0;
    if (idxJob === -1) idxJob = Math.min(1, rawHeaders.length - 1);

    // Fuzzy matching helper
    const areFuzzyEqual = (val1, val2) => {
      const s1 = String(val1 || "").toLowerCase().replace(/[^a-z0-9]/g, '');
      const s2 = String(val2 || "").toLowerCase().replace(/[^a-z0-9]/g, '');
      return s1 === s2;
    };

    // 7. Process CRMGoogleBridge Reconciliations (Maintains persistent UUIDs without touching client sheet)
    let bridgeSheet = localSs.getSheetByName('CRMGoogleBridge');
    if (!bridgeSheet) {
      bridgeSheet = localSs.insertSheet('CRMGoogleBridge');
    }
    const bridgeData = bridgeSheet.getDataRange().getValues();
    const bridgeHeaders = bridgeData.length > 0 ? bridgeData[0] : [];
    let bridgeRows = [];

    const isBridgeHeadersMatch = JSON.stringify(rawHeaders) === JSON.stringify(bridgeHeaders);
    let bridgeUuidIdx = bridgeHeaders.findIndex(h => String(h).trim() === 'System ID (Do Not Edit)');

    if (bridgeData.length <= 1 || bridgeUuidIdx === -1 || !isBridgeHeadersMatch) {
      console.log("Triggering CRMGoogleBridge full initialization.");
      bridgeRows = googleRows.map(r => {
        if (!r[uuidColIdx] || String(r[uuidColIdx]).trim() === '') {
          r[uuidColIdx] = Utilities.getUuid();
        }
        return r;
      });
    } else {
      console.log("Triggering CRMGoogleBridge weighted matching engine.");
      const oldBridgeRows = bridgeData.slice(1);
      const fuzzyName = (str) => String(str || "").toLowerCase().replace(/[^a-z0-9]/g, '').replace(/(ltd|limited|inc|llc|corp|company)$/g, '');
      const scoredPairs = [];

      googleRows.forEach((gRow, gIdx) => {
        // If row already has a preserved UUID (e.g. from existing column), reuse it
        if (gRow[uuidColIdx] && String(gRow[uuidColIdx]).trim() !== '') return;

        const gClient = String(gRow[idxClient] || "").trim();
        const gJob = String(gRow[idxJob] || "").trim();
        const gFuzzClient = fuzzyName(gClient);
        const gFuzzJob = fuzzyName(gJob);
        const gBaseKey = gFuzzClient + "|||" + gFuzzJob;

        oldBridgeRows.forEach((bRow, bIdx) => {
          const bClient = String(bRow[idxClient] || "").trim();
          const bJob = String(bRow[idxJob] || "").trim();
          const bFuzzClient = fuzzyName(bClient);
          const bFuzzJob = fuzzyName(bJob);
          const bBaseKey = bFuzzClient + "|||" + bFuzzJob;

          let score = 0;
          let clientMatched = false;

          if (gClient.toLowerCase() === bClient.toLowerCase() && gJob.toLowerCase() === bJob.toLowerCase()) {
            score += 5;
            clientMatched = true;
          } else if (gBaseKey === bBaseKey) {
            score += 3;
            clientMatched = true;
          } else if (gFuzzClient === bFuzzClient) {
            score += 1;
            clientMatched = true;
          }

          if (idxRev !== -1 && areFuzzyEqual(gRow[idxRev], bRow[idxRev])) score += 3;
          if (idxStart !== -1 && areFuzzyEqual(gRow[idxStart], bRow[idxStart])) score += 2;
          if (idxEnd !== -1 && areFuzzyEqual(gRow[idxEnd], bRow[idxEnd])) score += 1;
          if (idxLike !== -1 && areFuzzyEqual(gRow[idxLike], bRow[idxLike])) score += 1;

          if (score >= 2) {
            scoredPairs.push({ gIdx, bIdx, score, clientMatched });
          }
        });
      });

      scoredPairs.sort((a, b) => b.score - a.score);
      const matchedGoogleIndices = new Set();
      const matchedBridgeIndices = new Set();

      scoredPairs.forEach(pair => {
        if (pair.score >= 4 && !matchedGoogleIndices.has(pair.gIdx) && !matchedBridgeIndices.has(pair.bIdx)) {
          matchedGoogleIndices.add(pair.gIdx);
          matchedBridgeIndices.add(pair.bIdx);
          const gRow = googleRows[pair.gIdx];
          gRow[uuidColIdx] = oldBridgeRows[pair.bIdx][bridgeUuidIdx];
          bridgeRows.push(gRow);
        }
      });

      scoredPairs.forEach(pair => {
        if (pair.clientMatched && pair.score >= 2 && !matchedGoogleIndices.has(pair.gIdx) && !matchedBridgeIndices.has(pair.bIdx)) {
          matchedGoogleIndices.add(pair.gIdx);
          matchedBridgeIndices.add(pair.bIdx);
          const gRow = googleRows[pair.gIdx];
          gRow[uuidColIdx] = oldBridgeRows[pair.bIdx][bridgeUuidIdx];
          bridgeRows.push(gRow);
        }
      });

      googleRows.forEach((gRow, gIdx) => {
        if (!matchedGoogleIndices.has(gIdx)) {
          if (!gRow[uuidColIdx] || String(gRow[uuidColIdx]).trim() === '') {
            gRow[uuidColIdx] = Utilities.getUuid();
          }
          bridgeRows.push(gRow);
        }
      });
    }

    // Sanitize formula-leading strings in headers and rows
    const safeRawHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([rawHeaders])[0] : rawHeaders;
    const safeBridgeRows = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(bridgeRows) : bridgeRows;

    // Write to CRMGoogleBridge Sheet
    bridgeSheet.clear();
    bridgeSheet.getRange(1, 1, 1, safeRawHeaders.length).setValues([safeRawHeaders]).setFontWeight('bold');
    if (safeBridgeRows.length > 0) {
      bridgeSheet.getRange(2, uuidColIdx + 1, safeBridgeRows.length, 1).setNumberFormat("@");
      bridgeSheet.getRange(2, 1, safeBridgeRows.length, safeRawHeaders.length).setValues(safeBridgeRows);
    }

    // 7. Push all data to 'DataFromCRM' tab using the Delta Engine
    const destSheet = localSs.getSheetByName('DataFromCRM');
    if (!destSheet) throw new Error("DataFromCRM tab is missing in your system.");

    const incomingHeaders = safeRawHeaders;
    const incomingRows = safeBridgeRows;

    const lastRow = destSheet.getLastRow();
    const oldHeaders = lastRow > 0 ? destSheet.getRange(1, 1, 1, destSheet.getLastColumn()).getValues()[0] : [];
    const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(incomingHeaders);

    if (!headersMatch || lastRow <= 1) {
      destSheet.clear();
      destSheet.getRange(1, 1, 1, incomingHeaders.length).setValues([incomingHeaders]).setFontWeight('bold');
      if (incomingRows.length > 0) {
        destSheet.getRange(2, uuidColIdx + 1, incomingRows.length, 1).setNumberFormat("@");
        destSheet.getRange(2, 1, incomingRows.length, incomingHeaders.length).setValues(incomingRows);
      }
      logOrAlert(`Initialization complete. Fetched ${incomingRows.length} rows into DataFromCRM.`, isHeadless);
      _updateTimestamp("CRMComp", "J2");
      return;
    }

    // Delta update engine
    const oldDataRange = destSheet.getRange(2, 1, lastRow - 1, destSheet.getLastColumn());
    const oldData = oldDataRange.getValues();
    const incomingMap = new Map();
    incomingRows.forEach(row => incomingMap.set(String(row[uuidColIdx]), row));

    const rowsToDelete = [];
    const valueUpdates = [];
    let dataChanged = false;

    for (let i = 0; i < oldData.length; i++) {
      const rowId = String(oldData[i][uuidColIdx]);
      const sheetRowNum = i + 2;

      if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
      }

      if (!incomingMap.has(rowId)) {
        rowsToDelete.push(sheetRowNum);
        dataChanged = true;
      } else {
        const newData = incomingMap.get(rowId);
        if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
          valueUpdates.push({ range: `DataFromCRM!A${sheetRowNum}`, values: [newData] });
          dataChanged = true;
        }
        incomingMap.delete(rowId);
      }
    }

    const rowsToAppend = Array.from(incomingMap.values());
    if (rowsToAppend.length > 0) dataChanged = true;

    if (!dataChanged) {
      logOrAlert("No changes detected in Google Sheet CRM sync. Sheet is up to date.", isHeadless);
      _updateTimestamp("CRMComp", "J2");
      return;
    }

    while (rowsToAppend.length > 0) {
      const newRowData = rowsToAppend.shift();
      if (rowsToDelete.length > 0) {
        const recycleRow = rowsToDelete.shift();
        valueUpdates.push({ range: `DataFromCRM!A${recycleRow}`, values: [newRowData] });
      } else {
        const startRow = destSheet.getLastRow() + 1;
        destSheet.getRange(startRow, uuidColIdx + 1, 1, 1).setNumberFormat("@");
        destSheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
      }
    }

    if (rowsToDelete.length > 0) {
      const clearRanges = rowsToDelete.map(rowNum => `DataFromCRM!A${rowNum}:ZZ${rowNum}`);
      destSheet.getRangeList(clearRanges).clearContent();
    }

    if (valueUpdates.length > 0) {
      (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, localSs.getId()));
    }

    _updateTimestamp("CRMComp", "J2");
    logOrAlert("✅ Success! Google Sheet Sync Delta Update Complete.", isHeadless);
  } catch (error) {
    logOrAlert(`Google Sheet Sync Error: ${error.message}`, isHeadless);
    throw error;
  }
}

/**
 * Retrieves or initializes a unique, cryptographically strong client-specific secret
 * stored securely in the Master Sheet's private ScriptProperties.
 * Scoped strictly to this script project; never accessible via spreadsheet formulas.
 * 
 * @returns {string} The persistent client-specific secret
 */
function getOrCreatePulseClientSecret_() {
  try {
    const props = PropertiesService.getScriptProperties();
    let secret = props.getProperty('PULSE_CLIENT_SECRET');
    if (!secret) {
      secret = 'pcs_' + Utilities.getUuid().replace(/-/g, '') + Utilities.getUuid().replace(/-/g, '');
      props.setProperty('PULSE_CLIENT_SECRET', secret);
    }
    return secret;
  } catch (e) {
    return '';
  }
}

async function getBrokerGoogleSheetAccessToken_() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = (typeof getPulseBrokerBaseUrl_ === 'function')
      ? getPulseBrokerBaseUrl_()
      : "https://app.pulsedashboard.co.uk";
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=googlesheet&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': 'Bearer ' + (typeof getPulseInternalSecret_ === 'function' ? getPulseInternalSecret_() : (PropertiesService.getScriptProperties().getProperty('PULSE_INTERNAL_SECRET') || '')),
        'X-Pulse-Client-Secret': getOrCreatePulseClientSecret_(),
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const respCode = response.getResponseCode();
    if (respCode === 200) {
      const data = JSON.parse(response.getContentText());
      if (data && data.success && data.accessToken && !data.accessToken.startsWith("manual_")) {
        return data.accessToken;
      }
    } else {
      console.warn("Token Broker Google Sheet token request returned HTTP " + respCode + ": " + response.getContentText());
    }
  } catch (e) {
    console.warn("Token Broker Google Sheet token check note: " + e.message);
  }
  return null;
}

/**
 * Installs a weekly trigger to run the P&L sync between 2 AM and 3 AM 
 * on a randomized day of the week to prevent API quota stacking.
 */
function installRandomWeeklyPLTrigger() {
  const functionName = 'PullPLBasedOn';
  
  // 1. Remove any existing triggers for this function to prevent duplicates
  const triggers = ScriptApp.getProjectTriggers();
  triggers.forEach(trigger => {
    if (trigger.getHandlerFunction() === functionName) {
      ScriptApp.deleteTrigger(trigger);
    }
  });
  
  // 2. Select a random day of the week
  const days = [
    ScriptApp.WeekDay.SUNDAY,
    ScriptApp.WeekDay.MONDAY,
    ScriptApp.WeekDay.TUESDAY,
    ScriptApp.WeekDay.WEDNESDAY,
    ScriptApp.WeekDay.THURSDAY,
    ScriptApp.WeekDay.FRIDAY,
    ScriptApp.WeekDay.SATURDAY
  ];
  const randomDay = days[Math.floor(Math.random() * days.length)];
  
  // 3. Create the new randomized trigger
  ScriptApp.newTrigger(functionName)
    .timeBased()
    .onWeekDay(randomDay)
    .atHour(2) // Google interprets this as "Between 2:00 AM and 3:00 AM"
    .create();
    
  console.log(`Success: Randomized P&L Trigger installed. It will run every ${randomDay} between 2:00 AM and 3:00 AM.`);
  SpreadsheetApp.getUi().alert(`Trigger installed! The P&L will pull every ${randomDay} between 2:00 AM - 3:00 AM.`);
}


// ==========================================
// EXCEL CRM INTEGRATION
// ==========================================

/**
 * Fetches data from a Microsoft Excel file, synchronizes it via a Bridge sheet using 
 * a mandatory + threshold fuzzy matching engine, and pushes the delta to DataFromCRM.
 */
async function PullFromExcelSheet_() {
  try {
    console.log("Starting Microsoft Excel 'CRM' sync...");

    // 1. Get configurations from KeyInfo
    const driveId = (await getKeyInfoValue('X36'));
    const fileId = (await getKeyInfoValue('X37'));
    const sheetName = (await getKeyInfoValue('X38'));
    let headerRowNum = 1;
    try {
      headerRowNum = parseInt((await getKeyInfoValue('X40')), 10) || 1;
    } catch (_) {
      headerRowNum = 1;
    }
    const matchColsStr = (await getKeyInfoValue('X41'));

    if (!driveId || !fileId || !sheetName || !matchColsStr) {
      throw new Error("Missing Excel file configuration in KeyInfo (X36-X38, X41).");
    }

    // 2. Fetch data from Microsoft Graph API (Token Broker OAuth)
    console.log("Authenticating and fetching Excel data...");
    const token = (await getBrokerExcelAccessToken_());

    if (!token) {
      throw new Error("Missing Excel authorization. Please connect Microsoft Excel via PMA Integrations.");
    }

    const excelData = (await getExcelData_(token, driveId, fileId, sheetName));

    if (!excelData || excelData.length === 0) {
      console.log("The target Excel range is empty.");
      return;
    }

    const localSs = SpreadsheetApp.getActiveSpreadsheet();
    const scriptTimeZone = localSs.getSpreadsheetTimeZone();

    // 3. Write raw data to CRMExcelCopy
    let copySheet = localSs.getSheetByName('CRMExcelCopy');
    if (!copySheet) {
      copySheet = localSs.insertSheet('CRMExcelCopy');
    }
    copySheet.clear();
    const safeExcelData = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(excelData) : excelData;
    copySheet.getRange(1, 1, safeExcelData.length, safeExcelData[0].length).setValues(safeExcelData);

    // 4. Extract Headers and Rows based on Header Row Number
    const headerIdx = Math.max(0, headerRowNum - 1);
    if (headerIdx >= excelData.length) throw new Error("Header Row Number (X40) is out of bounds.");
    
    const rawHeaders = excelData[headerIdx];
    const excelRows = excelData.slice(headerIdx + 1).filter(r => r.join('').trim() !== '');

    // 5. Ensure UUID column exists
    let uuidColIdx = rawHeaders.findIndex(h => String(h).trim() === 'System ID (Do Not Edit)');
    if (uuidColIdx === -1) {
       uuidColIdx = rawHeaders.length;
       rawHeaders.push('System ID (Do Not Edit)');
       excelRows.forEach(r => r.push('')); // pad incoming rows
    } else {
       excelRows.forEach(r => { while(r.length <= uuidColIdx) r.push(''); });
    }

    // 6. Map Key Columns for Matching (Client and Job required; Value, Dates, Likelihood optional)
    const matchColNames = matchColsStr.split(',').map(s => s.trim());
    const [mClient, mJob, mRev, mStart, mEnd, mLike] = [
      matchColNames[0] || 'None',
      matchColNames[1] || 'None',
      matchColNames[2] || 'None',
      matchColNames[3] || 'None',
      matchColNames[4] || 'None',
      matchColNames[5] || 'None'
    ];

    const normHead = (h) => String(h||"").toLowerCase().replace(/[^a-z0-9]/g, '');
    const resolveIdx = (colName, headers) => {
      if (!colName || colName.toLowerCase() === 'none' || colName.toLowerCase() === '-- none / not in sheet --') return -1;
      const clean = normHead(colName);
      return headers.findIndex(h => normHead(h) === clean);
    };

    const idxClient = resolveIdx(mClient, rawHeaders);
    const idxJob = resolveIdx(mJob, rawHeaders);
    const idxRev = resolveIdx(mRev, rawHeaders);
    const idxStart = resolveIdx(mStart, rawHeaders);
    const idxEnd = resolveIdx(mEnd, rawHeaders);
    const idxLike = resolveIdx(mLike, rawHeaders);

    if (idxClient === -1 || idxJob === -1) {
      throw new Error(`Could not find required Client ('${mClient}') and Job ('${mJob}') columns in Excel headers.`);
    }

    // --- UPGRADED FUZZY MATCH HELPER ---
    const areFuzzyEqual = (val1, val2) => {
       // Handle Date alignment explicitly by coercing both to standard YYYY-MM-DD strings
       const toDateString = (v) => {
           if (v instanceof Date) return Utilities.formatDate(v, scriptTimeZone, "yyyy-MM-dd");
           if (typeof v === 'string') {
               // Clean up GMT strings to standard dates
               const d = new Date(v.replace(/GMT.*$/, '').trim());
               if (!isNaN(d.getTime())) return Utilities.formatDate(d, scriptTimeZone, "yyyy-MM-dd");
           }
           return null;
       };

       const d1 = toDateString(val1);
       const d2 = toDateString(val2);
       if (d1 && d2) return d1 === d2;

       // Fallback: Strip symbols, currency marks, commas, and spaces
       const s1 = String(val1||"").toLowerCase().replace(/[^a-z0-9]/g, '');
       const s2 = String(val2||"").toLowerCase().replace(/[^a-z0-9]/g, '');
       return s1 === s2;
    };

    // 7. Process CRMExcelBridge Reconciliations
    let bridgeSheet = localSs.getSheetByName('CRMExcelBridge');
    if (!bridgeSheet) {
      bridgeSheet = localSs.insertSheet('CRMExcelBridge');
    }
    const bridgeData = bridgeSheet.getDataRange().getValues();
    const bridgeHeaders = bridgeData.length > 0 ? bridgeData[0] : [];
    
    let bridgeRows = [];
    let newBridgeCount = 0;
    let updatedBridgeCount = 0;

    const isBridgeHeadersMatch = JSON.stringify(rawHeaders) === JSON.stringify(bridgeHeaders);
    
    let bridgeUuidIdx = bridgeHeaders.findIndex(h => String(h).trim() === 'System ID (Do Not Edit)');
    const bIdxClient = resolveIdx(mClient, bridgeHeaders);
    const bIdxJob = resolveIdx(mJob, bridgeHeaders);
    const bIdxRev = resolveIdx(mRev, bridgeHeaders);
    const bIdxStart = resolveIdx(mStart, bridgeHeaders);
    const bIdxEnd = resolveIdx(mEnd, bridgeHeaders);
    const bIdxLike = resolveIdx(mLike, bridgeHeaders);

    const bridgeHasAllKeys = bridgeUuidIdx !== -1 && bIdxClient !== -1 && bIdxJob !== -1;

    if (bridgeData.length <= 1 || !bridgeHasAllKeys) {
        console.log("Triggering FULL RESET. Missing key columns or empty bridge.");
        bridgeRows = excelRows.map(r => {
            r[uuidColIdx] = Utilities.getUuid();
            newBridgeCount++;
            return r;
        });
    } else {
        console.log("Triggering GLOBAL WEIGHTED MATCHING ENGINE.");
        const oldBridgeRows = bridgeData.slice(1);
        
        const fuzzyName = (str) => String(str || "").toLowerCase().replace(/[^a-z0-9]/g, '').replace(/(ltd|limited|inc|llc|corp|company)$/g, '');
        const scoredPairs = [];

        // 1. Score all possible pairs to prevent misaligned identity stealing
        excelRows.forEach((eRow, eIdx) => {
            const eClient = String(eRow[idxClient] || "").trim();
            const eJob = String(eRow[idxJob] || "").trim();
            const eFuzzClient = fuzzyName(eClient);
            const eFuzzJob = fuzzyName(eJob);
            const eBaseKey = eFuzzClient + "|||" + eFuzzJob;

            oldBridgeRows.forEach((bRow, bIdx) => {
                const bClient = String(bRow[bIdxClient] || "").trim();
                const bJob = String(bRow[bIdxJob] || "").trim();
                const bFuzzClient = fuzzyName(bClient);
                const bFuzzJob = fuzzyName(bJob);
                const bBaseKey = bFuzzClient + "|||" + bFuzzJob;

                let score = 0;
                let clientMatched = false;

                if (eClient.toLowerCase() === bClient.toLowerCase() && eJob.toLowerCase() === bJob.toLowerCase()) {
                    score += 5; // Exact Name Match
                    clientMatched = true;
                } else if (eBaseKey === bBaseKey) {
                    score += 3; // Fuzzy Name Match (strips spaces/suffixes)
                    clientMatched = true;
                } else if (eFuzzClient === bFuzzClient) {
                    score += 1; // Client Match Only
                    clientMatched = true;
                }

                if (idxRev !== -1 && bIdxRev !== -1 && areFuzzyEqual(eRow[idxRev], bRow[bIdxRev])) score += 3;
                if (idxStart !== -1 && bIdxStart !== -1 && areFuzzyEqual(eRow[idxStart], bRow[bIdxStart])) score += 1;
                if (idxEnd !== -1 && bIdxEnd !== -1 && areFuzzyEqual(eRow[idxEnd], bRow[bIdxEnd])) score += 1;
                if (idxLike !== -1 && bIdxLike !== -1 && areFuzzyEqual(eRow[idxLike], bRow[bIdxLike])) score += 1;

                // Queue pairs that have at least some merit
                if (score >= 2) {
                    scoredPairs.push({ eIdx, bIdx, score, clientMatched });
                }
            });
        });

        // 2. Sort descending by score to ensure strongest matches map first
        scoredPairs.sort((a, b) => b.score - a.score);

        const matchedExcelIndices = new Set();
        const matchedBridgeIndices = new Set();

        // 3. Pass 1: Strong Matches (Score >= 4)
        scoredPairs.forEach(pair => {
            if (pair.score >= 4 && !matchedExcelIndices.has(pair.eIdx) && !matchedBridgeIndices.has(pair.bIdx)) {
                matchedExcelIndices.add(pair.eIdx);
                matchedBridgeIndices.add(pair.bIdx);
                
                const eRow = excelRows[pair.eIdx];
                eRow[uuidColIdx] = oldBridgeRows[pair.bIdx][bridgeUuidIdx];
                bridgeRows.push(eRow);
                updatedBridgeCount++;
            }
        });

        // 4. Pass 2: Liberal Orphan Sweep (Score >= 2 AND Client Matched)
        scoredPairs.forEach(pair => {
            if (pair.clientMatched && pair.score >= 2 && !matchedExcelIndices.has(pair.eIdx) && !matchedBridgeIndices.has(pair.bIdx)) {
                matchedExcelIndices.add(pair.eIdx);
                matchedBridgeIndices.add(pair.bIdx);
                
                const eRow = excelRows[pair.eIdx];
                eRow[uuidColIdx] = oldBridgeRows[pair.bIdx][bridgeUuidIdx];
                bridgeRows.push(eRow);
                updatedBridgeCount++;
            }
        });

        // 5. Pass 3: Net New Generation
        excelRows.forEach((eRow, eIdx) => {
            if (!matchedExcelIndices.has(eIdx)) {
                eRow[uuidColIdx] = Utilities.getUuid();
                bridgeRows.push(eRow);
                newBridgeCount++;
            }
        });
    }

    // Sanitize formula-leading strings before writing to bridge and DataFromCRM
    const safeExcelHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([rawHeaders])[0] : rawHeaders;
    const safeExcelBridgeRows = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(bridgeRows) : bridgeRows;

    // Write to Bridge Sheet
    bridgeSheet.clear();
    bridgeSheet.getRange(1, 1, 1, safeExcelHeaders.length).setValues([safeExcelHeaders]).setFontWeight('bold');
    if (safeExcelBridgeRows.length > 0) {
        bridgeSheet.getRange(2, uuidColIdx + 1, safeExcelBridgeRows.length, 1).setNumberFormat("@"); 
        bridgeSheet.getRange(2, 1, safeExcelBridgeRows.length, safeExcelHeaders.length).setValues(safeExcelBridgeRows);
    }
    
    console.log(`Bridge reconciled: ${updatedBridgeCount} updated, ${newBridgeCount} new.`);

    // 8. Delta Push to DataFromCRM
    const destSheet = localSs.getSheetByName('DataFromCRM');
    if (!destSheet) throw new Error("DataFromCRM tab is missing in your system.");

    // Build Rectangular Data Array (Headers + Rows)
    const finalBridgeData = [safeExcelHeaders, ...safeExcelBridgeRows];
    const maxColsArr = Math.max(...finalBridgeData.map(r => r.length));
    
    const rectangularData = finalBridgeData.map(r => {
      while (r.length < maxColsArr) r.push("");
      return r.map(cell => {
        if (Object.prototype.toString.call(cell) === '[object Date]') {
          return Utilities.formatDate(cell, scriptTimeZone, "d-MMM-yy");
        }
        if (typeof cell === 'string' && cell.includes('GMT') && cell.match(/^[A-Z][a-z]{2} [A-Z][a-z]{2} \d{2}/)) {
          const parsedDate = new Date(cell);
          if (!isNaN(parsedDate.getTime())) {
            return Utilities.formatDate(parsedDate, scriptTimeZone, "d-MMM-yy");
          }
        }
        return cell;
      });
    });

    const incomingHeaders = rectangularData[0];
    const incomingRows = rectangularData.slice(1);
    
    const lastRow = destSheet.getLastRow();
    const oldHeaders = lastRow > 0 ? destSheet.getRange(1, 1, 1, destSheet.getLastColumn()).getValues()[0] : [];
    const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(incomingHeaders);

    if (!headersMatch || lastRow <= 1) {
      destSheet.clear();
      destSheet.getRange(1, 1, 1, incomingHeaders.length).setValues([incomingHeaders]).setFontWeight('bold');
      if (incomingRows.length > 0) {
        destSheet.getRange(2, uuidColIdx + 1, incomingRows.length, 1).setNumberFormat("@");
        destSheet.getRange(2, 1, incomingRows.length, incomingHeaders.length).setValues(incomingRows);
      }
      _updateTimestamp("CRMComp", "J2");
      console.log(`Header change or initialization. Full overwrite complete. Fetched ${incomingRows.length} rows.`);
      return;
    }

    const oldDataRange = destSheet.getRange(2, 1, lastRow - 1, destSheet.getLastColumn());
    const oldData = oldDataRange.getValues();
    const incomingMap = new Map();
    
    incomingRows.forEach(row => incomingMap.set(String(row[uuidColIdx]), row));

    const rowsToDelete = [];
    const valueUpdates = [];
    let dataChanged = false;

    for (let i = 0; i < oldData.length; i++) {
      const rowId = String(oldData[i][uuidColIdx]);
      const sheetRowNum = i + 2;

      if (!rowId || rowId.trim() === "") {
          rowsToDelete.push(sheetRowNum);
          continue;
      }

      if (!incomingMap.has(rowId)) {
        rowsToDelete.push(sheetRowNum);
        dataChanged = true;
      } else {
        const newData = incomingMap.get(rowId);
        if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
          valueUpdates.push({ range: `DataFromCRM!A${sheetRowNum}`, values: [newData] });
          dataChanged = true;
        }
        incomingMap.delete(rowId);
      }
    }

    const rowsToAppend = Array.from(incomingMap.values());
    if (rowsToAppend.length > 0) dataChanged = true;

    if (!dataChanged) {
      console.log(`No changes detected in Excel sync. Sheet is up to date.`);
      return;
    }

    while (rowsToAppend.length > 0) {
      const newRowData = rowsToAppend.shift(); 
      if (rowsToDelete.length > 0) {
        const recycleRow = rowsToDelete.shift(); 
        valueUpdates.push({ range: `DataFromCRM!A${recycleRow}`, values: [newRowData] });
      } else {
        const startRow = destSheet.getLastRow() + 1;
        destSheet.getRange(startRow, uuidColIdx + 1, 1, 1).setNumberFormat("@");
        destSheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
      }
    }

    if (rowsToDelete.length > 0) {
      const clearRanges = rowsToDelete.map(rowNum => `DataFromCRM!A${rowNum}:ZZ${rowNum}`);
      destSheet.getRangeList(clearRanges).clearContent();
    }

    if (valueUpdates.length > 0) {
      (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, localSs.getId()));
    }

    _updateTimestamp("CRMComp", "J2");
    console.log(`✅ Success! Excel Sync Delta Update Complete.`);

  } catch (error) {
    console.log(`Excel Sync Error: ${error.message}`);
    throw error;
  }
}

async function getExcelData_(token, driveId, fileId, sheetName) {
  // Inject a timestamp to force the URL to be unique on every call (Cache-Busting)
  const cacheBuster = new Date().getTime();
  const safeDriveId = encodeURIComponent(String(driveId || '').trim());
  const safeFileId = encodeURIComponent(String(fileId || '').trim());
  const url = `https://graph.microsoft.com/v1.0/drives/${safeDriveId}/items/${safeFileId}/workbook/worksheets/${encodeURIComponent(sheetName)}/usedRange?t=${cacheBuster}`;
  
  const options = {
    'method': 'get',
    'headers': {
      'Authorization': 'Bearer ' + token,
      'Cache-Control': 'no-cache, no-store, must-revalidate',
      'Pragma': 'no-cache'
    },
    'muteHttpExceptions': true
  };
  
  const response = (await UrlFetchApp.fetch(url, options));
  const json = JSON.parse(response.getContentText());
  
  if (json.error) throw new Error("Graph API Error: " + (json.error.message || JSON.stringify(json.error)));
  return json.text || json.values; 
}

async function getBrokerExcelAccessToken_() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = (typeof getPulseBrokerBaseUrl_ === 'function')
      ? getPulseBrokerBaseUrl_()
      : "https://app.pulsedashboard.co.uk";
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=excel&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': 'Bearer ' + (typeof getPulseInternalSecret_ === 'function' ? getPulseInternalSecret_() : (PropertiesService.getScriptProperties().getProperty('PULSE_INTERNAL_SECRET') || '')),
        'X-Pulse-Client-Secret': getOrCreatePulseClientSecret_(),
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const respCode = response.getResponseCode();
    if (respCode === 200) {
      const data = JSON.parse(response.getContentText());
      if (data && data.success && data.accessToken && !data.accessToken.startsWith("manual_")) {
        return data.accessToken;
      }
    } else {
      console.warn("Token Broker Excel token request returned HTTP " + respCode + ": " + response.getContentText());
    }
  } catch (e) {
    console.warn("Token Broker Excel token check note: " + e.message);
  }
  return null;
}



