function makeIdsUnique_(rows) {
   const idCounts = {};
   const idIndex = 8; 
   rows.forEach(row => {
       const id = row[idIndex];
       if (idCounts[id]) { idCounts[id]++; row[idIndex] = `${id}-${idCounts[id]}`; } 
       else { idCounts[id] = 1; }
   });
   return rows;
}
async function fetchXeroAccounts_(token) { 
  const accessToken = token || (await getXeroAccessToken());
  const tenantId = (await getKeyInfoValue('X2'));
  const url = 'https://api.xero.com/api.xro/2.0/Accounts?where=Class%3d%3d%22EXPENSE%22%20OR%20Class%3d%3d%22DIRECTCOSTS%22';
  const response = (await UrlFetchApp.fetch(url, { headers: { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': tenantId, 'Accept': 'application/json' }, muteHttpExceptions: true }));
  if (response.getResponseCode() !== 200) throw new Error("Xero API Error: " + response.getContentText());
  const json = JSON.parse(response.getContentText());
  return json.Accounts.map(a => ({ code: a.Code, name: a.Name }));
}
async function fetchXeroCostTransactions_(targetCodes, token, fetchAllExpenses = false) { 
  const accessToken = token || (await getXeroAccessToken());
  const tenantId = (await getKeyInfoValue('X2'));
  let allRows = [];
  const accountList = (await fetchXeroAccounts_(accessToken));
  const accountNameMap = new Map();
  accountList.forEach(acc => accountNameMap.set(acc.code, acc.name));
  const headers = { 'Authorization': 'Bearer ' + accessToken, 'xero-tenant-id': tenantId, 'Accept': 'application/json' };
  const parseXeroAmounts = (line, typeString) => {
      const rawAmt = line.LineAmount || 0;
      const taxAmt = line.TaxAmount || 0;
      let net = 0; let vat = taxAmt; let gross = 0;
      const type = (typeString || 'Exclusive').toUpperCase();
      if (type === 'INCLUSIVE') { gross = rawAmt; net = rawAmt - taxAmt;
      } 
      else { net = rawAmt; gross = rawAmt + taxAmt;
      }
      return { net, vat, gross };
  };
  let page = 1;
  let keepFetching = true;
  while (keepFetching) {
    const invUrl = `https://api.xero.com/api.xro/2.0/Invoices?where=Type%3d%3d%22ACCPAY%22%20AND%20Status!%3d%22DELETED%22&statuses=AUTHORISED,PAID,SUBMITTED&page=${page}`;
    (await Utilities.sleep(200));
    const invResp = (await UrlFetchApp.fetch(invUrl, { headers: headers, muteHttpExceptions: true }));
    if (invResp.getResponseCode() === 200) {
      const invoices = JSON.parse(invResp.getContentText()).Invoices || [];
      if (invoices.length > 0) {
        invoices.forEach(inv => {
          if (inv.LineItems) {
            inv.LineItems.forEach(line => {
              const shouldInclude = fetchAllExpenses ? accountNameMap.has(line.AccountCode) : (targetCodes && targetCodes.includes(line.AccountCode));
              if (shouldInclude) {
                const accName = line.AccountName || accountNameMap.get(line.AccountCode) || "";
                
                // Extract partial payment details
                const rawDue = parseFloat(inv.AmountDue) || 0;
                const rawPaid = parseFloat(inv.AmountPaid) || 0;
                const rawTotal = parseFloat(inv.Total) || (rawDue + rawPaid);

                let datePaid = "";
                if (inv.FullyPaidOnDate) {
                    const dateMatch = String(inv.FullyPaidOnDate).match(/\d+/);
                    if (dateMatch) datePaid = new Date(parseInt(dateMatch[0])).toISOString().split('T')[0];
                } else if (rawPaid > 0 && inv.Payments && inv.Payments.length > 0) {
                    let maxMs = 0;
                    inv.Payments.forEach(p => {
                        if (p.Date) {
                            const m = String(p.Date).match(/\d+/);
                            if (m) {
                                const d = new Date(parseInt(m[0]));
                                if (!isNaN(d.getTime()) && d.getTime() > maxMs) {
                                    maxMs = d.getTime();
                                    datePaid = d.toISOString().split('T')[0];
                                }
                            }
                        }
                    });
                }

                let dueDateStr = "";
                const rawDueD = inv.DueDateString || inv.DueDate;
                if (rawDueD) {
                    if (typeof rawDueD === 'string' && rawDueD.includes("-")) {
                        dueDateStr = rawDueD.split("T")[0].split(" ")[0];
                    } else if (String(rawDueD).includes("/Date(")) {
                        const dMatch = String(rawDueD).match(/\d+/);
                        if (dMatch) {
                            const d = new Date(parseInt(dMatch[0], 10));
                            dueDateStr = Utilities.formatDate(d, SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone(), "yyyy-MM-dd");
                        }
                    } else {
                        const parsedDue = parseDateSafe_(rawDueD);
                        if (parsedDue) dueDateStr = Utilities.formatDate(parsedDue, SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone(), "yyyy-MM-dd");
                    }
                }

                const { net, vat, gross } = parseXeroAmounts(line, inv.LineAmountTypes);
                
                // --- V11.3: SMART SUPPLIER DESCRIPTION ---
                // FIXED: Sanitize carriage returns and newlines from Xero immediately
                let rawDesc = String(line.Description || "No Desc").replace(/[\r\n]+/g, ' - ').trim();
                const supplier = (inv.Contact?.Name || "").trim();
                
                let desc;
                // If Description already starts with Supplier (case-insensitive), don't duplicate
                if (supplier && rawDesc.toLowerCase().startsWith(supplier.toLowerCase())) {
                    desc = rawDesc;
                } else {
                    desc = supplier ? `${supplier} (${rawDesc})` : rawDesc;
                }
                
                const currencyCode = inv.CurrencyCode || "";
                const currencyRate = parseFloat(inv.CurrencyRate) || 1;
                const convFactor = (currencyRate > 0 && currencyRate !== 1) ? (1 / currencyRate) : 1;
                const baseNet = Math.round(net * convFactor * 100) / 100;
                const baseVat = Math.round(vat * convFactor * 100) / 100;
                const baseGross = Math.round(gross * convFactor * 100) / 100;

                const lineRatio = (rawTotal > 0 && Math.abs(gross - rawTotal) > 0.01) ? (gross / rawTotal) : 1;
                const baseDue = Math.round(rawDue * lineRatio * convFactor * 100) / 100;
                const basePaid = Math.round(rawPaid * lineRatio * convFactor * 100) / 100;

                allRows.push([
                  inv.DateString||inv.Date, 
                  desc, 
                  baseNet, 
                  baseVat, 
                  baseGross, 
                  inv.Reference||inv.InvoiceNumber||"", 
                  `${line.AccountCode} - ${accName}`, 
                  inv.Status, 
                  inv.InvoiceID, 
                  datePaid,
                  currencyCode,
                  currencyRate,
                  baseDue,
                  basePaid,
                  dueDateStr
                ]);
              }
            });
          }
        });
        page++;
      } else { keepFetching = false;
      }
    } else { keepFetching = false;
    }
  }
  page = 1; keepFetching = true;
  while (keepFetching) {
    const bankUrl = `https://api.xero.com/api.xro/2.0/BankTransactions?where=Type%3d%3d%22SPEND%22%20AND%20Status!%3d%22DELETED%22&page=${page}`;
    (await Utilities.sleep(200));
    const bankResp = (await UrlFetchApp.fetch(bankUrl, { headers: headers, muteHttpExceptions: true }));
    if (bankResp.getResponseCode() === 200) {
      const bankTxns = JSON.parse(bankResp.getContentText()).BankTransactions || [];
      if (bankTxns.length > 0) {
        bankTxns.forEach(txn => {
          if (txn.LineItems) {
            txn.LineItems.forEach(line => {
              const shouldInclude = fetchAllExpenses ? accountNameMap.has(line.AccountCode) : (targetCodes && targetCodes.includes(line.AccountCode));
              if (shouldInclude) {
                const accName = line.AccountName || accountNameMap.get(line.AccountCode) || "";
                const datePaid = txn.DateString || txn.Date || "";
                const { net, vat, gross } = parseXeroAmounts(line, txn.LineAmountTypes);
                
                // --- V11.3: SMART SUPPLIER DESCRIPTION ---
                // FIXED: Sanitize carriage returns and newlines from Xero immediately
                let rawDesc = String(line.Description || "Direct Spend").replace(/[\r\n]+/g, ' - ').trim();
                const supplier = (txn.Contact?.Name || "").trim();
                
                let desc;
                if (supplier && rawDesc.toLowerCase().startsWith(supplier.toLowerCase())) {
                    desc = rawDesc;
                } else {
                    desc = supplier ? `${supplier} (${rawDesc})` : rawDesc;
                }
                
                const currencyCode = txn.CurrencyCode || "";
                const currencyRate = parseFloat(txn.CurrencyRate) || 1;
                const convFactor = (currencyRate > 0 && currencyRate !== 1) ? (1 / currencyRate) : 1;
                const baseNet = Math.round(net * convFactor * 100) / 100;
                const baseVat = Math.round(vat * convFactor * 100) / 100;
                const baseGross = Math.round(gross * convFactor * 100) / 100;
                allRows.push([
                  txn.DateString||txn.Date, 
                  desc, 
                  baseNet, 
                  baseVat, 
                  baseGross, 
                  txn.Reference||"", 
                  `${line.AccountCode} - ${accName}`, 
                  "PAID", 
                  txn.BankTransactionID, 
                  datePaid,
                  currencyCode,
                  currencyRate,
                  0,
                  baseGross,
                  datePaid
                ]);
              }
            });
          }
        });
        page++;
      } else { keepFetching = false;
      }
    } else { keepFetching = false;
    }
  }

  // --- 3. FETCH MANUAL JOURNALS (requires accounting.journals.read scope) ---
  page = 1; keepFetching = true;
  while (keepFetching) {
    const jnlUrl = `https://api.xero.com/api.xro/2.0/ManualJournals?where=Status%3d%3d%22POSTED%22&page=${page}`;
    (await Utilities.sleep(200));
    const jnlResp = (await UrlFetchApp.fetch(jnlUrl, { headers: headers, muteHttpExceptions: true }));
    const statusCode = jnlResp.getResponseCode();
    if (statusCode === 200) {
      const journals = JSON.parse(jnlResp.getContentText()).ManualJournals || [];
      if (journals.length > 0) {
        const firstLines = journals[0].JournalLines || journals[0].Lines;
        if (!firstLines || firstLines.length === 0) {
          // Xero list endpoint does not include line details without individual ID queries;
          // P&L reconciliation will seamlessly capture all manual journal adjustments.
          keepFetching = false;
        } else {
          journals.forEach(mj => {
            const jLines = mj.JournalLines || mj.Lines || [];
            jLines.forEach(line => {
              const shouldInclude = fetchAllExpenses ? accountNameMap.has(line.AccountCode) : (targetCodes && targetCodes.includes(line.AccountCode));
              if (shouldInclude) {
                const accName = accountNameMap.get(line.AccountCode) || "";
                const lineAmt = parseFloat(line.LineAmount) || 0;
                if (Math.abs(lineAmt) > 0.001) {
                  const taxAmt = parseFloat(line.TaxAmount) || 0;
                  const net = lineAmt;
                  const vat = taxAmt;
                  const gross = net + vat;

                  let rawDesc = String(line.Description || mj.Narration || "Manual Journal").replace(/[\r\n]+/g, ' - ').trim();
                  const narration = String(mj.Narration || "").trim();
                  let desc;
                  if (narration && rawDesc.toLowerCase() !== narration.toLowerCase()) {
                    desc = `${narration} (${rawDesc})`;
                  } else {
                    desc = rawDesc;
                  }

                  let mjDateStr = "";
                  if (mj.Date) {
                    const dateMatch = String(mj.Date).match(/\d+/);
                    if (dateMatch) {
                      mjDateStr = new Date(parseInt(dateMatch[0], 10)).toISOString().split('T')[0];
                    }
                  }
                  if (!mjDateStr) {
                    mjDateStr = mj.DateString || mj.Date || "";
                  }

                  allRows.push([
                    mjDateStr,
                    desc,
                    net,
                    vat,
                    gross,
                    "Manual Journal",
                    `${line.AccountCode} - ${accName}`,
                    mj.Status || "POSTED",
                    mj.ManualJournalID,
                    mjDateStr,
                    "",
                    1,
                    0,
                    gross,
                    mjDateStr
                  ]);
                }
              }
            });
          });
        }
        page++;
      } else {
        keepFetching = false;
      }
    } else {
      if (statusCode === 401 || statusCode === 403) {
        console.warn(`[Xero ManualJournals] HTTP ${statusCode} (accounting.journals.read scope not granted yet on current token). Skipping.`);
      } else {
        console.warn(`[Xero ManualJournals] HTTP ${statusCode} error fetching manual journals: ${jnlResp.getContentText().slice(0, 200)}`);
      }
      keepFetching = false;
    }
  }

  return makeIdsUnique_(allRows);
}
async function fetchQBAccounts_(token) { 
 const accessToken = token || (await getQBAccessToken());
 const realmId = String((await getKeyInfoValue('X3')) || '').trim();
 if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
 // FIXED: Added 'Other Expense', filtered for Active accounts only, and forced MAXRESULTS to 1000
 const query = "SELECT Id, Name, AcctNum FROM Account WHERE AccountType IN ('Expense', 'Cost of Goods Sold', 'Other Expense') AND Active = true MAXRESULTS 1000";
 const url = `https://quickbooks.api.intuit.com/v3/company/${realmId}/query?query=${encodeURIComponent(query)}`;
  const resp = (await UrlFetchApp.fetch(url, { headers: { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, muteHttpExceptions: true }));
  if (resp.getResponseCode() !== 200) throw new Error("QB API Error: " + resp.getContentText());
  const json = JSON.parse(resp.getContentText());
  return (json.QueryResponse.Account || []).map(a => ({ code: a.AcctNum ? a.AcctNum : a.Name, name: a.Name, id: a.Id }));
}
async function fetchQBBillPaymentDates_(paymentIds, accessToken, realmId) { 
  const dateMap = new Map();
  const safeRealmId = String(realmId || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(safeRealmId)) return dateMap;
  const uniqueIds = Array.from(new Set(paymentIds));
  if (uniqueIds.length === 0) return dateMap;
  const baseUrl = "https://quickbooks.api.intuit.com";
  const batchSize = 30;
  for (let i = 0; i < uniqueIds.length; i += batchSize) {
    const batch = uniqueIds.slice(i, i + batchSize);
    const idList = batch.map(id => `'${String(id).replace(/[^0-9a-zA-Z_-]/g, '')}'`).join(',');
    const query = encodeURIComponent(`SELECT Id, TxnDate FROM BillPayment WHERE Id IN (${idList})`);
    const url = `${baseUrl}/v3/company/${safeRealmId}/query?query=${query}`;
    const options = { 'method': 'get', 'headers': { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' }, 'muteHttpExceptions': true };
    const response = (await UrlFetchApp.fetch(url, options));
    if (response.getResponseCode() === 200) {
      const json = JSON.parse(response.getContentText());
      const payments = json.QueryResponse.BillPayment || [];
      payments.forEach(p => { if (p.Id && p.TxnDate) dateMap.set(p.Id, p.TxnDate); });
    }
    (await Utilities.sleep(50));
  }
  return dateMap;
}
async function fetchQBCostTransactions_(targetCodes, token, fetchAllExpenses = false) { 
  const accessToken = token || (await getQBAccessToken());
  const realmId = String((await getKeyInfoValue('X3')) || '').trim();
  if (!/^[0-9a-zA-Z_-]+$/.test(realmId)) throw new Error("Invalid QuickBooks Realm ID in KeyInfo!X3.");
  const headers = { 'Authorization': 'Bearer ' + accessToken, 'Accept': 'application/json' };
  const taxCodeRateMap = (typeof fetchQBTaxCodeRateMap_ === 'function') ? (await fetchQBTaxCodeRateMap_(accessToken, realmId)) : {};
  let allRows = [];
  const accountList = (await fetchQBAccounts_(accessToken)); 
  const accountMap = new Map();
  accountList.forEach(acc => { accountMap.set(acc.id, acc.code); });
  const itemExpenseAccountMap = new Map();
  try {
    const qItems = "SELECT Id, Name, ExpenseAccountRef FROM Item MAXRESULTS 1000";
    const rItems = (await UrlFetchApp.fetch(`https://quickbooks.api.intuit.com/v3/company/${realmId}/query?query=${encodeURIComponent(qItems)}`, { headers: headers, muteHttpExceptions: true }));
    if (rItems.getResponseCode() === 200) {
      const qbItems = JSON.parse(rItems.getContentText()).QueryResponse?.Item || [];
      qbItems.forEach(it => {
        if (it.Id && it.ExpenseAccountRef?.value) {
          itemExpenseAccountMap.set(String(it.Id), {
            value: String(it.ExpenseAccountRef.value),
            name: it.ExpenseAccountRef.name || it.Name || ""
          });
        }
      });
    }
  } catch (itemErr) {
    console.warn("Could not fetch QuickBooks Item ExpenseAccountRef map:", itemErr.message);
  }
  const paymentDatesMap = new Map();

  const getPaymentIdsFromBills = (bills) => {
    const ids = [];
    if (!bills) return ids;
    bills.forEach(bill => {
       if (bill.LinkedTxn) {
         bill.LinkedTxn.forEach(txn => {
            if (txn.TxnType && txn.TxnType.startsWith('BillPayment')) { ids.push(txn.TxnId); }
         });
       }
    });
    return ids;
  };

  const processQBLines = (items, type) => {
    if (!items) return;
    items.forEach(item => {
      let status = "PAID"; let datePaid = "";
      if (type === "Bill") {
        status = (parseFloat(item.Balance) === 0) ? "PAID" : "UNPAID";
        if (item.LinkedTxn) {
            let latestDate = "";
            item.LinkedTxn.forEach(txn => {
                if (txn.TxnType && txn.TxnType.startsWith('BillPayment')) {
                    const pDate = paymentDatesMap.get(txn.TxnId);
                    if (pDate) { if (!latestDate || pDate > latestDate) latestDate = pDate; }
                }
            });
            datePaid = latestDate;
        }
      } else { datePaid = item.TxnDate; }
      
      const vendorName = item.VendorRef?.name || item.EntityRef?.name || "";
      
      // FIXED: Pre-calculate total tax and total net for proportional VAT distribution
      const totalTax = item.TxnTaxDetail?.TotalTax || 0;
      let totalLineNet = 0;
      (item.Line || []).forEach(l => {
          if (l.DetailType === 'AccountBasedExpenseLineDetail' || l.DetailType === 'ItemBasedExpenseLineDetail' || l.DetailType === 'JournalEntryLineDetail') {
              totalLineNet += (l.Amount || 0);
          }
      });

      (item.Line || []).forEach(line => {
        let acctRef = null;
        let acctName = "Uncategorized"; // Default if no account found
        let isItemBased = false;

        // --- DESCRIPTION LOGIC ---
        let baseDesc = line.Description || item.PrivateNote || type;
        // FIXED: Sanitize carriage returns and newlines immediately
        let rawDesc = String(line.Description || item.PrivateNote || type || "Direct Spend").replace(/[\r\n]+/g, ' - ').trim();
        const supplier = (vendorName || "").trim();
        let fullDesc;
        if (supplier && rawDesc.toLowerCase().startsWith(supplier.toLowerCase())) {
            fullDesc = rawDesc;
        } else {
            fullDesc = supplier ? `${supplier} (${rawDesc})` : rawDesc;
        }

        // --- ACCOUNT/CATEGORY DETECTION ---
        if (line.DetailType === 'AccountBasedExpenseLineDetail') {
            acctRef = line.AccountBasedExpenseLineDetail.AccountRef;
        } else if (line.DetailType === 'JournalEntryLineDetail') {
            acctRef = line.JournalEntryLineDetail.AccountRef;
        } else if (line.DetailType === 'ItemBasedExpenseLineDetail') {
            const itemId = String(line.ItemBasedExpenseLineDetail.ItemRef?.value || "");
            const mappedExpenseAcct = itemId ? itemExpenseAccountMap.get(itemId) : null;
            if (mappedExpenseAcct && mappedExpenseAcct.value) {
                acctRef = mappedExpenseAcct;
            } else {
                acctRef = { 
                    value: line.ItemBasedExpenseLineDetail.ItemRef.value, 
                    name: line.ItemBasedExpenseLineDetail.ItemRef.name 
                };
                isItemBased = true;
            }
        }

        if (acctRef && acctRef.value) {
          let matchedCode = accountMap.get(acctRef.value) || acctRef.name;
          
          // FOR ITEM BASED: If we don't know the code, we just use the Name.
          // LOGIC: If it's an Item, we generally assume it IS a cost/expense and include it 
          // (or you can restrict this if you have a list of "Allowed Items")
          
          // Strict Check: Only include if Account Code is in targetCodes OR if it's an Item line (optional)
          // Currently: Strict check. If Item Name isn't in your "targetCodes" list, it skips.
          // ISSUE: Your "KeyInfo" list likely contains Account Codes (e.g., "5000"), not Item Names.
          
          // FIX: If it is ItemBased, we force include it OR check if the *Item Name* matches a code?
          // Since we can't validate the account, we will INCLUDE it but label it clearly.
          // OR: We check if the PARENT Bill has an APAccountRef (Accounts Payable), but that doesn't help with expense coding.
          
          // DECISION: If you want these lines, we must relax the check for ItemBased lines.
          const shouldInclude = fetchAllExpenses || (targetCodes && targetCodes.includes(matchedCode)) || isItemBased; 

          if (shouldInclude) {
             const net = line.Amount || 0; 
             
             // Apply line-level VAT using company TaxCodes and rates
             const lineTaxCodeId = String(
               line.AccountBasedExpenseLineDetail?.TaxCodeRef?.value ||
               line.ItemBasedExpenseLineDetail?.TaxCodeRef?.value ||
               line.TaxCodeRef?.value || ""
             ).trim();

             let vat = 0;
             if (totalTax === 0) {
                 vat = 0;
             } else if (lineTaxCodeId && taxCodeRateMap && taxCodeRateMap[lineTaxCodeId] !== undefined) {
                 vat = Math.round(net * taxCodeRateMap[lineTaxCodeId] * 100) / 100;
                 if (vat === 0 && totalTax > 0 && (item.Line || []).filter(l => (l.Amount || 0) > 0).length === 1) {
                     vat = totalTax;
                 }
             } else if (totalLineNet > 0) {
                 vat = (net / totalLineNet) * totalTax;
             } else if (totalTax > 0) {
                 const validLines = (item.Line || []).filter(l => l.Amount > 0).length || 1;
                 vat = totalTax / validLines;
             }
             const gross = net + vat;
             
             // If ItemBased, append "[Item]" to account name so you know why it's there
             const displayAccName = isItemBased ? `[Item] ${acctRef.name}` : acctRef.name;
             const qbCurrencyCode = item.CurrencyRef?.value || "";
             const qbCurrencyRate = parseFloat(item.ExchangeRate) || 1;
             const qbRef = (type === "Journal")
               ? (item.DocNumber ? `Manual Journal - ${item.DocNumber}` : "Manual Journal")
               : (item.DocNumber || "");

             allRows.push([ 
                 item.TxnDate, 
                 fullDesc, 
                 net, 
                 vat, 
                 gross, 
                 qbRef, 
                 displayAccName, 
                 status, 
                 item.Id, 
                 datePaid,
                 qbCurrencyCode,
                 qbCurrencyRate
             ]);
          }
        }
      });
    });
  };

  const qBill = "SELECT * FROM Bill MAXRESULTS 1000";
  const rBill = (await UrlFetchApp.fetch(`https://quickbooks.api.intuit.com/v3/company/${realmId}/query?query=${encodeURIComponent(qBill)}`, {headers: headers, muteHttpExceptions:true}));
  if (rBill.getResponseCode() === 200) {
      const bills = JSON.parse(rBill.getContentText()).QueryResponse.Bill || [];
      const paymentIds = getPaymentIdsFromBills(bills);
      const fetchedMap = (await fetchQBBillPaymentDates_(paymentIds, accessToken, realmId));
      fetchedMap.forEach((v, k) => paymentDatesMap.set(k, v));
      processQBLines(bills, "Bill");
  }
  const qPurch = "SELECT * FROM Purchase MAXRESULTS 1000";
  const rPurch = (await UrlFetchApp.fetch(`https://quickbooks.api.intuit.com/v3/company/${realmId}/query?query=${encodeURIComponent(qPurch)}`, {headers: headers, muteHttpExceptions:true}));
  if (rPurch.getResponseCode() === 200) processQBLines(JSON.parse(rPurch.getContentText()).QueryResponse.Purchase, "Purchase");
  
  const qJnl = "SELECT * FROM JournalEntry MAXRESULTS 1000";
  const rJnl = (await UrlFetchApp.fetch(`https://quickbooks.api.intuit.com/v3/company/${realmId}/query?query=${encodeURIComponent(qJnl)}`, {headers: headers, muteHttpExceptions:true}));
  if (rJnl.getResponseCode() === 200) processQBLines(JSON.parse(rJnl.getContentText()).QueryResponse.JournalEntry, "Journal");
  
  return makeIdsUnique_(allRows);
}


/**
 * Scans the EXTERNAL CLIENT 'Confirmed' sheet for overdue DIRECT EXPENSES only.
 * V3.0 - ROBUST HEADER MATCHING (Handles mixed "Direct inv" and "Dir inv" prefixes).
 * V3.1 - Renamed to match the new "Stale/Overdue" logic.
 * UPDATED: Adds [Confirmed] context to logs.
 */
async function updateStaleExpensesInConfirmed(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");

  // 1. Check Configuration
  const runConfig = alertSheet.getRange("B47").getValue();
  if (String(runConfig).trim().toLowerCase() !== "yes") {
    console.log("Update Stale Expenses skipped (B47 is not 'Yes').");
    return { count: 0, logs: [] };
  }

  console.log("Starting Stale Expense Audit...");
  
  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) return { count: 0, logs: ["Error: Overdue Expenses - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };

  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    console.log("Error: Could not open Client Spreadsheet: " + e.message);
    return { count: 0, logs: ["Error: Overdue Expenses - " + e.message], hasError: true, error: e.message };
  }

  const sheet = clientSs.getSheetByName("Confirmed");
  if (!sheet) return { count: 0, logs: ["Error: Overdue Expenses - 'Confirmed' sheet not found in Client Spreadsheet."], hasError: true, error: "'Confirmed' sheet not found in Client Spreadsheet." };

  const data = sheet.getDataRange().getValues();
  if (data.length < 2) return { count: 0, logs: [] };

  // Normalize headers
  const headers = data[0].map(h => String(h).trim().toLowerCase().replace(/\s+/g, ' '));
  const today = new Date();
  today.setHours(0,0,0,0);
  const currentMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  // Target: 5th of Current Month
  const targetDateCurrentMonth = new Date(today.getFullYear(), today.getMonth(), 5);
  const fmt = (d) => Utilities.formatDate(d, ss.getSpreadsheetTimeZone(), "dd-MMM-yy");
  const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM-yy HHmm");
  
  let updates = 0;
  const logs = [];

  // Helper: Flexible Column Finder
  const findCol = (variations) => {
      for (const v of variations) {
          const idx = headers.indexOf(v);
          if (idx !== -1) return idx;
      }
      return -1;
  };
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    for (let slot = 1; slot <= 3; slot++) {
      const statusColIdx = findCol([`dir inv ${slot} status`, `direct inv ${slot} status`]);
      const recDateColIdx = findCol([`direct inv ${slot} rec date`, `dir inv ${slot} rec date`]);
      const daysColIdx = findCol([`dir inv ${slot} days to pay`, `direct inv ${slot} days to pay`]);
      if (statusColIdx === -1 || recDateColIdx === -1 || daysColIdx === -1) continue;

      const statusVal = String(row[statusColIdx]).trim();
      // Case sensitive check later
      const recDateVal = row[recDateColIdx];
      const daysVal = safeParseDays_(row[daysColIdx], `Confirmed Row ${i+1}, Slot ${slot}`) || 0;

      if (recDateVal instanceof Date && !isNaN(recDateVal.getTime())) {
          const recDate = new Date(recDateVal);
          recDate.setHours(0,0,0,0);

          // --- SCENARIO 1: BLANK STATUS ---
          if (statusVal === "") {
              // If Rec Date is in a PREVIOUS month
              if (recDate < currentMonthStart) {
                  // Move Rec Date to 5th of Current Month
             
                  const newRecDate = new Date(targetDateCurrentMonth);
                  
                  const cell = sheet.getRange(i + 1, recDateColIdx + 1);
                  cell.setValue(newRecDate).setNumberFormat("dd-MMM-yy");
                  const oldNote = cell.getNote();
                  const noteText = `${timestamp}: Receive date changed from ${fmt(recDate)} to ${fmt(newRecDate)}`;
                  cell.setNote(oldNote ? `${noteText}\n\n${oldNote}` : noteText);
                  
                  const amtColIdx = findCol([`direct inv ${slot} amt`, `dir inv ${slot} amt`, `direct inv ${slot} amount`, `dir inv ${slot} amount`]);
                  let amtStr = "";
                  if (amtColIdx !== -1) {
                      const rawAmt = row[amtColIdx];
                      const numAmt = typeof rawAmt === 'number' ? rawAmt : parseFloat(String(rawAmt || "").replace(/[^0-9.-]+/g, '')) || 0;
                      if (numAmt > 0) {
                          amtStr = `£${numAmt.toLocaleString('en-GB', { minimumFractionDigits: (numAmt % 1 === 0 ? 0 : 2), maximumFractionDigits: 2 })} - `;
                      }
                  }

                  const client = row[headers.indexOf('client')] || "Unknown";
                  const job = row[headers.indexOf('job name')] || "Unknown";
                  
                  logs.push(`[Confirmed] Row ${i+1}, ${client} | ${job}, Slot ${slot}: ${amtStr}Rec Date updated ${fmt(recDate)} -> ${fmt(newRecDate)}`);
                  updates++;
              }
          }
          // --- SCENARIO 2: "Received" OR "Part-paid (balance)" STATUS ---
          else if (statusVal === "Received" || statusVal.toLowerCase() === "part-paid (balance)") {
              const payDate = new Date(recDate);
              payDate.setDate(recDate.getDate() + daysVal);
              
              // If Pay Date is in a PREVIOUS month
              if (payDate < currentMonthStart) {
                  const diffTime = targetDateCurrentMonth.getTime() - recDate.getTime();
                  const newDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                  if (newDays !== daysVal) {
                      const cell = sheet.getRange(i + 1, daysColIdx + 1);
                      cell.setValue(newDays);
                      
                      const oldNote = cell.getNote();
                      const noteText = `${timestamp}: Days to pay updated to ${newDays} (Pay date moved from ${fmt(payDate)} to ${fmt(targetDateCurrentMonth)})`;
                      cell.setNote(oldNote ? `${noteText}\n\n${oldNote}` : noteText);
                      
                      const client = row[headers.indexOf('client')] || "Unknown";
                      const job = row[headers.indexOf('job name')] || "Unknown";
                      
                      logs.push(`[Confirmed] Row ${i+1}, ${client} | ${job}, Slot ${slot}: Days updated ${daysVal} -> ${newDays}`);
                      updates++;
                  }
              }
          }
      }
    }
  }

  return { count: updates, logs: logs };
}


/**
 * Scans OUTGOINGS sheet for Manual/Gap entries with stale dates.
 * UPDATED: Logs "Before -> After" date changes for Rec and Pay.
 */
async function updateOverdueExpensesInOutgoings(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) return { count: 0, logs: ["Error: Overdue Expenses - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    return { count: 0, logs: ["Error: Overdue Expenses - " + e.message], hasError: true, error: e.message };
  }
  const sheet = clientSs.getSheetByName("Outgoings");
  if (!sheet) return { count: 0, logs: ["Error: Overdue Expenses - 'Outgoings' sheet not found in Client Spreadsheet."], hasError: true, error: "'Outgoings' sheet not found in Client Spreadsheet." };
  
  console.log("Starting Overdue Audit: Outgoings Sheet...");
  const today = new Date();
  const currentMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  const currentPayCutoff = 20;
  const currentPayDay = 28;
  const currentPayDateObj = today.getDate() > currentPayCutoff
    ? new Date(today.getFullYear(), today.getMonth() + 1, currentPayDay)
    : new Date(today.getFullYear(), today.getMonth(), currentPayDay);
  const currentPayDateStr = fmtDate_(currentPayDateObj);

  const range = sheet.getDataRange();
  const notes = range.getNotes();
  const values = range.getValues();
  const headers = values[0];
  let updates = 0;
  const logs = [];

  for (let r = 0; r < notes.length; r++) {
      const recTiming = String(values[r][2] || "Curr");
      const payTiming = String(values[r][3] || "Curr");

      for (let c = 0; c < notes[r].length; c++) {
          let note = notes[r][c];
          if (note && (note.includes("{App ID:") || note.includes("PLACE-EXP") || note.includes("MANUAL-ENTRY") || note.includes("UNRECON-GAP") || note.includes("PLACE-GAP") || note.includes("MANUAL-GAP") || note.includes("Part-paid (balance)"))) {
              const headerDate = headers[c];
              if (headerDate instanceof Date) {
                  // Separate top audit text from bottom data blocks if any
                  const firstDataIdx = note.indexOf("{App ID:");
                  let topAuditText = "";
                  let bottomDataText = note;
                  if (firstDataIdx !== -1) {
                      topAuditText = note.substring(0, firstDataIdx).trim();
                      bottomDataText = note.substring(firstDataIdx).trim();
                  }

                  let rawBlocks = bottomDataText.split(/(?=\{App ID:)/).map(s => s.trim()).filter(s => s.length > 0);
                  let cellChanged = false;
                  const cellLogs = [];

                  const cellVal = parseFloat(values[r][c]);
                  const isZeroCell = isNaN(cellVal) || Math.abs(cellVal) < 0.001;
                  if (isZeroCell) {
                      const hasNonPlaceholderOrPaid = rawBlocks.some(blk => {
                          const isPl = blk.includes("PLACE-EXP") || blk.includes("MANUAL-ENTRY") || blk.includes("UNRECON-GAP") || blk.includes("PLACE-GAP") || blk.includes("MANUAL-GAP");
                          if (!isPl) return true;
                          const stM = blk.match(/\{Status:\s*(.*?)\}/i);
                          const st = stM ? stM[1].trim().toLowerCase() : "";
                          return st === "paid" || st === "complete";
                      });
                      if (!hasNonPlaceholderOrPaid) {
                          notes[r][c] = topAuditText || "";
                          updates++;
                      }
                      continue;
                  }

                  const contractor = values[r][0] || "Unknown";
                  const monthStr = Utilities.formatDate(headerDate, ss.getSpreadsheetTimeZone(), "MMM yy");

                  for (let b = 0; b < rawBlocks.length; b++) {
                      let block = rawBlocks[b];
                      const isPlaceholder = block.includes("PLACE-EXP") || block.includes("MANUAL-ENTRY") || block.includes("UNRECON-GAP") || block.includes("PLACE-GAP") || block.includes("MANUAL-GAP");
                      const isPartPaidBal = block.includes("Part-paid (balance)");

                      // Check status of THIS block - skip paid, complete, or voided blocks
                      const statusMatch = block.match(/\{Status:\s*(.*?)\}/i);
                      if (statusMatch) {
                          const status = statusMatch[1].trim().toLowerCase();
                          if (status === "paid" || status === "complete" || status === "part-paid (paid)" || status === "void" || status === "deleted" || status === "cancelled") {
                              continue;
                          }
                      }

                      // Extract THIS block's existing dates and amount
                      let oldRec = "UNK";
                      let oldPay = "UNK";
                      const recMatch = block.match(/\{Rec date:\s*(.*?)\}/i);
                      if (recMatch) oldRec = recMatch[1].trim();
                      const payMatch = block.match(/\{Pay date:\s*(.*?)\}/i);
                      if (payMatch) oldPay = payMatch[1].trim();

                      let blockAmt = 0;
                      const amtMatch = block.match(/\{Amt:\s*(.*?)\}/i);
                      if (amtMatch && amtMatch[1]) {
                          blockAmt = parseFloat(amtMatch[1].replace(/[^0-9.-]+/g, '')) || 0;
                      }
                      if (!blockAmt && typeof values[r][c] === 'number') {
                          blockAmt = values[r][c];
                      }

                      const est = calculateEstDates(headerDate, recTiming, payTiming);

                      // Check if THIS block's existing Pay Date is overdue (< currentMonthStart)
                      const existingPayDate = parseDateSafe_(oldPay) || new Date(oldPay);
                      if (!isNaN(existingPayDate.getTime()) && existingPayDate < currentMonthStart) {
                          est.pay = currentPayDateStr;
                      } else if (oldPay !== "UNK" && oldPay !== "") {
                          est.pay = oldPay; // Preserve valid or future date
                      }

                      // Check if THIS block's existing Rec Date is overdue
                      if (!isPlaceholder) {
                          if (oldRec !== "UNK" && oldRec !== "") {
                              est.rec = oldRec; // Always preserve original invoice receive date for real bills and part-paid balances
                          }
                      } else {
                          const existingRecDate = parseDateSafe_(oldRec) || new Date(oldRec);
                          if (!isNaN(existingRecDate.getTime()) && existingRecDate >= currentMonthStart) {
                              est.rec = oldRec; // Preserve valid or future date
                          }
                      }

                      let blockModified = false;
                      const changes = [];

                      if (est.rec && est.rec !== oldRec) {
                          if (oldRec !== "UNK" && oldRec !== "") changes.push(`Rec: ${oldRec}->${est.rec}`);
                          block = block.replace(/\{Rec date:.*?\}/i, `{Rec date: ${est.rec}}`);
                          blockModified = true;
                      }
                      if (est.pay && est.pay !== oldPay) {
                          if (oldPay !== "UNK" && oldPay !== "") changes.push(`Pay: ${oldPay}->${est.pay}`);
                          block = block.replace(/\{Pay date:.*?\}/i, `{Pay date: ${est.pay}}`);
                          blockModified = true;
                      }

                      if (blockModified) {
                          rawBlocks[b] = block;
                          cellChanged = true;

                          if (changes.length > 0) {
                              let amtStr = "";
                              if (blockAmt > 0) {
                                  amtStr = `£${blockAmt.toLocaleString('en-GB', { minimumFractionDigits: (blockAmt % 1 === 0 ? 0 : 2), maximumFractionDigits: 2 })} - `;
                              }
                              const changeStr = changes.join(', ');
                              const changePart = changeStr ? ` - ${changeStr}` : '';
                              cellLogs.push(`[Outgoings] ${monthStr} - ${contractor} (Row ${r+1}): ${amtStr}Updated stale placeholder date${changePart}`);
                          }
                      }
                  }

                  if (cellChanged) {
                      const newBottomText = rawBlocks.join("\n\n");
                      const finalNote = (topAuditText && newBottomText) ? `${topAuditText}\n\n${newBottomText}` : (topAuditText || newBottomText);
                      notes[r][c] = finalNote;
                      updates++;
                      cellLogs.forEach(l => logs.push(l));
                  }
              }
          }
      }
  }

  if (updates > 0) {
      range.setNotes(notes);
      console.log(`Outgoings Overdue Audit: Updated dates in ${updates} cells.`);
  } else {
      console.log("Outgoings Overdue Audit: No stale dates found.");
  }
  return { count: updates, logs: logs };
}

function getSpecificAppAmount_(note, appId) {
    if (!note || !appId) return 0;
    // Escape regex characters in ID just in case, and sum across all tranche blocks for this App ID
    const safeId = appId.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
    const regex = new RegExp(`\\{App ID:\\s*${safeId}(?:-P1|-bal)?\\}[^\\n]*?\\{Amt:\\s*([\\d.]+)\\}`, "gi");
    let sum = 0;
    let match;
    while ((match = regex.exec(note)) !== null) {
        sum += parseFloat(match[1]) || 0;
    }
    return Math.round(sum * 100) / 100;
}

/**
 * Calculates final discrepancies AFTER the entire expense sequence has finished
 * and the external notes have been synced back to the master sheet.
 */
async function calculateFinalExpenseDiscrepancies() {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const dirCompSheet = ss.getSheetByName("DirComp");
    const alertSheet = ss.getSheetByName("DataChgAlert");
    if (!dirCompSheet || !alertSheet) return;

    // Force sheet to calculate incoming synced data
    (await SpreadsheetApp.flush());
    (await Utilities.sleep(2000));
    dirCompSheet.getRange("A1").getValue(); 
    (await SpreadsheetApp.flush());

    const sectionHeaders = dirCompSheet.getRange("4:4").getValues()[0];
    const colHeaders = dirCompSheet.getRange("5:5").getValues()[0];
    const data = dirCompSheet.getDataRange().getValues();

    const colIndexToSection = sectionHeaders.map(h => String(h||'').trim().toLowerCase());
    for(let i=1; i<colIndexToSection.length; i++) {
        if(!colIndexToSection[i]) colIndexToSection[i] = colIndexToSection[i-1];
    }
    const findCol = (sec, head) => {
        const s = sec.toLowerCase(); const h = head.toLowerCase();
        return colHeaders.findIndex((val, i) => String(val).toLowerCase().trim() === h && colIndexToSection[i] === s);
    };

    const dashIndexes = [
        findCol("Dashboard compare", "Missing cost?"),
        findCol("Dashboard compare", "Duplicate app ID?"),
        findCol("Dashboard compare", "Descr. mismatch?"),
        findCol("Dashboard compare", "Amount mismatch?"),
        findCol("Dashboard compare", "Rec date mismatch?"),
        findCol("Dashboard compare", "Pay date mismatch?"),
        findCol("Dashboard compare", "Status mismatch?")
    ];

    updateDiscrepancyCounts_(alertSheet, data, 5, dashIndexes, []);
}

/**
 * =========================================================================
 * EXPENSE TRANSACTION BREAKDOWN, ACTUAL VAT & P&L OUTGOINGS SYNCHRONIZER
 * =========================================================================
 * Synchronizes the expense transactions breakdown (Row 300), actual VAT amounts
 * (Rows 304 and 305), and finalized P&L Outgoings actuals (Rows 125-225) into
 * the Client Sheet's Outgoings tab with ultra-fast batch operations & delta checking.
 * 
 * - Trailing 13 months only: Historical months (>13m) are preserved permanently.
 * - Sourced from PLComp / PLFromApp: Base category actuals & Depreciation are read
 *   directly from Xero's official P&L report (including all manual journals, depreciation,
 *   prepayments, and adjustments), matching pushOutgoingsToClientSheet.
 * - Depreciation handling: Depreciation is read from PLComp Row 29 / PLFromApp Row 19,
 *   written to the Depreciation target row, and preserved if outside P&L window (never wiped).
 * - Synthetic Journal Line: If a category has manual journals in Xero (e.g. Office space
 *   rental £20.83, or Subscriptions £18.59 diff), a synthetic journal entry is added to
 *   Row 300 JSON so the popover sum matches the Outgoings cell to the exact penny.
 * - Recon Sheet Uncleared Items: Sourced from Recon Sheet CD4:CN60 for tabs YYMM and added
 *   to both Outgoings cells and Row 300 JSON breakdown.
 * - Ultra-Fast Batch Processing: Ingests Outgoings, PLComp, and PLFromApp in single calls,
 *   performs all delta checks and computations in memory, and writes back only modified
 *   columns in bulk (dropping runtime from ~8 minutes to ~2-3 seconds).
 * - CR2 Gate: Only months with Recon Sheet cell CR2 checked (true) are finalized. Forecast
 *   months (CR2 unchecked) have clean Row 300/304/305 and their cells are not overwritten.
 */
async function syncExpenseTransactionBreakdownToClientSheet_(isHeadless = false, injectedExpenseRows = null) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const clientSheetId = (await getKeyInfoValue('X28'));
    if (!clientSheetId) {
      console.warn("[Expense Breakdown] No Client Sheet ID found in KeyInfo!X28.");
      return { success: false, error: "No Client Sheet ID in KeyInfo!X28" };
    }

    const clientSs = (await SpreadsheetApp.openById(clientSheetId));
    const outgoingsSheet = clientSs.getSheetByName("Outgoings");
    if (!outgoingsSheet) {
      console.warn("[Expense Breakdown] 'Outgoings' tab not found in client spreadsheet.");
      return { success: false, error: "'Outgoings' tab not found in Client Sheet" };
    }

    // Ensure Outgoings sheet has at least 310 rows
    const maxRows = outgoingsSheet.getMaxRows();
    if (maxRows < 310) {
      outgoingsSheet.insertRowsAfter(maxRows, 310 - maxRows);
    }

    // Read full Outgoings data up to at least row 310 in ONE single batch call
    const lastCol = Math.max(outgoingsSheet.getLastColumn(), 50);
    const totalRowsToRead = Math.max(outgoingsSheet.getMaxRows(), 310);
    const outgoingsData = outgoingsSheet.getRange(1, 1, totalRowsToRead, lastCol).getValues();
    const headers = outgoingsData[0] || [];

    // Defensive guarantee: Ensure in-memory array has at least 310 rows and each row has all columns
    while (outgoingsData.length < 310) {
      outgoingsData.push(new Array(lastCol).fill(""));
    }
    for (let r = 0; r < outgoingsData.length; r++) {
      if (!outgoingsData[r] || !Array.isArray(outgoingsData[r])) {
        outgoingsData[r] = new Array(lastCol).fill("");
      }
    }

    // Ensure Column A labels exist in rows 300, 304, 305
    const label300 = String(outgoingsData[299]?.[0] || "").trim();
    if (label300 !== "Transactions Breakdown (JSON)") {
      outgoingsSheet.getRange(300, 1)
        .setValue("Transactions Breakdown (JSON)")
        .setFontSize(9)
        .setFontColor("#64748b");
      outgoingsData[299][0] = "Transactions Breakdown (JSON)";
    }
    const label304 = String(outgoingsData[303]?.[0] || "").trim();
    if (label304 !== "Actual VAT on expenses (Cash basis)") {
      outgoingsSheet.getRange(304, 1)
        .setValue("Actual VAT on expenses (Cash basis)")
        .setFontWeight("bold");
      outgoingsData[303][0] = "Actual VAT on expenses (Cash basis)";
    }
    const label305 = String(outgoingsData[304]?.[0] || "").trim();
    if (label305 !== "Actual VAT on expenses (Accrual basis)") {
      outgoingsSheet.getRange(305, 1)
        .setValue("Actual VAT on expenses (Accrual basis)")
        .setFontWeight("bold");
      outgoingsData[304][0] = "Actual VAT on expenses (Accrual basis)";
    }

    // Read contractor categories from KeyInfo!AT4:AT40 to EXCLUDE them from expense breakdown and expense VAT
    const infoSheet = ss.getSheetByName(COST_CONFIG.sheets.keyInfo);
    const rawTargets = infoSheet ? infoSheet.getRange("AT4:AT40").getValues() : [];
    const contractorCodes = rawTargets.flat().filter(String).map(s => s.split(' - ')[0].trim());

    // Determine expense rows: injectedExpenseRows if available, or fetch full expense rows, or fallback to JnlsFromApp
    let expenseRows = [];
    if (injectedExpenseRows && injectedExpenseRows.length > 0) {
      expenseRows = injectedExpenseRows;
    } else {
      const rawToolName = (await getKeyInfoValue('Q4'));
      const toolName = String(rawToolName || "").trim().toLowerCase();
      try {
        if (toolName === 'xero') {
          const token = (await getXeroAccessToken());
          expenseRows = (await fetchXeroCostTransactions_([], token, true));
        } else if (toolName.includes('quickbook')) {
          const token = (await getQBAccessToken());
          expenseRows = (await fetchQBCostTransactions_([], token, true));
        }
      } catch (fetchErr) {
        console.warn("[Expense Breakdown] Direct fetch failed, falling back to JnlsFromApp:", fetchErr.message);
      }

      if (!expenseRows || expenseRows.length === 0) {
        const jnlsSheet = ss.getSheetByName(COST_CONFIG.sheets.journalData);
        if (jnlsSheet && jnlsSheet.getLastRow() >= 2) {
          expenseRows = jnlsSheet.getDataRange().getValues().slice(1);
        }
      }
    }

    // Locate the "Other expenses" section dynamically in Outgoings Column A
    let otherExpStartRow = -1;
    let otherExpEndRow = -1;
    for (let r = 0; r < outgoingsData.length; r++) {
      const colAVal = String(outgoingsData[r][0] || "").trim().toLowerCase();
      if (colAVal === "other expenses" && otherExpStartRow === -1) {
        otherExpStartRow = r + 1; // 1-indexed (e.g. 124)
      } else if ((colAVal === "total other expenses" || colAVal.startsWith("total other expenses")) && otherExpEndRow === -1 && otherExpStartRow !== -1) {
        otherExpEndRow = r + 1; // 1-indexed (e.g. 227)
        break;
      }
    }

    // Locate Depreciation Target Row in Outgoings
    let depreciationTargetRow = -1;
    if (otherExpStartRow !== -1 && otherExpEndRow !== -1) {
      for (let r = otherExpStartRow; r < otherExpEndRow; r++) {
        const catName = String(outgoingsData[r - 1]?.[0] || "").trim().toLowerCase();
        if (catName.includes("depreciation")) {
          depreciationTargetRow = r;
          break;
        }
      }
      if (depreciationTargetRow === -1) {
        depreciationTargetRow = otherExpEndRow - 2;
      }
    }

    // Defensive cleanup: If a prior buggy run wrote non-expense headers ("Income", "Gross profit", etc.),
    // error strings ("#N/A", "#REF!", etc.), or placed values into row 125, clean them up immediately.
    if (otherExpStartRow !== -1 && depreciationTargetRow !== -1) {
      for (let r = otherExpStartRow; r < depreciationTargetRow; r++) {
        const rowNum = r;
        const name = String(outgoingsData[r - 1]?.[0] || "").trim();
        const lower = name.toLowerCase();
        const isErrorCat = name.startsWith("#") || lower.includes("#n/a") ||
                           lower.includes("#ref!") || lower.includes("#value!") ||
                           lower.includes("#name?") || lower.includes("#error!") ||
                           lower.includes("#null!") || lower.includes("#num!") ||
                           lower.includes("#div/0!");
        const isIgnoreCat = isErrorCat || lower === "income" || lower === "gross profit" || lower === "total income" ||
                            lower === "total cost of sales" || lower === "less cost of sales" ||
                            lower === "less operating expenses" || lower === "operating profit" ||
                            lower.startsWith("total operating") || lower.startsWith("---") ||
                            lower.startsWith("===") || (rowNum === 125 && name !== "");
        if (isIgnoreCat && name) {
          console.log(`[Expense Breakdown] Cleaning up invalid category row ${rowNum}: "${name}"`);
          outgoingsSheet.getRange(rowNum, 1, 1, lastCol).clearContent().setBackground(null);
          for (let c = 0; c < lastCol; c++) outgoingsData[r - 1][c] = "";
        }
      }
    }

    // Sourcing categories from Outgoings:
    // IMPORTANT: Row 125 should NEVER be used - data rows start strictly at row 126 onwards!
    const dataStartRow = Math.max(126, otherExpStartRow + 2);
    const outgoingsCategoryRows = [];
    const knownNormCats = new Set();
    let lastUsedRow = dataStartRow - 1; // Tracks the highest row number beneath which blank rows start

    if (otherExpStartRow !== -1 && otherExpEndRow !== -1) {
      for (let r = dataStartRow; r < depreciationTargetRow; r++) {
        const catName = String(outgoingsData[r - 1]?.[0] || "").trim();
        const lowerCat = catName.toLowerCase();
        const isInvalid = !catName || catName.startsWith("#") || lowerCat.includes("#n/a") ||
                          lowerCat.includes("#ref!") || lowerCat.includes("#value!") ||
                          lowerCat.startsWith("total") || lowerCat.startsWith("less ") ||
                          lowerCat.startsWith("---") || lowerCat.startsWith("===");
        if (!isInvalid) {
          const isDep = lowerCat.includes("depreciation") || (r === depreciationTargetRow);
          if (isDep) depreciationTargetRow = r;
          
          lastUsedRow = r;
          const norm = catName.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
          knownNormCats.add(norm);

          outgoingsCategoryRows.push({
            rowIdx: r - 1, // 0-indexed for outgoingsData
            rowNum: r,     // 1-indexed for Sheets
            name: catName,
            normName: norm,
            isDepreciation: isDep
          });
        }
      }
    }

    // Ingest valid categories STRICTLY from PLComp:
    // Range 1: Costs of Sale (Rows 30-49, Column E) -> CoS
    // Range 2: Overheads (Rows 89-596, Column E) -> Overhead
    // NO OTHER CATEGORIES SHOULD BE INCLUDED!
    const DEFAULTS_OVERHEAD = ["Yes", "Curr", "Curr", "0%", "100%"];
    const DEFAULTS_COS = ["Yes", "Curr", "Curr", "100%", "100%"];

    const validCategoriesMap = new Map(); // normName -> { displayName, type: 'CoS' | 'Overhead', defaults, compRowIdx }
    const plCompSheet = ss.getSheetByName("PLComp");
    let plCompData = null;
    let plCompDepRowIdx = -1;

    if (plCompSheet) {
      // Quarantine any new nominal accounts in PLFromApp not yet in PLComp!B:B or Outgoings to prevent Outgoings pollution
      try {
        (await checkAndQuarantineUnmappedPLCategories_(ss, knownNormCats, isHeadless));
      } catch (qErr) {
        console.warn("[Expense Breakdown] Quarantine check failed:", qErr.message);
      }

      plCompData = plCompSheet.getDataRange().getValues();

      // Range 1: Costs of Sale (Rows 30-49, 0-indexed 29-48, Col E is index 4)
      for (let r = 29; r <= 48 && r < plCompData.length; r++) {
        const rawName = String(plCompData[r]?.[4] || "").trim();
        const lowerRaw = rawName.toLowerCase();
        const isInvalid = !rawName || rawName.startsWith("#") || lowerRaw.includes("#n/a") ||
                          lowerRaw.includes("#ref!") || lowerRaw.includes("#value!") ||
                          lowerRaw.startsWith("total") || lowerRaw.startsWith("less ") ||
                          lowerRaw.startsWith("---") || lowerRaw.startsWith("===");
        if (!isInvalid) {
          const norm = rawName.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
          if (norm && !validCategoriesMap.has(norm)) {
            validCategoriesMap.set(norm, {
              displayName: rawName,
              type: 'CoS',
              defaults: DEFAULTS_COS,
              compRowIdx: r
            });
          }
        }
      }

      // Range 2: Overheads (Rows 89-596, 0-indexed 88-595, Col E is index 4)
      const maxOvhRow = Math.min(plCompData.length - 1, 595);
      for (let r = 88; r <= maxOvhRow; r++) {
        const rawName = String(plCompData[r]?.[4] || "").trim();
        const lowerRaw = rawName.toLowerCase();
        const isInvalid = !rawName || rawName.startsWith("#") || lowerRaw.includes("#n/a") ||
                          lowerRaw.includes("#ref!") || lowerRaw.includes("#value!") ||
                          lowerRaw.startsWith("total") || lowerRaw.startsWith("less ") ||
                          lowerRaw.startsWith("---") || lowerRaw.startsWith("===");
        if (!isInvalid) {
          const norm = rawName.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
          if (norm && !validCategoriesMap.has(norm)) {
            validCategoriesMap.set(norm, {
              displayName: rawName,
              type: 'Overhead',
              defaults: DEFAULTS_OVERHEAD,
              compRowIdx: r
            });
          }
        }
      }

      // Find "Depreciation total" row in PLComp Column E
      for (let r = 0; r < plCompData.length; r++) {
        if (String(plCompData[r]?.[4] || "").trim().toLowerCase() === "depreciation total") {
          plCompDepRowIdx = r;
          break;
        }
      }
    }

    // Ingest P&L data from PLFromApp and PLComp
    // key: "YYYY-MM" -> { categories: Map<normName, amount>, depreciation: number }
    const plDataByMonth = new Map();
    const getPlEntry = (mKey) => {
      if (!plDataByMonth.has(mKey)) {
        plDataByMonth.set(mKey, { categories: new Map(), depreciation: 0 });
      }
      return plDataByMonth.get(mKey);
    };

    // 1. Ingest from PLFromApp (historical months) - STRICTLY only categories in validCategoriesMap!
    const plFromAppSheet = ss.getSheetByName("PLFromApp");
    if (plFromAppSheet) {
      const plData = plFromAppSheet.getDataRange().getValues();
      if (plData.length > 1) {
        const plHeaders = plData[0];
        for (let c = 1; c < plHeaders.length; c++) {
          const hDate = parseHeaderDate_(plHeaders[c]);
          if (!hDate) continue;
          const mKey = `${hDate.getFullYear()}-${String(hDate.getMonth() + 1).padStart(2, '0')}`;
          const entry = getPlEntry(mKey);
          for (let r = 1; r < plData.length; r++) {
            const rawName = String(plData[r][0] || "").trim();
            if (!rawName) continue;
            const val = parseFloat(String(plData[r][c] || "0").replace(/[£$€,\s]/g, "")) || 0;
            if (rawName.toLowerCase().includes("depreciation")) {
              entry.depreciation = val;
            } else {
              const norm = rawName.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
              if (validCategoriesMap.has(norm)) {
                entry.categories.set(norm, val);
              }
            }
          }
        }
      }
    }

    // 2. Overlay from PLComp (matching pushOutgoingsToClientSheet)
    if (plCompData && plCompData.length > 88) {
      const compHeaders = plCompData[0];
      for (let c = 5; c <= 10 && c < compHeaders.length; c++) {
        const hDate = parseHeaderDate_(compHeaders[c]);
        if (!hDate) continue;
        const mKey = `${hDate.getFullYear()}-${String(hDate.getMonth() + 1).padStart(2, '0')}`;
        const entry = getPlEntry(mKey);
        if (plCompDepRowIdx !== -1) {
          entry.depreciation = parseFloat(String(plCompData[plCompDepRowIdx][c] || "0").replace(/[£$€,\s]/g, "")) || 0;
        }
        validCategoriesMap.forEach((info, norm) => {
          if (info.compRowIdx !== undefined && info.compRowIdx < plCompData.length) {
            const val = parseFloat(String(plCompData[info.compRowIdx][c] || "0").replace(/[£$€,\s]/g, "")) || 0;
            entry.categories.set(norm, val);
          }
        });
      }
    }

    // Read Recon Sheet if available (KeyInfo!G1)
    const rawReconUrl = (await getKeyInfoValue('G1'));
    const unreconciledMap = new Map(); // key: "YYYY-MM" -> array of unreconciled items
    const reconReadyMonthsMap = new Map(); // key: "YYYY-MM" -> boolean (CR2 checked)

    if (rawReconUrl) {
      // Auto-reconcile bank feeds in Pulse before reading unreconciled items
      (await autoReconcileBankFeedsBeforeBreakdown_(rawReconUrl));

      try {
        const reconSs = (await SpreadsheetApp.openByUrl(rawReconUrl));
        const reconSheets = reconSs.getSheets();
        reconSheets.forEach(sheet => {
          const tabName = sheet.getName().trim();
          if (/^\d{4}$/.test(tabName)) {
            const yy = parseInt(tabName.slice(0, 2), 10);
            const mm = parseInt(tabName.slice(2, 4), 10);
            const fullYear = yy < 100 ? 2000 + yy : yy;
            const monthKey = `${fullYear}-${String(mm).padStart(2, '0')}`;

            try {
              const crVals = sheet.getRange("CR1:CR2").getValues();
              const cr1Val = String(crVals[0][0] || "").trim();
              if (!cr1Val) {
                sheet.getRange("CR1").setValue("Month ready:");
              }
              const cr2Val = crVals[1][0];
              const isReady = (cr2Val === true || String(cr2Val).trim().toUpperCase() === "TRUE");
              reconReadyMonthsMap.set(monthKey, isReady);
            } catch (crErr) {
              console.warn(`[Expense Breakdown] Could not read CR1:CR2 on tab ${tabName}:`, crErr.message);
              reconReadyMonthsMap.set(monthKey, false);
            }

            if (sheet.getLastColumn() >= 92) {
              const lastR = Math.min(sheet.getLastRow(), 60);
              if (lastR >= 4) {
                const unreconRange = sheet.getRange(4, 82, lastR - 3, 11).getValues();
                unreconRange.forEach(r => {
                  const dateVal = r[2]; // CF (Col 84)
                  const payee = String(r[3] || "").trim();
                  const rawAmt = parseFloat(String(r[5] || "0").replace(/[£$€,\s]/g, "")) || 0;
                  const amt = Math.abs(rawAmt);
                  const cat = String(r[9] || "").trim();
                  const vatApplies = String(r[10] || "").trim().toLowerCase() === "yes";

                  if (amt > 0 && cat) {
                    const cleanCat = cat.replace(/^\d+\s*[-–]\s*/, "").trim();
                    const normCat = cleanCat.toLowerCase();

                    // STRICT REQUIREMENT: Only accept unreconciled items whose category is in PLComp!
                    if (validCategoriesMap.has(normCat)) {
                      const grossAmt = amt;
                      const vatAmt = vatApplies ? Math.round(grossAmt * (20 / 120) * 100) / 100 : 0;
                      const netAmt = Math.round((grossAmt - vatAmt) * 100) / 100;
                      const desc = payee || "Unreconciled item";

                      let dStr = "";
                      if (dateVal instanceof Date && !isNaN(dateVal.getTime())) {
                        dStr = fmtDate_(dateVal);
                      } else if (dateVal) {
                        dStr = String(dateVal);
                      }

                      const unrecItem = {
                        d: dStr,
                        c: cleanCat,
                        s: desc,
                        r: "UNRECON",
                        n: netAmt,
                        v: vatAmt,
                        g: grossAmt,
                        p: dStr,
                        u: true
                      };

                      if (!unreconciledMap.has(monthKey)) {
                        unreconciledMap.set(monthKey, []);
                      }
                      unreconciledMap.get(monthKey).push(unrecItem);
                    }
                  }
                });
              }
            }
          }
        });
      } catch (reconErr) {
        console.warn("[Expense Breakdown] Could not read Recon Sheet from KeyInfo!G1:", reconErr.message);
      }
    }

    // --- AUTO-PROVISION MISSING OUTGOINGS CATEGORIES ---
    // --- QUARANTINE UNMAPPED OUTGOINGS CATEGORIES ---
    // If any category is sourced from PLComp but does NOT yet exist on Outgoings,
    // do NOT auto-create a row on Outgoings! Instead, quarantine it to PLComp!B180:B229
    // so it is excluded from Outgoings until classified by the user in PMA.
    const categoriesToEnsure = new Map(); // normName -> catInfo
    validCategoriesMap.forEach((catInfo, norm) => {
      if (!knownNormCats.has(norm)) {
        categoriesToEnsure.set(norm, catInfo);
      }
    });

    const newlyAddedRowNums = [];
    if (categoriesToEnsure.size > 0) {
      console.log(`[Expense Breakdown] ${categoriesToEnsure.size} category(s) not in Outgoings - quarantining to protect sheet:`, Array.from(categoriesToEnsure.keys()).join(", "));
      try {
        (await checkAndQuarantineUnmappedPLCategories_(ss, knownNormCats, isHeadless));
      } catch (qErr) {
        console.warn("[Expense Breakdown] Quarantine of new Outgoings categories failed:", qErr.message);
      }
    }

    const now = new Date();
    const cutoffDate = new Date(now.getFullYear(), now.getMonth() - 13, 1);
    const futureCutoff = new Date(now.getFullYear(), now.getMonth() + 2, 1);

    // Identify all finalized months within the trailing 13 months window
    const finalizedMonthKeys = [];
    for (let c = 0; c < headers.length; c++) {
      const hDate = parseHeaderDate_(headers[c]);
      if (!hDate || hDate < cutoffDate || hDate > futureCutoff) continue;
      const mKey = `${hDate.getFullYear()}-${String(hDate.getMonth() + 1).padStart(2, '0')}`;
      if (reconReadyMonthsMap.get(mKey)) {
        finalizedMonthKeys.push(mKey);
      }
    }
    finalizedMonthKeys.sort();
    const latestFinalizedMonthKey = finalizedMonthKeys.length > 0 ? finalizedMonthKeys[finalizedMonthKeys.length - 1] : null;

    // Compute fresh monthly transaction fingerprints ({ count, netSum, catSig }) from live overhead expenses
    const freshFingerprints = {};
    const freshCatBuckets = {};
    expenseRows.forEach(row => {
      const rawAccount = String(row[6] || "").trim();
      const code = rawAccount.split(' - ')[0].trim();
      if (contractorCodes.includes(code)) return; // Direct contractor costs belong to Confirmed sheet

      const invDate = parseDateSafe_(row[0]);
      if (!invDate) return;
      const mKey = `${invDate.getFullYear()}-${String(invDate.getMonth() + 1).padStart(2, '0')}`;
      const net = parseFloat(row[2]) || 0;
      const normCat = rawAccount.replace(/^\d+\s*[-–]\s*/, "").trim().toLowerCase();

      if (!freshFingerprints[mKey]) {
        freshFingerprints[mKey] = { count: 0, netSum: 0, catSig: "" };
        freshCatBuckets[mKey] = {};
      }
      freshFingerprints[mKey].count++;
      freshFingerprints[mKey].netSum = Math.round((freshFingerprints[mKey].netSum + net) * 100) / 100;

      if (normCat) {
        if (!freshCatBuckets[mKey][normCat]) {
          freshCatBuckets[mKey][normCat] = { count: 0, netSum: 0 };
        }
        freshCatBuckets[mKey][normCat].count++;
        freshCatBuckets[mKey][normCat].netSum = Math.round((freshCatBuckets[mKey][normCat].netSum + net) * 100) / 100;
      }
    });
    Object.keys(freshCatBuckets).forEach(mKey => {
      const bucket = freshCatBuckets[mKey];
      freshFingerprints[mKey].catSig = Object.keys(bucket)
        .sort()
        .map(k => `${k}:${bucket[k].count}:${bucket[k].netSum.toFixed(2)}`)
        .join("|");
    });

    // Load stored monthly fingerprints from ScriptProperties
    let storedFingerprints = {};
    let scriptProps = null;
    try {
      scriptProps = PropertiesService.getScriptProperties();
      const rawFpJson = scriptProps.getProperty('PL_TXN_FINGERPRINTS');
      if (rawFpJson) storedFingerprints = JSON.parse(rawFpJson);
    } catch (propErr) {
      console.warn("[Expense Breakdown] Could not load stored fingerprints:", propErr.message);
    }

    // Build pre-sync transaction breakdown snapshot & cross-category/cross-month move context
    const plSyncDiffContext = buildPlSyncDiffContext_(
      headers,
      outgoingsData,
      cutoffDate,
      futureCutoff,
      expenseRows,
      unreconciledMap,
      fmtDate_,
      parseHeaderDate_,
      parseDateSafe_
    );

    let updatedMonthsCount = 0;
    let skippedMonthsCount = 0;

    const categoryRangeStartRow = outgoingsCategoryRows.length > 0 ? outgoingsCategoryRows[0].rowNum : -1;
    const categoryRangeEndRow = outgoingsCategoryRows.length > 0 ? outgoingsCategoryRows[outgoingsCategoryRows.length - 1].rowNum : -1;
    const categoryRangeHeight = (categoryRangeStartRow !== -1 && categoryRangeEndRow !== -1)
      ? (categoryRangeEndRow - categoryRangeStartRow + 1)
      : 0;

    for (let c = 0; c < headers.length; c++) {
      const hDate = parseHeaderDate_(headers[c]);
      if (!hDate) continue;

      // Restrict active delta processing to trailing 13 months window
      if (hDate < cutoffDate || hDate > futureCutoff) {
        continue;
      }

      const colIdx = c + 1; // 1-indexed for Sheets
      const targetYear = hDate.getFullYear();
      const targetMonth = hDate.getMonth();
      const monthKey = `${targetYear}-${String(targetMonth + 1).padStart(2, '0')}`;
      const isMonthComplete = Boolean(reconReadyMonthsMap.get(monthKey));

      // Delta Check: Read existing values in memory
      const curJson = String(outgoingsData[299]?.[c] || "").trim();
      const curCashVat = parseFloat(outgoingsData[303]?.[c]) || 0;
      const curAccrualVat = parseFloat(outgoingsData[304]?.[c]) || 0;

      // If month is NOT marked complete (CR2 unchecked / false / blank):
      // Treat as forecast! Ensure rows 300, 304, 305 remain clean/blank and do NOT overwrite Outgoings categories
      if (!isMonthComplete) {
        if (curJson !== "" || curCashVat !== 0 || curAccrualVat !== 0) {
          outgoingsSheet.getRange(300, colIdx).clearContent();
          outgoingsSheet.getRange(304, colIdx, 2, 1).clearContent();
          if (!outgoingsData[299]) outgoingsData[299] = new Array(headers.length).fill("");
          if (!outgoingsData[303]) outgoingsData[303] = new Array(headers.length).fill("");
          if (!outgoingsData[304]) outgoingsData[304] = new Array(headers.length).fill("");
          outgoingsData[299][c] = "";
          outgoingsData[303][c] = "";
          outgoingsData[304][c] = "";
          updatedMonthsCount++;
        } else {
          skippedMonthsCount++;
        }
        continue;
      }

      // 1. Month IS Reconciled & complete: Gather reconciled transactions where invoice Date falls in this month
      const monthTxns = [];
      const billsByCatNorm = new Map();
      const billsSumByCatNorm = new Map();
      let accrualVat = 0;
      let cashVat = 0;

      expenseRows.forEach(row => {
        const rawAccount = String(row[6] || "").trim();
        const code = rawAccount.split(' - ')[0].trim();
        if (contractorCodes.includes(code)) return;

        const invDate = parseDateSafe_(row[0]);
        const desc = String(row[1] || "").trim();
        const net = parseFloat(row[2]) || 0;
        const vat = parseFloat(row[3]) || 0;
        const gross = parseFloat(row[4]) || 0;
        const ref = String(row[5] || "").trim();
        const cleanCat = rawAccount.replace(/^\d+\s*[-–]\s*/, "").trim();
        const normCat = cleanCat.toLowerCase();

        // Strict expense filter: ONLY include categories that belong to valid P&L CoS/Overheads
        // or existing Outgoings categories! Ignore pensions, salaries, wages, taxes, etc.
        if (!validCategoriesMap.has(normCat) && !knownNormCats.has(normCat)) {
          return;
        }

        const paidDate = parseDateSafe_(row[9]);

        if (invDate && invDate.getFullYear() === targetYear && invDate.getMonth() === targetMonth) {
          accrualVat += vat;
          const billItem = {
            d: fmtDate_(invDate),
            c: cleanCat,
            s: desc,
            r: ref,
            n: Math.round(net * 100) / 100,
            v: Math.round(vat * 100) / 100,
            g: Math.round(gross * 100) / 100,
            p: paidDate ? fmtDate_(paidDate) : "",
            u: false
          };
          monthTxns.push(billItem);

          if (!billsByCatNorm.has(normCat)) billsByCatNorm.set(normCat, []);
          billsByCatNorm.get(normCat).push(billItem);
          billsSumByCatNorm.set(normCat, (billsSumByCatNorm.get(normCat) || 0) + net);
        }

        if (paidDate && paidDate.getFullYear() === targetYear && paidDate.getMonth() === targetMonth) {
          cashVat += vat;
        }
      });

      // 2. Append unreconciled items for this month
      const unrecForMonth = unreconciledMap.get(monthKey) || [];
      const unrecSumByCatNorm = new Map();
      unrecForMonth.forEach(u => {
        monthTxns.push(u);
        accrualVat += (u.v || 0);
        cashVat += (u.v || 0);
        const norm = String(u.c || "").replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
        unrecSumByCatNorm.set(norm, (unrecSumByCatNorm.get(norm) || 0) + (u.n || 0));
      });

      // 2.5 On-Demand Targeted Single-Month P&L Check:
      // Uses monthly transaction fingerprinting (count & net spend) stored in ScriptProperties.
      // Triggers a targeted single-month P&L pull ONLY when:
      // 1. Month is completely missing P&L data in PLFromApp / PLComp (e.g. April in Eleven), OR
      // 2. The live transaction fingerprint (count or netSum) changed compared to the stored snapshot, OR
      // 3. This is the latest active finalized closing month and periodic depreciation / P&L cooldown has expired (6 hours).
      // Unchanged historical months with existing P&L data are skipped with ZERO API calls!
      let plMonthData = plDataByMonth.get(monthKey);
      let hasPlForMonth = Boolean(plMonthData && plMonthData.categories && plMonthData.categories.size > 0);
      const isMissingPlData = !hasPlForMonth;

      const storedFp = storedFingerprints[monthKey];
      const freshFp = freshFingerprints[monthKey] || { count: 0, netSum: 0 };

      let hasFingerprintChanged = false;
      let changeDetails = "";

      if (!storedFp) {
        if (!isMissingPlData) {
          // If the month is already populated in PLFromApp/PLComp, initialize baseline fingerprint without an extra pull
          storedFingerprints[monthKey] = {
            count: freshFp.count,
            netSum: freshFp.netSum,
            catSig: freshFp.catSig || "",
            depChecked: true,
            lastCheckedAt: Date.now()
          };
        } else {
          hasFingerprintChanged = true;
          changeDetails = `initial snapshot (${freshFp.count} txns, £${freshFp.netSum.toFixed(2)})`;
        }
      } else if (storedFp.count !== freshFp.count || Math.abs(storedFp.netSum - freshFp.netSum) > 0.01) {
        hasFingerprintChanged = true;
        const countDiff = freshFp.count - storedFp.count;
        const sumDiff = freshFp.netSum - storedFp.netSum;
        const sign = sumDiff < 0 ? "-" : "+";
        changeDetails = `count ${storedFp.count}→${freshFp.count} (Δ ${countDiff}), sum £${storedFp.netSum.toFixed(2)}→£${freshFp.netSum.toFixed(2)} (Δ ${sign}£${Math.abs(sumDiff).toFixed(2)})`;
      } else if (typeof storedFp.catSig !== "string") {
        // Backfill category signature on legacy stored fingerprint without triggering an extra API call
        storedFp.catSig = freshFp.catSig || "";
      } else if (storedFp.catSig !== (freshFp.catSig || "")) {
        hasFingerprintChanged = true;
        changeDetails = "category allocation modified";
      }

      const isLatestFinalized = (monthKey === latestFinalizedMonthKey);

      // Periodic check cooldown for active closing month (6 hours)
      const SIX_HOURS_MS = 6 * 60 * 60 * 1000;
      const now = Date.now();
      const lastCheckedAt = storedFp?.lastCheckedAt || 0;
      const isCooldownExpired = (now - lastCheckedAt) > SIX_HOURS_MS;

      // Depreciation check is strictly scoped to the active closing month where journals may be posted during close.
      // Historical closed months already had P&L ingested (or will via isMissingPlData / hasFingerprintChanged).
      const isDepMissing = Boolean(
        isLatestFinalized &&
        depreciationTargetRow !== -1 &&
        (!plMonthData || !plMonthData.depreciation) &&
        (!storedFp?.depChecked || isCooldownExpired)
      );

      let shouldFetchLivePl = false;
      let fetchReason = "";
      if (isMissingPlData) {
        shouldFetchLivePl = true;
        fetchReason = "missing P&L data in Master Sheet";
      } else if (hasFingerprintChanged) {
        shouldFetchLivePl = true;
        fetchReason = `transactions modified in Xero [${changeDetails}]`;
      } else if (isDepMissing) {
        shouldFetchLivePl = true;
        fetchReason = "active closing month periodic depreciation check";
      } else if (isLatestFinalized && isCooldownExpired) {
        const activeCacheKey = `PL_ACTIVE_MONTH_${monthKey}`;
        let alreadyChecked = false;
        try {
          const cache = CacheService.getScriptCache();
          if (cache) alreadyChecked = Boolean(cache.get(activeCacheKey));
        } catch (cErr) {}
        if (!alreadyChecked) {
          shouldFetchLivePl = true;
          fetchReason = "active closing month periodic check";
        }
      }

      if (shouldFetchLivePl) {
        console.log(`[Expense Breakdown] Fetching targeted live P&L for ${monthKey} (reason: ${fetchReason})...`);
        const fromDateStr = `${targetYear}-${String(targetMonth + 1).padStart(2, '0')}-01`;
        const lastDay = new Date(targetYear, targetMonth + 1, 0).getDate();
        const toDateStr = `${targetYear}-${String(targetMonth + 1).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

        const freshPl = (await fetchSingleMonthPLReport_(fromDateStr, toDateStr));
        if (freshPl) {
          (await updateSingleMonthPLInSheet_(ss, monthKey, targetYear, targetMonth, freshPl));
          if (!plMonthData) {
            plMonthData = { categories: new Map(), depreciation: 0 };
            plDataByMonth.set(monthKey, plMonthData);
          }
          freshPl.categories.forEach((item, norm) => {
            if (validCategoriesMap.has(norm)) {
              plMonthData.categories.set(norm, item.amount);
            }
          });
          if (freshPl.depreciation > 0) {
            plMonthData.depreciation = freshPl.depreciation;
          }
          hasPlForMonth = true;
          console.log(`[Expense Breakdown] Live P&L refreshed and written to PLFromApp for ${monthKey}.`);
          // Record verified fingerprint and mark depreciation checked with timestamp
          storedFingerprints[monthKey] = {
            count: freshFp.count,
            netSum: freshFp.netSum,
            catSig: freshFp.catSig || "",
            depChecked: true,
            lastCheckedAt: Date.now()
          };
        }
        if (isLatestFinalized) {
          try {
            const cache = CacheService.getScriptCache();
            if (cache) cache.put(`PL_ACTIVE_MONTH_${monthKey}`, "true", 21600); // 6 hours (GAS maximum)
          } catch (cErr) {}
        }
      }

      // 3. Automated Outgoings Categories Sync (Rows 125-225) sourced from PLComp / PLFromApp
      const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0);
      const monthEndStr = fmtDate_(lastDayOfMonth);

      const categoryChanges = [];
      let monthNetDelta = 0;
      let categoriesDirty = false;

      if (outgoingsCategoryRows.length > 0) {
        outgoingsCategoryRows.forEach(cat => {
          let targetVal = 0;
          const curCatVal = parseFloat(outgoingsData[cat.rowIdx][c]) || 0;

          if (cat.isDepreciation) {
            // Depreciation Handling: Sourced from Live P&L / PLComp Row 29 / PLFromApp Row 19
            if (plMonthData && plMonthData.depreciation > 0) {
              targetVal = plMonthData.depreciation;
            } else if (curCatVal > 0) {
              // Preserve existing non-zero depreciation (never wipe to £0 if P&L is 0 or missing for this month)
              targetVal = curCatVal;
            } else {
              targetVal = 0;
            }

            if (targetVal > 0) {
              monthTxns.push({
                d: monthEndStr,
                c: cat.name,
                s: "Depreciation (from P&L)",
                r: "P&L",
                n: Math.round(targetVal * 100) / 100,
                v: 0,
                g: Math.round(targetVal * 100) / 100,
                p: "",
                u: false
              });
            }
          } else {
            // General Overhead Expense Category
            const unrecNet = unrecSumByCatNorm.get(cat.normName) || 0;
            const billsSum = billsSumByCatNorm.get(cat.normName) || 0;

            if (hasPlForMonth && plMonthData.categories.has(cat.normName)) {
              // Sourced from official P&L report + uncleared unreconciled items
              const plVal = plMonthData.categories.get(cat.normName) || 0;
              targetVal = Math.round((plVal + unrecNet) * 100) / 100;

              // Check for manual journal difference between P&L and bills
              const journalDiff = Math.round((plVal - billsSum) * 100) / 100;
              if (Math.abs(journalDiff) >= 0.01) {
                monthTxns.push({
                  d: monthEndStr,
                  c: cat.name,
                  s: "Journal / adjustment (from P&L)",
                  r: "P&L",
                  n: journalDiff,
                  v: 0,
                  g: journalDiff,
                  p: "",
                  u: false
                });
              }
            } else if (hasPlForMonth) {
              // P&L exists for this month, but category has 0 in P&L
              targetVal = Math.round(unrecNet * 100) / 100;
              const journalDiff = Math.round((0 - billsSum) * 100) / 100;
              if (Math.abs(journalDiff) >= 0.01) {
                monthTxns.push({
                  d: monthEndStr,
                  c: cat.name,
                  s: "Journal / adjustment (from P&L)",
                  r: "P&L",
                  n: journalDiff,
                  v: 0,
                  g: journalDiff,
                  p: "",
                  u: false
                });
              }
            } else {
              // Outside P&L window: preserve existing value
              targetVal = curCatVal;
            }
          }

          if (Math.abs(curCatVal - targetVal) > 0.01) {
            outgoingsData[cat.rowIdx][c] = targetVal;
            categoriesDirty = true;
            const delta = targetVal - curCatVal;
            const sign = delta < 0 ? "-" : "+";
            const reasonLines = buildOutgoingsCategoryChangeLines_(
              cat,
              monthKey,
              curCatVal,
              targetVal,
              monthTxns,
              plSyncDiffContext
            );
            const reasonBlock = reasonLines.length > 0 ? "\n" + reasonLines.join("\n") : "";
            categoryChanges.push(`• ${cat.name}: £${curCatVal.toFixed(2)} → £${targetVal.toFixed(2)} (Δ ${sign}£${Math.abs(delta).toFixed(2)})${reasonBlock}`);
            monthNetDelta += delta;
          }
        });
      }

      // Sort transactions chronologically
      monthTxns.sort((a, b) => {
        const da = new Date(a.d).getTime() || 0;
        const db = new Date(b.d).getTime() || 0;
        return da - db;
      });

      const newJson = monthTxns.length > 0 ? JSON.stringify(monthTxns) : "";
      const newCashVat = Math.round(cashVat * 100) / 100;
      const newAccrualVat = Math.round(accrualVat * 100) / 100;

      const isJsonEqual = (curJson === newJson);
      const isCashVatEqual = (Math.abs(curCashVat - newCashVat) < 0.01);
      const isAccrualVatEqual = (Math.abs(curAccrualVat - newAccrualVat) < 0.01);

      // Perform bulk writes for this month if anything was modified
      if (categoryRangeStartRow !== -1 && categoryRangeHeight > 0) {
        const targetMonthRange = outgoingsSheet.getRange(categoryRangeStartRow, colIdx, categoryRangeHeight, 1);
        if (categoriesDirty) {
          const colSlice = [];
          for (let r = categoryRangeStartRow - 1; r < categoryRangeEndRow; r++) {
            colSlice.push([outgoingsData[r][c]]);
          }
          targetMonthRange.setValues(colSlice);
        }
        // Clear shading for finalized month's actuals (matching original pushOutgoings)
        targetMonthRange.setBackground(null);

        // Highlight cells of newly provisioned categories for this month with peach (#ffcc99)
        newlyAddedRowNums.forEach(rowNum => {
          outgoingsSheet.getRange(rowNum, colIdx).setBackground("#ffcc99");
        });
      }

      if (!isJsonEqual || !isCashVatEqual || !isAccrualVatEqual) {
        outgoingsSheet.getRange(300, colIdx)
          .setValue(newJson)
          .setFontSize(9)
          .setFontColor("#64748b")
          .setWrapStrategy(SpreadsheetApp.WrapStrategy.CLIP);

        outgoingsSheet.getRange(304, colIdx, 2, 1).setValues([
          [newCashVat],
          [newAccrualVat]
        ]);
        outgoingsSheet.getRange(304, colIdx, 2, 1)
          .setNumberFormat("£#,##0.00")
          .setFontWeight("bold");

        if (!outgoingsData[299]) outgoingsData[299] = new Array(headers.length).fill("");
        if (!outgoingsData[303]) outgoingsData[303] = new Array(headers.length).fill("");
        if (!outgoingsData[304]) outgoingsData[304] = new Array(headers.length).fill("");
        outgoingsData[299][c] = newJson;
        outgoingsData[303][c] = newCashVat;
        outgoingsData[304][c] = newAccrualVat;
      }

      if (categoriesDirty || !isJsonEqual || !isCashVatEqual || !isAccrualVatEqual) {
        updatedMonthsCount++;
      } else {
        skippedMonthsCount++;
      }

      // If category amounts were updated for this finalized month, log directly to Master AutoLog
      if (categoryChanges.length > 0 && typeof writeToAutoLog === 'function') {
        const deltaSign = monthNetDelta < 0 ? "-" : "+";
        const formattedDelta = `${deltaSign}£${Math.abs(monthNetDelta).toFixed(2)}`;
        const summary = `P&L outgoings updated: ${monthKey} (Δ ${formattedDelta})`;
        const details = `Automated P&L sync updated Outgoings for finalized month ${monthKey}:\n` + categoryChanges.join("\n");
        writeToAutoLog("EXPENSES", summary, details);
        console.log(`[Expense Breakdown] Logged Outgoings update to AutoLog for ${monthKey}: ${summary}`);
      }
    }

    // Persist updated transaction fingerprints to ScriptProperties
    try {
      if (scriptProps) {
        scriptProps.setProperty('PL_TXN_FINGERPRINTS', JSON.stringify(storedFingerprints));
      }
    } catch (saveErr) {
      console.warn("[Expense Breakdown] Could not persist fingerprints to ScriptProperties:", saveErr.message);
    }

    const summaryMsg = `[Expense Breakdown] Synced: ${updatedMonthsCount} month(s) updated, ${skippedMonthsCount} unchanged month(s) skipped.`;
    console.log(summaryMsg);
    if (!isHeadless) {
      const ui = SpreadsheetApp.getUi();
      if (ui) ui.alert(summaryMsg);
    }
    return { success: true, updated: updatedMonthsCount, skipped: skippedMonthsCount };
  } catch (err) {
    console.error("[Expense Breakdown] Sync error:", err);
    if (!isHeadless) {
      const ui = SpreadsheetApp.getUi();
      if (ui) ui.alert("Error syncing expense breakdown: " + err.message);
    }
    return { success: false, error: err.message };
  }
}

/**
 * Manual menu trigger for syncing expense transaction breakdown & VAT to Client Sheet.
 */
async function syncExpenseTransactionBreakdownManual() {
  (await syncExpenseTransactionBreakdownToClientSheet_(false));
}

/**
 * Builds pre-sync transaction breakdown snapshots across all months from Outgoings Row 300
 * along with global removed/added transaction pools (including contractor/non-overhead categories)
 * to attribute cross-category and cross-month transaction movements.
 */
function buildPlSyncDiffContext_(
  headers,
  outgoingsData,
  cutoffDate,
  futureCutoff,
  expenseRows,
  unreconciledMap,
  fmtDate_,
  parseHeaderDate_,
  parseDateSafe_
) {
  const normCatFn = (s) => String(s || "").replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
  const normStrFn = (s) => String(s || "").toLowerCase().trim();
  const normRefFn = (r) => {
    const v = String(r || "").trim();
    if (!v || v === "UNRECON" || v === "P&L" || v.toLowerCase() === "manual journal") return "";
    return v.toLowerCase();
  };

  const prevTxnsByMonth = new Map(); // monthKey -> Array<txn>
  const prevBuckets = new Map();     // "monthKey||normCat" -> Array<txn>
  const newBuckets = new Map();      // "monthKey||normCat" -> Array<txn>

  // 1. Parse existing Row 300 JSON across all month columns
  for (let c = 0; c < headers.length; c++) {
    const hDate = parseHeaderDate_(headers[c]);
    if (!hDate || hDate < cutoffDate || hDate > futureCutoff) continue;
    const mKey = `${hDate.getFullYear()}-${String(hDate.getMonth() + 1).padStart(2, '0')}`;
    const rawJson = String(outgoingsData[299]?.[c] || "").trim();
    if (!rawJson) continue;
    try {
      const parsed = JSON.parse(rawJson);
      if (Array.isArray(parsed)) {
        prevTxnsByMonth.set(mKey, parsed);
        parsed.forEach(t => {
          if (!t || t.r === "P&L") return;
          const nCat = normCatFn(t.c);
          if (!nCat) return;
          const bKey = `${mKey}||${nCat}`;
          if (!prevBuckets.has(bKey)) prevBuckets.set(bKey, []);
          prevBuckets.get(bKey).push({
            d: String(t.d || ""),
            c: String(t.c || "").replace(/^\d+\s*[-–]\s*/, "").trim(),
            s: String(t.s || "").trim(),
            r: String(t.r || "").trim(),
            n: Math.round((parseFloat(t.n) || 0) * 100) / 100,
            g: Math.round((parseFloat(t.g ?? t.n) || 0) * 100) / 100,
            u: Boolean(t.u),
            monthKey: mKey,
            normCat: nCat
          });
        });
      }
    } catch (e) {}
  }

  // 2. Collect all live transactions across all months and categories (including contractor/direct cost categories)
  (expenseRows || []).forEach(row => {
    const rawAccount = String(row[6] || "").trim();
    if (!rawAccount) return;
    const invDate = parseDateSafe_(row[0]);
    if (!invDate || invDate < cutoffDate || invDate > futureCutoff) return;
    const mKey = `${invDate.getFullYear()}-${String(invDate.getMonth() + 1).padStart(2, '0')}`;
    const cleanCat = rawAccount.replace(/^\d+\s*[-–]\s*/, "").trim();
    const nCat = cleanCat.toLowerCase();
    if (!nCat) return;
    const net = Math.round((parseFloat(row[2]) || 0) * 100) / 100;
    const gross = Math.round((parseFloat(row[4]) || net) * 100) / 100;
    const bKey = `${mKey}||${nCat}`;
    if (!newBuckets.has(bKey)) newBuckets.set(bKey, []);
    newBuckets.get(bKey).push({
      d: fmtDate_(invDate),
      c: cleanCat,
      s: String(row[1] || "").trim(),
      r: String(row[5] || "").trim(),
      n: net,
      g: gross,
      u: false,
      monthKey: mKey,
      normCat: nCat
    });
  });

  if (unreconciledMap && typeof unreconciledMap.forEach === "function") {
    unreconciledMap.forEach((items, mKey) => {
      (items || []).forEach(u => {
        const cleanCat = String(u.c || "").replace(/^\d+\s*[-–]\s*/, "").trim();
        const nCat = cleanCat.toLowerCase();
        if (!nCat) return;
        const bKey = `${mKey}||${nCat}`;
        if (!newBuckets.has(bKey)) newBuckets.set(bKey, []);
        newBuckets.get(bKey).push({
          d: String(u.d || ""),
          c: cleanCat,
          s: String(u.s || "").trim(),
          r: String(u.r || "UNRECON").trim(),
          n: Math.round((parseFloat(u.n) || 0) * 100) / 100,
          g: Math.round((parseFloat(u.g ?? u.n) || 0) * 100) / 100,
          u: true,
          monthKey: mKey,
          normCat: nCat
        });
      });
    });
  }

  // 3. Pair transactions that remained within the same (monthKey, normCat) so only genuinely added/removed items enter the global move pools
  const globalRemovedPool = [];
  const globalAddedPool = [];
  const allBucketKeys = new Set([...prevBuckets.keys(), ...newBuckets.keys()]);

  allBucketKeys.forEach(bKey => {
    const pList = prevBuckets.get(bKey) || [];
    const nList = newBuckets.get(bKey) || [];
    const pUsed = new Array(pList.length).fill(false);
    const nUsed = new Array(nList.length).fill(false);

    // Pass A: Exact / same-amount match within same (monthKey, normCat)
    for (let i = 0; i < pList.length; i++) {
      const p = pList[i];
      for (let j = 0; j < nList.length; j++) {
        if (nUsed[j]) continue;
        const n = nList[j];
        if (Math.abs(p.n - n.n) < 0.01) {
          const pRef = normRefFn(p.r);
          const nRef = normRefFn(n.r);
          const sameRef = Boolean(pRef && nRef && pRef === nRef);
          const sameDesc = normStrFn(p.s) === normStrFn(n.s);
          if (sameRef || sameDesc) {
            pUsed[i] = true;
            nUsed[j] = true;
            break;
          }
        }
      }
    }

    // Pass B: In-place amount edit within same (monthKey, normCat)
    for (let i = 0; i < pList.length; i++) {
      if (pUsed[i]) continue;
      const p = pList[i];
      const pRef = normRefFn(p.r);
      for (let j = 0; j < nList.length; j++) {
        if (nUsed[j]) continue;
        const n = nList[j];
        const nRef = normRefFn(n.r);
        const sameRef = Boolean(pRef && nRef && pRef === nRef);
        const sameDescAndDate = Boolean(normStrFn(p.s) && normStrFn(p.s) === normStrFn(n.s) && p.d && p.d === n.d);
        if (sameRef || sameDescAndDate) {
          pUsed[i] = true;
          nUsed[j] = true;
          break;
        }
      }
    }

    for (let i = 0; i < pList.length; i++) {
      if (!pUsed[i]) globalRemovedPool.push(pList[i]);
    }
    for (let j = 0; j < nList.length; j++) {
      if (!nUsed[j]) globalAddedPool.push(nList[j]);
    }
  });

  return {
    prevTxnsByMonth,
    globalRemovedPool,
    globalAddedPool
  };
}

/**
 * Generates human-readable sub-bullet lines explaining which transaction(s) caused an Outgoings
 * category total to change from curCatVal to targetVal for a finalized month.
 */
function buildOutgoingsCategoryChangeLines_(
  cat,
  monthKey,
  curCatVal,
  targetVal,
  monthTxns,
  plSyncDiffContext
) {
  const normCatFn = (s) => String(s || "").replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
  const normStrFn = (s) => String(s || "").toLowerCase().trim();
  const normRefFn = (r) => {
    const v = String(r || "").trim();
    if (!v || v === "UNRECON" || v === "P&L" || v.toLowerCase() === "manual journal") return "";
    return v.toLowerCase();
  };
  const fmtSigned = (val) => {
    const sign = val < 0 ? "-" : "+";
    return `${sign}£${Math.abs(val).toFixed(2)}`;
  };
  const isSimilarPayee = (a, b) => {
    const sa = normStrFn(a);
    const sb = normStrFn(b);
    if (!sa || !sb) return false;
    if (sa === sb) return true;
    const baseA = sa.split("(")[0].trim();
    const baseB = sb.split("(")[0].trim();
    if (baseA.length >= 3 && baseB.length >= 3 && (baseA.includes(baseB) || baseB.includes(baseA))) {
      return true;
    }
    return false;
  };
  const formatTxnBrief = (t, includeRef = true) => {
    const desc = String(t.s || "Transaction").trim();
    const ref = String(t.r || "").trim();
    const hasRealRef = includeRef && ref && ref !== "UNRECON" && ref !== "P&L" && !desc.toLowerCase().includes(ref.toLowerCase());
    const refPart = hasRealRef ? ` [Ref: ${ref}]` : "";
    const datePart = (t.d && ref !== "P&L") ? ` on ${t.d}` : "";
    return `${desc}${refPart}${datePart}`;
  };

  const prevMonthTxns = plSyncDiffContext?.prevTxnsByMonth?.get(monthKey) || null;
  const isCatMatch = (t) => {
    if (!t) return false;
    if (cat.isDepreciation) {
      return normCatFn(t.c) === cat.normName || normStrFn(t.s).includes("depreciation");
    }
    return normCatFn(t.c) === cat.normName;
  };

  const newCatTxns = (monthTxns || []).filter(isCatMatch).map(t => ({
    d: String(t.d || ""),
    c: String(t.c || ""),
    s: String(t.s || "").trim(),
    r: String(t.r || "").trim(),
    n: Math.round((parseFloat(t.n) || 0) * 100) / 100,
    g: Math.round((parseFloat(t.g ?? t.n) || 0) * 100) / 100,
    u: Boolean(t.u)
  }));

  // Case A: No previous Row 300 JSON snapshot existed for this month
  if (!prevMonthTxns) {
    const lines = [];
    if (Math.abs(curCatVal) >= 0.01 && newCatTxns.length === 0) {
      lines.push(`  - Replaced prior forecast/manual figure (£${curCatVal.toFixed(2)}) with P&L actual (£0.00)`);
      return lines;
    }
    if (Math.abs(curCatVal) >= 0.01) {
      lines.push(`  - Replaced prior forecast/manual figure (£${curCatVal.toFixed(2)}) with finalized P&L actuals (£${targetVal.toFixed(2)}):`);
    }
    newCatTxns.slice(0, 8).forEach(n => {
      if (n.r === "P&L") {
        lines.push(`  - ${n.s}: ${fmtSigned(n.n)}`);
      } else if (n.u) {
        lines.push(`  - Unreconciled item: ${formatTxnBrief(n, false)} (${fmtSigned(n.n)})`);
      } else {
        lines.push(`  - ${formatTxnBrief(n)} (${fmtSigned(n.n)})`);
      }
    });
    if (newCatTxns.length > 8) {
      lines.push(`  - ...and ${newCatTxns.length - 8} more transaction(s)`);
    }
    return lines;
  }

  const prevCatTxns = prevMonthTxns.filter(isCatMatch).map(t => ({
    d: String(t.d || ""),
    c: String(t.c || ""),
    s: String(t.s || "").trim(),
    r: String(t.r || "").trim(),
    n: Math.round((parseFloat(t.n) || 0) * 100) / 100,
    g: Math.round((parseFloat(t.g ?? t.n) || 0) * 100) / 100,
    u: Boolean(t.u)
  }));

  const prevTxnsSum = Math.round(prevCatTxns.reduce((acc, t) => acc + t.n, 0) * 100) / 100;
  const pUsed = new Array(prevCatTxns.length).fill(false);
  const nUsed = new Array(newCatTxns.length).fill(false);

  // Pass 1: Exact match (unchanged transactions)
  for (let i = 0; i < prevCatTxns.length; i++) {
    const p = prevCatTxns[i];
    for (let j = 0; j < newCatTxns.length; j++) {
      if (nUsed[j]) continue;
      const n = newCatTxns[j];
      if (
        p.u === n.u &&
        (p.r === "P&L") === (n.r === "P&L") &&
        normStrFn(p.s) === normStrFn(n.s) &&
        normStrFn(p.r) === normStrFn(n.r) &&
        p.d === n.d &&
        Math.abs(p.n - n.n) < 0.01
      ) {
        pUsed[i] = true;
        nUsed[j] = true;
        break;
      }
    }
  }

  // Pass 2: Same net amount with matching ref, description, or reconciled placeholder (£0.00 net impact on category)
  for (let i = 0; i < prevCatTxns.length; i++) {
    if (pUsed[i]) continue;
    const p = prevCatTxns[i];
    for (let j = 0; j < newCatTxns.length; j++) {
      if (nUsed[j]) continue;
      const n = newCatTxns[j];
      if (Math.abs(p.n - n.n) < 0.01 && (p.r === "P&L") === (n.r === "P&L")) {
        const pRef = normRefFn(p.r);
        const nRef = normRefFn(n.r);
        const sameRef = Boolean(pRef && nRef && pRef === nRef);
        const sameDesc = normStrFn(p.s) === normStrFn(n.s);
        const unrecToRecMatch = (p.u !== n.u) && (p.d === n.d || isSimilarPayee(p.s, n.s));
        if (sameRef || sameDesc || unrecToRecMatch) {
          pUsed[i] = true;
          nUsed[j] = true;
          break;
        }
      }
    }
  }

  const subLines = [];

  // Pass 3: Modified transactions in the same category & month (amount changed)
  for (let i = 0; i < prevCatTxns.length; i++) {
    if (pUsed[i]) continue;
    const p = prevCatTxns[i];
    for (let j = 0; j < newCatTxns.length; j++) {
      if (nUsed[j]) continue;
      const n = newCatTxns[j];
      const diff = Math.round((n.n - p.n) * 100) / 100;
      if (Math.abs(diff) < 0.01) continue;

      // 3a: Synthetic P&L line (Journal / adjustment or Depreciation)
      if (p.r === "P&L" && n.r === "P&L" && normStrFn(p.s) === normStrFn(n.s)) {
        pUsed[i] = true;
        nUsed[j] = true;
        subLines.push(`  - Updated ${n.s}: £${p.n.toFixed(2)} → £${n.n.toFixed(2)} (Δ ${fmtSigned(diff)})`);
        break;
      }

      if (p.r === "P&L" || n.r === "P&L") continue;

      // 3b: Same non-empty invoice/bill reference
      const pRef = normRefFn(p.r);
      const nRef = normRefFn(n.r);
      if (!p.u && !n.u && pRef && nRef && pRef === nRef && (isSimilarPayee(p.s, n.s) || p.d === n.d)) {
        pUsed[i] = true;
        nUsed[j] = true;
        const dateNote = (p.d && n.d && p.d !== n.d) ? ` (date ${p.d} → ${n.d})` : "";
        subLines.push(`  - Amount changed: ${formatTxnBrief(n)}${dateNote}: £${p.n.toFixed(2)} → £${n.n.toFixed(2)} (Δ ${fmtSigned(diff)})`);
        break;
      }

      // 3c: Same description and same date
      if (p.u === n.u && normStrFn(p.s) && normStrFn(p.s) === normStrFn(n.s) && p.d === n.d) {
        pUsed[i] = true;
        nUsed[j] = true;
        const labelPrefix = n.u ? "Unreconciled item updated" : "Amount changed";
        subLines.push(`  - ${labelPrefix}: ${formatTxnBrief(n, !n.u)}: £${p.n.toFixed(2)} → £${n.n.toFixed(2)} (Δ ${fmtSigned(diff)})`);
        break;
      }

      // 3d: Unreconciled placeholder reconciled into an official bill with a different net amount (e.g. VAT extracted)
      if (p.u && !n.u && (Math.abs(p.g - n.g) < 0.01 || (p.d === n.d && isSimilarPayee(p.s, n.s)))) {
        pUsed[i] = true;
        nUsed[j] = true;
        subLines.push(`  - Reconciled with updated net amount: ${formatTxnBrief(n)}: £${p.n.toFixed(2)} (unreconciled) → £${n.n.toFixed(2)} (reconciled) (Δ ${fmtSigned(diff)})`);
        break;
      }
    }
  }

  // Helper to match a transaction against global added/removed pools across other categories/months
  const findCrossPoolMatch = (txn, pool) => {
    if (!Array.isArray(pool) || txn.r === "P&L") return null;
    const tRef = normRefFn(txn.r);

    // Priority 1: Matching non-empty Ref + (similar supplier or same net amount)
    if (tRef) {
      const m1 = pool.find(cand => {
        if (cand.monthKey === monthKey && cand.normCat === cat.normName) return false;
        const cRef = normRefFn(cand.r);
        return cRef === tRef && (Math.abs(cand.n - txn.n) < 0.01 || isSimilarPayee(cand.s, txn.s));
      });
      if (m1) return m1;
    }

    // Priority 2: Same supplier/description + same date + same amount (recategorized in same month)
    const m2 = pool.find(cand => {
      if (cand.monthKey === monthKey && cand.normCat === cat.normName) return false;
      return Boolean(normStrFn(txn.s) && normStrFn(cand.s) === normStrFn(txn.s) && cand.d === txn.d && Math.abs(cand.n - txn.n) < 0.01);
    });
    if (m2) return m2;

    // Priority 3: Same supplier/description + same amount across a different month (date changed)
    const m3 = pool.find(cand => {
      if (cand.monthKey === monthKey && cand.normCat === cat.normName) return false;
      return Boolean(normStrFn(txn.s) && normStrFn(cand.s) === normStrFn(txn.s) && Math.abs(cand.n - txn.n) < 0.01);
    });
    if (m3) return m3;

    // Priority 4: Unreconciled item reconciled into another category on same date / gross amount
    if (txn.u) {
      const m4 = pool.find(cand => {
        if (cand.monthKey === monthKey && cand.normCat === cat.normName) return false;
        return !cand.u && cand.monthKey === monthKey && (Math.abs(cand.g - txn.g) < 0.01 || Math.abs(cand.n - txn.n) < 0.01) && (cand.d === txn.d || isSimilarPayee(cand.s, txn.s));
      });
      if (m4) return m4;
    }

    return null;
  };

  // Pass 4: Remaining unmatched previous transactions (Removed or Moved out of this category/month)
  for (let i = 0; i < prevCatTxns.length; i++) {
    if (pUsed[i]) continue;
    const p = prevCatTxns[i];
    const impact = Math.round((-p.n) * 100) / 100;
    if (Math.abs(impact) < 0.01) continue;

    if (p.r === "P&L") {
      subLines.push(`  - Removed ${p.s}: ${fmtSigned(impact)}`);
      continue;
    }

    const movedTo = findCrossPoolMatch(p, plSyncDiffContext?.globalAddedPool);
    if (movedTo) {
      if (movedTo.monthKey === monthKey && movedTo.normCat !== cat.normName) {
        const amtChangeNote = Math.abs(movedTo.n - p.n) >= 0.01 ? `, updated to £${movedTo.n.toFixed(2)}` : "";
        subLines.push(`  - Moved to ${movedTo.c}: ${formatTxnBrief(p, !p.u)} (${fmtSigned(impact)}${amtChangeNote})`);
      } else {
        const catNote = movedTo.normCat !== cat.normName ? `, ${movedTo.c}` : "";
        subLines.push(`  - Moved to ${movedTo.monthKey} (new date ${movedTo.d || "N/A"}${catNote}): ${formatTxnBrief(p, !p.u)} (${fmtSigned(impact)})`);
      }
      continue;
    }

    if (p.u) {
      const hasReconciledInCat = newCatTxns.some(t =>
        !t.u && t.r !== "P&L" && (Math.abs(t.n - p.n) < 0.01 || Math.abs(t.g - p.g) < 0.01 || isSimilarPayee(p.s, t.s))
      );
      if (hasReconciledInCat) {
        subLines.push(`  - Unreconciled item cleared (reconciled in accounting): ${formatTxnBrief(p, false)} (${fmtSigned(impact)})`);
      } else {
        subLines.push(`  - Removed unreconciled item: ${formatTxnBrief(p, false)} (${fmtSigned(impact)})`);
      }
    } else {
      subLines.push(`  - Removed: ${formatTxnBrief(p)} (${fmtSigned(impact)})`);
    }
  }

  // Pass 5: Remaining unmatched new transactions (Added or Moved into this category/month)
  for (let j = 0; j < newCatTxns.length; j++) {
    if (nUsed[j]) continue;
    const n = newCatTxns[j];
    const impact = Math.round(n.n * 100) / 100;
    if (Math.abs(impact) < 0.01) continue;

    if (n.r === "P&L") {
      subLines.push(`  - Added ${n.s}: ${fmtSigned(impact)}`);
      continue;
    }

    const movedFrom = findCrossPoolMatch(n, plSyncDiffContext?.globalRemovedPool);
    if (movedFrom) {
      if (movedFrom.monthKey === monthKey && movedFrom.normCat !== cat.normName) {
        subLines.push(`  - Moved from ${movedFrom.c}: ${formatTxnBrief(n, !n.u)} (${fmtSigned(impact)})`);
      } else {
        const catNote = movedFrom.normCat !== cat.normName ? `, ${movedFrom.c}` : "";
        subLines.push(`  - Moved from ${movedFrom.monthKey} (was ${movedFrom.d || "N/A"}${catNote}): ${formatTxnBrief(n, !n.u)} (${fmtSigned(impact)})`);
      }
      continue;
    }

    if (n.u) {
      subLines.push(`  - Added unreconciled item: ${formatTxnBrief(n, false)} (${fmtSigned(impact)})`);
    } else {
      subLines.push(`  - Added: ${formatTxnBrief(n)} (${fmtSigned(impact)})`);
    }
  }

  // Pass 6: Account for any prior manual/forecast variance between curCatVal and prevTxnsSum
  const priorCellVariance = Math.round((prevTxnsSum - curCatVal) * 100) / 100;
  if (Math.abs(priorCellVariance) >= 0.01) {
    if (subLines.length === 0) {
      subLines.push(`  - Adjusted from prior manual/forecast figure (£${curCatVal.toFixed(2)}) to match P&L breakdown (£${targetVal.toFixed(2)}, Δ ${fmtSigned(targetVal - curCatVal)})`);
    } else {
      subLines.push(`  - Prior manual/forecast variance adjusted: ${fmtSigned(priorCellVariance)}`);
    }
  }

  if (subLines.length > 10) {
    const extra = subLines.length - 10;
    return [...subLines.slice(0, 10), `  - ...and ${extra} more transaction change(s)`];
  }

  return subLines;
}

/**
 * Fetches a single month's Profit & Loss report directly from the accounting software (Xero or QuickBooks)
 * for a targeted date range (e.g. fromDateStr = '2026-09-01', toDateStr = '2026-09-30').
 */
async function fetchSingleMonthPLReport_(fromDateStr, toDateStr) {
  const rawToolName = (await getKeyInfoValue('Q4'));
  const toolName = String(rawToolName || "").trim().toLowerCase();
  const plMap = new Map(); // normName -> { originalTitle, amount }
  let depreciationVal = 0;

  try {
    if (toolName === 'xero') {
      const accessToken = (await getXeroAccessToken());
      const xeroTenantId = (await getKeyInfoValue('X2'));
      if (!accessToken || !xeroTenantId) {
        console.warn("[Single P&L] Missing Xero access token or tenant ID.");
        return null;
      }

      const url = `https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss?fromDate=${fromDateStr}&toDate=${toDateStr}&standardLayout=false`;
      const options = {
        method: 'get',
        headers: {
          'Authorization': 'Bearer ' + accessToken,
          'xero-tenant-id': xeroTenantId,
          'Accept': 'application/json'
        },
        muteHttpExceptions: true
      };
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) {
        console.warn(`[Single P&L] Xero P&L fetch failed for ${fromDateStr}..${toDateStr}: ${response.getContentText()}`);
        return null;
      }

      const json = JSON.parse(response.getContentText());
      const report = json.Reports?.[0];
      if (!report || !report.Rows) return null;

      const processXeroRow = (r) => {
        if (r.RowType === 'Section' && r.Rows) {
          r.Rows.forEach(processXeroRow);
        } else if ((r.RowType === 'Row' || r.RowType === 'SummaryRow') && r.Cells && r.Cells.length > 1) {
          const rawTitle = String(r.Cells[0]?.Value || "").trim();
          const rawVal = r.Cells[1]?.Value;
          if (!rawTitle) return;
          const numVal = parseFloat(String(rawVal || "0").replace(/[£$€,\s]/g, "")) || 0;
          const norm = rawTitle.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
          if (norm.includes("depreciation")) {
            depreciationVal = numVal;
          }
          if (r.RowType === 'Row') {
            plMap.set(norm, { originalTitle: rawTitle, amount: numVal });
          }
        }
      };
      report.Rows.forEach(processXeroRow);

    } else if (toolName.includes('quickbook')) {
      const accessToken = (await getQBAccessToken());
      const realmId = String((await getKeyInfoValue('X3')) || '').trim();
      if (!accessToken || !realmId || !/^[0-9a-zA-Z_-]+$/.test(realmId)) {
        console.warn("[Single P&L] Missing or invalid QuickBooks access token or realm ID.");
        return null;
      }

      const baseUrl = "https://quickbooks.api.intuit.com";
      const url = `${baseUrl}/v3/company/${realmId}/reports/ProfitAndLoss?start_date=${fromDateStr}&end_date=${toDateStr}`;
      const options = {
        method: 'get',
        headers: {
          'Authorization': 'Bearer ' + accessToken,
          'Accept': 'application/json'
        },
        muteHttpExceptions: true
      };
      const response = (await UrlFetchApp.fetch(url, options));
      if (response.getResponseCode() !== 200) {
        console.warn(`[Single P&L] QuickBooks P&L fetch failed for ${fromDateStr}..${toDateStr}: ${response.getContentText()}`);
        return null;
      }

      const json = JSON.parse(response.getContentText());
      const processQBRow = (r) => {
        if (r.type === 'Section' && r.Rows?.Row) {
          r.Rows.Row.forEach(processQBRow);
        }
        const colData = (r.ColData && r.ColData.length > 1) ? r.ColData : (r.Summary?.ColData && r.Summary.ColData.length > 1 ? r.Summary.ColData : null);
        if (colData) {
          const rawTitle = String(colData[0]?.value || "").trim();
          const rawVal = colData[1]?.value;
          if (!rawTitle) return;
          const numVal = parseFloat(String(rawVal || "0").replace(/[£$€,\s]/g, "")) || 0;
          const norm = rawTitle.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
          if (norm.includes("depreciation")) {
            depreciationVal = numVal;
          }
          plMap.set(norm, { originalTitle: rawTitle, amount: numVal });
        }
      };
      if (json?.Rows?.Row) {
        json.Rows.Row.forEach(processQBRow);
      }
    }

    return { categories: plMap, depreciation: depreciationVal };
  } catch (err) {
    console.error("[Single P&L] Error fetching single month P&L:", err.message);
    return null;
  }
}

/**
 * Writes a fresh single-month P&L report into the Master Sheet's PLFromApp tab.
 * Locates or creates the month's column, aligns every category with Column A,
 * and carefully inserts new rows if additional categories exist in Xero/QB.
 */
async function updateSingleMonthPLInSheet_(ss, monthKey, targetYear, targetMonth, freshPl) {
  if (!freshPl || !freshPl.categories) return;

  const plFromAppSheet = ss.getSheetByName("PLFromApp");
  if (!plFromAppSheet) return;

  const dataRange = plFromAppSheet.getDataRange();
  const values = dataRange.getValues();
  if (values.length < 1) return;

  const headers = values[0];
  let targetColIdx = -1; // 1-indexed for Sheets

  // 1. Locate the column matching targetYear and targetMonth in Row 1
  for (let c = 1; c < headers.length; c++) {
    const hDate = parseHeaderDate_(headers[c]);
    if (hDate && hDate.getFullYear() === targetYear && hDate.getMonth() === targetMonth) {
      targetColIdx = c + 1; // 1-indexed
      break;
    }
  }

  // If column doesn't exist, append a new month column
  if (targetColIdx === -1) {
    const lastCol = plFromAppSheet.getLastColumn();
    targetColIdx = lastCol + 1;
    const monthDate = new Date(targetYear, targetMonth, 1);
    const headerLabel = monthDate.toLocaleString('default', { month: 'long', year: 'numeric' });
    plFromAppSheet.getRange(1, targetColIdx).setValue(headerLabel).setFontWeight("bold");
  }

  // 2. Map existing category rows in Column A
  const existingRowMap = new Map(); // normName -> rowNum (1-indexed)
  for (let r = 1; r < values.length; r++) {
    const rawTitle = String(values[r][0] || "").trim();
    if (!rawTitle) continue;
    const norm = rawTitle.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
    if (!existingRowMap.has(norm)) {
      existingRowMap.set(norm, r + 1); // 1-indexed
    }
  }

  // 3. Write category amounts to the month's column
  freshPl.categories.forEach((item, norm) => {
    let rowNum = existingRowMap.get(norm);
    if (!rowNum) {
      // Category does not exist in Column A yet: insert a new row
      const lastRow = plFromAppSheet.getLastRow();
      plFromAppSheet.insertRowAfter(lastRow);
      rowNum = lastRow + 1;
      plFromAppSheet.getRange(rowNum, 1).setValue(sanitizeSheetCell_(item.originalTitle));
      existingRowMap.set(norm, rowNum);
    }
    plFromAppSheet.getRange(rowNum, targetColIdx).setValue(item.amount);
  });

  // If depreciation was found, ensure it is written to the depreciation row
  if (freshPl.depreciation > 0) {
    let depRowNum = -1;
    for (const [norm, rNum] of existingRowMap.entries()) {
      if (norm.includes("depreciation")) {
        depRowNum = rNum;
        break;
      }
    }
    if (depRowNum !== -1) {
      plFromAppSheet.getRange(depRowNum, targetColIdx).setValue(freshPl.depreciation);
    }
  }

  (await SpreadsheetApp.flush());
}

/**
 * Automatically detects unmapped nominal accounts in PLFromApp!A:A,
 * refreshes Chart of Accounts (KeyInfo!AW), and quarantines them into
/**
 * Scans PLFromApp against all known/mapped accounts in Outgoings, PLComp!B:B, and KeyInfo!AT4:AT40.
 * If a genuinely new nominal account appears that is NOT in Outgoings, PLComp!B, or KeyInfo!AT,
 * it is automatically quarantined into the first empty cell in PLComp!B180:B229 ("Extra ignore")
 * to prevent Outgoings pollution pending classification in PMA.
 */
async function checkAndQuarantineUnmappedPLCategories_(ss, knownNormCats = null, isHeadless = false) {
  try {
    const plFromAppSheet = ss.getSheetByName("PLFromApp");
    const plCompSheet = ss.getSheetByName("PLComp");
    if (!plFromAppSheet || !plCompSheet) return [];

    const plFromAppValues = plFromAppSheet.getRange("A1:A" + Math.max(plFromAppSheet.getLastRow(), 20)).getValues();
    const plCompValues = plCompSheet.getRange("B1:B235").getValues();

    const knownMappedNormSet = new Set();

    // 1. Existing Outgoings categories from client sheet are known and mapped!
    if (knownNormCats && knownNormCats.size > 0) {
      knownNormCats.forEach(cat => {
        if (cat) {
          knownMappedNormSet.add(cat.toLowerCase());
          knownMappedNormSet.add(cat.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim());
        }
      });
    } else {
      // Fallback: Read existing categories directly from the client Outgoings sheet
      try {
        const clientSheetId = (await getKeyInfoValue('X28'));
        if (clientSheetId) {
          const clientSs = (await SpreadsheetApp.openById(clientSheetId));
          const outgoingsSheet = clientSs.getSheetByName("Outgoings");
          if (outgoingsSheet) {
            const outVals = outgoingsSheet.getRange("A120:A235").getValues();
            outVals.forEach(r => {
              const c = String(r[0] || "").trim();
              if (c && !c.toLowerCase().startsWith("total") && !c.toLowerCase().startsWith("---")) {
                const norm = c.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim();
                knownMappedNormSet.add(norm);
                knownMappedNormSet.add(c.toLowerCase());
              }
            });
          }
        }
      } catch (clientErr) {
        console.warn("[P&L Quarantine] Could not read Outgoings sheet for fallback:", clientErr.message);
      }
    }

    // 2. Existing PLComp!B (Revenue, Staff, Delivery, Ignored, etc.) are known and mapped!
    plCompValues.forEach(row => {
      const s = String(row[0] || "").trim();
      if (s) {
        knownMappedNormSet.add(s.toLowerCase());
        knownMappedNormSet.add(s.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim());
      }
    });

    const infoSheet = ss.getSheetByName(COST_CONFIG.sheets.keyInfo);
    if (infoSheet) {
      const atVals = infoSheet.getRange("AT4:AT40").getValues();
      atVals.forEach(row => {
        const s = String(row[0] || "").trim();
        if (s) {
          knownMappedNormSet.add(s.toLowerCase());
          knownMappedNormSet.add(s.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim());
        }
      });
      const baVals = infoSheet.getRange("BA2:BA180").getValues();
      baVals.forEach(row => {
        const s = String(row[0] || "").trim();
        if (s) {
          knownMappedNormSet.add(s.toLowerCase());
          knownMappedNormSet.add(s.replace(/^\d+\s*[-–]\s*/, "").toLowerCase().trim());
        }
      });
    }

    const IGNORE_TITLES = new Set([
      "description", "income", "total income", "less cost of sales", "cost of sales",
      "total cost of sales", "gross profit", "less operating expenses", "operating expenses",
      "total operating expenses", "operating profit", "net profit", "total other income",
      "less other expenses", "total other expenses", "net other income", "profit before taxation",
      "taxation", "profit after taxation", "other comprehensive income", "total comprehensive income",
      "pull p&l:", "extra ignore"
    ]);

    const unmappedToQuarantine = [];
    plFromAppValues.forEach((row) => {
      const rawTitle = String(row[0] || "").trim();
      if (!rawTitle) return;
      const lower = rawTitle.toLowerCase();
      if (lower.startsWith("#") || lower.includes("#n/a") || lower.includes("#ref!") || lower.includes("#value!") || lower.includes("#name?") || lower.includes("#error!")) return;
      if (IGNORE_TITLES.has(lower)) return;
      if (lower.startsWith("total ") || lower.startsWith("less ") || lower.startsWith("---") || lower.startsWith("===")) return;

      const cleanTitle = rawTitle.replace(/^\d+\s*[-–]\s*/, "").trim();
      const normClean = cleanTitle.toLowerCase();
      const normRaw = lower;

      if (!knownMappedNormSet.has(normRaw) && !knownMappedNormSet.has(normClean)) {
        unmappedToQuarantine.push({ rawTitle, cleanTitle });
        // Prevent duplicate quarantine in same loop
        knownMappedNormSet.add(normRaw);
        knownMappedNormSet.add(normClean);
      }
    });

    if (unmappedToQuarantine.length === 0) return [];

    console.log(`[P&L Quarantine] Found ${unmappedToQuarantine.length} unmapped category(s) in PLFromApp:`, unmappedToQuarantine.map(u => u.cleanTitle).join(", "));

    // 1. Refresh Chart of Accounts in KeyInfo!AW
    try {
      (await refreshAccountingToolChartOfAccounts(true));
    } catch (coaErr) {
      console.warn("[P&L Quarantine] Failed to refresh Chart of Accounts:", coaErr.message);
    }

    // 2. Quarantine each unmapped category into the first available cell in PLComp!B180:B229
    const extraIgnoreRange = plCompSheet.getRange("B180:B229");
    const extraIgnoreVals = extraIgnoreRange.getValues();

    unmappedToQuarantine.forEach(item => {
      let targetRow = -1;
      for (let i = 0; i < extraIgnoreVals.length; i++) {
        const val = String(extraIgnoreVals[i][0] || "").trim();
        if (!val) {
          targetRow = 180 + i;
          extraIgnoreVals[i][0] = item.cleanTitle; // mark used in memory
          break;
        }
      }

      if (targetRow !== -1) {
        plCompSheet.getRange(targetRow, 2).setValue(sanitizeSheetCell_(item.cleanTitle));
        console.log(`[P&L Quarantine] Quarantined "${item.cleanTitle}" into PLComp!B${targetRow}.`);

        if (typeof writeToAutoLog === 'function') {
          const summary = `New P&L Category Quarantined: "${item.cleanTitle}"`;
          const details = `Detected unmapped nominal account in PLFromApp: "${item.rawTitle}". Refreshed Chart of Accounts (KeyInfo!AW) and quarantined into PLComp!B${targetRow} to prevent Outgoings pollution pending PMA classification.`;
          writeToAutoLog("EXPENSES", summary, details);
        }
      } else {
        console.warn(`[P&L Quarantine] No empty rows in PLComp!B180:B229 to quarantine "${item.cleanTitle}".`);
      }
    });

    (await SpreadsheetApp.flush());
    return unmappedToQuarantine;
  } catch (err) {
    console.error("[P&L Quarantine] Error in checkAndQuarantineUnmappedPLCategories_:", err);
    return [];
  }
}

/**
 * Automatically triggers bank feed reconciliation in Pulse before reading unreconciled items.
 * Gradually removes items one-by-one from the Recon Sheet (CD4:CN) as they become reconciled in QuickBooks/Xero.
 */
async function autoReconcileBankFeedsBeforeBreakdown_(rawReconUrl) {
  if (!rawReconUrl) return;
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const keyInfoSheet = ss.getSheetByName('KeyInfo');
    const clientName = keyInfoSheet ? String(keyInfoSheet.getRange('B3').getValue() || '').trim() : '';

    const baseUrl = (typeof getPulseBrokerBaseUrl_ === 'function')
      ? getPulseBrokerBaseUrl_()
      : "https://app.pulsedashboard.co.uk";

    const triageUrl = `${baseUrl}/api/triage`;
    const payload = {
      action: "auto_reconcile_bank_feeds",
      clientName: clientName,
      masterSheetId: spreadsheetId,
      reconSheetId: rawReconUrl
    };

    const options = {
      method: "post",
      contentType: "application/json",
      payload: JSON.stringify(payload),
      headers: {
        "Authorization": "Bearer " + (typeof getPulseInternalSecret_ === "function" ? getPulseInternalSecret_() : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "")),
        "Accept": "application/json"
      },
      muteHttpExceptions: true
    };

    const resp = (await UrlFetchApp.fetch(triageUrl, options));
    const code = resp.getResponseCode();
    if (code === 200) {
      console.log(`[Expense Breakdown] Auto-reconciled bank feeds via Pulse API for ${clientName || spreadsheetId}`);
    } else {
      console.warn(`[Expense Breakdown] Auto-reconcile bank feeds returned status ${code}: ${resp.getContentText().slice(0, 200)}`);
    }
  } catch (err) {
    console.warn("[Expense Breakdown] Could not auto-reconcile bank feeds:", err.message);
  }
}

/**
 * PART-PAID EXPENSES & CONTRACTOR BILLS AUTOMATION
 * ============================================================================
 * 
 * Scans JnlsFromApp, Outgoings, and Confirmed to detect:
 * 1. Part-paid expenses / contractor bills (AmountPaid > 0.005 && AmountDue > 0.005):
 *    A. In Outgoings:
 *       - Finds the cell containing {App ID: <TransactionID>} (or <TransactionID>-P1).
 *       - Splits the note into two blocks:
 *         1. Paid block: {App ID: <ID>}{Amt: <paidNet>}{Status: Part-paid (paid)}{Rec date: <recDate>}{Pay date: <paidDate>}{Description: <desc>}
 *         2. Balance block: {App ID: <ID>}{Amt: <dueNet>}{Status: Part-paid (balance)}{Rec date: <recDate>}{Pay date: <dueDate>}{Description: <desc>}
 *    B. In Confirmed (Direct Costs):
 *       - Updates primary slot to "Part-paid (paid)" with the paid ex-VAT amount and actual payment days.
 *       - Finds next available direct cost slot and writes the balance as "Part-paid (balance)" with due date.
 * 2. Fully-paid expenses that previously had part-payment blocks:
 *    A. In Outgoings:
 *       - Consolidates the note back to a single block with status "Paid", removing the -bal block.
 *    B. In Confirmed:
 *       - Clears the balance slot and restores primary slot to full amount with status "Paid".
 */
async function processPartPaidExpenses(ss, alertSheet) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!alertSheet) alertSheet = ss.getSheetByName("DataChgAlert");

  const clientSheetId = (await getKeyInfoValue('X28'));
  if (!clientSheetId) {
    return { count: 0, logs: ["Error: Part-Paid Expenses - Client Sheet ID (X28) not found in KeyInfo."], hasError: true, error: "Client Sheet ID (X28) not found in KeyInfo." };
  }

  const jnlSheet = ss.getSheetByName(COST_CONFIG.sheets.journalData || "JnlsFromApp");
  if (!jnlSheet) {
    return { count: 0, logs: ["Error: Part-Paid Expenses - 'JnlsFromApp' sheet not found."], hasError: true, error: "'JnlsFromApp' sheet not found." };
  }

  let clientSs;
  try {
    clientSs = (await SpreadsheetApp.openById(clientSheetId));
  } catch (e) {
    return { count: 0, logs: ["Error: Part-Paid Expenses - " + e.message], hasError: true, error: e.message };
  }

  const outgoingsSheet = clientSs.getSheetByName("Outgoings");
  const confirmedSheet = clientSs.getSheetByName("Confirmed");
  if (!outgoingsSheet && !confirmedSheet) {
    return { count: 0, logs: ["Error: Part-Paid Expenses - Neither 'Outgoings' nor 'Confirmed' found in Client Spreadsheet."], hasError: true, error: "Neither 'Outgoings' nor 'Confirmed' found in Client Spreadsheet." };
  }

  const jnlData = jnlSheet.getDataRange().getValues();
  if (jnlData.length <= 1) return { count: 0, logs: [] };

  const jnlHeaders = jnlData[0].map(h => String(h || "").trim().toLowerCase().replace(/[\s_]+/g, ""));
  const idxId = jnlHeaders.findIndex(h => h.includes("transactionid") || h.includes("sourceid") || h === "id");
  const idxDue = jnlHeaders.findIndex(h => h.includes("amountdue") || h.includes("due"));
  const idxPaid = jnlHeaders.findIndex(h => h.includes("amountpaid") || h.includes("paidamt"));
  const idxGross = jnlHeaders.findIndex(h => h.includes("gross"));
  const idxNet = jnlHeaders.findIndex(h => h.includes("net") || h === "amount");
  const idxDate = jnlHeaders.findIndex(h => h === "date" || h.includes("recdate"));
  const idxPayDate = jnlHeaders.findIndex(h => h.includes("datepaid") || h.includes("paiddate"));
  const idxDueDate = jnlHeaders.findIndex(h => h.includes("duedate"));
  const idxDesc = jnlHeaders.findIndex(h => h.includes("description") || h.includes("desc"));
  const idxStatus = jnlHeaders.findIndex(h => h === "status");
  const idxRef = jnlHeaders.findIndex(h => h === "reference" || h.includes("ref"));

  if (idxId === -1 || idxNet === -1) {
    return { count: 0, logs: ["Error: Part-Paid Expenses - Required headers missing in JnlsFromApp."], hasError: true, error: "Required headers missing in JnlsFromApp." };
  }

  const partPaidMap = new Map();
  const fullyPaidSet = new Set();

  for (let r = 1; r < jnlData.length; r++) {
    const row = jnlData[r];
    const txnId = String(row[idxId] || "").trim();
    if (!txnId) continue;

    const rawDue = idxDue !== -1 ? (parseFloat(String(row[idxDue]).replace(/,/g, "")) || 0) : 0;
    const rawPaid = idxPaid !== -1 ? (parseFloat(String(row[idxPaid]).replace(/,/g, "")) || 0) : 0;
    const rawNet = parseFloat(String(row[idxNet]).replace(/,/g, "")) || 0;
    const rawGross = idxGross !== -1 ? (parseFloat(String(row[idxGross]).replace(/,/g, "")) || rawNet) : rawNet;
    const status = idxStatus !== -1 ? String(row[idxStatus] || "").trim().toUpperCase() : "";
    const recDate = idxDate !== -1 ? row[idxDate] : null;
    const payDate = idxPayDate !== -1 ? row[idxPayDate] : null;
    const dueDate = idxDueDate !== -1 ? row[idxDueDate] : null;
    const desc = idxDesc !== -1 ? String(row[idxDesc] || "").trim() : "";
    const ref = idxRef !== -1 ? String(row[idxRef] || "").trim() : "";

    const ratio = rawGross > 0 ? (rawNet / rawGross) : 1;
    const paidNet = Math.round(rawPaid * ratio * 100) / 100;
    const dueNet = Math.round((rawNet - paidNet) * 100) / 100;

    if (rawPaid > 0.005 && rawDue > 0.005) {
      partPaidMap.set(txnId, {
        txnId,
        rawDue,
        rawPaid,
        rawNet,
        rawGross,
        paidNet,
        dueNet,
        recDate,
        payDate,
        dueDate,
        desc,
        ref,
        status
      });
    } else if (rawPaid > 0.005 && rawDue <= 0.005 && (status === "PAID" || status === "Paid")) {
      fullyPaidSet.add(txnId);
    }
  }

  if (partPaidMap.size === 0 && fullyPaidSet.size === 0) {
    return { count: 0, logs: ["No part-paid or newly resolved expenses found in JnlsFromApp."] };
  }

  let totalUpdated = 0;
  const logDetails = [];

  // --- PART 1: OUTGOINGS SHEET PROCESSING ---
  if (outgoingsSheet) {
    const outDataRange = outgoingsSheet.getDataRange();
    const outNotes = outDataRange.getNotes();
    const outValues = outDataRange.getValues();
    const headers = outValues[0];

    // Find all month columns
    const monthCols = [];
    for (let c = 0; c < headers.length; c++) {
      if (parseHeaderDate_(headers[c])) {
        monthCols.push(c);
      }
    }

    // Process Part-Paid Expenses in Outgoings
    for (const [txnId, exp] of partPaidMap.entries()) {
      for (let r = 1; r < outNotes.length; r++) {
        for (const c of monthCols) {
          const note = outNotes[r][c];
          if (!note) continue;

          // Check if this cell contains this App ID
          if (note.includes(`{App ID: ${txnId}}`) || note.includes(`{App ID: ${txnId}-P1}`) || note.includes(`{App ID: ${txnId}-bal}`)) {
            // Calculate payment dates and descriptions first
            const recStr = fmtDate_(exp.recDate) || fmtDate_(headers[c]);
            const payStr = fmtDate_(exp.payDate) || recStr;

            // Target payment run for active/overdue forecast:
            // Contractor standard pay day is 28th. Cutoff is the 20th of the month.
            // If today is past the 20th, target next month's 28th; otherwise target current month's 28th.
            const today = new Date();
            const currentMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
            const currentPayCutoff = 20;
            const currentPayDay = 28;
            const currentPayDateObj = today.getDate() > currentPayCutoff
              ? new Date(today.getFullYear(), today.getMonth() + 1, currentPayDay)
              : new Date(today.getFullYear(), today.getMonth(), currentPayDay);
            const currentPayDateStr = fmtDate_(currentPayDateObj);

            // 1. Check if there is already an existing user-selected or previously set future pay date on the balance block
            let duePayStr = "";
            const rawBlocksPre = note.split(/(?=\{App ID:)/).map(s => s.trim()).filter(Boolean);
            const existingBalBlock = rawBlocksPre.find(b => (b.includes(`{App ID: ${txnId}}`) || b.includes(`{App ID: ${txnId}-bal}`)) && b.includes("Part-paid (balance)"));
            if (existingBalBlock) {
              const payDateMatch = existingBalBlock.match(/\{Pay date:\s*([^}]+)\}/);
              if (payDateMatch) {
                const parsedBalDate = parseDateSafe_(payDateMatch[1].trim());
                if (parsedBalDate && parsedBalDate >= currentMonthStart) {
                  duePayStr = payDateMatch[1].trim();
                }
              }
            }

            if (!duePayStr && exp.dueDate) {
              const parsedDue = parseDateSafe_(exp.dueDate);
              const parsedRec = parseDateSafe_(exp.recDate);
              // Use accounting due date only if it is in the active/future forecast (>= currentMonthStart) and strictly after invoice date
              if (parsedDue && parsedRec && parsedDue.getTime() > parsedRec.getTime() && parsedDue >= currentMonthStart) {
                duePayStr = fmtDate_(parsedDue);
              }
            }

            if (!duePayStr) {
              const rowTiming = outValues[r];
              const recTiming = rowTiming && rowTiming[2] ? String(rowTiming[2]).trim() : "Curr";
              const payTiming = rowTiming && rowTiming[3] ? String(rowTiming[3]).trim() : "Next";
              const anchor = exp.recDate ? parseDateSafe_(exp.recDate) : headers[c];
              const est = calculateEstDates(anchor, recTiming, payTiming);
              const parsedEstPay = parseDateSafe_(est.pay);
              if (parsedEstPay && parsedEstPay >= currentMonthStart) {
                duePayStr = est.pay;
              } else {
                // If estimated pay date from invoice date is in the past (< currentMonthStart), roll forward to active forecast pay date
                duePayStr = currentPayDateStr;
              }
            }

            // Fallback safety: an unpaid balance can NEVER have a forecast pay date in a past month (< currentMonthStart)
            const parsedFinalDue = parseDateSafe_(duePayStr);
            if (!parsedFinalDue || parsedFinalDue < currentMonthStart) {
              duePayStr = currentPayDateStr;
            }

            // Check if already split correctly with matching amounts AND dates
            const isAlreadySplit = (note.includes(`{App ID: ${txnId}}`) || note.includes(`{App ID: ${txnId}-bal}`)) &&
                                   note.includes("Part-paid (paid)") &&
                                   note.includes("Part-paid (balance)");
            if (isAlreadySplit) {
              const currentPaidBlock = rawBlocksPre.find(b => (b.includes(`{App ID: ${txnId}}`) || b.includes(`{App ID: ${txnId}-P1}`)) && b.includes("Part-paid (paid)"));
              const currentDueBlock = rawBlocksPre.find(b => (b.includes(`{App ID: ${txnId}}`) || b.includes(`{App ID: ${txnId}-bal}`)) && b.includes("Part-paid (balance)"));
              const curPaid = currentPaidBlock ? parseFloat(currentPaidBlock.match(/\{Amt:\s*([\d.]+)\}/)?.[1] || "0") : 0;
              const curDue = currentDueBlock ? parseFloat(currentDueBlock.match(/\{Amt:\s*([\d.]+)\}/)?.[1] || "0") : 0;
              const curPaidDate = currentPaidBlock ? (currentPaidBlock.match(/\{Pay date:\s*([^}]+)\}/)?.[1] || "").trim() : "";
              const curDueDate = currentDueBlock ? (currentDueBlock.match(/\{Pay date:\s*([^}]+)\}/)?.[1] || "").trim() : "";

              const hasLegacyBalId = currentDueBlock && currentDueBlock.includes(`{App ID: ${txnId}-bal}`);
              const hasLegacyDesc = (currentPaidBlock && currentPaidBlock.includes("(Part payment)")) || (currentDueBlock && currentDueBlock.includes("(Balance)"));

              if (!hasLegacyBalId && !hasLegacyDesc && Math.abs(curPaid - exp.paidNet) < 0.05 && Math.abs(curDue - exp.dueNet) < 0.05 && curPaidDate === payStr && curDueDate === duePayStr) {
                continue;
              }
            }

            // Separate top audit text from bottom data blocks
            const firstDataIdx = note.indexOf("{App ID:");
            let topAuditText = "";
            let bottomDataText = note;
            if (firstDataIdx !== -1) {
              topAuditText = note.substring(0, firstDataIdx).trim();
              bottomDataText = note.substring(firstDataIdx).trim();
            }

            let rawBlocks = bottomDataText.split(/(?=\{App ID:)/).map(s => s.trim()).filter(s => s.length > 0);

            // Filter out existing blocks for this txnId
            const otherBlocks = rawBlocks.filter(b => !b.includes(`{App ID: ${txnId}}`) && !b.includes(`{App ID: ${txnId}-P1}`) && !b.includes(`{App ID: ${txnId}-bal}`));

            let cleanDesc = exp.desc;
            cleanDesc = cleanDesc.replace(/\s*\((?:Part payment|Balance|Part \d+)\)/gi, "").trim();

            const paidBlock = `{App ID: ${txnId}}{Amt: ${exp.paidNet.toFixed(2)}}{Status: Part-paid (paid)}{Rec date: ${recStr}}{Pay date: ${payStr}}{Description: ${cleanDesc}}`;
            const balBlock = `{App ID: ${txnId}}{Amt: ${exp.dueNet.toFixed(2)}}{Status: Part-paid (balance)}{Rec date: ${recStr}}{Pay date: ${duePayStr}}{Description: ${cleanDesc}}`;

            otherBlocks.push(paidBlock);
            otherBlocks.push(balBlock);

            const newBottomText = otherBlocks.join("\n\n");
            const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM HH:mm");
            const auditMsg = `${timestamp}: Part-payment split applied (Paid £${exp.paidNet.toFixed(2)}, Due £${exp.dueNet.toFixed(2)})`;
            const newTopText = topAuditText ? `${auditMsg}\n${topAuditText}` : auditMsg;
            const finalNote = `${newTopText}\n\n${newBottomText}`;

            outgoingsSheet.getRange(r + 1, c + 1).setNote(finalNote);
            outNotes[r][c] = finalNote;
            totalUpdated++;

            const colMonthName = headers[c] instanceof Date ? fmtDate_(headers[c]) : String(headers[c]);
            const rowLabel = String(outValues[r][0] || `Row ${r + 1}`).trim();
            logDetails.push(`[Outgoings] Applied part-payment split for ${rowLabel} (${exp.ref || txnId}): Paid = £${exp.paidNet.toFixed(2)} (Part-paid (paid), Paid ${payStr}), Balance = £${exp.dueNet.toFixed(2)} (Part-paid (balance), Due ${duePayStr}) in ${colMonthName}.`);
          }
        }
      }
    }

    // Process Fully-Paid part-payment resolution in Outgoings
    for (const txnId of fullyPaidSet) {
      for (let r = 1; r < outNotes.length; r++) {
        for (const c of monthCols) {
          const note = outNotes[r][c];
          if (!note) continue;

          const hasExplicitPartPaid = note.includes(`{App ID: ${txnId}-bal}`) || (note.includes(`{App ID: ${txnId}}`) && (note.includes("Part-paid") || note.includes("part-paid")));
          const hasMultipleBlocksForTxn = note.split(`{App ID: ${txnId}}`).length - 1 > 1;

          if (hasExplicitPartPaid || hasMultipleBlocksForTxn) {
            const jnlRow = jnlData.find(jr => String(jr[idxId]).trim() === txnId);
            if (!jnlRow) continue;

            const recD = idxDate !== -1 ? jnlRow[idxDate] : null;
            const payD = idxPayDate !== -1 ? jnlRow[idxPayDate] : null;
            const dText = idxDesc !== -1 ? String(jnlRow[idxDesc] || "").trim() : "";
            const cleanD = dText.replace(/\s*\((?:Part payment|Balance|Part \d+)\)/gi, "").trim();

            const recStr = fmtDate_(recD) || fmtDate_(headers[c]);
            const payStr = fmtDate_(payD) || recStr;

            const firstDataIdx = note.indexOf("{App ID:");
            let topAuditText = "";
            let bottomDataText = note;
            if (firstDataIdx !== -1) {
              topAuditText = note.substring(0, firstDataIdx).trim();
              bottomDataText = note.substring(firstDataIdx).trim();
            }

            let rawBlocks = bottomDataText.split(/(?=\{App ID:)/).map(s => s.trim()).filter(s => s.length > 0);
            let noteModified = false;

            const targetIndices = [];
            rawBlocks.forEach((b, idx) => {
              if (b.includes(`{App ID: ${txnId}}`) || b.includes(`{App ID: ${txnId}-P1}`) || b.includes(`{App ID: ${txnId}-bal}`)) {
                targetIndices.push(idx);
              }
            });

            const anyBlockMatchesPayStr = targetIndices.some(idx => {
              const pm = rawBlocks[idx].match(/\{Pay date:\s*([^}]+)\}/i);
              return pm && pm[1].trim() === payStr;
            });
            const lastTargetIdx = targetIndices.length > 1 ? targetIndices[targetIndices.length - 1] : -1;

            const updatedBlocks = rawBlocks.map((block, idx) => {
              const isTargetBlock = targetIndices.includes(idx);
              if (!isTargetBlock) return block;

              const isBalance = block.includes("Part-paid (balance)") || block.includes(`{App ID: ${txnId}-bal}`);
              const isPartPaid = block.includes("Part-paid (paid)") || block.includes("Part-paid");
              const isLatestUnmatchedTranche = (!isBalance && !isPartPaid && idx === lastTargetIdx && !anyBlockMatchesPayStr);

              if (isBalance || isLatestUnmatchedTranche) {
                let newBlock = block.replace(/\{App ID:\s*[^}]+\}/, `{App ID: ${txnId}}`);
                newBlock = newBlock.replace(/\{Status:\s*[^}]+\}/, `{Status: Paid}`);
                newBlock = newBlock.replace(/\{Pay date:\s*[^}]+\}/, `{Pay date: ${payStr}}`);
                if (cleanD) {
                  newBlock = newBlock.replace(/\{Description:\s*[^}]+\}/, `{Description: ${cleanD}}`);
                }
                if (newBlock !== block) noteModified = true;
                return newBlock;
              } else if (isPartPaid) {
                let newBlock = block.replace(/\{App ID:\s*[^}]+\}/, `{App ID: ${txnId}}`);
                newBlock = newBlock.replace(/\{Status:\s*[^}]+\}/, `{Status: Paid}`);
                if (cleanD) {
                  newBlock = newBlock.replace(/\{Description:\s*[^}]+\}/, `{Description: ${cleanD}}`);
                }
                if (newBlock !== block) noteModified = true;
                return newBlock;
              }
              return block;
            });

            if (noteModified) {
              const newBottomText = updatedBlocks.join("\n\n");
              const timestamp = Utilities.formatDate(new Date(), ss.getSpreadsheetTimeZone(), "dd-MMM HH:mm");
              const auditMsg = `${timestamp}: Part-payment balance resolved to Paid (${payStr})`;
              const newTopText = topAuditText ? `${auditMsg}\n${topAuditText}` : auditMsg;
              const finalNote = `${newTopText}\n\n${newBottomText}`;

              outgoingsSheet.getRange(r + 1, c + 1).setNote(finalNote);
              outNotes[r][c] = finalNote;
              totalUpdated++;

              const colMonthName = headers[c] instanceof Date ? fmtDate_(headers[c]) : String(headers[c]);
              const rowLabel = String(outValues[r][0] || `Row ${r + 1}`).trim();
              logDetails.push(`[Outgoings] Resolved part-payment balance to Paid for ${rowLabel} (${txnId}) on ${payStr} in ${colMonthName} (preserving individual payment tranches and cashflow timing).`);
            }
          }
        }
      }
    }
  }

  // --- PART 2: CONFIRMED SHEET (DIRECT COSTS) PROCESSING ---
  if (confirmedSheet) {
    const confData = confirmedSheet.getDataRange().getValues();
    if (confData.length > 1) {
      const confHeaders = confData[0].map(h => String(h || "").trim().toLowerCase());
      const getSlotCol = (slot, suffix) => confHeaders.findIndex(h => (h === `dir inv ${slot} ${suffix}` || h === `direct inv ${slot} ${suffix}`));

      const slotCols = {
        1: { desc: getSlotCol(1, "descr."), amt: getSlotCol(1, "amt"), vat: getSlotCol(1, "vat?"), rec: getSlotCol(1, "rec date"), days: getSlotCol(1, "days to pay"), status: getSlotCol(1, "status"), id: getSlotCol(1, "app id") },
        2: { desc: getSlotCol(2, "descr."), amt: getSlotCol(2, "amt"), vat: getSlotCol(2, "vat?"), rec: getSlotCol(2, "rec date"), days: getSlotCol(2, "days to pay"), status: getSlotCol(2, "status"), id: getSlotCol(2, "app id") },
        3: { desc: getSlotCol(3, "descr."), amt: getSlotCol(3, "amt"), vat: getSlotCol(3, "vat?"), rec: getSlotCol(3, "rec date"), days: getSlotCol(3, "days to pay"), status: getSlotCol(3, "status"), id: getSlotCol(3, "app id") }
      };

      for (const [txnId, exp] of partPaidMap.entries()) {
        for (let r = 1; r < confData.length; r++) {
          const row = confData[r];
          for (let s = 1; s <= 3; s++) {
            const idCol = slotCols[s].id;
            if (idCol !== -1 && String(row[idCol] || "").trim() === txnId) {
              const primaryCols = slotCols[s];
              const currentStatus = String(row[primaryCols.status] || "");
              const currentAmt = parseFloat(row[primaryCols.amt]) || 0;

              if (currentStatus === "Part-paid (paid)" && Math.abs(currentAmt - exp.paidNet) < 0.05) {
                continue;
              }

              confirmedSheet.getRange(r + 1, primaryCols.amt + 1).setValue(exp.paidNet).setFontWeight("bold").setFontLine("underline");
              confirmedSheet.getRange(r + 1, primaryCols.status + 1).setValue("Part-paid (paid)").setFontWeight("bold").setFontLine("underline");
              
              if (exp.payDate && exp.recDate) {
                const recD = parseDateSafe_(exp.recDate);
                const payD = parseDateSafe_(exp.payDate);
                if (recD && payD) {
                  const days = Math.max(0, Math.round((payD.getTime() - recD.getTime()) / (1000 * 60 * 60 * 24)));
                  if (primaryCols.days !== -1) {
                    confirmedSheet.getRange(r + 1, primaryCols.days + 1).setValue(days);
                  }
                }
              }

              const balId = txnId;
              let targetSlot = null;
              for (let s2 = 1; s2 <= 3; s2++) {
                if (s2 !== s) {
                  const id2 = String(row[slotCols[s2].id] || "").trim();
                  const status2 = String(row[slotCols[s2].status] || "").trim();
                  if (id2 === balId && status2.includes("balance")) { targetSlot = s2; break; }
                  if (!targetSlot && (!id2 || id2 === "") && (!row[slotCols[s2].amt] || parseFloat(row[slotCols[s2].amt]) === 0)) {
                    targetSlot = s2;
                  }
                }
              }

              if (targetSlot) {
                const balCols = slotCols[targetSlot];
                confirmedSheet.getRange(r + 1, balCols.desc + 1).setValue(exp.desc);
                confirmedSheet.getRange(r + 1, balCols.amt + 1).setValue(exp.dueNet).setFontWeight("bold").setFontLine("underline");
                if (balCols.vat !== -1 && primaryCols.vat !== -1) {
                  confirmedSheet.getRange(r + 1, balCols.vat + 1).setValue(row[primaryCols.vat] || "Yes");
                }
                if (balCols.rec !== -1 && primaryCols.rec !== -1) {
                  confirmedSheet.getRange(r + 1, balCols.rec + 1).setValue(row[primaryCols.rec]);
                }
                if (balCols.days !== -1) {
                  let balDays = 0;
                  const recD = parseDateSafe_(exp.recDate || (primaryCols.rec !== -1 ? row[primaryCols.rec] : null));
                  const dueD = parseDateSafe_(exp.dueDate);
                  if (recD && dueD) {
                    balDays = Math.max(0, Math.round((dueD.getTime() - recD.getTime()) / (1000 * 60 * 60 * 24)));
                  }
                  confirmedSheet.getRange(r + 1, balCols.days + 1).setValue(balDays);
                }
                confirmedSheet.getRange(r + 1, balCols.status + 1).setValue("Part-paid (balance)").setFontWeight("bold").setFontLine("underline");
                confirmedSheet.getRange(r + 1, balCols.id + 1).setNumberFormat("@").setValue(balId);
              }

              totalUpdated++;
              logDetails.push(`[Confirmed] Applied part-payment split for Direct Cost Row ${r + 1} Slot ${s} (${exp.ref || txnId}): Paid = £${exp.paidNet.toFixed(2)} (Part-paid (paid)), Balance = £${exp.dueNet.toFixed(2)} (Part-paid (balance)).`);
            }
          }
        }
      }

      // Process Fully-Paid part-payment resolution in Confirmed
      for (const txnId of fullyPaidSet) {
        const jnlRow = jnlData.find(jr => String(jr[idxId]).trim() === txnId);
        if (!jnlRow) continue;
        const payDate = idxPayDate !== -1 ? jnlRow[idxPayDate] : null;
        const recDate = idxDate !== -1 ? jnlRow[idxDate] : null;
        const recD = parseDateSafe_(recDate);
        const payD = parseDateSafe_(payDate);
        const finalDays = (recD && payD) ? Math.max(0, Math.round((payD.getTime() - recD.getTime()) / (1000 * 60 * 60 * 24))) : null;

        for (let r = 1; r < confData.length; r++) {
          const row = confData[r];
          const matchingSlots = [];
          for (let s = 1; s <= 3; s++) {
            const idCol = slotCols[s].id;
            if (idCol !== -1 && String(row[idCol] || "").trim() === txnId) {
              matchingSlots.push(s);
            }
          }
          if (matchingSlots.length === 0) continue;

          const anySlotMatchesFinalDays = finalDays !== null && matchingSlots.some(s => {
            const dCol = slotCols[s].days;
            return dCol !== -1 && parseInt(row[dCol], 10) === finalDays;
          });
          let selfHealSlot = null;
          if (!anySlotMatchesFinalDays && matchingSlots.length > 1 && finalDays !== null) {
            const hasExplicitBal = matchingSlots.some(s => String(row[slotCols[s].status] || "").toLowerCase().includes("balance"));
            if (!hasExplicitBal) {
              selfHealSlot = matchingSlots[matchingSlots.length - 1];
              let maxDays = -Infinity;
              matchingSlots.forEach(s => {
                const st = String(row[slotCols[s].status] || "").toLowerCase();
                if (st.includes("part-paid") && !st.includes("balance")) return;
                const dVal = slotCols[s].days !== -1 ? parseInt(row[slotCols[s].days], 10) : NaN;
                const val = isNaN(dVal) ? -1 : dVal;
                if (val >= maxDays) {
                  maxDays = val;
                  selfHealSlot = s;
                }
              });
            }
          }

          for (const s of matchingSlots) {
            const statusCol = slotCols[s].status;
            const currentStatus = String(row[statusCol] || "").trim();
            if (currentStatus.toLowerCase().includes("balance") || s === selfHealSlot) {
              if (currentStatus !== "Paid") {
                confirmedSheet.getRange(r + 1, statusCol + 1).setValue("Paid");
              }
              if (finalDays !== null && slotCols[s].days !== -1) {
                const curDays = parseInt(row[slotCols[s].days], 10);
                if (curDays !== finalDays) {
                  confirmedSheet.getRange(r + 1, slotCols[s].days + 1).setValue(finalDays);
                  totalUpdated++;
                  logDetails.push(`[Confirmed] Resolved part-payment balance to Paid for Direct Cost Row ${r + 1} Slot ${s} (${txnId}) (preserving individual payment tranches and cashflow timing).`);
                } else if (currentStatus !== "Paid") {
                  totalUpdated++;
                  logDetails.push(`[Confirmed] Resolved part-payment balance to Paid for Direct Cost Row ${r + 1} Slot ${s} (${txnId}) (preserving individual payment tranches and cashflow timing).`);
                }
              }
            } else if (currentStatus.toLowerCase().includes("part-paid")) {
              confirmedSheet.getRange(r + 1, statusCol + 1).setValue("Paid");
              totalUpdated++;
              logDetails.push(`[Confirmed] Resolved part-paid primary slot to Paid for Direct Cost Row ${r + 1} Slot ${s} (${txnId}).`);
            }
          }
        }
      }
    }
  }

  return { count: totalUpdated, logs: logDetails };
}

