// --- VERTEX AI CONFIGURATION ---
const GCP_PROJECT_ID = 'amd-updater-v2';      // Your exact project ID
const GCP_LOCATION = 'us-central1';           // The primary Tier-0 hub
const MODEL_ID = 'gemini-2.5-flash';          // The full-weight modern model

/**
 * Opens the sidebar UI
 */
function showSalariesSidebar() {
  var html = HtmlService.createHtmlOutputFromFile('SalariesUI')
    .setTitle('Payroll and Time Importer')
    .setWidth(400);
  SpreadsheetApp.getUi().showSidebar(html);
}

/**
 * 1. PAYROLL PROCESSOR (Extraction Phase)
 */
async function processPayload(payloadObj) {
  try {
    if (!payloadObj || !payloadObj.data) throw new Error("No file data received.");
    
    const currentSs = SpreadsheetApp.getActiveSpreadsheet();
    const keyInfoSheet = currentSs.getSheetByName("KeyInfo");
    if (!keyInfoSheet) throw new Error("Tab 'KeyInfo' not found.");
    
    const destUrl = keyInfoSheet.getRange("C1").getValue();
    if (!destUrl) throw new Error("Cell C1 in 'KeyInfo' is empty.");

    const destSs = (await SpreadsheetApp.openByUrl(destUrl));
    const salariesSheet = destSs.getSheetByName("Salaries");
    if (!salariesSheet) throw new Error("'Salaries' tab not found.");

    // Limit to rows 4 to 53 (50 rows)
    const rawList = salariesSheet.getRange(4, 1, 50, 1).getDisplayValues();
    const validEmployeeNames = rawList.flat().filter(name => name && name.trim() !== "");

    const extractedData = (await callGemini(payloadObj, validEmployeeNames));
    if (!extractedData || !extractedData.employees) return "Error: AI extracted data but 'employees' list was empty.";

    const targetMonthStr = extractedData.period; 
    
    if (!targetMonthStr || targetMonthStr.toLowerCase() === "unknown" || targetMonthStr.toLowerCase() === "null") {
      return {
        status: "CONFIRM_PERIOD",
        data: extractedData,
        fallback: getPreviousMonthStr(),
        type: "payroll"
      };
    }

    return (await writePayrollData(extractedData, targetMonthStr));

  } catch (e) { console.error(e); return "Error: " + (e.message || e.toString()); }
}

/**
 * 2. TIME DATA PROCESSOR (Extraction Phase)
 */
async function processTimePayload(payloadObj) {
  try {
    if (!payloadObj || !payloadObj.data) throw new Error("No file data received.");
    
    const currentSs = SpreadsheetApp.getActiveSpreadsheet();
    const timeSheet = currentSs.getSheetByName("TimeComp");
    if (!timeSheet) throw new Error("Tab 'TimeComp' not found.");

    // Limit to rows 12 to 62 (51 rows)
    const rawList = timeSheet.getRange(12, 1, 51, 1).getDisplayValues();
    const validEmployeeNames = rawList.flat().filter(name => name && name.trim() !== "");

    const extractedData = (await callGeminiTime(payloadObj, validEmployeeNames));
    if (!extractedData || !extractedData.employees) return "Error: AI extracted data but 'employees' list was empty.";

    const targetMonthStr = extractedData.period; 

    if (!targetMonthStr || targetMonthStr.toLowerCase() === "unknown" || targetMonthStr.toLowerCase() === "null") {
      return {
        status: "CONFIRM_PERIOD",
        data: extractedData,
        fallback: getPreviousMonthStr(),
        type: "time"
      };
    }

    return writeTimeData(extractedData, targetMonthStr);

  } catch (e) { console.error(e); return "Error: " + (e.message || e.toString()); }
}

/**
 * ==========================================
 * 3. WRITING PHASE FUNCTIONS
 * ==========================================
 */

async function saveConfirmedData(extractedData, targetMonthStr, type) {
  if (type === "payroll") return (await writePayrollData(extractedData, targetMonthStr));
  if (type === "time") return writeTimeData(extractedData, targetMonthStr);
  return "Error: Unknown document type.";
}

function getPreviousMonthStr() {
  const d = new Date();
  d.setMonth(d.getMonth() - 1);
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return months[d.getMonth()] + " " + d.getFullYear();
}

async function writePayrollData(extractedData, targetMonthStr) {
  try {
    const currentSs = SpreadsheetApp.getActiveSpreadsheet();
    const destUrl = currentSs.getSheetByName("KeyInfo").getRange("C1").getValue();
    const salariesSheet = (await (await SpreadsheetApp.openByUrl(destUrl)).getSheetByName("Salaries"));

    // Limit to rows 4 to 53 (50 rows)
    const rawList = salariesSheet.getRange(4, 1, 50, 1).getDisplayValues();
    const headers = salariesSheet.getRange(1, 1, 1, salariesSheet.getLastColumn()).getDisplayValues()[0];

    let startCol = -1;
    for (let i = 0; i < headers.length; i++) {
      if (headers[i] && isDateMatch(headers[i], targetMonthStr)) {
        startCol = i + 1; break;
      }
    }

    if (startCol === -1) return `Error: Could not find column for '${targetMonthStr}'.`;

    const allSheetRows = rawList.flat(); 
    const validEmployeeNames = allSheetRows.filter(name => name && name.trim() !== "");

    let missingLog = `--- MISSING FROM PAYROLL DOCUMENT ---\n`;
    let processedLog = `\n--- PROCESSED EMPLOYEES ---\n`;
    let headerLog = `Target: ${targetMonthStr} (Col ${startCol})\n\n`;
    
    let updateCount = 0;
    let newStarterCount = 0;
    let missingFromDocCount = 0;

    // 1. Find who the AI successfully mapped
    const namesFoundInDoc = [];
    extractedData.employees.forEach(emp => { if (emp.mappedName !== "NEW_STARTER") namesFoundInDoc.push(emp.mappedName); });

    // 2. Check the sheet against the AI's list
    validEmployeeNames.forEach(sheetName => {
      if (!namesFoundInDoc.includes(sheetName)) {
        missingLog += `⚪ IN SHEET, MISSING FROM DOC: ${sheetName}\n`;
        missingFromDocCount++;
      }
    });
    if (missingFromDocCount === 0) missingLog += `✅ All sheet employees found in document.\n`;

    // 3. Process the AI data & flag New Starters
    extractedData.employees.forEach(emp => {
      if (emp.mappedName === "NEW_STARTER") {
        processedLog += `🔴 IN DOC, NOT IN SHEET: ${emp.originalName}\n`;
        newStarterCount++;
        return; 
      }

      const rowIndex = allSheetRows.indexOf(emp.mappedName);
      if (rowIndex > -1) {
        const row = rowIndex + 4; 
        const rowData = [[
            emp.grossPay || 0, emp.eeNic || 0, emp.erNic || 0,
            emp.studLoan || 0, emp.eePension || 0, emp.erPension || 0, emp.paye || 0
        ]];
        salariesSheet.getRange(row, startCol, 1, 7).setValues(rowData);
        updateCount++;
        processedLog += `✅ ${emp.originalName}\n`;
      } else {
        processedLog += `⚠️ UNMATCHED: ${emp.originalName} (Mapped to: ${emp.mappedName})\n`;
        newStarterCount++;
      }
    });

    let summary = `Success! Updated ${updateCount} rows.`;
    if (newStarterCount > 0 || missingFromDocCount > 0) {
      summary += `\n⚠️ Issues: ${newStarterCount} new in doc | ${missingFromDocCount} missing from doc.`;
    }
    
    return summary + "\n\n" + headerLog + missingLog + processedLog;
  } catch (e) { return "Error writing payroll data: " + e.message; }
}

function writeTimeData(extractedData, targetMonthStr) {
  try {
    const currentSs = SpreadsheetApp.getActiveSpreadsheet();
    const timeSheet = currentSs.getSheetByName("TimeComp");
    const rawList = timeSheet.getRange(12, 1, 51, 1).getDisplayValues();
    const validEmployeeNames = rawList.flat().filter(name => name && name.trim() !== "");
    const headers = timeSheet.getRange(4, 1, 1, timeSheet.getLastColumn()).getDisplayValues()[0];

    let startCol = -1;
    for (let i = 0; i < headers.length; i++) {
      if (headers[i] && isDateMatch(headers[i], targetMonthStr)) {
        startCol = i + 1; break;
      }
    }

    if (startCol === -1) return `Error: Could not find column for '${targetMonthStr}' in Row 4.`;

    const allSheetRows = rawList.flat(); 
    let missingLog = `--- MISSING FROM DOCUMENT ---\n`;
    let processedLog = `\n--- PROCESSED EMPLOYEES ---\n`;
    let headerLog = `Target: ${targetMonthStr} (Col ${startCol})\n\n`;
    
    let updateCount = 0;
    let missingFromSheetCount = 0;
    let missingFromDocCount = 0;

    const namesFoundInDoc = [];
    extractedData.employees.forEach(emp => { if (emp.mappedName !== "NEW_STARTER") namesFoundInDoc.push(emp.mappedName); });

    validEmployeeNames.forEach(sheetName => {
      if (!namesFoundInDoc.includes(sheetName)) {
        missingLog += `⚪ IN SHEET, NO TIME LOGGED: ${sheetName}\n`;
        missingFromDocCount++;
      }
    });
    if (missingFromDocCount === 0) missingLog += `✅ All sheet employees had time logged.\n`;

    extractedData.employees.forEach(emp => {
      if (emp.mappedName === "NEW_STARTER") {
        processedLog += `🔴 IN DOC, NOT IN SHEET: ${emp.originalName}\n`;
        missingFromSheetCount++;
        return; 
      }

      const rowIndex = allSheetRows.indexOf(emp.mappedName);
      if (rowIndex > -1) {
        const row = rowIndex + 12; 
        const rowData = [[ emp.billableHrs || 0, emp.totalHrs || 0 ]];
        timeSheet.getRange(row, startCol, 1, 2).setValues(rowData);
        updateCount++;
        processedLog += `✅ ${emp.originalName}\n`;
      } else {
        processedLog += `⚠️ UNMATCHED: ${emp.originalName}\n`;
      }
    });

    let summary = `Success! Updated ${updateCount} rows.`;
    if (missingFromSheetCount > 0 || missingFromDocCount > 0) {
      summary += `\n⚠️ Issues: ${missingFromSheetCount} new in doc | ${missingFromDocCount} missing time.`;
    }
    
    return summary + "\n\n" + headerLog + missingLog + processedLog;
  } catch (e) { return "Error writing time data: " + e.message; }
}

/**
 * ==========================================
 * 4. GEMINI API CALLER (Vertex AI Version)
 * ==========================================
 */

async function callGemini(payloadObj, validNames) {
  const namesString = JSON.stringify(validNames);
  // Get the current real-world date context (e.g., "Jun 2026")
  const currentDateContext = new Date().toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });

  const promptText = `
    Analyze this payroll document.
    TASK 1: Identify the Period. Find the "Ending Date", "Process Date", or "Tax Point". Output format: "MMM YYYY" (e.g. "Jan 2026").
    - CRITICAL DATE HANDLING: The current real-world date context is ${currentDateContext}. If the document explicitly states a month but does NOT provide a year, calculate and output the most recent instance of that month relative to this context date (e.g., if context is Jun 2026 and doc says May, output "May 2026". If doc says Dec, output "Dec 2025"). If no period info is found at all, output "Unknown".
    
    TASK 2: Extract Employee Data visible ON THE DOCUMENT.
    - Go through the document row by row. Extract each person exactly ONCE.
    - Match each name on the document to the closest name in this list: ${namesString}.
    - If a name on the document has NO MATCH in the list, set mappedName to "NEW_STARTER".
    - CRITICAL: Do NOT create entries for names in the list if they do not physically appear on the document.
    - STRICT EXTRACTION RULE: Do NOT perform any math or calculations. Extract the exact numbers as they appear.
    - SEMANTIC FIELD MAPPING: Document headers vary wildly by client. Map the document's keys to our output JSON fields by understanding the financial concept of the field:
      * 'grossPay': The employee's total pay before deductions (e.g., Gross Pay, Total Earnings, Basic Pay).
      * 'eeNic': The employee's National Insurance contribution (e.g., Ee NICs, Class One National Insurance).
      * 'erNic': The employer's National Insurance contribution (e.g., Er NICs, Employer Class One).
      * 'studLoan': Student loan deductions (e.g., Student Loan, Post Graduate Loan).
      * 'eePension': The employee's pension contribution (e.g., Pension Plan Relief At Source, Ee Pension).
      * 'erPension': The employer's pension contribution (e.g., Employer Pension Contribution, Er Pension).
      * 'paye': Income tax paid by the employee (e.g., PAYE, Income Tax, Tax).
    - Extract data for THIS PERIOD ONLY (No YTD).
  `;

  const schema = {
    type: "OBJECT",
    properties: {
      period: { type: "STRING" },
      employees: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            originalName: { type: "STRING" },
            mappedName: { type: "STRING" },
            grossPay: { type: "NUMBER" },
            eeNic: { type: "NUMBER" },
            erNic: { type: "NUMBER" },
            studLoan: { type: "NUMBER" },
            eePension: { type: "NUMBER" },
            erPension: { type: "NUMBER" },
            paye: { type: "NUMBER" }
          },
          required: ["originalName", "mappedName", "grossPay", "eeNic", "erNic", "studLoan", "eePension", "erPension", "paye"]
        }
      }
    },
    required: ["period", "employees"]
  };

  return (await executeGeminiRequest(promptText, payloadObj, schema));
}

async function callGeminiTime(payloadObj, validNames) {
  const namesString = JSON.stringify(validNames);
  // Get the current real-world date context (e.g., "Jun 2026")
  const currentDateContext = new Date().toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });

  const promptText = `
    Analyze this time tracking document.
    TASK 1: Identify the Period (Month/Year). Output format: "MMM YYYY" (e.g. "Jan 2026").
    - CRITICAL DATE HANDLING: The current real-world date context is ${currentDateContext}. If the document explicitly states a month but does NOT provide a year, calculate and output the most recent instance of that month relative to this context date (e.g., if context is Jun 2026 and doc says May, output "May 2026". If doc says Dec, output "Dec 2025"). If no period info is found at all, output "Unknown".
    
    TASK 2: Extract Employee Data visible ON THE DOCUMENT.
    - Go through the document row by row. Extract each person exactly ONCE.
    - Match each name on the document to the closest name in this list: ${namesString}.
    - If a name on the document has NO MATCH in the list, set mappedName to "NEW_STARTER".
    - CRITICAL: Do NOT create entries for names in the list if they do not physically appear on the document.
    
    TASK 3: Extract Hours.
    - SEMANTIC FIELD MAPPING FOR HOURS: Document headers vary by client. Map the document's keys to output fields based on these financial concepts:
      * 'billableHrs': Billable, chargeable, or client hours (e.g., Billable Hours, Actual Billable, Charged Time).
      * 'totalHrs': Total, logged, worked, or overall hours (e.g., Total Hours, Total Logged, Hours Worked, Gross Hours).
  `;

  const schema = {
    type: "OBJECT",
    properties: {
      period: { type: "STRING" },
      employees: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            originalName: { type: "STRING" },
            mappedName: { type: "STRING" },
            billableHrs: { type: "NUMBER" },
            totalHrs: { type: "NUMBER" }
          },
          required: ["originalName", "mappedName", "billableHrs", "totalHrs"]
        }
      }
    },
    required: ["period", "employees"]
  };

  return (await executeGeminiRequest(promptText, payloadObj, schema));
}


async function executeGeminiRequest(promptText, payloadObj, schema) {
  // 1. Build the Vertex AI Endpoint URL
  const url = `https://${GCP_LOCATION}-aiplatform.googleapis.com/v1/projects/${GCP_PROJECT_ID}/locations/${GCP_LOCATION}/publishers/google/models/${MODEL_ID}:generateContent`;

  const parts = [{ text: promptText }];
  
  if (payloadObj.type === 'text') {
    let cleanData = "";
    try {
      const parsedCsv = Utilities.parseCsv(payloadObj.data);
      if (parsedCsv.length > 1) {
        
        // Dynamically find the real header row (skipping garbage rows like "--- SHEET: Sheet1 ---")
        let headerIndex = 0;
        for (let i = 0; i < Math.min(10, parsedCsv.length); i++) {
          const populatedCols = parsedCsv[i].filter(cell => cell && cell.trim() !== "");
          if (populatedCols.length > 2) {
            headerIndex = i;
            break;
          }
        }
        
        const headers = parsedCsv[headerIndex].map(h => h.trim());

        // Build a Vertical Key-Value List, preserving zeroes for structural integrity
        for (let i = headerIndex + 1; i < parsedCsv.length; i++) {
          const row = parsedCsv[i];
          let rowText = `---\n`; 
          let hasData = false;
          
          for (let j = 0; j < headers.length; j++) {
            let val = row[j] ? row[j].trim() : "";
            // Always include the key so the AI schema doesn't misalign missing data
            if (val === "" || val === "NaN") {
              val = "0"; 
            }
            rowText += `${headers[j]}: ${val}\n`;
            hasData = true;
          }
          if (hasData) cleanData += rowText;
        }
      }
    } catch (e) {
      console.warn("CSV parsing failed, using raw text.");
    }
    
    // DEBUG: Toggle this to true if you ever need to inspect the payload again
    const DEBUG_MODE = false;
    if (DEBUG_MODE) {
      console.log("=== COMPILED AI PAYLOAD (START) ===");
      console.log(cleanData.substring(0, 3000)); 
      console.log("=== COMPILED AI PAYLOAD (END) ===");
    }
    
    parts[0].text += `\n\nDOCUMENT DATA (Vertical List):\n${cleanData}`;
  } else {
    parts.push({ inline_data: { mime_type: "image/jpeg", data: payloadObj.data } });
  }

  const payload = {
    // Vertex AI requires the "role" parameter
    contents: [{ role: "user", parts: parts }],
    generationConfig: { 
      responseMimeType: "application/json",
      responseSchema: schema 
    },
    safetySettings: [
      { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
      { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
      { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
      { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" }
    ]
  };

  // 2. Generate secure OAuth token
  const token = ScriptApp.getOAuthToken();

  const options = {
    method: "post", 
    contentType: "application/json", 
    headers: {
      "Authorization": "Bearer " + token
    },
    payload: JSON.stringify(payload), 
    muteHttpExceptions: true
  };

  const maxRetries = 3; let attempt = 0;
  while (attempt < maxRetries) {
    try {
      const response = (await UrlFetchApp.fetch(url, options));
      const responseCode = response.getResponseCode();
      const json = JSON.parse(response.getContentText());

      // Catch GCP permission errors gracefully
      if (responseCode === 403) {
          console.error("Vertex AI 403 error details:", JSON.stringify(json));
          throw new Error("Permission Denied (403): Ensure the Vertex AI API is enabled in your GCP project and billing is active.");
      }
      
      if (responseCode === 429) {
        attempt++; if (attempt < maxRetries) { (await Utilities.sleep(5000)); continue; }
      }
      
      if (!json.candidates || !json.candidates[0]) {
          console.error(`Vertex AI empty/error response (${responseCode}):`, JSON.stringify(json));
          throw new Error(`AI returned empty response or error (HTTP ${responseCode}).`);
      }
      
      const finishReason = json.candidates[0].finishReason;
      if (finishReason && finishReason !== "STOP") {
          console.warn(`AI stopped early. Reason: ${finishReason}`);
      }

      const rawText = json.candidates[0].content.parts[0].text.trim();
      
      try {
        const aiOutput = JSON.parse(rawText);
        console.log("=== EXACT AI OUTPUT ===");
        console.log(JSON.stringify(aiOutput, null, 2));
        return aiOutput;
      } catch (parseError) {
        console.error("=== BROKEN AI JSON OUTPUT ===");
        console.error(rawText);
        console.error("=============================");
        throw new Error(`AI generated malformed text. (${parseError.message})`);
      }

    } catch (e) {
      if (attempt === maxRetries - 1) throw e;
      attempt++; (await Utilities.sleep(3000));
    }
  }
}

/**
 * ==========================================
 * 5. UTILS
 * ==========================================
 */
function isDateMatch(sheetHeader, aiDate) {
  if (!sheetHeader || !aiDate) return false;
  const s1 = sheetHeader.toString().toLowerCase(); 
  const s2 = aiDate.toString().toLowerCase();
  
  if (s1 === s2) return true;
  
  const months = ["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"];
  const m1 = months.find(m => s1.includes(m)); 
  const m2 = months.find(m => s2.includes(m));
  
  const y1 = s1.match(/\d{2,4}/); 
  const y2 = s2.match(/\d{2,4}/);
  
  if (m1 && m2 && m1 === m2) {
    if (!y1 || !y2) return true;
    const year1 = y1[0].length === 2 ? "20" + y1[0] : y1[0];
    const year2 = y2[0].length === 2 ? "20" + y2[0] : y2[0];
    return year1 === year2;
  }
  return false;
}

function findEmployeeRow(sheetNames, targetName) {
  if (!targetName) return -1;
  const target = targetName.toLowerCase().replace(/[^a-z ]/g, "");
  for (let i = 0; i < sheetNames.length; i++) {
    const sheetName = sheetNames[i].toLowerCase().replace(/[^a-z ]/g, "");
    if (sheetName === target) return i;
    if (target.includes(sheetName) || sheetName.includes(target)) return i;

    const tParts = target.split(" ");
    const sParts = sheetName.split(" ");
    if (tParts.length >= 2 && sParts.length >= 2) {
      if (tParts[0] === sParts[0] && tParts[tParts.length - 1] === sParts[sParts.length - 1]) {
        return i;
      }
    }
  }
  return -1;
}




