// CENTRAL PULSE VAULT TOKEN BROKER INTEGRATION (CAPSULE CRM)
// ============================================================================

const PULSE_BROKER_CONFIG_CAPSULE = {
  DEFAULT_BROKER_URL: "https://app.pulsedashboard.co.uk",
  get INTERNAL_SECRET() {
    return typeof getPulseInternalSecret_ === "function"
      ? getPulseInternalSecret_()
      : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "");
  }
};

function getPulseBrokerBaseUrl_Capsule_() {
  return PULSE_BROKER_CONFIG_CAPSULE.DEFAULT_BROKER_URL;
}

async function getBrokerCapsuleAccessToken() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = getPulseBrokerBaseUrl_Capsule_();
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=capsule&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CAPSULE.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : '',
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        return data.accessToken;
      }
    }

    if (statusCode === 404) {
      console.log("Pulse Token Broker returned 404 (not in vault). Checking for existing local Capsule tokens to auto-migrate...");
      const migratedToken = (await autoMigrateLocalCapsuleTokensToPulseVault_(spreadsheetId));
      if (migratedToken) {
        return migratedToken;
      }
    }

    console.warn(`Pulse Token Broker responded with code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("getBrokerCapsuleAccessToken error: " + err.message);
  }

  return null;
}

async function autoMigrateLocalCapsuleTokensToPulseVault_(spreadsheetId) {
  try {
    const props = PropertiesService.getScriptProperties();
    let accessToken = props.getProperty('CAPSULE_ACCESS_TOKEN');
    let refreshToken = props.getProperty('CAPSULE_REFRESH_TOKEN');

    // If we have a local refresh token and the library is available, refresh it to ensure fresh active credentials
    if (refreshToken && typeof CapsuleConnector !== 'undefined' && typeof CapsuleConnector.refreshTokens === 'function') {
      try {
        const refreshed = CapsuleConnector.refreshTokens(refreshToken);
        if (refreshed && refreshed.accessToken) {
          accessToken = refreshed.accessToken;
          refreshToken = refreshed.refreshToken || refreshToken;
          props.setProperty('CAPSULE_ACCESS_TOKEN', accessToken);
          props.setProperty('CAPSULE_REFRESH_TOKEN', refreshToken);
          console.log("Successfully refreshed Capsule tokens via library prior to Vault import.");
        }
      } catch (refErr) {
        console.log("Note: Capsule local library pre-migration refresh attempt: " + refErr.message);
      }
    }

    if (!accessToken && !refreshToken) {
      console.log("No local Capsule CRM tokens found in Script Properties for auto-migration.");
      return null;
    }

    let clientName = "";
    try {
      if (typeof getClientDisplayName === 'function') {
        clientName = getClientDisplayName();
      }
    } catch (e) {}

    const baseUrl = getPulseBrokerBaseUrl_Capsule_();
    const importUrl = `${baseUrl}/api/integrations/import`;

    const payload = {
      tool: 'capsule',
      spreadsheetId: spreadsheetId,
      clientName: clientName,
      accessToken: accessToken || "",
      refreshToken: refreshToken || ""
    };

    const options = {
      method: 'post',
      contentType: 'application/json',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CAPSULE.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : ''
      },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    console.log("Sending Capsule CRM auto-migration request to Pulse Vault for " + (clientName || spreadsheetId) + "...");
    const response = (await UrlFetchApp.fetch(importUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const resData = JSON.parse(responseText);
      if (resData && resData.success && resData.accessToken) {
        console.log("✅ Capsule CRM auto-migration to Pulse Vault successful for " + (clientName || spreadsheetId) + "! Fresh token active.");
        return resData.accessToken;
      }
    }

    console.warn("Capsule auto-migration returned code " + statusCode + ": " + responseText);
  } catch (migErr) {
    console.error("autoMigrateLocalCapsuleTokensToPulseVault_ exception: " + migErr.message);
  }

  return null;
}

async function testPulseCapsuleBroker() {
  Logger.log("=== Testing Pulse Capsule CRM Token Broker ===");
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const spreadsheetId = ss.getId();
  Logger.log("Sheet ID: " + spreadsheetId);

  const token = (await getBrokerCapsuleAccessToken());
  if (token) {
    Logger.log("✅ SUCCESS: Successfully retrieved fresh Capsule CRM access token from Pulse Broker!");
    return "SUCCESS: Token retrieved: " + token.substring(0, 15) + "...";
  } else {
    Logger.log("❌ FAILED: Unable to retrieve Capsule CRM access token from Pulse Broker.");
    return "FAILED: Check execution transcript logs.";
  }
}

