/**
 * Native Inlined API Task Fetcher (Replaces external GAS library dependency)
 */
async function fetchClickUpTasksFromView_(accessToken, viewId) {
  if (!accessToken) {
    throw new Error('No ClickUp access token provided.');
  }

  const allTasks = [];
  let page = 0;
  let hasMore = true;
  
  while (hasMore) {
    const viewUrl = `https://api.clickup.com/api/v2/view/${encodeURIComponent(viewId)}/task?page=${page}&include_custom_fields=true`;
    const options = {
      method: 'get',
      headers: { 'Authorization': accessToken },
      muteHttpExceptions: true
    };
    
    const response = (await UrlFetchApp.fetch(viewUrl, options));
    const result = JSON.parse(response.getContentText());

    if (response.getResponseCode() !== 200) {
      throw new Error(`ClickUp API Error: ${result.err || response.getContentText()} (Code: ${result.ECODE || response.getResponseCode()})`);
    }

    if (result.tasks && result.tasks.length > 0) {
      allTasks.push(...result.tasks);
      page++;
      (await Utilities.sleep(100)); 
    } else {
      hasMore = false;
    }
  }

  return allTasks;
}

/**
 * Main Export Function - Now Headless Compatible
 */
async function exportClickUpListToSheet(isHeadless = false) {
  // 1. Try Central Pulse Vault Token Broker first
  let accessToken = null;
  if (typeof getBrokerClickUpAccessToken === 'function') {
    accessToken = (await getBrokerClickUpAccessToken());
    if (accessToken) {
      Logger.log('Obtained fresh ClickUp access token from Central Pulse Vault.');
    }
  }

  // 2. Legacy fallback
  if (!accessToken) {
    const props = PropertiesService.getScriptProperties();
    accessToken = props.getProperty('CLICKUP_ACCESS_TOKEN');
  }

  if (!accessToken) {
    logOrAlertClickUp('Authorization is required. Please authorize ClickUp manually or connect in Pulse.', isHeadless);
    return;
  }

  // 2. Get Sheet Config
  try {
    const CONFIG = (await getClickUpSheetConfig());
    if (!CONFIG || !CONFIG.CLICKUP_VIEW_ID) {
      logOrAlertClickUp('Error: CLICKUP_VIEW_ID is missing in KeyInfo sheet (Cell X17).', isHeadless);
      return;
    }

    // 3. Fetch Data (uses native inlined fetcher)
    const allTasks = (await fetchClickUpTasksFromView_(accessToken, CONFIG.CLICKUP_VIEW_ID));

    if (!allTasks || allTasks.length === 0) {
      logOrAlertClickUp('No tasks found in the specified view.', isHeadless);
      return;
    }

    // 4. Write to Sheet
    (await writeClickUpDataToSheet(allTasks));
    // 5. Update Timestamp
    if (typeof _updateTimestamp === 'function') _updateTimestamp('CRMComp', 'J2');

    logOrAlertClickUp(`✅ Success! Exported ${allTasks.length} tasks from ClickUp.`, isHeadless);
  } catch (e) {
    logOrAlertClickUp(`ClickUp Export Error: ${e.message}`, isHeadless);
  }
}

// --- LOCAL DATA PARSING FUNCTIONS ---

function parseClickUpCustomFieldValue(field) {
  if (!field || typeof field.value === 'undefined') return '';
  const value = field.value;
  
  // We use the Script's timezone to ensure dates match your location
  const timeZone = Session.getScriptTimeZone(); 

  switch (field.type) {
    case 'drop_down':
      const options = field.type_config.options;
      // Note: usage of '==' is intentional here as value might be string or int
      const selectedOption = options.find(opt => opt.orderindex == value); 
      return selectedOption ? selectedOption.name : '';
      
    case 'labels':
      const labelOptions = field.type_config.options;
      const selectedLabels = value.map(labelId => {
        const foundLabel = labelOptions.find(opt => opt.id === labelId);
        return foundLabel ? foundLabel.label : '';
      });
      return selectedLabels.join(', ');
      
    case 'date': 
      // FIX: Use Utilities.formatDate to strictly enforce dd/MM/yyyy
      return value ? Utilities.formatDate(new Date(parseInt(value)), timeZone, "dd/MM/yyyy") : '';
      
    case 'users': 
      return value.map(user => user.username).join(', ');
      
    case 'checkbox': 
      return value ? 'true' : 'false';
      
    default: 
      return Array.isArray(value) || typeof value === 'object' ? JSON.stringify(value) : value;
  }
}

async function writeClickUpDataToSheet(tasks) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetName = "DataFromCRM";
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) sheet = ss.insertSheet(sheetName);

  // 1. Extract Headers & Compile Data Array
  const baseHeaders = ['Task ID', 'Custom ID', 'Task Name', 'Status', 'Start Date', 'Due Date', 'Date Created', 'Assignees', 'Priority', 'URL'];
  const customFieldHeadersSet = new Set();
  tasks.forEach(task => {
    if (task.custom_fields) {
      task.custom_fields.forEach(field => customFieldHeadersSet.add(field.name));
    }
  });
  const customFieldHeaders = Array.from(customFieldHeadersSet).sort();
  const allHeaders = [...baseHeaders, ...customFieldHeaders];
  
  const customFieldHeaderMap = new Map();
  customFieldHeaders.forEach((header, index) => customFieldHeaderMap.set(header, index));
  
  const timeZone = Session.getScriptTimeZone();
  const dateTimePattern = "dd/MM/yyyy HH:mm";
  
  const data = tasks.map(task => {
    const assignees = task.assignees.map(a => a.username || a.email).join(', ');
    const priority = task.priority ? task.priority.priority : 'N/A';
    const customId = task.custom_id || '';

    const createdDate = task.date_created ? Utilities.formatDate(new Date(parseInt(task.date_created)), timeZone, dateTimePattern) : '';
    const startDate = task.start_date ? Utilities.formatDate(new Date(parseInt(task.start_date)), timeZone, dateTimePattern) : '';
    const dueDate = task.due_date ? Utilities.formatDate(new Date(parseInt(task.due_date)), timeZone, dateTimePattern) : '';

    const baseRow = [task.id, customId, task.name, task.status.status, startDate, dueDate, createdDate, assignees, priority, task.url];
    
    const customFieldValues = new Array(customFieldHeaders.length).fill('');
    if (task.custom_fields) {
      task.custom_fields.forEach(field => {
        const columnIndex = customFieldHeaderMap.get(field.name);
        if (columnIndex !== undefined) {
          customFieldValues[columnIndex] = parseClickUpCustomFieldValue(field);
        }
      });
    }
    return [...baseRow, ...customFieldValues];
  });
  const safeData = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(data) : data;
  const safeHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([allHeaders])[0] : allHeaders;

  const lastRow = sheet.getLastRow();
  const oldHeaders = lastRow > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(safeHeaders);

  // --- EDGE CASE: HEADER CHANGE OR EMPTY SHEET ---
  if (!headersMatch || lastRow <= 1) {
    sheet.clear();
    sheet.getRange(1, 1, 1, safeHeaders.length).setValues([safeHeaders]).setFontWeight('bold');
    if (safeData.length > 0) {
      sheet.getRange(2, 1, safeData.length, 1).setNumberFormat("@"); // Task ID
      sheet.getRange(2, 2, safeData.length, 1).setNumberFormat("@"); // Custom ID
      sheet.getRange(2, 1, safeData.length, safeHeaders.length).setValues(safeData);
    }
    _logDataChangeAlertClickUp();
    Logger.log(`Header change or initialization. Full overwrite complete. Wrote ${safeData.length} rows.`);
    return;
  }

  // --- DELTA UPDATE ENGINE (WITH SLOT REUSE) ---
  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  
  safeData.forEach(row => incomingMap.set(String(row[0]), row)); // Map by Task ID (Col 0)

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  // 1. Identify Updates and Empty Slots
  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      const newData = incomingMap.get(rowId);
      if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
        valueUpdates.push({
          range: `${sheetName}!A${sheetRowNum}`,
          values: [newData]
        });
        dataChanged = true;
      }
      incomingMap.delete(rowId);
    }
  }

  // 2. Identify Appends
  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) dataChanged = true;

  if (!dataChanged) {
    Logger.log('No changes detected in ClickUp. Sheet is up to date.');
    return;
  }

  // 3. Slot Reuse Logic
  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({
        range: `${sheetName}!A${recycleRow}`,
        values: [newRowData]
      });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 2, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  // 4. Clear Remaining Gaps
  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  // 5. Execute all value updates
  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({
      valueInputOption: "USER_ENTERED",
      data: valueUpdates
    }, ss.getId()));
  }

  _logDataChangeAlertClickUp();
  Logger.log(`ClickUp Delta Update Complete.`);
}

