function logOrAlertClickUp(msg, isHeadless) {
  if (typeof logOrAlert === 'function') {
    logOrAlert(msg, isHeadless);
  } else {
    if (isHeadless) Logger.log(msg);
    else SpreadsheetApp.getUi().alert(msg);
  }
}

