// CENTRAL PULSE VAULT TOKEN BROKER INTEGRATION (CLICKUP)
// ============================================================================

const PULSE_BROKER_CONFIG_CLICKUP = {
  DEFAULT_BROKER_URL: "https://app.pulsedashboard.co.uk",
  get INTERNAL_SECRET() {
    return typeof getPulseInternalSecret_ === "function"
      ? getPulseInternalSecret_()
      : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "");
  }
};

function getPulseBrokerBaseUrl_ClickUp_() {
  return PULSE_BROKER_CONFIG_CLICKUP.DEFAULT_BROKER_URL;
}

async function getBrokerClickUpAccessToken() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = getPulseBrokerBaseUrl_ClickUp_();
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=clickup&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CLICKUP.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : '',
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        return data.accessToken;
      }
    }

    if (statusCode === 404) {
      console.log("Pulse Token Broker returned 404 (not in vault). Checking for existing local ClickUp tokens to auto-migrate...");
      const migratedToken = (await autoMigrateLocalClickUpTokensToPulseVault_(spreadsheetId));
      if (migratedToken) {
        return migratedToken;
      }
    }

    console.warn(`Pulse Token Broker responded with code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("getBrokerClickUpAccessToken error: " + err.message);
  }

  return null;
}

async function autoMigrateLocalClickUpTokensToPulseVault_(spreadsheetId) {
  try {
    const props = PropertiesService.getScriptProperties();
    let accessToken = props.getProperty('CLICKUP_ACCESS_TOKEN');

    if (!accessToken && typeof ClickUpConnector !== 'undefined' && typeof ClickUpConnector.getCapturedTokens === 'function') {
      try {
        const tokens = ClickUpConnector.getCapturedTokens();
        if (tokens && tokens.accessToken) accessToken = tokens.accessToken;
      } catch (e) {}
    }

    if (!accessToken) {
      console.log("No local ClickUp access token found in Script Properties for auto-migration.");
      return null;
    }

    let clientName = "";
    try {
      if (typeof getClientDisplayName === 'function') {
        clientName = getClientDisplayName();
      }
    } catch (e) {}

    const baseUrl = getPulseBrokerBaseUrl_ClickUp_();
    const importUrl = `${baseUrl}/api/integrations/import`;

    const payload = {
      tool: 'clickup',
      spreadsheetId: spreadsheetId,
      clientName: clientName,
      accessToken: accessToken
    };

    const options = {
      method: 'post',
      contentType: 'application/json',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CLICKUP.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : ''
      },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    console.log("Sending ClickUp auto-migration request to Pulse Vault for " + (clientName || spreadsheetId) + "...");
    const response = (await UrlFetchApp.fetch(importUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const resData = JSON.parse(responseText);
      if (resData && resData.success && resData.accessToken) {
        console.log("✅ ClickUp auto-migration to Pulse Vault successful for " + (clientName || spreadsheetId) + "! Fresh token active.");
        return resData.accessToken;
      }
    }

    console.warn("ClickUp auto-migration returned code " + statusCode + ": " + responseText);
  } catch (migErr) {
    console.error("autoMigrateLocalClickUpTokensToPulseVault_ exception: " + migErr.message);
  }

  return null;
}

async function testPulseClickUpBroker() {
  Logger.log("=== Testing Pulse ClickUp Token Broker ===");
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const spreadsheetId = ss.getId();
  Logger.log("Sheet ID: " + spreadsheetId);

  const token = (await getBrokerClickUpAccessToken());
  if (token) {
    Logger.log("✅ SUCCESS: Successfully retrieved fresh ClickUp access token from Pulse Broker!");
    return "SUCCESS: Token retrieved: " + token.substring(0, 15) + "...";
  } else {
    Logger.log("❌ FAILED: Unable to retrieve ClickUp access token from Pulse Broker.");
    return "FAILED: Check execution transcript logs.";
  }
}

