/**
 * Native Inlined API Opportunity Fetcher (Replaces external GAS library dependency)
 */
async function fetchCloseOpportunities_(accessToken) {
  if (!accessToken) throw new Error('No Close CRM access token provided.');
  
  const headers = { 'Authorization': `Bearer ${accessToken}` };
  const customFieldUrl = 'https://api.close.com/api/v1/custom_field/opportunity/';
  const cfOptions = { method: 'get', headers: headers, muteHttpExceptions: true };
  const cfResponse = (await UrlFetchApp.fetch(customFieldUrl, cfOptions));
  const cfResult = JSON.parse(cfResponse.getContentText());
  
  if (cfResponse.getResponseCode() !== 200) {
    throw new Error(`Close API Error: ${cfResult.error || cfResponse.getContentText()}`);
  }
  
  const customFieldMap = {};
  if (cfResult.data) {
    cfResult.data.forEach(field => { customFieldMap[field.id] = field.name; });
  }

  const allOpportunities = [];
  let hasMore = true;
  let skip = 0;
  const limit = 100;

  while (hasMore) {
    const opportunitiesUrl = `https://api.close.com/api/v1/opportunity/?_skip=${skip}&_limit=${limit}`;
    const oppOptions = { method: 'get', headers: headers, muteHttpExceptions: true };
    const oppResponse = (await UrlFetchApp.fetch(opportunitiesUrl, oppOptions));
    const oppResult = JSON.parse(oppResponse.getContentText());

    if (oppResponse.getResponseCode() !== 200) {
      throw new Error(`Close API Error: ${oppResult.error || oppResponse.getContentText()}`);
    }

    if (oppResult.data && oppResult.data.length > 0) {
      allOpportunities.push(...oppResult.data);
      skip += oppResult.data.length;
      hasMore = oppResult.has_more;
    } else {
      hasMore = false;
    }
    (await Utilities.sleep(250)); 
  }

  return allOpportunities.map(opp => {
    const cleanCustomFields = [];
    for (const key in opp) {
      if (key.startsWith('custom.') && customFieldMap[key.substring(7)]) {
        const fieldId = key.substring(7);
        const fieldDefinition = cfResult.data ? cfResult.data.find(f => f.id === fieldId) : null;
        cleanCustomFields.push({
          name: customFieldMap[fieldId],
          value: opp[key],
          type: fieldDefinition ? fieldDefinition.type : 'text', 
          type_config: { options: (fieldDefinition && fieldDefinition.choices) ? fieldDefinition.choices : [] }
        });
      }
    }
    opp.custom_fields = cleanCustomFields;
    return opp;
  });
}

/**
 * Main Export Function - Headless Compatible
 */
async function exportCloseOpportunitiesToSheet(isHeadless = false) {
  // 1. Try Central Pulse Vault Token Broker first
  let accessToken = null;
  if (typeof getBrokerCloseAccessToken === 'function') {
    accessToken = (await getBrokerCloseAccessToken());
    if (accessToken) {
      Logger.log('Obtained fresh Close CRM access token from Central Pulse Vault.');
    }
  }

  // 2. Legacy fallback
  if (!accessToken) {
    const props = PropertiesService.getScriptProperties();
    const refreshToken = props.getProperty('CLOSE_REFRESH_TOKEN');

    if (!refreshToken) {
      logOrAlertClose('No connection found. Please authorize Close manually or connect in Pulse.', isHeadless);
      return;
    }

    try {
      if (typeof CloseConnector !== 'undefined' && typeof CloseConnector.refreshTokens === 'function') {
        const newCreds = CloseConnector.refreshTokens(refreshToken);
        props.setProperty('CLOSE_ACCESS_TOKEN', newCreds.accessToken);
        if (newCreds.refreshToken) props.setProperty('CLOSE_REFRESH_TOKEN', newCreds.refreshToken);
        accessToken = newCreds.accessToken;
      } else {
        logOrAlertClose('Close CRM connection required in PMA.', isHeadless);
        return;
      }
      props.setProperty('CLOSE_ACCESS_TOKEN', newCreds.accessToken);
      if (newCreds.refreshToken) props.setProperty('CLOSE_REFRESH_TOKEN', newCreds.refreshToken);
      accessToken = newCreds.accessToken;
    } catch (e) {
      logOrAlertClose(`Close Refresh Error: ${e.message}`, isHeadless);
      return;
    }
  }

  try {
    // Fetch Data
    const allOpportunities = (await fetchCloseOpportunities_(accessToken));
    if (!allOpportunities || allOpportunities.length === 0) {
      logOrAlertClose('No opportunities found.', isHeadless);
      return;
    }

    (await writeCloseOpportunitiesToSheet(allOpportunities));
    if (typeof _updateTimestamp === 'function') _updateTimestamp('CRMComp', 'J2');

    logOrAlertClose(`✅ Success! Exported ${allOpportunities.length} opportunities.`, isHeadless);
  } catch (e) {
    logOrAlertClose(`Close Export Error: ${e.message}`, isHeadless);
  }
}

async function writeCloseOpportunitiesToSheet(opportunities) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetName = "DataFromCRM"; 
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) sheet = ss.insertSheet(sheetName);

  // 1. Extract Headers & Compile Data
  const baseHeaders = ['Opportunity ID', 'Lead ID', 'Lead Name', 'Status', 'Value', 'Confidence', 'Expected Value', 'Created Date', 'Updated Date', 'Won Date', 'User Name'];
  const customFieldHeadersSet = new Set();
  opportunities.forEach(opp => {
    if (opp.custom_fields) opp.custom_fields.forEach(field => customFieldHeadersSet.add(field.name));
  });
  const customFieldHeaders = Array.from(customFieldHeadersSet).sort();
  const allHeaders = [...baseHeaders, ...customFieldHeaders];
  
  const customFieldHeaderMap = new Map();
  customFieldHeaders.forEach((header, index) => customFieldHeaderMap.set(header, index));
  const dateOptions = { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' };

  const data = opportunities.map(opp => {
    const formatDate = (dateString) => dateString ? new Date(dateString).toLocaleString('en-GB', dateOptions) : '';
    const value = opp.value_period === 'one_time' ? (opp.value / 100) : (opp.value / 100) + ` per ${opp.value_period}`;
    const expectedValue = opp.value_period === 'one_time' ? ((opp.value * (opp.confidence / 100)) / 100) : (((opp.value * (opp.confidence / 100)) / 100) + ` per ${opp.value_period}`);

    const baseRow = [
      opp.id, opp.lead_id, opp.lead_name, opp.status_label, value,
      opp.confidence ? opp.confidence + '%' : '0%', 
      expectedValue,
      formatDate(opp.date_created), formatDate(opp.date_updated), formatDate(opp.date_won), opp.user_name
    ];
    
    const customFieldValues = new Array(customFieldHeaders.length).fill('');
    if (opp.custom_fields) {
      opp.custom_fields.forEach(field => {
        const columnIndex = customFieldHeaderMap.get(field.name);
        if (columnIndex !== undefined) customFieldValues[columnIndex] = parseCloseCustomFieldValue(field);
      });
    }
    return [...baseRow, ...customFieldValues];
  });
  const safeData = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(data) : data;
  const safeHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([allHeaders])[0] : allHeaders;

  const lastRow = sheet.getLastRow();
  const oldHeaders = lastRow > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(safeHeaders);

  // --- EDGE CASE: HEADER CHANGE OR EMPTY SHEET ---
  if (!headersMatch || lastRow <= 1) {
    sheet.clear();
    sheet.getRange(1, 1, 1, safeHeaders.length).setValues([safeHeaders]).setFontWeight('bold');
    if (safeData.length > 0) {
      sheet.getRange(2, 1, safeData.length, 1).setNumberFormat("@"); // Opp ID
      sheet.getRange(2, 2, safeData.length, 1).setNumberFormat("@"); // Lead ID
      sheet.getRange(2, 1, safeData.length, safeHeaders.length).setValues(safeData);
    }
    Logger.log(`Header change or initialization. Full overwrite complete. Wrote ${safeData.length} rows.`);
    return;
  }

  // --- DELTA UPDATE ENGINE (WITH SLOT REUSE) ---
  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  safeData.forEach(row => incomingMap.set(String(row[0]), row));

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      const newData = incomingMap.get(rowId);
      if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
        valueUpdates.push({ range: `${sheetName}!A${sheetRowNum}`, values: [newData] });
        dataChanged = true;
      }
      incomingMap.delete(rowId);
    }
  }

  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) dataChanged = true;

  if (!dataChanged) return;

  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({ range: `${sheetName}!A${recycleRow}`, values: [newRowData] });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 2, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, ss.getId()));
  }
}

function parseCloseCustomFieldValue(field) {
  if (!field || typeof field.value === 'undefined' || field.value === null) return '';
  const value = field.value;
  switch (field.type) {
    case 'choices': return Array.isArray(value) ? value.join(', ') : value;
    case 'date': return value ? new Date(value).toLocaleDateString('en-GB') : '';
    case 'datetime': return value ? new Date(value).toLocaleString('en-GB', { timeZone: 'Europe/London' }) : '';
    case 'user':
    case 'contact': return Array.isArray(value) ? value.join(', ') : value;
    default: return (typeof value === 'object') ? JSON.stringify(value) : value.toString();
  }
}

