const PULSE_BROKER_CONFIG_CLOSE = {
  DEFAULT_BROKER_URL: "https://app.pulsedashboard.co.uk",
  get INTERNAL_SECRET() {
    return typeof getPulseInternalSecret_ === "function"
      ? getPulseInternalSecret_()
      : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "");
  }
};

function getPulseBrokerBaseUrl_Close_() {
  return PULSE_BROKER_CONFIG_CLOSE.DEFAULT_BROKER_URL;
}

async function getBrokerCloseAccessToken() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = getPulseBrokerBaseUrl_Close_();
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=close&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CLOSE.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : '',
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        return data.accessToken;
      }
    }

    if (statusCode === 404) {
      console.log("Pulse Token Broker returned 404 (not in vault). Checking for existing local Close CRM tokens to auto-migrate...");
      const migratedToken = (await autoMigrateLocalCloseTokensToPulseVault_(spreadsheetId));
      if (migratedToken) {
        return migratedToken;
      }
    }

    console.warn(`Pulse Token Broker responded with code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("getBrokerCloseAccessToken error: " + err.message);
  }

  return null;
}

async function autoMigrateLocalCloseTokensToPulseVault_(spreadsheetId) {
  try {
    const props = PropertiesService.getScriptProperties();
    let accessToken = props.getProperty('CLOSE_ACCESS_TOKEN');
    let refreshToken = props.getProperty('CLOSE_REFRESH_TOKEN');

    // If we have a local refresh token and the library is available, refresh it to ensure fresh active credentials
    if (refreshToken && typeof CloseConnector !== 'undefined' && typeof CloseConnector.refreshTokens === 'function') {
      try {
        const refreshed = CloseConnector.refreshTokens(refreshToken);
        if (refreshed && refreshed.accessToken) {
          accessToken = refreshed.accessToken;
          refreshToken = refreshed.refreshToken || refreshToken;
          props.setProperty('CLOSE_ACCESS_TOKEN', accessToken);
          props.setProperty('CLOSE_REFRESH_TOKEN', refreshToken);
          console.log("Successfully refreshed Close CRM tokens via library prior to Vault import.");
        }
      } catch (refErr) {
        console.log("Note: Close local library pre-migration refresh attempt: " + refErr.message);
      }
    }

    if (!accessToken && !refreshToken) {
      console.log("No local Close CRM tokens found in Script Properties for auto-migration.");
      return null;
    }

    let clientName = "";
    try {
      if (typeof getClientDisplayName === 'function') {
        clientName = getClientDisplayName();
      }
    } catch (e) {}

    const baseUrl = getPulseBrokerBaseUrl_Close_();
    const importUrl = `${baseUrl}/api/integrations/import`;

    const payload = {
      tool: 'close',
      spreadsheetId: spreadsheetId,
      clientName: clientName,
      accessToken: accessToken || "",
      refreshToken: refreshToken || ""
    };

    const options = {
      method: 'post',
      contentType: 'application/json',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_CLOSE.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : ''
      },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    console.log("Sending Close CRM auto-migration request to Pulse Vault for " + (clientName || spreadsheetId) + "...");
    const response = (await UrlFetchApp.fetch(importUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const resData = JSON.parse(responseText);
      if (resData && resData.success && resData.accessToken) {
        console.log("✅ Close CRM auto-migration to Pulse Vault successful for " + (clientName || spreadsheetId) + "! Fresh token active.");
        return resData.accessToken;
      }
    }

    console.warn("Close auto-migration returned code " + statusCode + ": " + responseText);
  } catch (migErr) {
    console.error("autoMigrateLocalCloseTokensToPulseVault_ exception: " + migErr.message);
  }

  return null;
}

async function testPulseCloseBroker() {
  Logger.log("=== Testing Pulse Close CRM Token Broker ===");
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const spreadsheetId = ss.getId();
  Logger.log("Sheet ID: " + spreadsheetId);

  const token = (await getBrokerCloseAccessToken());
  if (token) {
    Logger.log("✅ SUCCESS: Successfully retrieved fresh Close CRM access token from Pulse Broker!");
    return "SUCCESS: Token retrieved: " + token.substring(0, 15) + "...";
  } else {
    Logger.log("❌ FAILED: Unable to retrieve Close CRM access token from Pulse Broker.");
    return "FAILED: Check execution transcript logs.";
  }
}

