/**
 * Native Inlined API Deal Fetcher (Replaces external GAS library dependency)
 */
async function fetchHubSpotDeals_(accessToken) {
  if (!accessToken) throw new Error('No HubSpot access token provided.');

  const headers = { 
    'Authorization': 'Bearer ' + accessToken,
    'Content-Type': 'application/json'
  };

  const propertiesUrl = 'https://api.hubapi.com/crm/v3/properties/deals';
  const propOptions = { method: 'get', headers: headers, muteHttpExceptions: true };
  const propResponse = (await UrlFetchApp.fetch(propertiesUrl, propOptions));
  
  if (propResponse.getResponseCode() !== 200) {
    throw new Error('Error fetching Deal Properties: ' + propResponse.getContentText());
  }

  const propJson = JSON.parse(propResponse.getContentText());
  const allPropertyNames = [];
  const propertyLabelMap = {}; 
  
  if (propJson.results) {
    propJson.results.forEach(prop => {
      if (!prop.hidden) {
        allPropertyNames.push(prop.name);
        propertyLabelMap[prop.name] = prop.label;
      }
    });
  }

  const allDeals = [];
  let after = 0;
  let hasMore = true;
  
  while (hasMore) {
    const searchUrl = 'https://api.hubapi.com/crm/v3/objects/deals/search';
    const payload = {
      "filterGroups": [], 
      "properties": allPropertyNames,
      "limit": 100,
      "after": after
    };

    const searchOptions = {
      method: 'post',
      headers: headers,
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(searchUrl, searchOptions));
    const result = JSON.parse(response.getContentText());

    if (response.getResponseCode() !== 200) {
      throw new Error(`HubSpot API Error: ${result.message || response.getContentText()}`);
    }

    if (result.results && result.results.length > 0) {
      allDeals.push(...result.results);
      if (result.paging && result.paging.next && result.paging.next.after) {
        after = result.paging.next.after;
      } else {
        hasMore = false;
      }
    } else {
      hasMore = false;
    }
    
    (await Utilities.sleep(200)); 
  }

  return allDeals.map(deal => {
    const props = deal.properties || {};
    const flatDeal = {
      id: deal.id,
      createdAt: deal.createdAt,
      updatedAt: deal.updatedAt,
      archived: deal.archived,
      dealname: props.dealname || '',
      amount: props.amount || '',
      dealstage: props.dealstage || '',
      pipeline: props.pipeline || ''
    };

    flatDeal.custom_fields = [];
    for (const key in props) {
      flatDeal.custom_fields.push({
        name: propertyLabelMap[key] || key,
        value: props[key]
      });
    }
    
    return flatDeal;
  });
}

/**
 * Main Export Function - Headless Compatible
 */
async function exportHubSpotDealsToSheet(isHeadless = false) {
  // 1. Try Central Pulse Vault Token Broker first
  let accessToken = null;
  if (typeof getBrokerHubSpotAccessToken === 'function') {
    accessToken = (await getBrokerHubSpotAccessToken());
    if (accessToken) {
      Logger.log('Obtained fresh HubSpot access token from Central Pulse Vault.');
    }
  }

  // 2. Legacy fallback
  if (!accessToken) {
    const props = PropertiesService.getScriptProperties();
    const refreshToken = props.getProperty('HUBSPOT_REFRESH_TOKEN');

    if (!refreshToken) {
      logOrAlertHubSpot('Authorization required. Please authorize HubSpot manually or connect in Pulse.', isHeadless);
      return;
    }

    try {
      if (typeof HubSpotConnector !== 'undefined' && typeof HubSpotConnector.refreshTokens === 'function') {
        const newCreds = HubSpotConnector.refreshTokens(refreshToken);
        props.setProperty('HUBSPOT_ACCESS_TOKEN', newCreds.accessToken);
        if (newCreds.refreshToken) props.setProperty('HUBSPOT_REFRESH_TOKEN', newCreds.refreshToken);
        accessToken = newCreds.accessToken;
      } else {
        logOrAlertHubSpot('HubSpot connection required in PMA.', isHeadless);
        return;
      }
      props.setProperty('HUBSPOT_ACCESS_TOKEN', newCreds.accessToken);
      if (newCreds.refreshToken) props.setProperty('HUBSPOT_REFRESH_TOKEN', newCreds.refreshToken);
      accessToken = newCreds.accessToken;
    } catch (e) {
      logOrAlertHubSpot(`HubSpot Refresh Error: ${e.message}`, isHeadless);
      return;
    }
  }

  try {
    // Fetch Data
    const allDeals = (await fetchHubSpotDeals_(accessToken));
    if (!allDeals || allDeals.length === 0) {
      logOrAlertHubSpot('No deals found in HubSpot.', isHeadless);
      return;
    }

    // 3. Write to Sheet
    (await writeHubSpotDataToSheet(allDeals));
    // 4. Update Timestamp
    if (typeof _updateTimestamp === 'function') {
        _updateTimestamp('CRMComp', 'J2');
    }

    logOrAlertHubSpot(`✅ Success! Exported ${allDeals.length} deals from HubSpot.`, isHeadless);
  } catch (e) {
    logOrAlertHubSpot(`HubSpot Export Error: ${e.message}`, isHeadless);
  }
}

// --- LOCAL DATA PARSING FUNCTIONS ---

function parseHubSpotValue(val) {
  if (val === undefined || val === null) return '';
  if (typeof val === 'object') return JSON.stringify(val);
  return val;
}

async function writeHubSpotDataToSheet(deals) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetName = "DataFromCRM";
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) sheet = ss.insertSheet(sheetName);

  const baseHeaders = ['Deal ID', 'Deal Name', 'Stage', 'Amount', 'Pipeline', 'Created Date', 'Updated Date'];
  const cfHeadersSet = new Set();
  deals.forEach(deal => {
    if (deal.custom_fields && Array.isArray(deal.custom_fields)) {
      deal.custom_fields.forEach(cf => { 
        if (!['Deal Name', 'Amount', 'Deal Stage', 'Pipeline'].includes(cf.name)) {
            cfHeadersSet.add(cf.name); 
        }
      });
    }
  });
  const cfHeaders = Array.from(cfHeadersSet).sort();
  const allHeaders = [...baseHeaders, ...cfHeaders];
  
  const cfHeaderMap = new Map();
  cfHeaders.forEach((h, i) => cfHeaderMap.set(h, i));
  const dateOptions = { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' };
  const formatDate = (d) => d ? new Date(d).toLocaleString('en-GB', dateOptions) : '';

  const data = deals.map(deal => {
    const baseRow = [
      deal.id, deal.dealname, deal.dealstage, deal.amount, deal.pipeline,
      formatDate(deal.createdAt), formatDate(deal.updatedAt)
    ];

    const cfValues = new Array(cfHeaders.length).fill('');
    if (deal.custom_fields && Array.isArray(deal.custom_fields)) {
      deal.custom_fields.forEach(cf => {
        const idx = cfHeaderMap.get(cf.name);
        if (idx !== undefined) cfValues[idx] = parseHubSpotValue(cf.value);
      });
    }
    return [...baseRow, ...cfValues];
  });
  const safeData = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(data) : data;
  const safeHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([allHeaders])[0] : allHeaders;

  const lastRow = sheet.getLastRow();
  const oldHeaders = lastRow > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(safeHeaders);

  if (!headersMatch || lastRow <= 1) {
    sheet.clear();
    sheet.getRange(1, 1, 1, safeHeaders.length).setValues([safeHeaders]).setFontWeight('bold');
    if (safeData.length > 0) {
      sheet.getRange(2, 1, safeData.length, 1).setNumberFormat("@");
      sheet.getRange(2, 1, safeData.length, safeHeaders.length).setValues(safeData);
    }
    _logDataChangeAlertHubSpot();
    return;
  }

  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  safeData.forEach(row => incomingMap.set(String(row[0]), row));

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      const newData = incomingMap.get(rowId);
      if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
        valueUpdates.push({ range: `${sheetName}!A${sheetRowNum}`, values: [newData] });
        dataChanged = true;
      }
      incomingMap.delete(rowId);
    }
  }

  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) dataChanged = true;

  if (!dataChanged) return;

  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({ range: `${sheetName}!A${recycleRow}`, values: [newRowData] });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, ss.getId()));
  }

  _logDataChangeAlertHubSpot();
}

