/**
 * =========================================
 * ==      MONDAY.COM CONNECTOR FUNCTIONS ==
 * =========================================
 * VERSION 3.31 - Validate Monday boardId and cursor against GraphQL injection and sanitize formula-leading cells in writeMondayDataToSheet
 * VERSION 3.30 - Enforce canonical Pulse Broker URL and remove legacy OAuth HTML dialog fallback
 */

async function showMondayAuthorizationDialog() {
  if (typeof showPulseIntegrationDialog === 'function') {
    (await showPulseIntegrationDialog('Monday.com', 'monday'));
    return;
  }
  const ui = SpreadsheetApp.getUi();
  ui.alert('Please manage Monday.com in the Pulse Management Area (PMA > Integrations).');
}

function saveMondayConnection() {
  const ui = SpreadsheetApp.getUi();
  try {
    const tokens = MondayConnector.getCapturedTokens();
    PropertiesService.getScriptProperties().setProperty('MONDAY_ACCESS_TOKEN', tokens.accessToken);
    if (tokens.refreshToken) PropertiesService.getScriptProperties().setProperty('MONDAY_REFRESH_TOKEN', tokens.refreshToken);
    ui.alert('Success! Monday.com connection saved.');
  } catch (e) { ui.alert('Error: ' + e.message); }
}

function logoffFromMonday() {
  const ui = SpreadsheetApp.getUi();
  PropertiesService.getScriptProperties().deleteProperty('MONDAY_ACCESS_TOKEN');
  PropertiesService.getScriptProperties().deleteProperty('MONDAY_REFRESH_TOKEN');
  if (typeof MondayConnector !== 'undefined' && typeof MondayConnector.reset === 'function') {
    MondayConnector.reset();
  }
  ui.alert('Local Monday.com token cleared.\n\nTo disconnect or revoke access centrally, please visit the Pulse Management Area (PMA > Integrations).');
}

/**
 * Native Inlined API Board Fetcher (Replaces external GAS library dependency)
 */
async function fetchMondayBoardData_(accessToken, boardId) {
  if (!accessToken) throw new Error('No Monday.com access token provided.');
  if (!boardId) throw new Error('No Monday.com Board ID provided.');
  const safeBoardId = String(boardId).trim();
  if (!/^\d+$/.test(safeBoardId)) {
    throw new Error('Invalid Monday.com Board ID format (must be numeric).');
  }

  const columnsQuery = `query { boards (ids: ${safeBoardId}) { columns { id title type } } }`;
  const columnsData = (await makeMondayGraphQLRequest_(accessToken, columnsQuery));
  
  if (!columnsData.boards || columnsData.boards.length === 0) {
    throw new Error(`Board with ID ${safeBoardId} not found or access denied.`);
  }
  
  const columns = columnsData.boards[0].columns;
  const columnMap = {};
  columns.forEach(col => columnMap[col.id] = col.title);

  const allItems = [];
  let cursor = null;
  let hasMore = true;

  while (hasMore) {
    let query = '';
    if (cursor) {
      if (!/^[A-Za-z0-9+/=_.-]+$/.test(String(cursor))) {
        throw new Error('Invalid Monday.com pagination cursor.');
      }
      query = `query { boards (ids: ${safeBoardId}) { items_page (limit: 100, cursor: "${cursor}") { cursor items { id name created_at updated_at column_values { id text value } } } } }`;
    } else {
      query = `query { boards (ids: ${safeBoardId}) { items_page (limit: 100) { cursor items { id name created_at updated_at column_values { id text value } } } } }`;
    }

    const data = (await makeMondayGraphQLRequest_(accessToken, query));
    const page = data.boards[0].items_page;
    
    if (page.items && page.items.length > 0) {
      allItems.push(...page.items);
    }
    
    cursor = page.cursor;
    if (!cursor) {
      hasMore = false;
    }
    
    (await Utilities.sleep(100));
  }

  return allItems.map(item => {
    const processedItem = {
      id: item.id,
      name: item.name,
      created_at: item.created_at,
      updated_at: item.updated_at,
      columns: {}
    };

    if (item.column_values) {
      item.column_values.forEach(cv => {
        const title = columnMap[cv.id] || cv.id;
        processedItem.columns[title] = cv.text || '';
      });
    }
    
    return processedItem;
  });
}

async function makeMondayGraphQLRequest_(accessToken, query) {
  const options = {
    method: 'post',
    headers: {
      'Authorization': accessToken,
      'Content-Type': 'application/json'
    },
    payload: JSON.stringify({ query: query }),
    muteHttpExceptions: true
  };

  const response = (await UrlFetchApp.fetch('https://api.monday.com/v2', options));
  const json = JSON.parse(response.getContentText());

  if (json.errors) {
    throw new Error('Monday GraphQL Error: ' + JSON.stringify(json.errors));
  }
  if (response.getResponseCode() >= 400) {
    throw new Error('Monday API Error: ' + response.getContentText());
  }

  return json.data;
}

/**
 * Main Export Function - Headless Compatible
 */
async function exportMondayBoardToSheet(isHeadless = false) {
  // Reuse core helper for Board ID if possible
  let boardId;
  try {
    boardId = (await getKeyInfoValue('X24'));
  } catch(e) {
    if(!isHeadless) logOrAlertMonday('KeyInfo X24 Error: ' + e.message, isHeadless);
    return;
  }

  // 1. Try Central Pulse Vault Token Broker first
  let currentToken = null;
  if (typeof getBrokerMondayAccessToken === 'function') {
    currentToken = (await getBrokerMondayAccessToken());
    if (currentToken) {
      Logger.log('Obtained fresh Monday.com access token from Central Pulse Vault.');
    }
  }

  // 2. Legacy fallback
  if (!currentToken) {
    const props = PropertiesService.getScriptProperties();
    const accessToken = props.getProperty('MONDAY_ACCESS_TOKEN');
    const refreshToken = props.getProperty('MONDAY_REFRESH_TOKEN');

    if (!accessToken) {
      logOrAlertMonday('Please Authorize Monday.com in Pulse.', isHeadless);
      return;
    }

    currentToken = accessToken;
    if (refreshToken) {
      try {
        if (typeof MondayConnector !== 'undefined' && typeof MondayConnector.refreshTokens === 'function') {
        const newCreds = MondayConnector.refreshTokens(refreshToken);
        props.setProperty('MONDAY_ACCESS_TOKEN', newCreds.accessToken);
        if (newCreds.refreshToken) props.setProperty('MONDAY_REFRESH_TOKEN', newCreds.refreshToken);
        currentToken = newCreds.accessToken;
      }
        props.setProperty('MONDAY_ACCESS_TOKEN', newCreds.accessToken);
        if (newCreds.refreshToken) props.setProperty('MONDAY_REFRESH_TOKEN', newCreds.refreshToken);
        currentToken = newCreds.accessToken;
      } catch (err) {
        console.log("Token refresh failed/not needed: " + err.message);
      }
    }
  }

  try {
    const items = (await fetchMondayBoardData_(currentToken, boardId));
    if (!items || items.length === 0) {
      logOrAlertMonday('No items found on this board.', isHeadless);
      return;
    }

    (await writeMondayDataToSheet(items));
    if (typeof _updateTimestamp === 'function') _updateTimestamp('CRMComp', 'J2');

    logOrAlertMonday(`✅ Success! Exported ${items.length} items from Monday.com.`, isHeadless);
  } catch (e) {
    logOrAlertMonday('Monday Export Error: ' + e.message, isHeadless);
  }
}

async function writeMondayDataToSheet(items) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetName = "DataFromCRM";
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) sheet = ss.insertSheet(sheetName);

  const dynamicHeaders = new Set();
  items.forEach(item => Object.keys(item.columns).forEach(key => dynamicHeaders.add(key)));
  const sortedDynamicHeaders = Array.from(dynamicHeaders).sort();
  const staticHeaders = ['ID', 'Name', 'Created At', 'Updated At'];
  const allHeaders = [...staticHeaders, ...sortedDynamicHeaders];
  const headerMap = new Map();
  allHeaders.forEach((h, i) => headerMap.set(h, i));

  const rawData = items.map(item => {
    const row = new Array(allHeaders.length).fill('');
    row[0] = item.id; row[1] = item.name; row[2] = item.created_at; row[3] = item.updated_at;
    Object.keys(item.columns).forEach(colName => {
      const idx = headerMap.get(colName);
      if (idx !== undefined) row[idx] = item.columns[colName];
    });
    return row;
  });
  const data = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(rawData) : rawData;
  const safeHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([allHeaders])[0] : allHeaders;

  const lastRow = sheet.getLastRow();
  const oldHeaders = lastRow > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(safeHeaders);

  if (!headersMatch || lastRow <= 1) {
    sheet.clear();
    sheet.getRange(1, 1, 1, safeHeaders.length).setValues([safeHeaders]).setFontWeight('bold');
    if (data.length > 0) {
      sheet.getRange(2, 1, data.length, 1).setNumberFormat("@");
      sheet.getRange(2, 1, data.length, safeHeaders.length).setValues(data);
    }
    _logDataChangeAlertMonday();
    return;
  }

  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  data.forEach(row => incomingMap.set(String(row[0]), row));

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      const newData = incomingMap.get(rowId);
      if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
        valueUpdates.push({ range: `${sheetName}!A${sheetRowNum}`, values: [newData] });
        dataChanged = true;
      }
      incomingMap.delete(rowId);
    }
  }

  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) dataChanged = true;

  if (!dataChanged) return;

  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({ range: `${sheetName}!A${recycleRow}`, values: [newRowData] });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, ss.getId()));
  }

  _logDataChangeAlertMonday();
}

// --- MONDAY LOCAL HELPERS ---

function _logDataChangeAlertMonday() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let s = ss.getSheetByName('DataChgAlert');
    if (!s) s = ss.insertSheet('DataChgAlert', 0);
    s.getRange('H2').setValue('Yes');
    s.getRange('I2').setValue(new Date());
  } catch (e) {}
}

