/**
 * Native Inlined API Opportunity Fetcher (Replaces external GAS library dependency)
 */
async function fetchPipedriveOpportunities_(accessToken) {
  if (!accessToken) {
    throw new Error('No Pipedrive access token provided.');
  }

  const fieldsUrl = 'https://api.pipedrive.com/v1/dealFields';
  const fieldsOptions = {
    method: 'get',
    headers: { 'Authorization': 'Bearer ' + accessToken },
    muteHttpExceptions: true
  };
  const fieldsResponse = (await UrlFetchApp.fetch(fieldsUrl, fieldsOptions));
  const fieldsJson = JSON.parse(fieldsResponse.getContentText());
  
  if (fieldsResponse.getResponseCode() !== 200) {
    throw new Error('Error fetching Deal Fields: ' + fieldsResponse.getContentText());
  }

  const fieldMap = {};
  if (fieldsJson.data) {
    fieldsJson.data.forEach(field => {
      fieldMap[field.key] = field.name;
    });
  }

  const allDeals = [];
  let start = 0;
  const limit = 100;
  let hasMore = true;

  while (hasMore) {
    const dealsUrl = `https://api.pipedrive.com/v1/deals?start=${start}&limit=${limit}`;
    const dealsOptions = {
      method: 'get',
      headers: { 'Authorization': 'Bearer ' + accessToken },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(dealsUrl, dealsOptions));
    const result = JSON.parse(response.getContentText());

    if (response.getResponseCode() !== 200) {
      throw new Error(`Pipedrive API Error: ${result.error || response.getContentText()}`);
    }

    if (result.data && result.data.length > 0) {
      allDeals.push(...result.data);
      if (result.additional_data && result.additional_data.pagination && result.additional_data.pagination.more_items_in_collection) {
        start = result.additional_data.pagination.next_start;
      } else {
        hasMore = false;
      }
    } else {
      hasMore = false;
    }
    
    (await Utilities.sleep(200));
  }

  return allDeals.map(deal => {
    const customFields = [];
    for (const key in deal) {
      if (fieldMap[key] && key.length > 20) {
        let val = deal[key];
        if (typeof val === 'object' && val !== null) {
           val = JSON.stringify(val);
        }
        customFields.push({
          name: fieldMap[key],
          value: val
        });
      }
    }

    return {
      id: deal.id,
      title: deal.title,
      person_name: deal.person_name,
      org_name: deal.org_name,
      status: deal.status,
      value: deal.value,
      currency: deal.currency,
      stage_id: deal.stage_id,
      won_time: deal.won_time,
      add_time: deal.add_time,
      close_time: deal.close_time,
      expected_close_date: deal.expected_close_date,
      probability: deal.probability,
      owner_name: deal.owner_name,
      custom_fields: customFields
    };
  });
}

/**
 * Main Export Function - Headless Compatible
 */
async function exportPipeDriveDealsToSheet(isHeadless = false) {
  // 1. Try Central Pulse Vault Token Broker first
  let accessToken = null;
  if (typeof getBrokerPipedriveAccessToken === 'function') {
    accessToken = (await getBrokerPipedriveAccessToken());
    if (accessToken) {
      Logger.log('Obtained fresh Pipedrive access token from Central Pulse Vault.');
    }
  }

  // 2. Legacy fallback
  if (!accessToken) {
    const props = PropertiesService.getScriptProperties();
    const refreshToken = props.getProperty('PIPEDRIVE_REFRESH_TOKEN');

    if (!refreshToken) {
      logOrAlertPipedrive('Authorization required. Please authorize PipeDrive in Pulse.', isHeadless);
      return;
    }

    try {
      if (typeof PipedriveConnector !== 'undefined' && typeof PipedriveConnector.refreshTokens === 'function') {
        const newCreds = PipedriveConnector.refreshTokens(refreshToken);
        props.setProperty('PIPEDRIVE_ACCESS_TOKEN', newCreds.accessToken);
        if (newCreds.refreshToken) props.setProperty('PIPEDRIVE_REFRESH_TOKEN', newCreds.refreshToken);
        accessToken = newCreds.accessToken;
      } else {
        logOrAlertPipedrive('Pipedrive connection required in PMA.', isHeadless);
        return;
      }
      props.setProperty('PIPEDRIVE_ACCESS_TOKEN', newCreds.accessToken);
      if (newCreds.refreshToken) props.setProperty('PIPEDRIVE_REFRESH_TOKEN', newCreds.refreshToken);
      accessToken = newCreds.accessToken;
    } catch (refreshErr) {
      logOrAlertPipedrive(`PipeDrive Token Refresh Error: ${refreshErr.message}`, isHeadless);
      return;
    }
  }

  try {
    // Fetch Data
    const allDeals = (await fetchPipedriveOpportunities_(accessToken));
    if (!allDeals || allDeals.length === 0) {
      logOrAlertPipedrive('No deals found.', isHeadless);
      return;
    }

    // Write to Sheet
    (await writePipeDriveDataToSheet(allDeals));
    
    // Update Timestamp
    if (typeof _updateTimestamp === 'function') _updateTimestamp('CRMComp', 'J2');
    logOrAlertPipedrive(`✅ Success! Exported ${allDeals.length} deals to the sheet.`, isHeadless);
    
  } catch (e) {
    logOrAlertPipedrive(`PipeDrive Export Error: ${e.message}`, isHeadless);
  }
}

function parsePipeDriveCustomField(val) {
  if (val === undefined || val === null) return '';
  if (typeof val === 'object') return JSON.stringify(val);
  return val;
}

async function writePipeDriveDataToSheet(deals) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheetName = "DataFromCRM";
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) sheet = ss.insertSheet(sheetName);

  const baseHeaders = ['Deal ID', 'Title', 'Person', 'Organization', 'Status', 'Value', 'Currency', 'Probability %', 'Won Time', 'Add Time', 'Update Time', 'Owner'];
  const cfHeadersSet = new Set();
  deals.forEach(deal => {
    if (deal.custom_fields && Array.isArray(deal.custom_fields)) {
      deal.custom_fields.forEach(cf => { if (cf.name) cfHeadersSet.add(cf.name); });
    }
  });
  const cfHeaders = Array.from(cfHeadersSet).sort();
  const allHeaders = [...baseHeaders, ...cfHeaders];
  const cfHeaderMap = new Map();
  cfHeaders.forEach((h, i) => cfHeaderMap.set(h, i));
  const dateOptions = { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' };
  const formatDate = (d) => d ? new Date(d).toLocaleString('en-GB', dateOptions) : '';

  const data = deals.map(deal => {
    const baseRow = [
      deal.id, deal.title, deal.person_name, deal.org_name, deal.status,
      deal.value, deal.currency, deal.probability ? deal.probability + '%' : '0%',
      formatDate(deal.won_time), formatDate(deal.add_time), formatDate(deal.update_time), deal.owner_name
    ];

    const cfValues = new Array(cfHeaders.length).fill('');
    if (deal.custom_fields && Array.isArray(deal.custom_fields)) {
      deal.custom_fields.forEach(cf => {
        const idx = cfHeaderMap.get(cf.name);
        if (idx !== undefined) cfValues[idx] = parsePipeDriveCustomField(cf.value);
      });
    }
    return [...baseRow, ...cfValues];
  });
  const safeData = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_(data) : data;
  const safeHeaders = (typeof sanitizeSheetMatrix_ === 'function') ? sanitizeSheetMatrix_([allHeaders])[0] : allHeaders;

  const lastRow = sheet.getLastRow();
  const oldHeaders = lastRow > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const headersMatch = JSON.stringify(oldHeaders) === JSON.stringify(safeHeaders);

  if (!headersMatch || lastRow <= 1) {
    sheet.clear();
    sheet.getRange(1, 1, 1, safeHeaders.length).setValues([safeHeaders]).setFontWeight('bold');
    if (safeData.length > 0) {
      sheet.getRange(2, 1, safeData.length, 1).setNumberFormat("@");
      sheet.getRange(2, 1, safeData.length, safeHeaders.length).setValues(safeData);
    }
    _logDataChangeAlertPipedrive();
    return;
  }

  const oldDataRange = sheet.getRange(2, 1, lastRow - 1, sheet.getLastColumn());
  const oldData = oldDataRange.getValues();
  const incomingMap = new Map();
  safeData.forEach(row => incomingMap.set(String(row[0]), row));

  const rowsToDelete = [];
  const valueUpdates = [];
  let dataChanged = false;

  for (let i = 0; i < oldData.length; i++) {
    const rowId = String(oldData[i][0]);
    const sheetRowNum = i + 2;

    if (!rowId || rowId.trim() === "") {
        rowsToDelete.push(sheetRowNum);
        continue;
    }

    if (!incomingMap.has(rowId)) {
      rowsToDelete.push(sheetRowNum);
      dataChanged = true;
    } else {
      const newData = incomingMap.get(rowId);
      if (JSON.stringify(oldData[i]) !== JSON.stringify(newData)) {
        valueUpdates.push({ range: `${sheetName}!A${sheetRowNum}`, values: [newData] });
        dataChanged = true;
      }
      incomingMap.delete(rowId);
    }
  }

  const rowsToAppend = Array.from(incomingMap.values());
  if (rowsToAppend.length > 0) dataChanged = true;

  if (!dataChanged) return;

  while (rowsToAppend.length > 0) {
    const newRowData = rowsToAppend.shift(); 
    if (rowsToDelete.length > 0) {
      const recycleRow = rowsToDelete.shift(); 
      valueUpdates.push({ range: `${sheetName}!A${recycleRow}`, values: [newRowData] });
    } else {
      const startRow = sheet.getLastRow() + 1;
      sheet.getRange(startRow, 1, 1, 1).setNumberFormat("@");
      sheet.getRange(startRow, 1, 1, newRowData.length).setValues([newRowData]);
    }
  }

  if (rowsToDelete.length > 0) {
    const clearRanges = rowsToDelete.map(rowNum => `${sheetName}!A${rowNum}:ZZ${rowNum}`);
    sheet.getRangeList(clearRanges).clearContent();
  }

  if (valueUpdates.length > 0) {
    (await Sheets.Spreadsheets.Values.batchUpdate({ valueInputOption: "USER_ENTERED", data: valueUpdates }, ss.getId()));
  }
  
  _logDataChangeAlertPipedrive();
}

