const PULSE_BROKER_CONFIG_QB = {
  DEFAULT_BROKER_URL: "https://app.pulsedashboard.co.uk",
  get INTERNAL_SECRET() {
    return typeof getPulseInternalSecret_ === "function"
      ? getPulseInternalSecret_()
      : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "");
  }
};

/**
 * Resolves the base Pulse Broker URL.
 */
function getPulseBrokerBaseUrl_QB_() {
  return PULSE_BROKER_CONFIG_QB.DEFAULT_BROKER_URL;
}

/**
 * Retrieves a fresh QuickBooks access token from the Central Pulse Vault Token Broker.
 * If Pulse does not yet have tokens for this spreadsheet, it automatically
 * attempts a one-time migration of existing local credentials into the Vault!
 * 
 * @returns {string|null} Valid Bearer access token or null if unavailable
 */
async function getBrokerQBAccessToken() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = getPulseBrokerBaseUrl_QB_();
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=quickbooks&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_QB.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : '',
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        // Auto-heal / maintain KeyInfo!X3 (Realm ID) if returned by the token broker
        if (data.realmId) {
          try {
            const keyInfo = ss.getSheetByName('KeyInfo');
            if (keyInfo) {
              const currentX3 = String(keyInfo.getRange('X3').getValue() || '').trim();
              if (!currentX3 || currentX3 !== data.realmId) {
                console.log("Auto-populating KeyInfo!X3 with realm ID from Pulse Vault: " + data.realmId);
                keyInfo.getRange('X3').setValue(data.realmId);
              }
            }
          } catch (x3Err) {
            console.warn("Could not auto-populate KeyInfo!X3: " + x3Err.message);
          }
        }
        return data.accessToken;
      }
    }

    // If 404 (not in vault), check if we have existing local tokens to self-migrate
    if (statusCode === 404) {
      console.log("Pulse Token Broker returned 404 (not in vault). Checking for existing local QuickBooks tokens to auto-migrate...");
      const migratedToken = (await autoMigrateLocalQBTokensToPulseVault_(spreadsheetId));
      if (migratedToken) {
        return migratedToken;
      }
    }

    console.warn(`Pulse Token Broker responded with code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("getBrokerQBAccessToken error: " + err.message);
  }

  return null;
}

/**
 * One-time auto-migration: extracts existing local tokens (library or ScriptProperties)
 * and sends them to Pulse /api/integrations/import so they are verified with Intuit
 * and stored encrypted in the Redis Vault.
 */
async function autoMigrateLocalQBTokensToPulseVault_(spreadsheetId) {
  try {
    let refreshToken = null;
    let libRealmId = null;

    // 1. First priority: Try reading live refreshed credentials directly from QuickBooksConnector library
    try {
      if (typeof QuickBooksConnector !== 'undefined' && QuickBooksConnector && typeof QuickBooksConnector.getRefreshedCredentials === 'function') {
        const creds = QuickBooksConnector.getRefreshedCredentials();
        if (creds && creds.refreshToken) {
          refreshToken = creds.refreshToken;
          libRealmId = creds.realmId || null;
          console.log("Successfully extracted active refreshToken from QuickBooksConnector library in memory.");
        }
      }
    } catch (libErr) {
      console.log("QuickBooksConnector library query note: " + libErr.message);
    }

    // 2. Second priority: Fall back to local ScriptProperties
    if (!refreshToken) {
      const props = PropertiesService.getScriptProperties();
      refreshToken = props.getProperty('REFRESH_TOKEN');
      if (refreshToken) {
        console.log("Retrieved REFRESH_TOKEN from ScriptProperties for auto-migration.");
      }
    }

    if (!refreshToken) {
      console.log("No local REFRESH_TOKEN found for QuickBooks auto-migration.");
      return null;
    }

    // 3. Resolve Realm ID
    let realmId = libRealmId || "";
    try {
      const ss = SpreadsheetApp.getActiveSpreadsheet();
      const keyInfo = ss.getSheetByName('KeyInfo');
      if (keyInfo) {
        const sheetRealm = keyInfo.getRange('X3').getValue();
        if (sheetRealm) realmId = String(sheetRealm).trim();
      }
    } catch (e) {}

    // 4. Resolve Client ID and Secret if present in KeyInfo!U2:U3
    let clientId = "";
    let clientSecret = "";
    try {
      const ss = SpreadsheetApp.getActiveSpreadsheet();
      const keyInfo = ss.getSheetByName('KeyInfo');
      if (keyInfo) {
        clientId = String(keyInfo.getRange('U2').getValue() || "").trim();
        clientSecret = String(keyInfo.getRange('U3').getValue() || "").trim();
      }
    } catch (e) {}

    // 5. Resolve Client Name
    let clientName = "";
    try {
      if (typeof getClientDisplayName === 'function') {
        clientName = getClientDisplayName();
      }
    } catch (e) {}

    const baseUrl = getPulseBrokerBaseUrl_QB_();
    const importUrl = `${baseUrl}/api/integrations/import`;

    const payload = {
      tool: 'quickbooks',
      spreadsheetId: spreadsheetId,
      clientName: clientName,
      refreshToken: refreshToken,
      realmId: realmId,
      clientId: clientId,
      clientSecret: clientSecret
    };

    const options = {
      method: 'post',
      contentType: 'application/json',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG_QB.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': typeof getOrCreatePulseClientSecret_ === 'function' ? getOrCreatePulseClientSecret_() : ''
      },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    console.log("Sending QuickBooks auto-migration request to Pulse Vault for " + (clientName || spreadsheetId) + "...");
    const response = (await UrlFetchApp.fetch(importUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const resData = JSON.parse(responseText);
      if (resData && resData.success && resData.accessToken) {
        console.log("✅ QuickBooks auto-migration to Pulse Vault successful for " + (clientName || spreadsheetId) + "! Fresh token active.");
        return resData.accessToken;
      }
    }

    console.warn("Auto-migration returned code " + statusCode + ": " + responseText);
  } catch (migErr) {
    console.error("autoMigrateLocalQBTokensToPulseVault_ exception: " + migErr.message);
  }

  return null;
}

/**
 * Diagnostic / manual test function to verify Token Broker and auto-migration
 * directly from Apps Script editor.
 */
async function testPulseQBBroker() {
  Logger.log("=== Testing Pulse QuickBooks Token Broker ===");
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const spreadsheetId = ss.getId();
  Logger.log("Sheet ID: " + spreadsheetId);

  const token = (await getBrokerQBAccessToken());
  if (token) {
    Logger.log("✅ SUCCESS: Successfully retrieved fresh QuickBooks access token from Pulse Broker!");
    Logger.log("Token snippet: " + token.substring(0, 15) + "..." + token.substring(token.length - 10));
    return "SUCCESS: Token retrieved: " + token.substring(0, 15) + "...";
  } else {
    Logger.log("❌ FAILED: Unable to retrieve QuickBooks access token from Pulse Broker or auto-migration.");
    return "FAILED: Check execution transcript logs.";
  }
}

