/**
 * =========================================
 * ==        XERO CONNECTOR FUNCTIONS     ==
 * =========================================
 * VERSION 1.30 - Sanitize Xero tenantId before writing to KeyInfo!X2
 * VERSION 1.29 - Enforce canonical Pulse Broker URL (remove KeyInfo!X30 cell override)
 *
 * This script handles manual admin dialogs (Menu: Pulse > Xero) and connects
 * to the Pulse Central Auth Broker (/api/integrations/token) for automatic
 * AES-256-GCM token retrieval, refreshes, and self-migration.
 */

const PULSE_BROKER_CONFIG = {
  // Production Pulse App URL
  DEFAULT_BROKER_URL: "https://app.pulsedashboard.co.uk",
  // Shared internal ecosystem secret for authenticated token vending (reads ScriptProperties)
  get INTERNAL_SECRET() {
    return typeof getPulseInternalSecret_ === "function"
      ? getPulseInternalSecret_()
      : (PropertiesService.getScriptProperties().getProperty("PULSE_INTERNAL_SECRET") || "");
  }
};

/**
 * Resolves the base Pulse Broker URL.
 */
function getPulseBrokerBaseUrl_() {
  return PULSE_BROKER_CONFIG.DEFAULT_BROKER_URL;
}

/**
 * Retrieves or initializes a unique, cryptographically strong client-specific secret
 * stored securely in the Master Sheet's private ScriptProperties.
 * Scoped strictly to this script project; never accessible via spreadsheet formulas.
 * 
 * @returns {string} The persistent client-specific secret
 */
function getOrCreatePulseClientSecret_() {
  try {
    const props = PropertiesService.getScriptProperties();
    let secret = props.getProperty('PULSE_CLIENT_SECRET');
    if (!secret) {
      secret = 'pcs_' + Utilities.getUuid().replace(/-/g, '') + Utilities.getUuid().replace(/-/g, '');
      props.setProperty('PULSE_CLIENT_SECRET', secret);
    }
    return secret;
  } catch (e) {
    return '';
  }
}

/**
 * Retrieves a fresh Xero access token from the Central Pulse Vault Token Broker.
 * If Pulse does not yet have tokens for this spreadsheet, it automatically
 * attempts a one-time migration of existing local ScriptProperties into the Vault!
 * 
 * @returns {string|null} Valid Bearer access token or null if unavailable
 */
async function getBrokerXeroAccessToken() {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const spreadsheetId = ss.getId();
    const baseUrl = getPulseBrokerBaseUrl_();
    const tokenUrl = `${baseUrl}/api/integrations/token?tool=xero&spreadsheetId=${encodeURIComponent(spreadsheetId)}`;

    const options = {
      method: 'get',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': getOrCreatePulseClientSecret_(),
        'Accept': 'application/json'
      },
      muteHttpExceptions: true
    };

    const response = (await UrlFetchApp.fetch(tokenUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        // Auto-heal / maintain KeyInfo!X2 (Tenant ID) if returned by the token broker
        if (data.tenantId) {
          try {
            const keyInfo = ss.getSheetByName('KeyInfo');
            if (keyInfo) {
              const currentX2 = String(keyInfo.getRange('X2').getValue() || '').trim();
              if (!currentX2 || currentX2 !== data.tenantId) {
                console.log("Auto-populating KeyInfo!X2 with tenant ID from Pulse Vault: " + data.tenantId);
                const safeTenantId = typeof sanitizeSheetCell_ === 'function' ? sanitizeSheetCell_(String(data.tenantId || '').trim()) : String(data.tenantId || '').trim();
                keyInfo.getRange('X2').setValue(safeTenantId);
              }
            }
          } catch (x2Err) {
            console.warn("Could not auto-populate KeyInfo!X2: " + x2Err.message);
          }
        }
        return data.accessToken;
      }
    }

    // If 404 (not in vault), check if we have existing local tokens to self-migrate
    if (statusCode === 404) {
      console.log("Pulse Token Broker returned 404 (not in vault). Checking for existing local tokens to auto-migrate...");
      const migratedToken = (await autoMigrateLocalXeroTokensToPulseVault_(spreadsheetId));
      if (migratedToken) {
        return migratedToken;
      }
    }

    console.warn(`Pulse Token Broker responded with code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("getBrokerXeroAccessToken error: " + err.message);
  }

  return null;
}

/**
 * One-time auto-migration: sends existing local ScriptProperties refresh token
 * to Pulse /api/integrations/import so it is verified and stored in the Redis Vault.
 */
async function autoMigrateLocalXeroTokensToPulseVault_(spreadsheetId) {
  try {
    const props = PropertiesService.getScriptProperties();
    const refreshToken = props.getProperty('REFRESH_TOKEN');
    if (!refreshToken) {
      console.log("No local REFRESH_TOKEN found in Script Properties for auto-migration.");
      return null;
    }

    let tenantId = "";
    try {
      const ss = SpreadsheetApp.getActiveSpreadsheet();
      const keyInfo = ss.getSheetByName('KeyInfo');
      if (keyInfo) {
        tenantId = String(keyInfo.getRange('X2').getValue() || "").trim();
      }
    } catch (e) {}

    let clientName = "";
    try {
      if (typeof getClientDisplayName === 'function') {
        clientName = getClientDisplayName();
      }
    } catch (e) {}

    const baseUrl = getPulseBrokerBaseUrl_();
    const importUrl = `${baseUrl}/api/integrations/import`;

    const payload = {
      tool: 'xero',
      spreadsheetId: spreadsheetId,
      clientName: clientName,
      refreshToken: refreshToken,
      tenantId: tenantId
    };

    const options = {
      method: 'post',
      contentType: 'application/json',
      headers: {
        'Authorization': `Bearer ${PULSE_BROKER_CONFIG.INTERNAL_SECRET}`,
        'X-Pulse-Client-Secret': getOrCreatePulseClientSecret_()
      },
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    };

    console.log("Sending auto-migration request to Pulse Vault for " + (clientName || spreadsheetId) + "...");
    const response = (await UrlFetchApp.fetch(importUrl, options));
    const statusCode = response.getResponseCode();
    const responseText = response.getContentText();

    if (statusCode === 200) {
      const data = JSON.parse(responseText);
      if (data && data.success && data.accessToken) {
        console.log("🎉 Successfully migrated Xero tokens into Pulse Vault for Org: " + (data.tenantName || tenantId));
        return data.accessToken;
      }
    }

    console.warn(`Auto-migration returned code ${statusCode}: ${responseText}`);
  } catch (err) {
    console.warn("autoMigrateLocalXeroTokensToPulseVault_ error: " + err.message);
  }

  return null;
}

/**
 * Manual Test Routine: Callable from menu (Pulse > Xero > Test Pulse Token Broker)
 * or run directly in Apps Script editor.
 */
async function testPulseXeroBroker() {
  const ui = (typeof SpreadsheetApp.getUi === 'function') ? SpreadsheetApp.getUi() : null;
  try {
    console.log("=== Testing Pulse Central Token Broker ===");
    const token = (await getBrokerXeroAccessToken());
    if (token) {
      const msg = `✅ SUCCESS: Pulse Token Broker returned a valid live access token!\n\nToken prefix: ${token.substring(0, 15)}...\nToken length: ${token.length} chars.`;
      console.log(msg);
      if (ui) ui.alert("Pulse Token Broker Test", msg, ui.ButtonSet.OK);
      return true;
    } else {
      const msg = `⚠️ NOTICE: Pulse Token Broker did not return a token. Check Apps Script execution logs for details.`;
      console.log(msg);
      if (ui) ui.alert("Pulse Token Broker Test", msg, ui.ButtonSet.OK);
      return false;
    }
  } catch (e) {
    console.error("testPulseXeroBroker error: " + e.message);
    if (ui) ui.alert("Pulse Token Broker Test", "Error: " + e.message, ui.ButtonSet.OK);
    return false;
  }
}

